    // Unified Media URL Resolver for subfolder deployments (e.g. /pos)
    function resolveMediaUrl(url) {
      if (!url || typeof url !== 'string') return '';
      if (url.startsWith('data:') || url.startsWith('blob:') || url.startsWith('http://') || url.startsWith('https://')) return url;
      const basePath = window.location.pathname.replace(/\/index\.html$/, '').replace(/\/$/, '');
      if (url.startsWith('/')) {
        if (basePath && !url.startsWith(basePath + '/')) return basePath + url;
        return url;
      }
      return (basePath ? basePath + '/' : '') + url;
    }
    window.resolveMediaUrl = resolveMediaUrl;

    // Initialize SDKs
    async function apiRequest(path, options = {}) {
      // Get the current location and format it as a base path
      const basePath = window.location.pathname.replace(/\/index\.html$/, '').replace(/\/$/, '');

      // If the incoming path starts with '/', prepend the base path, otherwise use it directly
      const fullPath = path.startsWith('/') ? basePath + path : path;

      const headers = { 'Content-Type': 'application/json', 'X-Requested-With': 'XMLHttpRequest', ...(options.headers || {}) };
      try {
        const dToken = typeof getOrCreateDeviceToken === 'function' ? getOrCreateDeviceToken() : (localStorage.getItem('pos_device_token') || '');
        if (dToken && !headers['X-Device-Token']) headers['X-Device-Token'] = dToken;
        const sToken = sessionStorage.getItem('pos_setup_token');
        if (sToken && !headers['X-Setup-Token']) headers['X-Setup-Token'] = sToken;
      } catch (e) {}

      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 15000);

      try {
        const response = await fetch(fullPath, { ...options, headers, credentials: 'include', signal: controller.signal });
        let payload = null;
        try {
          payload = await response.json();
        }
 catch (e) {
          payload = null;
        }

        if (!response.ok) {
          if (response.status === 423 || (payload && (payload.code === 'LICENSE_MISMATCH' || payload.code === 'LICENSE_INVALID' || payload.code === 'LICENSE_EXPIRED' || payload.code === 'LICENSE_MISSING'))) {
            if (typeof triggerLicenseHardLockout === 'function') {
              triggerLicenseHardLockout(payload || {});
            }

          }

          if (response.status === 401) {
            if (typeof terminateAllAudioAndMediaSession === 'function') {
              try { terminateAllAudioAndMediaSession(); } catch (e) {}
            }

          }

          const message = payload && payload.error ? payload.error : 'Request failed';
          const err = new Error(message);
          err.status = response.status;
          err.payload = payload;
          throw err;
        }

        if (payload && payload.setup_token) {
          try {
            const getSetupTokenStep = (tok) => {
              if (!tok || typeof tok !== 'string' || !tok.includes('.')) return 0;
              try {
                const parts = tok.split('.');
                const b64 = parts[0].replace(/-/g, '+').replace(/_/g, '/');
                const parsed = JSON.parse(atob(b64));
                return Number(parsed.step || 0);
              } catch (_) { return 0; }
            };
            const currentTok = sessionStorage.getItem('pos_setup_token');
            const currentStep = getSetupTokenStep(currentTok);
            const newStep = getSetupTokenStep(payload.setup_token);
            if (newStep >= currentStep || !currentTok) {
              sessionStorage.setItem('pos_setup_token', payload.setup_token);
            }
          } catch (e) {}
        }

        return payload || {};
      } catch (e) {
        if (e.name === 'AbortError') throw new Error('Request timed out. Please try again.');
        throw e;
      } finally {
        clearTimeout(timeoutId);
      }
    }

    async function apiUpload(path, formData, options = {}) {
      const basePath = window.location.pathname.replace(/\/index\.html$/, '').replace(/\/$/, '');
      const fullPath = path.startsWith('/') ? basePath + path : path;

      const headers = { 'X-Requested-With': 'XMLHttpRequest', ...(options.headers || {}) };
      try {
        const dToken = typeof getOrCreateDeviceToken === 'function' ? getOrCreateDeviceToken() : (localStorage.getItem('pos_device_token') || '');
        if (dToken && !headers['X-Device-Token']) headers['X-Device-Token'] = dToken;
      } catch (e) {}

      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 60000); // 60s for file/voice uploads

      try {
        const response = await fetch(fullPath, {
          method: 'POST',
          body: formData,
          headers,
          credentials: 'include',
          signal: controller.signal,
          ...options
        }
);

        let payload = null;
        const text = await response.text();
        try {
          payload = JSON.parse(text);
        }
 catch (e) {
          payload = null;
        }


        if (!response.ok) {
          const message = payload && payload.error ? payload.error : `Upload failed (${response.status} ${response.statusText || 'Error'})`;
          throw new Error(message);
        }


        if (!payload) {
          throw new Error('Invalid response from server');
        }


        return payload;
      } catch (e) {
        if (e.name === 'AbortError') throw new Error('Upload timed out. Please try again.');
        throw e;
      } finally {
        clearTimeout(timeoutId);
      }
    }
    window.apiUpload = apiUpload;

    // Watchdog: auto-recover buttons stuck in loading state
    // Stamps data-disabled-at + data-original-text when a button becomes disabled,
    // then re-enables it after 20 s if it's still showing a "..." loading label.
    (function () {
      const obs = new MutationObserver(mutations => {
        for (const m of mutations) {
          if (m.type !== 'attributes' || m.attributeName !== 'disabled') continue;
          const el = m.target;
          if (el.tagName !== 'BUTTON') continue;
          if (el.disabled) {
            if (!el.dataset.disabledAt) {
              el.dataset.disabledAt = Date.now();
              el.dataset.originalText = el.textContent.trim();
            }

          }
 else {
            delete el.dataset.disabledAt;
            delete el.dataset.originalText;
          }

        }

      });
      obs.observe(document.body, { subtree: true, attributeFilter: ['disabled'] });

      setInterval(() => {
        const now = Date.now();
        document.querySelectorAll('button[disabled][data-disabled-at]').forEach(btn => {
          const stuckMs = now - parseInt(btn.dataset.disabledAt || now);
          // Only recover buttons visually in a "loading…" state stuck for more than 20 s
          if (stuckMs > 20000 && btn.textContent.trim().endsWith('...')) {
            btn.disabled = false;
            btn.textContent = btn.dataset.originalText || btn.textContent.replace(/\.\.\.$/,'');
            delete btn.dataset.disabledAt;
            delete btn.dataset.originalText;
          }

        }
);
      }, 5000);
    })();

