    function buildOrderItemsData(orderItems) {
      const items = orderItems || [];
      return JSON.stringify(items.map(item => {
        const prodId = item.product_id ? String(item.product_id) : (item.productId ? String(item.productId) : (item.id ? String(item.id) : null));
        let catId = item.category_id ? String(item.category_id) : (item.categoryId ? String(item.categoryId) : null);

        // Find categoryId from productsCache if available and not already provided
        let productObj = null;
        if (prodId && typeof productsCache !== 'undefined' && Array.isArray(productsCache)) {
          productObj = productsCache.find(p => String(p.__backendId || p.id) === String(prodId));
        }

        if (!catId && productObj) catId = productObj.categoryId || productObj.category_id;
        let catObj = null;
        if (catId && typeof categoriesCache !== 'undefined' && Array.isArray(categoriesCache)) {
          catObj = categoriesCache.find(c => String(c.__backendId || c.id) === String(catId));
        }


        const price = item.price || '0';
        const quantity = item.quantity || '0';
        const costOwner = item.cost_owner_id ? String(item.cost_owner_id) : (item.costOwnerId ? String(item.costOwnerId) : null);

        return {
          ...item,
          id: prodId,
          productId: prodId,
          product_id: prodId,
          categoryId: catId,
          category_id: catId,
          name: item.name || item.product_name || (productObj ? productObj.name : ''),
          product_name: item.product_name || item.name || (productObj ? productObj.name : ''),
          product_uid: item.product_uid || item.productUid || (productObj ? productObj.uid : null),
          category_uid: item.category_uid || item.categoryUid || (catObj ? catObj.uid : null),
          category_name: item.category_name || item.categoryName || (catObj ? catObj.name : ''),
          type: prodId ? 'product' : null,
          price: price,
          quantity: quantity,
          total: exactMultiply(price, quantity),
          cost: item.cost || '0',
          displayDecimals: prodId && typeof productsCache !== 'undefined' ? (productObj?.displayDecimals ?? null) : null,
          batchId: item.purchase_id ? String(item.purchase_id) : (item.batchId ? String(item.batchId) : null),
          purchase_id: item.purchase_id ? String(item.purchase_id) : (item.batchId ? String(item.batchId) : null),
          batch_uid: item.batch_uid || item.batchUid || null,
          description: item.description || '',
          cost_owner_id: costOwner,
          costOwnerId: costOwner,
          cost_owner_name: item.cost_owner_name || item.costOwnerName || '',
          profit_split_type: item.profit_split_type || item.profitSplitType || 'none',
          product_owner_share_pct: item.product_owner_share_pct !== undefined ? String(item.product_owner_share_pct) : (item.productOwnerSharePct !== undefined ? String(item.productOwnerSharePct) : '0'),
          product_owner_profit: item.product_owner_profit !== undefined ? String(item.product_owner_profit) : (item.productOwnerProfit !== undefined ? String(item.productOwnerProfit) : '0'),
          service_owner_profit: item.service_owner_profit !== undefined ? String(item.service_owner_profit) : (item.serviceOwnerProfit !== undefined ? String(item.serviceOwnerProfit) : '0'),
          is_returned: item.is_returned || 0,
          returned_at: item.returned_at || null,
          returned_by: item.returned_by || null
        }
;
      }));
    }

