    async function getSetupLicenseAllowedStores(forceRefresh = false) {
      if (!forceRefresh && window.setupLicensePayload && window.setupLicensePayload.allowed_stores) {
        return window.setupLicensePayload.allowed_stores;
      }
      if (!forceRefresh) {
        try {
          const cached = sessionStorage.getItem('pos_license_payload');
          if (cached) {
            const parsed = JSON.parse(cached);
            if (parsed && parsed.allowed_stores) {
              window.setupLicensePayload = parsed;
              return parsed.allowed_stores;
            }
          }
        } catch (e) {}
      }
      try {
        const res = await apiRequest('/api/setup/license/status');
        if (res && res.valid && res.payload) {
          window.setupLicensePayload = res.payload;
          try { sessionStorage.setItem('pos_license_payload', JSON.stringify(res.payload)); } catch (e) {}
          return res.payload.allowed_stores || null;
        }
      } catch (e) {}
      return null;
    }
    window.getSetupLicenseAllowedStores = getSetupLicenseAllowedStores;

    function isStorePresetAllowed(presetKey, allowedStores) {
      if (!allowedStores) return true; // Legacy or unrestricted license
      if (Array.isArray(allowedStores)) {
        if (allowedStores.includes('*') || allowedStores.includes('all')) return true;
        return allowedStores.includes(presetKey);
      }
      if (typeof allowedStores === 'string') {
        if (allowedStores === '*' || allowedStores.toLowerCase() === 'all') return true;
        return allowedStores === presetKey;
      }
      return true;
    }
    window.isStorePresetAllowed = isStorePresetAllowed;

    function applyPresetCardsLicenseState(allowedStores) {
      const isRepairAllowed = isStorePresetAllowed('phone_repair', allowedStores);
      const isCryptoAllowed = isStorePresetAllowed('crypto_cash', allowedStores);

      const cardRepair = document.getElementById('preset-card-repair');
      const cardCrypto = document.getElementById('preset-card-crypto');
      const badgeRepair = document.getElementById('preset-badge-repair');
      const badgeCrypto = document.getElementById('preset-badge-crypto');
      const checkRepair = document.getElementById('preset-check-repair');
      const checkCrypto = document.getElementById('preset-check-crypto');

      if (!isRepairAllowed && cardRepair) {
        cardRepair.className = 'group relative rounded-3xl p-5 sm:p-6 border-2 border-dashed border-rose-500/40 bg-gradient-to-b from-rose-500/[0.08] via-rose-950/[0.04] to-slate-900/90 opacity-75 cursor-not-allowed transition-all duration-300 flex flex-col justify-between min-h-[310px] sm:min-h-[330px]';
        if (checkRepair) checkRepair.classList.add('hidden');
        if (badgeRepair) {
          badgeRepair.removeAttribute('data-i18n');
          badgeRepair.className = 'px-2.5 py-1 rounded-2xl text-[10px] font-bold uppercase tracking-wider bg-rose-500/15 text-rose-500 dark:text-rose-400 border border-rose-500/30 shadow-2xs shrink-0 max-w-[170px] sm:max-w-[190px] whitespace-normal inline-flex items-start gap-1.5 text-start leading-tight';
          badgeRepair.innerHTML = '<span class="w-1.5 h-1.5 rounded-full bg-rose-500 dark:bg-rose-400 shrink-0 mt-0.5"></span><span>' + (window.__t ? window.__t('setup.preset_unlicensed_badge', 'Available, but not included in your license') : 'Available, but not included in your license') + '</span>';
        }
      }

      if (!isCryptoAllowed && cardCrypto) {
        cardCrypto.className = 'group relative rounded-3xl p-5 sm:p-6 border-2 border-dashed border-rose-500/40 bg-gradient-to-b from-rose-500/[0.08] via-rose-950/[0.04] to-slate-900/90 opacity-75 cursor-not-allowed transition-all duration-300 flex flex-col justify-between min-h-[310px] sm:min-h-[330px]';
        if (checkCrypto) checkCrypto.classList.add('hidden');
        if (badgeCrypto) {
          badgeCrypto.removeAttribute('data-i18n');
          badgeCrypto.className = 'px-2.5 py-1 rounded-2xl text-[10px] font-bold uppercase tracking-wider bg-rose-500/15 text-rose-500 dark:text-rose-400 border border-rose-500/30 shadow-2xs shrink-0 max-w-[170px] sm:max-w-[190px] whitespace-normal inline-flex items-start gap-1.5 text-start leading-tight';
          badgeCrypto.innerHTML = '<span class="w-1.5 h-1.5 rounded-full bg-rose-500 dark:bg-rose-400 shrink-0 mt-0.5"></span><span>' + (window.__t ? window.__t('setup.preset_unlicensed_badge', 'Available, but not included in your license') : 'Available, but not included in your license') + '</span>';
        }
      }
    }
    window.applyPresetCardsLicenseState = applyPresetCardsLicenseState;

    async function showPresetSetupPage() {
      if (typeof terminateAllAudioAndMediaSession === 'function') terminateAllAudioAndMediaSession();
      sessionStorage.removeItem('tab_session');
      sessionStorage.removeItem('pos_current_user');
      sessionStorage.removeItem('pos_active_page');
      try { document.documentElement.setAttribute('data-pre-auth', 'setup-preset'); } catch (e) {}
      document.getElementById('license-setup-page')?.classList.add('hidden');
      document.getElementById('login-page')?.classList.add('hidden');
      document.getElementById('db-setup-page')?.classList.add('hidden');
      document.getElementById('setup-fork-page')?.classList.add('hidden');
      document.getElementById('setup-page')?.classList.add('hidden');
      document.getElementById('preset-setup-page')?.classList.remove('hidden');
      document.getElementById('app')?.classList.add('hidden');
      document.getElementById('preset-setup-error')?.classList.add('hidden');

      updateSetupLanguagePills();
      if (window.i18n && typeof window.i18n.applyTranslations === 'function') {
        const pp = document.getElementById('preset-setup-page');
        if (pp) window.i18n.applyTranslations(pp);
      }

      const allowedStores = await getSetupLicenseAllowedStores(true);
      window._allowedSetupStores = allowedStores;
      if (!window.setupLicensePayload) window.setupLicensePayload = {};
      window.setupLicensePayload.allowed_stores = allowedStores;
      const isRepairAllowed = isStorePresetAllowed('phone_repair', allowedStores);
      const isCryptoAllowed = isStorePresetAllowed('crypto_cash', allowedStores);

      let targetPreset = typeof selectedSetupPreset !== 'undefined' ? selectedSetupPreset : 'phone_repair';
      if (targetPreset === 'phone_repair' && !isRepairAllowed && isCryptoAllowed) {
        targetPreset = 'crypto_cash';
      } else if (targetPreset === 'crypto_cash' && !isCryptoAllowed && isRepairAllowed) {
        targetPreset = 'phone_repair';
      }

      if (typeof selectPresetOption === 'function') {
        selectPresetOption(targetPreset);
      }
      applyPresetCardsLicenseState(allowedStores);
    }
    window.showPresetSetupPage = showPresetSetupPage;

