    async function setupRestoreDecisionFresh() {
      const modal = document.getElementById('setup-restore-decision-modal');
      const progEl = document.getElementById('setup-restore-progress') || document.getElementById('fork-restore-progress');
      const progText = document.getElementById('setup-restore-progress-text') || document.getElementById('fork-restore-progress-text');

      modal.classList.add('hidden');
      if (progEl) {
        progEl.classList.remove('hidden');
        if (progText) progText.textContent = 'Wiping restored data and starting fresh…';
      }

      try {
        await apiRequest('/api/setup/restore/discard', { method: 'POST', body: JSON.stringify({}) });
        if (progEl) progEl.classList.add('hidden');
        const fileInput = document.getElementById('setup-restore-file');
        if (fileInput) fileInput.value = '';
        document.getElementById('setup-restore-file-name')?.classList.add('hidden');
        cancelForkRestore();
        showToast(_t('settings.setup_restore_wiped_success_toast', 'Database wiped. Setup mode restarted.'), 'default');
        showSetupForkPage();
      } catch (e) {
        if (progEl) progEl.classList.add('hidden');
        const errEl = document.getElementById('setup-restore-error') || document.getElementById('fork-restore-error');
        if (errEl) {
          errEl.textContent = e.message || 'Failed to wipe data';
          errEl.classList.remove('hidden');
        }
      }
    }

    // ─── Restore from backup AT the database-creation step ────────
    // Applies the connection form (so the target DB exists), then restores the
    // chosen .sql into it. Reuses the same Keep/Discard decision modal.
    async function applyDbConfigFromForm(errEl) {
      const host = document.getElementById('db-host').value.trim();
      const port = document.getElementById('db-port').value.trim();
      const database = document.getElementById('db-name').value.trim();
      const username = document.getElementById('db-username').value.trim();
      const password = document.getElementById('db-password').value;
      const useTls = document.getElementById('db-use-tls').checked;
      if (!host || !port || !database || !username) {
        errEl.textContent = 'Fill in the connection details above first (or click "Use the built-in database" and restore on the next screen).';
        errEl.classList.remove('hidden');
        return false;
      }
      // force: true — this path connects only to then restore a backup over the
      // database (which drops + recreates it), so any existing target version is
      // irrelevant here. The backup's own version is checked by the restore step.
      await apiRequest('/api/setup/db/apply', {
        method: 'POST',
        body: JSON.stringify({ host, port, database, username, password, use_tls: useTls, force: true })
      });
      return true;
    }

    // Shared restore upload used by both setup screens. ui = {progress, progressText, err, pickBtn}
    async function doSetupRestoreUpload(file, ui, force = false) {
      ui.err.classList.add('hidden');
      ui.progress.classList.remove('hidden');
      ui.progressText.textContent = 'Uploading & restoring backup…';
      if (ui.pickBtn) { ui.pickBtn.disabled = true; ui.pickBtn.classList.add('opacity-60', 'cursor-not-allowed'); }

      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 120000);
      try {
        const formData = new FormData();
        formData.append('backup_file', file);
        if (force) formData.append('force', '1');
        const response = await fetch(getApiUrl('/api/setup/restore'), {
          method: 'POST', body: formData, credentials: 'include', headers: { 'X-Requested-With': 'XMLHttpRequest' }, signal: controller.signal
        });
        const result = await response.json().catch(() => null);
        clearTimeout(timeoutId);

        if (result && result.needs_confirmation) {
          ui.progress.classList.add('hidden');
          if (ui.pickBtn) { ui.pickBtn.disabled = false; ui.pickBtn.classList.remove('opacity-60', 'cursor-not-allowed'); }
          showVersionWarning(result, () => doSetupRestoreUpload(file, ui, true));
          return;
        }

        if (!response.ok || !result || !result.ok) {
          throw new Error((result && result.error) ? result.error : 'Restore failed');
        }


        if (result.has_users) {
          ui.progressText.textContent = 'Restore complete! Redirecting to login…';
          showToast(_t('settings.setup_restore_success_toast', 'Backup restored successfully. Please sign in.'), 'default');
          setTimeout(() => window.location.reload(), 1500);
          return;
        }

        if (!result.has_users && result.setup_token) {
          try { sessionStorage.setItem('pos_setup_token', result.setup_token); } catch (e) {}
        }

        // No login account in the backup — offer Keep / Start fresh.
        ui.progress.classList.add('hidden');
        if (ui.pickBtn) { ui.pickBtn.disabled = false; ui.pickBtn.classList.remove('opacity-60', 'cursor-not-allowed'); }
        document.getElementById('setup-restore-decision-modal').classList.remove('hidden');
      } catch (e) {
        clearTimeout(timeoutId);
        ui.progress.classList.add('hidden');
        ui.err.textContent = e.name === 'AbortError'
          ? 'Restore is taking too long. Check the server and try again.'
          : (e.message || 'Failed to restore backup');
        ui.err.classList.remove('hidden');
        if (ui.pickBtn) { ui.pickBtn.disabled = false; ui.pickBtn.classList.remove('opacity-60', 'cursor-not-allowed'); }
      }
    }

    async function onDbSetupRestoreFileChosen(event) {
      const file = event.target.files && event.target.files[0];
      if (!file) return;
      const errEl = document.getElementById('db-setup-restore-error');
      const nameEl = document.getElementById('db-setup-restore-name');
      const progEl = document.getElementById('db-setup-restore-progress');
      const progText = document.getElementById('db-setup-restore-progress-text');
      const pickBtn = document.getElementById('db-setup-restore-btn');
      const fileInput = document.getElementById('db-setup-restore-file');

      errEl.classList.add('hidden');
      nameEl.textContent = file.name + '  (' + formatRestoreFileSize(file.size) + ')';
      nameEl.classList.remove('hidden');

      // Step 1: connect / create the database from the form values.
      progEl.classList.remove('hidden');
      progText.textContent = 'Connecting to the database…';
      pickBtn.disabled = true; pickBtn.classList.add('opacity-60', 'cursor-not-allowed');
      try {
        const ok = await applyDbConfigFromForm(errEl);
        if (!ok) {
          progEl.classList.add('hidden');
          pickBtn.disabled = false; pickBtn.classList.remove('opacity-60', 'cursor-not-allowed');
          fileInput.value = ''; nameEl.classList.add('hidden');
          return;
        }

      } catch (e) {
        progEl.classList.add('hidden');
        errEl.textContent = e.message || 'Failed to connect to the database';
        errEl.classList.remove('hidden');
        pickBtn.disabled = false; pickBtn.classList.remove('opacity-60', 'cursor-not-allowed');
        fileInput.value = ''; nameEl.classList.add('hidden');
        return;
      }

      // Step 2: restore the backup into the now-connected database.
      await doSetupRestoreUpload(file, { progress: progEl, progressText: progText, err: errEl, pickBtn });
      fileInput.value = '';
    }

