      sessionStorage.removeItem('pos_recovery_watermark_dismissed');
      sessionStorage.removeItem('pos_has_personal_recovery_code');
      sessionStorage.removeItem('pos_has_master_recovery_code');
      try { document.documentElement.setAttribute('data-pre-auth', '0'); } catch (e) {}
