      const setSelect = document.getElementById('settlement-partner-filter');
      if (setSelect) setSelect.innerHTML = '<option value="all">' + (window.__t ? window.__t('statements.filter_all_partners', '👥 All Partners') : '👥 All Partners') + '</option>';
      const ordersUserFilter = document.getElementById('orders-user-filter');
