    function autoLogoutInactivity() {
      if (typeof terminateAllAudioAndMediaSession === 'function') terminateAllAudioAndMediaSession();
      if (typeof stopHeartbeat === 'function') stopHeartbeat();
      // preserve pos_device_token so physical device identity persists across logins per Rule 17
      sessionStorage.removeItem('tab_session');
      sessionStorage.removeItem('pos_active_page');
      sessionStorage.removeItem('pos_data_cache');
      sessionStorage.removeItem('pos_recovery_session');
      sessionStorage.removeItem('pos_can_set_password_once');
      sessionStorage.removeItem('pos_recovery_type');
      try { document.documentElement.setAttribute('data-pre-auth', '0'); } catch (e) {}
      try { document.documentElement.setAttribute('data-active-page', 'dashboard'); } catch (e) {}
      // Use full logout (clears session in DB too) with keepalive and device token header
      const dt = (typeof getOrCreateDeviceToken === 'function') ? getOrCreateDeviceToken() : (localStorage.getItem('pos_device_token') || '');
      fetch(getApiUrl('/api/auth/logout'), {
        method: 'POST',
        keepalive: true,
        credentials: 'include',
        headers: { 'Content-Type': 'application/json', 'X-Device-Token': dt, 'X-Requested-With': 'XMLHttpRequest' },
        body: JSON.stringify({ reason: 'inactivity' })
      }).catch(() => {});
      currentUser = null;
      try { sessionStorage.removeItem('pos_current_user'); } catch(e) {}
      usersCache = []; productsCache = []; customersCache = []; suppliersCache = [];
      purchasesCache = []; ordersCache = []; categoriesCache = [];
      if (typeof settlementHubCache !== 'undefined') settlementHubCache = null;
      if (typeof settlementPartnerFilter !== 'undefined') settlementPartnerFilter = 'all';
      if (typeof settlementPartnerFilterManuallySet !== 'undefined') settlementPartnerFilterManuallySet = false;
      if (typeof settlementHubFilter !== 'undefined') settlementHubFilter = 'all';
      if (typeof settlementDirectionFilter !== 'undefined') settlementDirectionFilter = 'all';
      if (typeof dashboardUserFilter !== 'undefined') dashboardUserFilter = 'self';
      if (typeof expensesCache !== 'undefined') expensesCache = [];
      if (typeof expensesStaffFilter !== 'undefined') expensesStaffFilter = 'all';
      if (typeof vaultSummaryCache !== 'undefined') vaultSummaryCache = null;
      if (typeof resetMessagesPageCache === 'function') resetMessagesPageCache();
      if (typeof window.resetMessagesPageCache === 'function') window.resetMessagesPageCache();
      if (typeof activeMessagesList !== 'undefined') activeMessagesList = [];
      if (typeof activeConversationId !== 'undefined') activeConversationId = null;
      try { sessionStorage.removeItem('pos_active_conversation_id'); } catch(e) {}
      setAllData();
      sessionStorage.setItem('pos_browser_session_active', '1');
      document.getElementById('app').classList.add('hidden');
      document.getElementById('login-page').classList.remove('hidden');
      if (typeof resetLoginForm === 'function') resetLoginForm({ force: true }); else document.getElementById('login-form')?.reset();
      loadPublicBranding();
      if (typeof updateLoginLanguagePills === 'function') updateLoginLanguagePills();
      if (window.i18n && typeof window.i18n.applyTranslations === 'function') {
        const lp = document.getElementById('login-page');
        if (lp) window.i18n.applyTranslations(lp);
      }
      showToast(_t('auth.toast_you_were_logged_out_due_to_inactivi', 'You were logged out due to inactivity'), 'default');
    }


    function updateSidebarAvatar() {
      if (!currentUser) return;

      const avatar = document.getElementById('user-avatar');
      if (!avatar) return;
      avatar.innerHTML = '';

      const pic = currentUser.profilePicture || currentUser.profile_picture;
      if (pic) {
        const img = document.createElement('img');
        img.src = pic;
        img.alt = currentUser.username || 'User';
        img.className = 'w-full h-full object-cover transition-transform duration-300 ease-out pointer-events-none';
        avatar.appendChild(img);
      } else {
        avatar.textContent = ((currentUser.username || currentUser.name || 'A').charAt(0)).toUpperCase();
      }
    }

