          // Match UID, customer name, customer UID, customer phone, or "(ID)" or "#ID" format or note
          const matchesUid = uid.includes(cleanQuery) || (`#${uid}`).includes(searchQuery);
          const matchesCustomer = customerName.includes(searchQuery) || customerName.includes(cleanQuery);
