                    <span class="px-2 py-0.5 rounded-full text-[10px] font-bold ${ctx.isPhase2Consensus ? 'bg-emerald-100 text-emerald-800 border border-emerald-300 dark:bg-emerald-900/60 dark:text-emerald-200' : (ctx.isPartnerRefused ? 'bg-rose-100 text-rose-800 border border-rose-300 dark:bg-rose-900/60 dark:text-rose-200' : 'bg-amber-100 text-amber-800 border border-amber-300 dark:bg-amber-900/60 dark:text-amber-200')}">
                      ${ctx.isPhase2Consensus ? _t('orders.consensus_locked_100', '100% Consensus Locked') : (ctx.isPartnerRefused ? _t('orders.consensus_terms_refused', 'Terms Refused') : _t('orders.consensus_pending', 'Consensus Pending'))}
                    </span>
