    window._odCustodyCollapsedState = window._odCustodyCollapsedState || {};
    function toggleCustomServiceCustodyItems(orderId) {
      window._odCustodyCollapsedState = window._odCustodyCollapsedState || {};
      window._odCustodyCollapsedState[orderId] = !window._odCustodyCollapsedState[orderId];
      const body = document.getElementById(`od-custody-body-${orderId}`);
      const chevron = document.getElementById(`od-custody-chevron-${orderId}`);
      if (body) {
        if (window._odCustodyCollapsedState[orderId]) {
          body.classList.add('hidden');
          if (chevron) chevron.classList.add('-rotate-90');
        }
 else {
          body.classList.remove('hidden');
          if (chevron) chevron.classList.remove('-rotate-90');
        }

      }
    }
    window.toggleCustomServiceCustodyItems = toggleCustomServiceCustodyItems;

    function scrollOdAttTrack(idx, direction) {
      const track = document.getElementById(`od-att-track-${idx}`);
      if (!track) return;
      const scrollStep = 280 * direction;
      track.scrollBy({ left: scrollStep, behavior: 'smooth' });
      setTimeout(() => updateOdAttScrollArrows(idx), 220);
    }
    window.scrollOdAttTrack = scrollOdAttTrack;

    function updateOdAttScrollArrows(idx) {
      const track = document.getElementById(`od-att-track-${idx}`);
      const leftBtn = document.getElementById(`od-att-scroll-left-${idx}`);
      const rightBtn = document.getElementById(`od-att-scroll-right-${idx}`);
      if (!track) return;

      const canScroll = track.scrollWidth > track.clientWidth + 5;
      if (!canScroll) {
        if (leftBtn) { leftBtn.classList.add('hidden'); leftBtn.classList.remove('md:flex'); }
        if (rightBtn) { rightBtn.classList.add('hidden'); rightBtn.classList.remove('md:flex'); }
        return;
      }

      const atStart = track.scrollLeft <= 5;
      const atEnd = Math.ceil(track.scrollLeft + track.clientWidth) >= track.scrollWidth - 5;

      if (leftBtn) {
        if (atStart) {
          leftBtn.classList.add('hidden');
          leftBtn.classList.remove('md:flex');
        }
 else {
          leftBtn.classList.remove('hidden');
          leftBtn.classList.add('hidden', 'md:flex');
        }

      }

      if (rightBtn) {
        if (atEnd) {
          rightBtn.classList.add('hidden');
          rightBtn.classList.remove('md:flex');
        }
 else {
          rightBtn.classList.remove('hidden');
          rightBtn.classList.add('hidden', 'md:flex');
        }

      }
    }
    window.updateOdAttScrollArrows = updateOdAttScrollArrows;

