                <span class="font-black text-sm text-slate-900 dark:text-white truncate">
                  ${isHardware ? '📱 ' : '📄 '}${escapeHtml(item.text || item.title || item.item || item.name || _t('orders.untitled_document', 'Untitled Document / Item'))}
                </span>
