        const collector = p.username || order.ownerName || order.owner_username || order.createdBy || _t('orders.cashier_label', 'Cashier');
        const remDisplay = (p.remaining !== null && p.remaining !== undefined) ? formatPrice(p.remaining) : (idx === paymentEvents.length - 1 ? (isFullySettled ? (formatPrice('0') + ' ✓') : formatPrice(remainingDue)) : '---');

