            const costBoundaryPct = totalF > 0 ? Math.min(100, Math.max(0, (costTargetF / totalF) * 100)) : 100;

            const costFillPct = totalF > 0 ? Math.min(costBoundaryPct, Math.max(0, (parseFloat(nextCostClaimed) / totalF) * 100)) : 0;
            const profitFillPct = totalF > 0 ? Math.min(100 - costBoundaryPct, Math.max(0, (parseFloat(nextProfitClaimed) / totalF) * 100)) : 0;

            const isCostSatisfied = exactCompare(nextCostClaimed, costTarget) >= 0;
            const isFull = exactCompare(nextClaimed, totalTarget) >= 0;
            const overallPct = totalF > 0 ? Math.min(100, Math.round((parseFloat(nextClaimed) / totalF) * 100)) : 100;

            let headline = '';
            let statusHtml = '';
