    let _historySnapshotData = null;

    function downloadDataUri(dataUri, fileName) {
      if (!dataUri) return;
      try {
        const link = document.createElement('a');
        link.href = dataUri;
        link.download = fileName || 'attachment';
        document.body.appendChild(link);
        link.click();
        setTimeout(() => {
          try { document.body.removeChild(link); } catch (e) {}
        }
, 100);
      } catch (err) {
        console.error('downloadDataUri failed:', err);
      }
    }
    window.downloadDataUri = downloadDataUri;

    async function downloadCustodyAttachment(orderId, attId, fileName) {
      try {
        let fileData = null;
        let safeName = fileName || 'attachment';

        const res = await apiRequest(`/api/orders/${orderId}/attachments/${attId}/download`).catch(() => null);
        if (res && res.ok && (res.file_data || (res.attachment && res.attachment.file_data))) {
          fileData = res.file_data || res.attachment.file_data;
          safeName = fileName || res.file_name || (res.attachment && res.attachment.file_name) || safeName;
        }
 else {
          const pool = (Array.isArray(window._currentAttachmentsList) ? window._currentAttachmentsList : [])
            .concat((_historySnapshotData && Array.isArray(_historySnapshotData.attachments)) ? _historySnapshotData.attachments : []);
          const match = pool.find(a => (String(a.id) === String(attId) || a.attachment_uid === attId || a.file_name === attId || a.file_name === fileName) && a.file_data);
          if (match) {
            fileData = match.file_data;
            safeName = fileName || match.file_name || safeName;
          }

        }


        if (!fileData) {
          showToast(_t('orders.toast_attachment_data_could_not_be_loaded', 'Attachment data could not be loaded'), 'error');
          return;
        }


        downloadDataUri(fileData, safeName);
      } catch (err) {
        console.error('Failed to download custody attachment:', err);
        showToast(_t('orders.toast_failed_to_download_attachment', 'Failed to download attachment'), 'error');
      }
    }
    window.downloadCustodyAttachment = downloadCustodyAttachment;

    async function previewOrDownloadAttachment(orderId, attId, fileName) {
      try {
        let fileData = null;
        let mime = 'application/octet-stream';
        let safeName = fileName || 'attachment';
        let safeSize = 0;

        const res = await apiRequest(`/api/orders/${orderId}/attachments/${attId}/download`).catch(() => null);
        if (res && res.ok && (res.file_data || (res.attachment && res.attachment.file_data))) {
          fileData = res.file_data || res.attachment.file_data;
          mime = res.mime_type || res.file_type || (res.attachment && (res.attachment.mime_type || res.attachment.file_type)) || mime;
          safeName = fileName || res.file_name || (res.attachment && res.attachment.file_name) || safeName;
          safeSize = res.file_size || (res.attachment && res.attachment.file_size) || 0;
        }
 else {
          const pool = (Array.isArray(window._currentAttachmentsList) ? window._currentAttachmentsList : [])
            .concat((_historySnapshotData && Array.isArray(_historySnapshotData.attachments)) ? _historySnapshotData.attachments : []);
          const match = pool.find(a => (String(a.id) === String(attId) || a.attachment_uid === attId || a.file_name === attId || a.file_name === fileName) && a.file_data);
          if (match) {
            fileData = match.file_data;
            mime = match.mime_type || match.file_type || (match.file_name && /\.pdf$/i.test(match.file_name) ? 'application/pdf' : mime);
            safeName = fileName || match.file_name || safeName;
            safeSize = match.file_size || 0;
          }

        }


        if (!fileData) {
          showToast(_t('orders.toast_attachment_data_could_not_be_loaded', 'Attachment data could not be loaded'), 'error');
          return;
        }


        if (typeof openDocumentPreviewDirect === 'function') {
          openDocumentPreviewDirect(safeName, mime, fileData, safeSize);
          return;
        }

        if (typeof previewOrderAttDirect === 'function') {
          previewOrderAttDirect(safeName, mime, fileData, safeSize);
          return;
        }


        downloadDataUri(fileData, safeName);
      } catch (err) {
        console.error('Failed to preview/download attachment:', err);
        showToast(_t('orders.toast_failed_to_load_attachment_preview', 'Failed to load attachment preview'), 'error');
      }
    }
    window.previewOrDownloadAttachment = previewOrDownloadAttachment;

    async function restoreCustomServiceAttachment(orderId, attId, fileName) {
      const proceed = await showSystemConfirmModal({
        title: _t('history.confirm_restore_att_title', 'Restore Custody Attachment?'),
        message: _t('history.confirm_restore_att_msg', 'Are you sure you want to restore "{name}" back to active custody? This file will be re-added to the custom service checklist.', { name: escapeHtml(fileName) }),
        confirmText: _t('history.btn_restore_to_custody', 'Yes, Restore to Custody'),
        cancelText: _t('common.cancel', 'Cancel'),
        type: 'info'
      });
      if (!proceed) return;

      try {
        const res = await apiRequest(`/api/orders/${orderId}/attachments/${attId}/restore`, {
          method: 'POST'
        }
);

        if (res && res.ok) {
          if (typeof showToast === 'function') showToast(res.message || _t('history.att_restored_success', 'Attachment restored successfully'), 'success');
          await showCustomServiceHistory(orderId, true);
          if (typeof loadOrders === 'function') loadOrders();
        }
 else {
          if (typeof showToast === 'function') showToast(res?.message || _t('history.att_restore_failed', 'Failed to restore attachment'), 'error');
        }

      } catch (err) {
        console.error('Failed to restore attachment:', err);
        if (typeof showToast === 'function') showToast(_t('history.att_restore_failed', 'Failed to restore attachment'), 'error');
      }
    }
    window.restoreCustomServiceAttachment = restoreCustomServiceAttachment;

