      const _t = (k, d, p) => (window.__t ? window.__t(k, d, p) : (window.i18n ? window.i18n.t(k, d, p) : (d !== undefined ? d : k)));
      window._currentHistoryOrderId = orderId;
      window._lastHistoryOrderId = orderId;
      window._currentHistoryIsCustom = isCustomService;

      // ── Always reset compare state when opening any order's history ──────
      _compareMode = false;
      _selectedLogIndices.clear();
      const _toggleBtn = document.getElementById('history-compare-toggle-btn');
