      if (_toggleBtn) { _toggleBtn.classList.remove('bg-indigo-100', 'text-indigo-700', 'border-indigo-300'); _toggleBtn.classList.add('bg-slate-100', 'text-slate-600', 'border-slate-200'); }
      if (_bar) _bar.classList.add('hidden');

