    function syncProductsViewModeUI() {
      const gridBtn = document.getElementById('products-view-grid-btn');
      const tableBtn = document.getElementById('products-view-table-btn');
      const gridContainer = document.getElementById('products-grid');
      const tableContainer = document.getElementById('products-table-container');

      if (productsViewMode === 'grid') {
        if (gridBtn) {
          gridBtn.className = 'h-8 w-8 sm:h-9 sm:w-9 flex items-center justify-center rounded-lg sm:rounded-xl text-xs font-bold transition-all bg-white dark:bg-[#151b26] text-emerald-600 dark:text-emerald-300 shadow-xs cursor-pointer';
        }

        if (tableBtn) {
          tableBtn.className = 'h-8 w-8 sm:h-9 sm:w-9 flex items-center justify-center rounded-lg sm:rounded-xl text-xs font-bold transition-all text-slate-500 dark:text-slate-400 hover:text-slate-800 dark:hover:text-slate-200 cursor-pointer';
        }

        if (gridContainer) gridContainer.classList.remove('hidden');
        if (tableContainer) tableContainer.classList.add('hidden');
      } else {
        if (tableBtn) {
          tableBtn.className = 'h-8 w-8 sm:h-9 sm:w-9 flex items-center justify-center rounded-lg sm:rounded-xl text-xs font-bold transition-all bg-white dark:bg-[#151b26] text-emerald-600 dark:text-emerald-300 shadow-xs cursor-pointer';
        }

        if (gridBtn) {
          gridBtn.className = 'h-8 w-8 sm:h-9 sm:w-9 flex items-center justify-center rounded-lg sm:rounded-xl text-xs font-bold transition-all text-slate-500 dark:text-slate-400 hover:text-slate-800 dark:hover:text-slate-200 cursor-pointer';
        }

        if (gridContainer) gridContainer.classList.add('hidden');
        if (tableContainer) tableContainer.classList.remove('hidden');
      }
    }
    window.syncProductsViewModeUI = syncProductsViewModeUI;

