    // Products Pagination State & Controls (50 per page - Owner Rule)
    let productsCurrentPage = 1;
    const PRODUCTS_PAGE_SIZE = 50;
    window.productsCurrentPage = productsCurrentPage;

    function renderProductsPaginationControls(totalCount, totalPages, currentPage) {
      let container = document.getElementById('products-pagination-container');
      if (!container) return;

      // RULE: Hide bar completely if items <= 50 or totalPages <= 1
      if (!totalCount || totalCount <= PRODUCTS_PAGE_SIZE || totalPages <= 1) {
        container.innerHTML = '';
        container.classList.add('hidden');
        return;
      }
      container.classList.remove('hidden');

      const startItem = (currentPage - 1) * PRODUCTS_PAGE_SIZE + 1;
      const endItem = Math.min(currentPage * PRODUCTS_PAGE_SIZE, totalCount);
      const hasPrev = currentPage > 1;
      const hasNext = currentPage < totalPages;

      const showingText = window.__t ? window.__t('common.pagination_showing', 'Showing') : 'Showing';
      const ofText = window.__t ? window.__t('common.pagination_of', 'of') : 'of';
      const productsText = window.__t ? window.__t('products.kpi_products_label', 'products') : 'products';
      const prevText = window.__t ? window.__t('common.pagination_prev', 'Prev') : 'Prev';
      const nextText = window.__t ? window.__t('common.pagination_next', 'Next') : 'Next';
      const pageText = window.__t ? window.__t('common.pagination_page', 'Page') : 'Page';

      container.innerHTML = `
        <div class="flex items-center gap-2 text-slate-500 dark:text-slate-400 font-semibold text-xs text-center sm:text-left">
          <span>${showingText} <strong class="text-slate-900 dark:text-white font-black">${startItem}–${endItem}</strong> ${ofText} <strong class="text-slate-900 dark:text-white font-black">${totalCount}</strong> ${productsText}</span>
        </div>
        <div class="flex items-center gap-2 select-none justify-center">
          <button type="button" id="products-page-prev-btn" onclick="goToProductsPage(${currentPage - 1})"
            class="min-h-[36px] px-3.5 py-1.5 rounded-xl border flex items-center gap-1.5 text-xs font-bold transition-all ${hasPrev ? 'bg-white dark:bg-slate-800 text-slate-700 dark:text-slate-200 border-slate-200/80 dark:border-white/[0.08] hover:bg-slate-50 dark:hover:bg-slate-700 cursor-pointer shadow-xs active:scale-95' : 'opacity-40 cursor-not-allowed bg-slate-100 dark:bg-slate-900 text-slate-400 border-transparent'}"
            ${!hasPrev ? 'disabled' : ''}>
            <span class="text-sm rtl-flip rtl:rotate-180">←</span><span>${prevText}</span>
          </button>
          <span class="min-h-[36px] px-3 py-1.5 rounded-xl bg-slate-100 dark:bg-white/[0.06] font-black text-xs text-slate-700 dark:text-slate-300 border border-slate-200/60 dark:border-white/[0.06] flex items-center justify-center">
            ${pageText} ${currentPage} ${ofText} ${totalPages}
          </span>
          <button type="button" id="products-page-next-btn" onclick="goToProductsPage(${currentPage + 1})"
            class="min-h-[36px] px-3.5 py-1.5 rounded-xl border flex items-center gap-1.5 text-xs font-bold transition-all ${hasNext ? 'bg-white dark:bg-slate-800 text-slate-700 dark:text-slate-200 border-slate-200/80 dark:border-white/[0.08] hover:bg-slate-50 dark:hover:bg-slate-700 cursor-pointer shadow-xs active:scale-95' : 'opacity-40 cursor-not-allowed bg-slate-100 dark:bg-slate-900 text-slate-400 border-transparent'}"
            ${!hasNext ? 'disabled' : ''}>
            <span>${nextText}</span><span class="text-sm rtl-flip rtl:rotate-180">→</span>
          </button>
        </div>
      `;
    }
    window.renderProductsPaginationControls = renderProductsPaginationControls;

    function goToProductsPage(page) {
      productsCurrentPage = page;
      window.productsCurrentPage = page;
      filterProducts(false);
      const scrollTarget = document.getElementById('products-content-container') || document.getElementById('page-products');
      if (scrollTarget && typeof scrollTarget.scrollIntoView === 'function') {
        scrollTarget.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      }
    }
    window.goToProductsPage = goToProductsPage;

    function filterProducts(resetPage = true) {
      if (resetPage) productsCurrentPage = 1;
      restoreProductsMobileKpiState();
      const products = getProducts() || [];
      const grid = document.getElementById('products-grid');
      const tableBody = document.getElementById('products-table-body');
      if (!grid && !tableBody) return;

      const categoryFilter = document.getElementById('products-category-filter')?.value || 'all';
      const stockFilter = document.getElementById('products-stock-filter')?.value || 'all';
      const userFilter = document.getElementById('products-user-filter')?.value || 'all';
      const sortFilter = document.getElementById('products-sort-filter')?.value || 'name_asc';
      const searchQuery = (document.getElementById('products-search')?.value || '').toLowerCase().trim();

      const clearBtn = document.getElementById('products-search-clear');
      if (clearBtn) {
        if (searchQuery) clearBtn.classList.remove('hidden');
        else clearBtn.classList.add('hidden');
      }

      // 1. Calculate overall KPI metrics with exact math
      let totalProductsCount = 0;
      let inStockCount = 0;
      let lowStockCount = 0;
      let totalValuation = '0';

      products.forEach(p => {
        if (!p.deleted_at && !p.deletedAt) {
          totalProductsCount++;
          const stock = getProductAvailableQuantity(p.__backendId);
          const pVal = getProductInventoryValue(p.__backendId);
          totalValuation = exactAdd(totalValuation, pVal);

          if (exactCompare(String(stock), '0') > 0) {
            inStockCount++;
          }
 else {
            lowStockCount++;
          }

        }

      });

      const kpiCountEl = document.getElementById('products-kpi-count');
      if (kpiCountEl) kpiCountEl.textContent = totalProductsCount;
      const kpiActiveDescEl = document.getElementById('products-kpi-active-desc');
      if (kpiActiveDescEl) kpiActiveDescEl.textContent = `${totalProductsCount} ${window.__t ? window.__t('products.kpi_total_desc', 'catalog items') : 'catalog items'}`;
      const kpiInStockEl = document.getElementById('products-kpi-in-stock-count');
      if (kpiInStockEl) kpiInStockEl.textContent = inStockCount;
      const kpiLowStockEl = document.getElementById('products-kpi-low-stock-count');
      if (kpiLowStockEl) kpiLowStockEl.textContent = lowStockCount;
      const kpiTotalValEl = document.getElementById('products-kpi-total-val');
      if (kpiTotalValEl) kpiTotalValEl.textContent = formatPrice(totalValuation);

      // 2. Filter products list
      let filtered = showDeletedProducts
        ? products.filter(p => !!(p.deleted_at || p.deletedAt))
        : products.filter(p => !(p.deleted_at || p.deletedAt));

      if (categoryFilter && categoryFilter !== 'all') {
        filtered = filtered.filter(p => String(p.categoryId) === String(categoryFilter));
      }

      if (userFilter && userFilter !== 'all') {
        if (userFilter === 'system') {
          filtered = filtered.filter(p => !p.createdBy || String(p.createdBy).toLowerCase() === 'system');
        }
 else {
          filtered = filtered.filter(p => String(p.createdBy || '').toLowerCase() === String(userFilter).toLowerCase());
        }

      }

      if (stockFilter !== 'all') {
        filtered = filtered.filter(p => {
          const stock = getProductAvailableQuantity(p.__backendId);
          if (stockFilter === 'in_stock') return exactCompare(String(stock), '0') > 0;
          if (stockFilter === 'out_of_stock') return exactCompare(String(stock), '0') <= 0;
          if (stockFilter === 'low_stock') {
            const lowThresh = p.stockLowThreshold !== null && p.stockLowThreshold !== undefined ? String(p.stockLowThreshold) : '5';
            return exactCompare(String(stock), '0') > 0 && exactCompare(String(stock), lowThresh) <= 0;
          }

          return true;
        }
);
      }

      if (searchQuery) {
        const cleanQuery = searchQuery.startsWith('#') ? searchQuery.slice(1).trim() : searchQuery;
        filtered = filtered.filter(p =>
          (p.name || '').toLowerCase().includes(searchQuery) ||
          (p.uid && (p.uid.toLowerCase().includes(searchQuery) || p.uid.toLowerCase().includes(cleanQuery) || (`#${p.uid.toLowerCase()}`).includes(searchQuery))) ||
          (p.sku && p.sku.toLowerCase().includes(cleanQuery)) ||
          (p.barcode && p.barcode.toLowerCase().includes(cleanQuery)) ||
          (p.description && p.description.toLowerCase().includes(searchQuery))
        );
      }

      // 3. Sort products
      filtered.sort((a, b) => {
        if (sortFilter === 'name_asc') {
          return (a.name || '').localeCompare(b.name || '');
        }
 else if (sortFilter === 'stock_desc') {
          const stockA = getProductAvailableQuantity(a.__backendId);
          const stockB = getProductAvailableQuantity(b.__backendId);
          return exactCompare(String(stockB), String(stockA));
        }
 else if (sortFilter === 'valuation_desc') {
          const valA = getProductInventoryValue(a.__backendId);
          const valB = getProductInventoryValue(b.__backendId);
          return exactCompare(valB, valA);
        }
 else if (sortFilter === 'newest') {
          const tB = new Date(String(b.createdAt || b.created_at || '').replace(' ', 'T')).getTime() || 0;
          const tA = new Date(String(a.createdAt || a.created_at || '').replace(' ', 'T')).getTime() || 0;
          return tB - tA;
        }

        return 0;
      });

      // 4. Render Empty State or Cards/Table
      if (filtered.length === 0) {
        const emptyHtml = `
          <div class="glass-card rounded-3xl p-12 text-center border border-slate-200 dark:border-slate-800 bg-white/70 dark:bg-slate-900/70 shadow-sm col-span-full w-full">
            <div class="w-16 h-16 rounded-3xl bg-emerald-50 dark:bg-emerald-950/60 border border-emerald-100 dark:border-emerald-800/80 flex items-center justify-center mx-auto mb-4 text-emerald-500">
              <svg class="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4"></path></svg>
            </div>
            <h4 class="text-base font-bold text-slate-800 dark:text-slate-100">${window.__t ? window.__t('products.empty_title', 'No products found') : 'No products found'}</h4>
            <p class="text-xs text-slate-400 dark:text-slate-500 mt-1 max-w-sm mx-auto">${window.__t ? window.__t('products.empty_desc', 'No products match your search keyword or active filter selection.') : 'No products match your search keyword or active filter selection.'}</p>
            <button onclick="showProductModal()" class="mt-4 px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white font-bold text-xs rounded-xl shadow-xs transition-all cursor-pointer">${window.__t ? window.__t('products.empty_btn_create', 'Add New Product') : 'Add New Product'}</button>
          </div>
        `;
        if (grid) grid.innerHTML = emptyHtml;
        if (tableBody) tableBody.innerHTML = `<tr><td colspan="6" class="p-12 text-center">${emptyHtml}</td></tr>`;
        renderProductsPaginationControls(0, 1, 1);
        return;
      }

      // 50 Items Per Page Pagination (Owner Rule)
      const totalFiltered = filtered.length;
      const totalPages = Math.max(1, Math.ceil(totalFiltered / PRODUCTS_PAGE_SIZE));
      if (productsCurrentPage > totalPages) productsCurrentPage = totalPages;
      if (productsCurrentPage < 1) productsCurrentPage = 1;

      const pageStart = (productsCurrentPage - 1) * PRODUCTS_PAGE_SIZE;
      const paginatedProducts = filtered.slice(pageStart, pageStart + PRODUCTS_PAGE_SIZE);

      if (productsViewMode === 'table') {
        if (tableBody) {
          tableBody.innerHTML = paginatedProducts.map(renderProductTableRow).join('');
        }

        if (grid) grid.innerHTML = '';
      } else {
        if (grid) {
          grid.innerHTML = paginatedProducts.map(buildProductCardHtml).join('');
        }

        if (tableBody) tableBody.innerHTML = '';
      }

      renderProductsPaginationControls(totalFiltered, totalPages, productsCurrentPage);
    }

    //     // Reusable Apple/iOS Bento Product Card (With Big Hero Product Image & Obsidian Velvet-Black Surface)
    function buildProductCardHtml(p) {
        const category = getCategoryById(p.categoryId);
        const pColors = getColorStyles(p.color || '#10b981');
        const cColors = category ? getColorStyles(category.color || '#3b82f6') : null;
        const isDeleted = !!(p.deleted_at || p.deletedAt);
        const stock = getProductAvailableQuantity(p.__backendId);
        const valuation = getProductInventoryValue(p.__backendId);
        const pDecimals = p.displayDecimals !== null && p.displayDecimals !== undefined ? p.displayDecimals : null;

        // Big Hero Product Photo or Stylized Visual Box
        const productHero = p.picture
          ? `<img src="${p.picture}" loading="lazy" decoding="async" class="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300" alt="${escapeHtml(p.name)}">`
          : `<div class="w-full h-full flex items-center justify-center" style="${pColors.bg}">
              <svg class="w-16 h-16 text-white/90 drop-shadow-md group-hover:scale-110 transition-transform duration-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4"></path></svg>
             </div>`;

        return `
          <div class="product-card-obsidian overflow-hidden flex flex-col justify-between relative group ${isDeleted ? 'opacity-85 grayscale-[0.3] !border-rose-500/40' : ''}">
            
            <!-- BIG HERO PRODUCT IMAGE (h-48 / aspect-[4/3]) -->
            <div class="relative w-full h-48 flex items-center justify-center overflow-hidden bg-slate-100 dark:bg-[#080b10] border-b border-slate-100 dark:border-white/[0.06]">
              ${productHero}

              <!-- Floating Info Button -->
              <button onclick="showProductDetails('${escapeJsString(p.__backendId)}')"
                class="absolute top-3 right-3 w-8 h-8 rounded-full bg-black/50 hover:bg-black/75 backdrop-blur-md text-white flex items-center justify-center transition-all shadow-md z-10 cursor-pointer active:scale-90" title="${window.__t ? window.__t('products.details_modal_title', 'Product Details & History') : 'Product Details & History'}">
                <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
              </button>

              <!-- Floating Status Badge -->
              ${isDeleted ? `
                <div class="absolute top-3 left-3">
                  <span class="px-2.5 py-0.5 bg-rose-600/90 backdrop-blur-md text-white text-[10px] font-black uppercase tracking-wider rounded-full shadow border border-white/10">${window.__t ? window.__t('common.deleted', 'Deleted') : 'Deleted'}</span>
                </div>
              ` : `
                <div class="absolute top-3 left-3">
                  <span class="px-2.5 py-0.5 bg-black/50 backdrop-blur-md text-white text-[10px] font-bold uppercase tracking-wider rounded-full shadow border border-white/10 flex items-center gap-1.5">
                    <span class="w-2 h-2 rounded-full" style="background-color:${p.color || '#10b981'}"></span>
                    <span>${window.__t ? window.__t('products.card_product_badge', 'Product') : 'Product'}</span>
                  </span>
                </div>
              `}
            </div>

            <!-- Card Body Details -->
            <div class="p-5 flex flex-col flex-1 justify-between">
              <div>
                <!-- Category Theme Badge & Display Decimals Strip -->
                <div class="flex items-center gap-1.5 flex-wrap mb-2">
                  ${category ? `<span class="px-2.5 py-0.5 rounded-lg text-[10px] font-bold truncate max-w-[160px] sm:max-w-[200px]" style="${cColors.badge}" title="${escapeHtml(category.name)}">${escapeHtml(category.name)}</span>` : `<span class="text-[10px] text-slate-400">${window.__t ? window.__t('products.card_no_category', 'No category') : 'No category'}</span>`}
                  ${pDecimals !== null ? `<span class="px-2 py-0.5 rounded-lg text-[10px] font-mono font-bold bg-slate-100 dark:bg-[#080b10] text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-white/[0.08]">${pDecimals} ${window.__t ? window.__t('products.card_decimals_suffix', 'dec') : 'dec'}</span>` : ''}
                  ${exactCompare(String(p.hiddenStock || '0'), '0') > 0 ? `<button type="button" onclick="openReclaimHiddenModal('${escapeJsString(p.__backendId)}')" class="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-lg text-[10px] font-bold bg-amber-500/15 text-amber-600 dark:text-amber-400 border border-amber-500/30 hover:bg-amber-500/25 transition-colors cursor-pointer" title="${window.__t ? window.__t('products.card_reclaim_hidden_title', 'Click to reclaim hidden stock') : 'Click to reclaim hidden stock'}">⊕ ${formatQuantity(p.hiddenStock, 16)} ${window.__t ? window.__t('products.card_hidden_suffix', 'hidden') : 'hidden'}</button>` : ''}
                </div>

                <!-- Product Name & Selling Price Badge Row -->
                <div class="flex items-center justify-between gap-2 mb-2 min-h-[28px]">
                  <h4 class="font-black text-slate-900 dark:text-white text-base truncate flex-1 min-w-0" title="${escapeHtml(p.name)}">
                    ${escapeHtml(p.name)}
                  </h4>
                  ${(p.price && parseFloat(p.price) > 0)
                    ? `<span class="px-2.5 py-0.5 rounded-xl bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 font-mono font-black text-xs sm:text-sm border border-emerald-500/20 shrink-0 tabular-nums shadow-2xs">
                        ${formatPrice(p.price, pDecimals)}
                      </span>`
                    : ''}
                </div>

                <!-- Prominent Full-Width Monospace UID Bar -->
                <div class="mb-3">
                  <button onclick="copyProductUid('${escapeJsString(p.uid || p.__backendId)}', event)" title="${window.__t ? window.__t('products.card_copy_uid_title', 'Click to copy Product UID: #{uid}', { uid: p.uid || p.__backendId }) : `Click to copy Product UID: #${p.uid || p.__backendId}`}"
                    class="w-full flex items-center justify-between px-3 py-1.5 rounded-xl bg-slate-50 hover:bg-emerald-50 hover:text-emerald-600 hover:border-emerald-300 dark:bg-[#080b10] dark:hover:bg-[#080b10] text-slate-700 dark:text-slate-200 font-mono text-xs font-bold transition-all border border-slate-200/90 dark:border-white/[0.08] shadow-[inset_0_1px_0_0_rgba(255,255,255,0.04)] group/uid cursor-pointer active:scale-[0.99]">
                    <div class="flex items-center gap-2 min-w-0">
                      <span class="text-emerald-500 font-black text-sm">#</span>
                      <span class="tracking-wide font-black text-slate-900 dark:text-slate-100 text-xs truncate">${p.uid || p.__backendId}</span>
                    </div>
                    <div class="flex items-center gap-1 text-[10px] text-slate-400 group-hover/uid:text-emerald-500 font-sans font-bold uppercase tracking-wider shrink-0">
                      <span>${window.__t ? window.__t('common.copy', 'Copy') : 'Copy'}</span>
                      <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z"></path></svg>
                    </div>
                  </button>
                </div>

                <!-- Stock & Valuation Micro-Dock -->
                <div class="grid grid-cols-2 gap-2 py-2.5 px-3 mb-3 rounded-2xl bg-slate-50/80 dark:bg-[#080b10] border border-slate-100 dark:border-white/[0.06] shadow-[inset_0_1px_0_0_rgba(255,255,255,0.04)] text-center">
                  <div>
                    <p class="text-[10px] font-extrabold uppercase tracking-wider text-slate-400 dark:text-slate-500">${window.__t ? window.__t('products.card_available_stock', 'Available Stock') : 'Available Stock'}</p>
                    <p class="text-sm sm:text-base font-black ${exactCompare(String(stock), '0') > 0 ? 'text-emerald-600 dark:text-emerald-400' : 'text-slate-400'} mt-0.5 font-mono tabular-nums">${formatQuantity(stock, pDecimals)}</p>
                  </div>
                  <div class="border-l border-slate-200/60 dark:border-white/[0.06]">
                    <p class="text-[10px] font-extrabold uppercase tracking-wider text-slate-400 dark:text-slate-500">${window.__t ? window.__t('products.card_inventory_value', 'Inventory Value') : 'Inventory Value'}</p>
                    <p class="text-sm sm:text-base font-black text-slate-900 dark:text-slate-100 mt-0.5 font-mono tabular-nums">${formatPrice(valuation)}</p>
                  </div>
                </div>

                <!-- Description with Tooltip & 2-Line Ellipsis Clamp -->
                <p class="text-xs text-slate-500 dark:text-slate-400 line-clamp-2 min-h-[32px] mb-3 leading-relaxed overflow-hidden text-ellipsis" title="${p.description ? escapeHtml(p.description) : ''}">${escapeHtml(p.description || (window.__t ? window.__t('products.card_no_desc', 'No description provided for this product.') : 'No description provided for this product.'))}</p>
              </div>

              <div>
                <!-- Creator & Date Footer (Decoupled & Barcode Removed) -->
                <div class="pt-2.5 border-t border-slate-100 dark:border-white/[0.06] text-[11px] text-slate-500 dark:text-slate-400 mb-2.5 flex items-center justify-between" ${p.editedBy ? `title="${window.__t ? window.__t('common.last_edited_tooltip', 'Last edited on ${date} by @${user}', { date: formatDate(p.updatedAt || p.updated_at), user: p.editedBy }) : `Last edited on ${formatDate(p.updatedAt || p.updated_at)} by @${escapeHtml(p.editedBy)}`}"` : ''}>
                  <div class="flex items-center gap-1 min-w-0">
                    <span>${window.__t ? window.__t('common.by_colon', 'By:') : 'By:'}</span>
                    <span class="font-bold text-emerald-600 dark:text-emerald-400 ml-1 truncate">@${escapeHtml(p.createdBy || (window.__t ? window.__t('products.system_user', 'System') : 'System'))}</span>
                    ${p.editedBy ? `<span class="text-[10px] text-slate-400 cursor-help ml-1 shrink-0" title="Edited on ${formatDate(p.updatedAt || p.updated_at)} by @${escapeHtml(p.editedBy)}">✏️</span>` : ''}
                  </div>
                  <div class="flex items-center gap-1.5 shrink-0">
                    <span class="text-slate-400 dark:text-slate-500 font-medium">📅 ${formatDate(p.createdAt || p.created_at || new Date())}</span>
                  </div>
                </div>

                <!-- Action Buttons Dock -->
                <div class="pt-2.5 border-t border-slate-100 dark:border-white/[0.06] flex items-center gap-2">
                  ${!isDeleted ? `
                    <button onclick="editProduct('${escapeJsString(p.__backendId)}')"
                      class="flex-1 h-10 min-h-[40px] sm:min-h-[44px] py-2 px-3 bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-600 dark:text-emerald-400 font-bold text-xs rounded-xl transition-all border border-emerald-500/25 shadow-2xs flex items-center justify-center gap-1.5 cursor-pointer active:scale-95">
                      <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"></path></svg>
                      <span>${window.__t ? window.__t('common.edit', 'Edit') : 'Edit'}</span>
                    </button>
                    ${p.barcode ? `
                      <button onclick="printProductBarcodeLabel('${escapeJsString(p.__backendId)}')" title="${window.__t ? window.__t('products.btn_print_label', 'Print Label') : 'Print Label'}"
                        class="w-10 h-10 min-w-[40px] min-h-[40px] sm:min-w-[44px] sm:min-h-[44px] flex items-center justify-center p-2 bg-indigo-500/10 hover:bg-indigo-500/20 text-indigo-600 dark:text-indigo-400 rounded-xl transition-all border border-indigo-500/25 shadow-2xs cursor-pointer active:scale-95">
                        <svg class="w-4 h-4 pointer-events-none" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4H7v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z"></path></svg>
                      </button>
                    ` : ''}
                    <button onclick="showProductStockSettings('${escapeJsString(p.__backendId)}')" title="${window.__t ? window.__t('products.card_btn_thresholds_title', 'Stock Thresholds') : 'Stock Thresholds'}"
                      class="w-10 h-10 min-w-[40px] min-h-[40px] sm:min-w-[44px] sm:min-h-[44px] flex items-center justify-center p-2 bg-slate-100 hover:bg-slate-200 dark:bg-white/[0.06] dark:hover:bg-white/[0.12] text-slate-600 dark:text-slate-300 rounded-xl transition-all border border-slate-200 dark:border-white/[0.08] shadow-2xs cursor-pointer active:scale-95">
                      <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"></path><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
                    </button>
                    <button onclick="deleteProduct('${escapeJsString(p.__backendId)}')" title="${window.__t ? window.__t('products.card_btn_delete_title', 'Delete Product') : 'Delete Product'}"
                      class="w-10 h-10 min-w-[40px] min-h-[40px] sm:min-w-[44px] sm:min-h-[44px] flex items-center justify-center p-2 bg-rose-500/10 hover:bg-rose-500/20 text-rose-600 dark:text-rose-400 rounded-xl transition-all border border-rose-500/25 shadow-2xs cursor-pointer active:scale-95">
                      <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg>
                    </button>
                  ` : `
                    <button onclick="showRestoreProductModal('${escapeJsString(p.__backendId)}')"
                      class="flex-1 h-10 min-h-[40px] sm:min-h-[44px] py-2 px-3 bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-600 dark:text-emerald-400 font-bold text-xs rounded-xl transition-all border border-emerald-500/25 shadow-2xs flex items-center justify-center gap-1.5 cursor-pointer active:scale-95">
                      <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path></svg>
                      <span>${window.__t ? window.__t('products.card_btn_restore', 'Restore Product') : 'Restore Product'}</span>
                    </button>
                  `}
                </div>
              </div>

            </div>
          </div>
        `;
    }

    function renderProductTableRow(p) {
      const category = getCategoryById(p.categoryId);
      const cColors = category ? getColorStyles(category.color || '#3b82f6') : null;
      const isDeleted = !!(p.deleted_at || p.deletedAt);
      const stock = getProductAvailableQuantity(p.__backendId);
      const valuation = getProductInventoryValue(p.__backendId);
      const pDecimals = p.displayDecimals !== null && p.displayDecimals !== undefined ? p.displayDecimals : null;

      return `
        <tr class="hover:bg-slate-50/80 dark:hover:bg-white/[0.04] transition-colors ${isDeleted ? 'opacity-75 bg-rose-500/10' : ''}">
          <!-- Product & UID -->
          <td class="px-5 py-4 border-r border-slate-100 dark:border-white/[0.06]">
            <div class="flex items-center gap-3">
              <div class="w-10 h-10 rounded-xl flex items-center justify-center shrink-0 overflow-hidden shadow-xs border border-slate-200 dark:border-white/[0.08] bg-slate-100 dark:bg-[#080b10]">
                ${p.picture ? `<img src="${p.picture}" class="w-full h-full object-cover" alt="${escapeHtml(p.name)}">` : `<svg class="w-5 h-5 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4"></path></svg>`}
              </div>
              <div class="min-w-0">
                <div class="flex items-center gap-2">
                  <p class="font-black text-slate-900 dark:text-white text-xs truncate">@${escapeHtml(p.name)}</p>
                  ${(p.price && parseFloat(p.price) > 0)
                    ? `<span class="px-2 py-0.5 rounded-lg bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 font-mono font-bold text-[10px] border border-emerald-500/20 shrink-0 tabular-nums">
                        ${formatPrice(p.price, pDecimals)}
                      </span>`
                    : ''}
                </div>
                <p class="font-mono text-[11px] text-emerald-600 dark:text-emerald-400 font-bold tracking-tight mt-0.5">#${p.uid || p.__backendId}</p>
              </div>
            </div>
          </td>

          <!-- Category & Decimals -->
          <td class="px-5 py-4 border-r border-slate-100 dark:border-white/[0.06] text-xs">
            <div class="flex items-center gap-1.5 flex-wrap">
              ${category ? `<span class="px-2.5 py-0.5 rounded-lg text-[10px] font-bold" style="${cColors.badge}">${escapeHtml(category.name)}</span>` : `<span class="text-slate-400 italic">${window.__t ? window.__t('products.card_no_category', 'No category') : 'No category'}</span>`}
              ${pDecimals !== null ? `<span class="px-2.5 py-0.5 rounded-lg text-[10px] font-mono font-bold bg-slate-100 dark:bg-[#080b10] text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-white/[0.08]">${pDecimals} ${window.__t ? window.__t('products.card_decimals_suffix', 'dec') : 'dec'}</span>` : ''}
            </div>
          </td>

          <!-- Available Stock -->
          <td class="px-5 py-4 border-r border-slate-100 dark:border-white/[0.06] text-center">
            <span class="px-2.5 py-1 rounded-full text-xs font-black font-mono tabular-nums ${
              exactCompare(String(stock), '0') > 0 ? 'bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 border border-emerald-500/30' : 'bg-slate-100 dark:bg-white/[0.06] text-slate-500 dark:text-slate-400 border border-slate-200 dark:border-white/[0.08]'
            }
">${formatQuantity(stock, pDecimals)} ${window.__t ? window.__t('products.units', 'Units') : 'Units'}</span>
          </td>

          <!-- Inventory Valuation -->
          <td class="px-5 py-4 border-r border-slate-100 dark:border-white/[0.06] text-center">
            <span class="font-black font-mono tabular-nums text-slate-900 dark:text-slate-100 text-xs">${formatPrice(valuation)}</span>
          </td>

          <!-- Status & Creator -->
          <td class="px-5 py-4 border-r border-slate-100 dark:border-white/[0.06] text-xs">
            <p class="font-bold text-slate-800 dark:text-slate-200">@${escapeHtml(p.createdBy || (window.__t ? window.__t('products.system_user', 'System') : 'System'))}</p>
            <p class="text-[10px] text-slate-400 mt-0.5">📅 ${formatDate(p.createdAt || p.created_at || new Date())}${p.barcode ? ' · #' + escapeHtml(p.barcode) : ''}</p>
          </td>

          <!-- Actions -->
          <td class="px-5 py-4 text-right rtl:text-left">
            <div class="flex items-center justify-end rtl:justify-start gap-1.5">
              <button onclick="showProductDetails('${escapeJsString(p.__backendId)}')" title="${window.__t ? window.__t('products.details_modal_title', 'Product Details') : 'Product Details'}"
                class="w-8 h-8 sm:w-9 sm:h-9 flex items-center justify-center p-1.5 bg-slate-100 hover:bg-slate-200 dark:bg-white/[0.06] dark:hover:bg-white/[0.12] text-slate-600 dark:text-slate-300 rounded-xl transition-all border border-slate-200 dark:border-white/[0.08] cursor-pointer active:scale-95">
                <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
              </button>
              ${!isDeleted ? `
                <button onclick="editProduct('${escapeJsString(p.__backendId)}')" title="${window.__t ? window.__t('products.btn_edit', 'Edit Product') : 'Edit Product'}"
                  class="w-8 h-8 sm:w-9 sm:h-9 flex items-center justify-center p-1.5 bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-600 dark:text-emerald-400 rounded-xl transition-all border border-emerald-500/25 cursor-pointer active:scale-95">
                  <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"></path></svg>
                </button>
                ${p.barcode ? `
                  <button onclick="printProductBarcodeLabel('${escapeJsString(p.__backendId)}')" title="${window.__t ? window.__t('products.btn_print_label', 'Print Label') : 'Print Label'}"
                    class="w-8 h-8 sm:w-9 sm:h-9 flex items-center justify-center p-1.5 bg-indigo-500/10 hover:bg-indigo-500/20 text-indigo-600 dark:text-indigo-400 rounded-xl transition-all border border-indigo-500/25 cursor-pointer active:scale-95">
                    <svg class="w-4 h-4 pointer-events-none" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4H7v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z"></path></svg>
                  </button>
                ` : ''}
                <button onclick="showProductStockSettings('${escapeJsString(p.__backendId)}')" title="${window.__t ? window.__t('products.card_btn_thresholds_title', 'Stock Thresholds') : 'Stock Thresholds'}"
                  class="w-8 h-8 sm:w-9 sm:h-9 flex items-center justify-center p-1.5 bg-slate-100 hover:bg-slate-200 dark:bg-white/[0.06] dark:hover:bg-white/[0.12] text-slate-600 dark:text-slate-300 rounded-xl transition-all border border-slate-200 dark:border-white/[0.08] cursor-pointer active:scale-95">
                  <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"></path><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
                </button>
                <button onclick="deleteProduct('${escapeJsString(p.__backendId)}')" title="${window.__t ? window.__t('products.card_btn_delete_title', 'Delete Product') : 'Delete Product'}"
                  class="w-8 h-8 sm:w-9 sm:h-9 flex items-center justify-center p-1.5 bg-rose-500/10 hover:bg-rose-500/20 text-rose-600 dark:text-rose-400 rounded-xl transition-all border border-rose-500/25 cursor-pointer active:scale-95">
                  <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg>
                </button>
              ` : `
                <button onclick="showRestoreProductModal('${escapeJsString(p.__backendId)}')" title="${window.__t ? window.__t('products.card_btn_restore', 'Restore Product') : 'Restore Product'}"
                  class="w-8 h-8 sm:w-9 sm:h-9 flex items-center justify-center p-1.5 bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-600 dark:text-emerald-400 rounded-xl transition-all border border-emerald-500/25 cursor-pointer active:scale-95">
                  <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path></svg>
                </button>
              `}
            </div>
          </td>
        </tr>
      `;
    }
    window.renderProductTableRow = renderProductTableRow;

    let pendingRestoreProductId = null;

    function showRestoreProductModal(id) {
      const product = productsCache.find(d => d.__backendId === id);
      if (!product) return;
      pendingRestoreProductId = id;
      document.getElementById('restore-product-name').textContent = product.name;
      document.getElementById('restore-product-reason').value = '';
      const modal = document.getElementById('restore-product-modal');
      if (modal) {
        if (typeof ModalManager !== 'undefined' && typeof ModalManager.bringToFront === 'function') {
          ModalManager.bringToFront(modal);
        }

        modal.classList.remove('hidden');
      }
    }
    window.showRestoreProductModal = showRestoreProductModal;

    function closeRestoreProductModal() {
      const modal = document.getElementById('restore-product-modal');
      if (modal) {
        if (typeof ModalManager !== 'undefined' && typeof ModalManager.resetZIndex === 'function') {
          ModalManager.resetZIndex(modal);
        }

        modal.classList.add('hidden');
      }
      pendingRestoreProductId = null;
    }
    window.closeRestoreProductModal = closeRestoreProductModal;

    async function confirmRestoreProduct(e) {
      if (e && e.preventDefault) e.preventDefault();
      if (!pendingRestoreProductId) return;

      const reason = (document.getElementById('restore-product-reason').value || '').trim();
      if (!reason) {
        showToast(window.__t ? window.__t('products.restore_reason_required', 'Please provide a reason for restoration') : 'Please provide a reason for restoration');
        return;
      }

      const btn = document.getElementById('confirm-restore-product-btn');
      if (btn) {
        btn.disabled = true;
        btn.textContent = window.__t ? window.__t('products.restore_btn_restoring', 'Restoring...') : 'Restoring...';
      }

      try {
        await apiRequest(`/api/products/${pendingRestoreProductId}/restore`, {
          method: 'POST',
          body: JSON.stringify({ restore_reason: reason })
        }
);
        showToast(window.__t ? window.__t('products.restore_success', 'Product restored successfully') : 'Product restored successfully');
        closeRestoreProductModal();
        if (typeof closeProductDetailsModal === 'function') closeProductDetailsModal();
        await loadAllData();
      } catch (err) {
        showToast((window.__t ? window.__t('products.restore_failed', 'Failed to restore product: ') : 'Failed to restore product: ') + (err.message || ''));
      } finally {
        if (btn) {
          btn.disabled = false;
          btn.textContent = window.__t ? window.__t('products.restore_btn_confirm', 'Confirm Restore') : 'Confirm Restore';
        }

      }
    }
    window.confirmRestoreProduct = confirmRestoreProduct;

    function clearProductFilters() {
      const catFilter = document.getElementById('products-category-filter');
      if (catFilter) catFilter.value = 'all';
      const usrFilter = document.getElementById('products-user-filter');
      if (usrFilter) usrFilter.value = 'all';
      const searchEl = document.getElementById('products-search');
      if (searchEl) searchEl.value = '';
      filterProducts();
      showToast(window.__t ? window.__t('products.filters_cleared', 'Product filters cleared') : 'Product filters cleared');
    }
    window.clearProductFilters = clearProductFilters;

    function setProductColorPreset(hex) {
      if (!hex) return;
      const cleanHex = hex.startsWith('#') ? hex : '#' + hex;
      const picker = document.getElementById('product-color-picker');
      const hexInput = document.getElementById('product-color-hex');
      if (picker) picker.value = cleanHex;
      if (hexInput) hexInput.value = cleanHex.toUpperCase();
    }
    window.setProductColorPreset = setProductColorPreset;

    function toggleProductInitialStock() {
      const content = document.getElementById('product-initial-stock-content');
      const icon = document.getElementById('product-initial-stock-btn-icon');
      const text = document.getElementById('product-initial-stock-btn-text');
      const editId = document.getElementById('product-edit-id')?.value;
      if (!content) return;
      const isHidden = content.classList.contains('hidden');
      if (isHidden) {
        content.classList.remove('hidden');
        if (icon) icon.textContent = '−';
        if (text) text.textContent = window.__t ? window.__t('products.btn_hide_stock', 'Hide Stock') : 'Hide Stock';
      } else {
        content.classList.add('hidden');
        if (icon) icon.textContent = '+';
        if (text) {
          text.textContent = editId 
            ? (window.__t ? window.__t('products.btn_restock', 'Restock') : 'Restock')
            : (window.__t ? window.__t('products.lbl_opening_stock', 'Opening Stock') : 'Opening Stock');
        }

      }
    }
    window.toggleProductInitialStock = toggleProductInitialStock;

    function updateInitialStockValuation() {
      const qtyInput = document.getElementById('product-initial-qty');
      const costInput = document.getElementById('product-initial-cost');
      const valBadge = document.getElementById('product-initial-total-val');
      if (!valBadge) return;

      const qty = (qtyInput?.value || '').trim();
      const cost = (costInput?.value || '').trim();

      if (!qty || !cost || isNaN(Number(qty)) || isNaN(Number(cost)) || Number(qty) <= 0 || Number(cost) <= 0) {
        valBadge.textContent = '0.00 ' + (config.currency_symbol || 'DZD');
        return;
      }

      try {
        const total = typeof exactMultiply === 'function' ? exactMultiply(qty, cost) : String(Number(qty) * Number(cost));
        valBadge.textContent = (typeof formatNumber === 'function' ? formatNumber(total, 2) : Number(total).toFixed(2)) + ' ' + (config.currency_symbol || 'DZD');
      } catch (e) {
        valBadge.textContent = '0.00 ' + (config.currency_symbol || 'DZD');
      }
    }
    window.updateInitialStockValuation = updateInitialStockValuation;

    function setProductDecimalPreset(n) {
      const input = document.getElementById('product-display-decimals');
      if (input) {
        input.value = n;
        input.dispatchEvent(new Event('input', { bubbles: true }));
        input.dispatchEvent(new Event('change', { bubbles: true }));
      }
    }
    window.setProductDecimalPreset = setProductDecimalPreset;

    // ═══════════════════════════════════════════════════════════════════════════
    // ── Pure Vector SVG Barcode & QR Code Engine (Zero External Dependencies) ──
    // ═══════════════════════════════════════════════════════════════════════════
    const BarcodeVectorEngine = {
      // ISO/IEC 15417 Code 128 Patterns (Indices 0..106)
      patterns: [
        '212222','222122','222221','121223','121322','131222','122213','122312','132212','221213',
        '221312','231212','112232','122132','122231','113222','123122','123221','223211','221132',
        '221231','213212','223112','312131','311222','321122','321221','312212','322112','322211',
        '212123','212321','232121','111323','131123','131321','112313','132113','132311','211313',
        '231113','231311','112133','112331','132131','113123','113321','133121','313121','211331',
        '231131','213113','213311','213131','311123','311321','331121','312113','312311','332111',
        '314111','221411','431111','111224','111422','121124','121421','141122','141221','112214',
        '112412','122114','122411','142112','142211','241211','221114','413111','241112','134111',
        '111242','121142','121241','114212','124112','124211','411212','421112','421211','212141',
        '214121','412121','111143','111341','131141','114113','114311','411113','411311','113141',
        '114131','311141','411131',
        '211412', // 103: Start A
        '211214', // 104: Start B (Alphanumeric ASCII 32..126)
        '211232', // 105: Start C (Double density numeric)
        '2331112' // 106: Stop (7 elements, sums to 13)
      ],

      /**
       * Generates crisp vector SVG markup for Code 128 (Subset B)
       */
      renderCode128Svg(text, options = {}) {
        if (!text || typeof text !== 'string') return '';
        const cleanText = text.trim();
        if (!cleanText) return '';

        // Validate ASCII 32..126
        for (let i = 0; i < cleanText.length; i++) {
          const charCode = cleanText.charCodeAt(i);
          if (charCode < 32 || charCode > 126) {
            return `<div class="p-2 text-xs text-rose-500 font-bold text-center">Invalid barcode characters</div>`;
          }
        }

        const moduleWidth = options.moduleWidth || 2;
        const barHeight = options.barHeight || 54;
        const quietZone = options.quietZone !== undefined ? options.quietZone : 10;
        const showText = options.showText !== false;
        const fontSize = options.fontSize || 12;

        const startB = 104;
        let checksum = startB;
        const codes = [startB];

        for (let i = 0; i < cleanText.length; i++) {
          const val = cleanText.charCodeAt(i) - 32;
          codes.push(val);
          checksum += val * (i + 1);
        }
        codes.push(checksum % 103);
        codes.push(106); // Stop symbol

        let currentModule = quietZone;
        let pathData = '';

        for (const code of codes) {
          const pattern = this.patterns[code];
          if (!pattern) continue;
          for (let j = 0; j < pattern.length; j++) {
            const width = parseInt(pattern[j], 10);
            if (j % 2 === 0) {
              // Black bar: SVG path rectangle slice
              pathData += `M${currentModule * moduleWidth},4h${width * moduleWidth}v${barHeight}h-${width * moduleWidth}z`;
            }
            currentModule += width;
          }
        }

        const totalModules = currentModule + quietZone;
        const totalWidth = totalModules * moduleWidth;
        const totalHeight = showText ? (barHeight + fontSize + 16) : (barHeight + 8);

        let textElement = '';
        if (showText) {
          const textY = barHeight + fontSize + 8;
          textElement = `<text x="${totalWidth / 2}" y="${textY}" text-anchor="middle" font-family="ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace" font-size="${fontSize}" font-weight="bold" fill="#0f172a" letter-spacing="1.5">${escapeHtml(cleanText)}</text>`;
        }

        return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${totalWidth} ${totalHeight}" width="100%" height="100%" style="max-width:100%; height:auto; display:block; margin:0 auto;" shape-rendering="crispEdges">
          <rect width="100%" height="100%" fill="#ffffff" rx="6" />
          <path d="${pathData}" fill="#000000" />
          ${textElement}
        </svg>`;
      },

      /**
       * Renders 2D QR Code using the application's built-in QRCode engine
       */
      renderQrCode(containerEl, text, size = 110) {
        if (!containerEl) return;
        containerEl.innerHTML = '';
        if (typeof QRCode !== 'undefined') {
          try {
            const mLevel = (QRCode.CorrectLevel && QRCode.CorrectLevel.M !== undefined) ? QRCode.CorrectLevel.M : 0;
            new QRCode(containerEl, {
              text: text,
              width: size,
              height: size,
              colorDark: '#000000',
              colorLight: '#ffffff',
              correctLevel: mLevel
            });
            const canvas = containerEl.querySelector('canvas');
            if (canvas) {
              canvas.style.display = 'block';
              canvas.style.margin = '0 auto';
              canvas.style.borderRadius = '6px';
            }
            const img = containerEl.querySelector('img');
            if (img) {
              img.style.display = 'block';
              img.style.margin = '0 auto';
              img.style.borderRadius = '6px';
            }
          } catch (e) {
            console.error('QR code render error:', e);
          }
        }
      },

      /**
       * Universal Dispatcher with Empty State Handling
       */
      renderPreview(containerEl, text, type = 'CODE128') {
        if (!containerEl) return;
        const clean = (text || '').trim();

        if (!clean) {
          containerEl.innerHTML = `
            <div class="flex flex-col items-center justify-center py-5 px-3 text-slate-400 select-none">
              <svg class="w-7 h-7 mb-1.5 opacity-40" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.5" d="M12 4v1m6 11h2m-6 0h-2v4m0-11v3m0 0h.01M12 12h4.01M16 20h4M4 12h4m12 0h.01M5 8h2a1 1 0 001-1V5a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1zm12 0h2a1 1 0 001-1V5a1 1 0 00-1-1h-2a1 1 0 00-1 1v2a1 1 0 001 1zM5 20h2a1 1 0 001-1v-2a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1z"></path></svg>
              <span class="text-xs font-semibold">${window.__t ? window.__t('products.barcode_preview_empty', 'Enter or generate a barcode to preview') : 'Enter or generate a barcode to preview'}</span>
            </div>`;
          return;
        }

        if (type === 'QR') {
          this.renderQrCode(containerEl, clean, 110);
        } else {
          containerEl.innerHTML = this.renderCode128Svg(clean);
        }
      }
    };
    window.BarcodeVectorEngine = BarcodeVectorEngine;

    // ── Barcode Collision Check & Generation ──
    function getConflictingBarcodeProduct(code, currentProductId = null) {
      if (!code || typeof code !== 'string') return null;
      const target = code.trim().toUpperCase();
      if (!target) return null;

      const currentIdStr = currentProductId ? String(currentProductId) : null;

      if (Array.isArray(productsCache)) {
        for (const p of productsCache) {
          const pId = String(p.__backendId || p.id);
          if (currentIdStr && pId === currentIdStr) continue;

          // Primary barcode check
          if (p.barcode && String(p.barcode).trim().toUpperCase() === target) {
            return p;
          }

          // Secondary barcodes check (relational product_barcodes)
          const secondary = p.secondary_barcodes || p.barcodes || p.secondaryBarcodes;
          if (Array.isArray(secondary)) {
            for (const sb of secondary) {
              const val = typeof sb === 'string' ? sb : (sb.barcode_value || sb.barcode);
              if (val && String(val).trim().toUpperCase() === target) {
                return p;
              }
            }
          }
        }
      }

      if (window.barcodeToProductMap && window.barcodeToProductMap instanceof Map) {
        const entry = window.barcodeToProductMap.get(target);
        if (entry) {
          const entryId = String(entry.product_id || entry.productId || entry.__backendId || entry.id);
          if (!currentIdStr || entryId !== currentIdStr) {
            return entry;
          }
        }
      }

      return null;
    }
    window.getConflictingBarcodeProduct = getConflictingBarcodeProduct;

    function isBarcodeTaken(code, currentProductId = null) {
      return !!getConflictingBarcodeProduct(code, currentProductId);
    }
    window.isBarcodeTaken = isBarcodeTaken;

    function generateProductBarcode(customPrefix = null) {
      let prefix = customPrefix;
      if (!prefix) {
        const prefixInput = document.getElementById('product-barcode-prefix');
        if (prefixInput && prefixInput.value.trim()) {
          prefix = prefixInput.value.trim();
        }
      }
      if (!prefix) {
        prefix = (typeof config !== 'undefined' && config.barcode_prefix)
          ? config.barcode_prefix
          : (window.config?.barcode_prefix || 'PHN');
      }
      prefix = String(prefix).replace(/[^A-Za-z0-9]/g, '').toUpperCase().slice(0, 6) || 'PHN';

      const editId = document.getElementById('product-edit-id')?.value || null;

      let candidate = '';
      let attempts = 0;
      const maxAttempts = 50;

      do {
        const timeHex = Date.now().toString(16).toUpperCase().slice(-4);
        const randNum = Math.floor(100 + Math.random() * 900);
        candidate = `${prefix}-${timeHex}-${randNum}`;
        attempts++;
      } while (isBarcodeTaken(candidate, editId) && attempts < maxAttempts);

      if (isBarcodeTaken(candidate, editId)) {
        const cryptoEntropy = Math.floor(Math.random() * 0xFFFF).toString(16).toUpperCase().padStart(4, '0');
        candidate = `${prefix}-${Date.now().toString(36).toUpperCase()}-${cryptoEntropy}`;
      }

      return candidate;
    }
    window.generateProductBarcode = generateProductBarcode;

    function triggerProductBarcodeGenerate() {
      const barcodeInput = document.getElementById('product-barcode-input');
      if (!barcodeInput) return;
      const newBarcode = generateProductBarcode();
      barcodeInput.value = newBarcode;
      onProductBarcodeInput(newBarcode);
      showToast(window.__t ? window.__t('products.toast_barcode_generated', 'New collision-free barcode generated') : 'New collision-free barcode generated', 'default');
    }
    window.triggerProductBarcodeGenerate = triggerProductBarcodeGenerate;

    // ── Product Modal Barcode Controls ──
    function toggleProductBarcodeControls(isChecked) {
      const container = document.getElementById('product-barcode-controls-container');
      const statusPill = document.getElementById('product-barcode-status-pill');
      const statusDot = document.getElementById('product-barcode-status-dot');
      const statusText = document.getElementById('product-barcode-status-text');
      const barcodeInput = document.getElementById('product-barcode-input');
      const prefixInput = document.getElementById('product-barcode-prefix');

      if (isChecked) {
        if (container) container.classList.remove('hidden');
        if (statusPill) {
          statusPill.className = 'inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full text-[10px] font-bold bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border border-emerald-500/20 transition-all';
        }
        if (statusDot) statusDot.className = 'w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse';
        if (statusText) statusText.textContent = window.__t ? window.__t('products.barcode_status_active', 'Active') : 'Active';

        if (prefixInput && !prefixInput.value.trim()) {
          prefixInput.value = (typeof config !== 'undefined' && config.barcode_prefix) ? config.barcode_prefix : 'PHN';
        }

        if (barcodeInput && !barcodeInput.value.trim()) {
          barcodeInput.value = generateProductBarcode();
        }
        renderProductModalBarcodePreview();
      } else {
        if (container) container.classList.add('hidden');
        if (statusPill) {
          statusPill.className = 'inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full text-[10px] font-bold bg-slate-200/60 dark:bg-white/[0.06] text-slate-500 dark:text-slate-400 border border-slate-300/40 dark:border-white/[0.06] transition-all';
        }
        if (statusDot) statusDot.className = 'w-1.5 h-1.5 rounded-full bg-slate-400';
        if (statusText) statusText.textContent = window.__t ? window.__t('products.barcode_status_disabled', 'Disabled') : 'Disabled';
      }
    }
    window.toggleProductBarcodeControls = toggleProductBarcodeControls;

    function onProductBarcodeTypeChange() {
      const typeSelect = document.getElementById('product-barcode-type');
      const pill = document.getElementById('product-barcode-preview-pill');
      const type = typeSelect ? typeSelect.value : 'CODE128';
      if (pill) pill.textContent = type;
      renderProductModalBarcodePreview();
    }
    window.onProductBarcodeTypeChange = onProductBarcodeTypeChange;

    let _barcodePreviewDebounceTimer = null;

    function onProductBarcodeInput(val) {
      if (_barcodePreviewDebounceTimer) {
        clearTimeout(_barcodePreviewDebounceTimer);
      }
      _barcodePreviewDebounceTimer = setTimeout(() => {
        // If user changed barcode text while in note editing mode, check if it still matches an existing code
        if (window._selectedEditingBarcode) {
          const cleanVal = (val || '').trim().toUpperCase();
          const matchesCurrent = window._selectedEditingBarcode.code.toUpperCase() === cleanVal;
          if (!matchesCurrent) {
            const matchesPrimary = window._registeredPrimaryBarcode && (window._registeredPrimaryBarcode.barcode_value || '').toUpperCase() === cleanVal;
            const matchesSec = currentProductSecondaryBarcodes.some(b => (b.barcode_value || b.barcode || '').toUpperCase() === cleanVal);
            if (!matchesPrimary && !matchesSec) {
              // Code no longer exists in registered deck: unlock inputs and exit editing mode!
              clearBarcodeNoteEditingSelection();
            }
          }
        }
        renderProductModalBarcodePreview();
      }, 50);
    }
    window.onProductBarcodeInput = onProductBarcodeInput;

    function renderProductModalBarcodePreview() {
      const input = document.getElementById('product-barcode-input');
      const typeSelect = document.getElementById('product-barcode-type');
      const target = document.getElementById('product-barcode-svg-target');
      const placeholder = document.getElementById('product-barcode-empty-placeholder');
      const feedback = document.getElementById('product-barcode-feedback');
      const editId = document.getElementById('product-edit-id')?.value || null;

      if (!input || !target) return;
      const val = input.value.trim();
      const type = typeSelect ? typeSelect.value : 'CODE128';

      if (!val) {
        target.innerHTML = '';
        if (placeholder) placeholder.classList.remove('hidden');
        if (feedback) feedback.classList.add('hidden');
        return;
      }

      if (placeholder) placeholder.classList.add('hidden');
      BarcodeVectorEngine.renderPreview(target, val, type);

      if (feedback) {
        const conflict = getConflictingBarcodeProduct(val, editId);
        if (conflict) {
          const prodName = escapeHtml(conflict.name || 'Product');
          const prodUid = escapeHtml(conflict.uid || conflict.__backendId || conflict.id);
          feedback.className = 'mt-1.5 text-[11px] font-bold text-amber-600 dark:text-amber-400 flex items-center gap-1.5';
          feedback.innerHTML = `<svg class="w-3.5 h-3.5 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 9v2m0 4h.01M5.07 19h13.86c1.54 0 2.5-1.67 1.73-3L13.73 4a2 2 0 00-3.46 0L3.34 16c-.77 1.33.19 3 1.73 3z"/></svg> <span>${window.__t ? window.__t('products.barcode_already_assigned_to', 'Barcode already assigned to {name} (#{uid})', { name: prodName, uid: prodUid }) : `Barcode already assigned to ${prodName} (#${prodUid})`}</span>`;
          feedback.classList.remove('hidden');
        } else {
          feedback.className = 'mt-1.5 text-[11px] font-bold text-emerald-600 dark:text-emerald-400 flex items-center gap-1.5';
          feedback.innerHTML = `<svg class="w-3.5 h-3.5 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7"/></svg> <span>${window.__t ? window.__t('products.barcode_unique_available', 'Barcode is unique & available') : 'Barcode is unique & available'}</span>`;
          feedback.classList.remove('hidden');
        }
      }
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // MISSION 52 PHASE 3.5: MULTI-BARCODE & STUDIO BATCH PRINTING CONTROLLER
    // ═══════════════════════════════════════════════════════════════════════════
    let currentProductSecondaryBarcodes = [];
    window._registeredPrimaryBarcode = null;
    window._productPrimaryBarcodeTag = '';
    window._selectedEditingBarcode = null;

    function selectBarcodeForNoteEditing(codeVal, isPrimary) {
      if (!codeVal) return;
      window._selectedEditingBarcode = { code: codeVal, isPrimary: !!isPrimary };

      // Resolve current note/tag
      let currentNote = '';
      if (isPrimary) {
        currentNote = (window._registeredPrimaryBarcode ? window._registeredPrimaryBarcode.label_tag : '') || window._productPrimaryBarcodeTag || '';
      } else {
        const item = currentProductSecondaryBarcodes.find(b => (b.barcode_value || b.barcode || '').toUpperCase() === codeVal.toUpperCase());
        if (item) currentNote = item.label_tag || item.label || '';
      }

      // Populate inputs
      const barcodeInput = document.getElementById('product-barcode-input');
      const aliasLabel = document.getElementById('product-alias-label');
      const prefixInput = document.getElementById('product-barcode-prefix');
      const typeSelect = document.getElementById('product-barcode-type');
      const generateBtn = document.getElementById('product-barcode-generate-btn');
      const banner = document.getElementById('product-barcode-editing-banner');
      const bannerCode = document.getElementById('product-barcode-editing-code-val');
      const addBtn = document.getElementById('product-alias-add-btn');

      if (barcodeInput) {
        barcodeInput.value = codeVal;
        barcodeInput.readOnly = true;
        barcodeInput.classList.add('bg-slate-100/70', 'dark:bg-white/[0.04]', 'cursor-not-allowed', 'opacity-90');
        renderProductModalBarcodePreview();
      }

      if (aliasLabel) {
        aliasLabel.value = currentNote;
        aliasLabel.focus();
        aliasLabel.select();
      }

      // Lock prefix, type, and generate button while editing note of existing code
      if (prefixInput) {
        prefixInput.disabled = true;
        prefixInput.classList.add('cursor-not-allowed', 'opacity-50');
      }
      if (typeSelect) {
        typeSelect.disabled = true;
        typeSelect.classList.add('cursor-not-allowed', 'opacity-50');
      }
      if (generateBtn) {
        generateBtn.disabled = true;
        generateBtn.classList.add('cursor-not-allowed', 'opacity-50', 'pointer-events-none');
      }

      // Show banner
      if (banner) {
        if (bannerCode) bannerCode.textContent = codeVal;
        banner.classList.remove('hidden');
      }

      // Update Add button into Update Note button
      if (addBtn) {
        const btnText = window.__t ? window.__t('products.btn_update_note', 'Update Note') : 'Update Note';
        addBtn.innerHTML = `
          <span class="text-indigo-400 font-bold">✏️</span>
          <span data-i18n="products.btn_update_note">${btnText}</span>
        `;
        addBtn.classList.remove('bg-slate-900', 'hover:bg-black');
        addBtn.classList.add('bg-indigo-600', 'hover:bg-indigo-700');
      }

      renderProductBarcodesList();
    }
    window.selectBarcodeForNoteEditing = selectBarcodeForNoteEditing;

    function clearBarcodeNoteEditingSelection() {
      window._selectedEditingBarcode = null;

      const barcodeInput = document.getElementById('product-barcode-input');
      const prefixInput = document.getElementById('product-barcode-prefix');
      const typeSelect = document.getElementById('product-barcode-type');
      const generateBtn = document.getElementById('product-barcode-generate-btn');
      const banner = document.getElementById('product-barcode-editing-banner');
      const addBtn = document.getElementById('product-alias-add-btn');

      if (barcodeInput) {
        barcodeInput.readOnly = false;
        barcodeInput.classList.remove('bg-slate-100/70', 'dark:bg-white/[0.04]', 'cursor-not-allowed', 'opacity-90');
      }

      if (prefixInput) {
        prefixInput.disabled = false;
        prefixInput.classList.remove('cursor-not-allowed', 'opacity-50');
      }

      if (typeSelect) {
        typeSelect.disabled = false;
        typeSelect.classList.remove('cursor-not-allowed', 'opacity-50');
      }

      if (generateBtn) {
        generateBtn.disabled = false;
        generateBtn.classList.remove('cursor-not-allowed', 'opacity-50', 'pointer-events-none');
      }

      if (banner) {
        banner.classList.add('hidden');
      }

      if (addBtn) {
        const btnText = window.__t ? window.__t('products.btn_add_alias', 'Add Code') : 'Add Code';
        addBtn.innerHTML = `
          <span class="text-emerald-400 font-bold">+</span>
          <span data-i18n="products.btn_add_alias">${btnText}</span>
        `;
        addBtn.classList.remove('bg-indigo-600', 'hover:bg-indigo-700');
        addBtn.classList.add('bg-slate-900', 'hover:bg-black');
      }

      renderProductBarcodesList();
    }
    window.clearBarcodeNoteEditingSelection = clearBarcodeNoteEditingSelection;

    function onBarcodeCardClick(codeVal, isPrimary) {
      if (window._selectedEditingBarcode && window._selectedEditingBarcode.code.toUpperCase() === (codeVal || '').toUpperCase()) {
        clearBarcodeNoteEditingSelection();
      } else {
        selectBarcodeForNoteEditing(codeVal, isPrimary);
      }
    }
    window.onBarcodeCardClick = onBarcodeCardClick;

    function renderProductBarcodesList() {
      const container = document.getElementById('product-secondary-barcodes-list');
      const countBadge = document.getElementById('product-secondary-barcodes-count-badge');
      const primaryCard = document.getElementById('product-primary-barcode-card');
      if (!container) return;

      const primaryObj = window._registeredPrimaryBarcode;
      const hasPrimary = !!(primaryObj && primaryObj.barcode_value);
      const primaryVal = hasPrimary ? primaryObj.barcode_value : '';
      const primaryType = hasPrimary ? (primaryObj.barcode_type || 'CODE128') : 'CODE128';
      const primaryTag = hasPrimary ? (primaryObj.label_tag || window._productPrimaryBarcodeTag || '') : '';

      // Update primary barcode prominent card
      if (primaryCard) {
        if (hasPrimary) {
          const isSelected = !!(window._selectedEditingBarcode && window._selectedEditingBarcode.isPrimary);
          let badgeColor = 'bg-indigo-50 dark:bg-indigo-950/60 text-indigo-700 dark:text-indigo-300 border-indigo-200/60 dark:border-indigo-800/60';
          if (primaryType === 'QR') {
            badgeColor = 'bg-emerald-50 dark:bg-emerald-950/60 text-emerald-700 dark:text-emerald-300 border-emerald-200/60 dark:border-emerald-800/60';
          } else if (primaryType === 'EAN13') {
            badgeColor = 'bg-amber-50 dark:bg-amber-950/60 text-amber-700 dark:text-amber-300 border-amber-200/60 dark:border-amber-800/60';
          }

          const activeBorder = isSelected
            ? 'ring-2 ring-indigo-500 bg-indigo-50/90 dark:bg-indigo-950/60 shadow-md border-indigo-400 dark:border-indigo-600'
            : 'border-amber-300/60 dark:border-amber-400/25 hover:border-amber-400 dark:hover:border-amber-400/40';

          primaryCard.className = `p-2.5 sm:p-3 rounded-2xl bg-gradient-to-r from-amber-500/[0.08] via-amber-500/[0.03] to-transparent dark:from-amber-400/[0.07] dark:via-amber-400/[0.02] dark:to-transparent border border-s-2 border-s-amber-400 dark:border-s-amber-400 transition-all cursor-pointer ${activeBorder}`;
          primaryCard.setAttribute('onclick', `if (!event.target.closest('button')) onBarcodeCardClick('${escapeJsString(primaryVal)}', true)`);
          primaryCard.setAttribute('title', window.__t ? window.__t('products.click_to_edit_note_hint', 'Click to edit note / tag') : 'Click to edit note / tag');

          primaryCard.innerHTML = `
            <div class="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-2">
              <!-- Tier 1: Identity & Primary Indicator -->
              <div class="flex items-center gap-2 min-w-0 flex-1">
                <span class="px-1.5 py-0.5 rounded text-[9px] font-mono font-black uppercase border ${badgeColor} shrink-0">
                  ${escapeHtml(primaryType)}
                </span>
                <span class="font-mono text-xs font-bold tracking-wider text-slate-900 dark:text-slate-100 select-all truncate tabular-nums" dir="ltr">
                  ${escapeHtml(primaryVal)}
                </span>
                ${primaryTag ? `<span class="px-2 py-0.5 rounded-md text-[10px] font-medium bg-slate-200/70 dark:bg-white/[0.06] text-slate-700 dark:text-slate-300 border border-slate-300/50 dark:border-white/[0.08] truncate max-w-[130px]" title="${escapeHtml(primaryTag)}">${escapeHtml(primaryTag)}</span>` : ''}
                <span class="px-2 py-0.5 rounded-full text-[9px] font-bold bg-amber-500/10 dark:bg-amber-400/10 text-amber-600 dark:text-amber-400 border border-amber-500/20 flex items-center gap-1 shrink-0 shadow-2xs">
                  <svg class="w-3 h-3 text-amber-400 fill-amber-400 drop-shadow-[0_0_4px_rgba(251,191,36,0.5)] shrink-0 pointer-events-none" viewBox="0 0 20 20" fill="currentColor">
                    <path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z"/>
                  </svg>
                  <span data-i18n="products.lbl_primary">${window.__t ? window.__t('products.lbl_primary', 'Primary') : 'Primary'}</span>
                </span>
                ${isSelected ? `<span class="px-1.5 py-0.5 rounded text-[9px] font-bold bg-indigo-600 text-white shrink-0">✏️ ${window.__t ? window.__t('products.editing_note_for', 'Editing') : 'Editing'}</span>` : ''}
              </div>

              <!-- Tier 2: Ergonomic Decoupled Actions Rail for Primary Barcode -->
              <div class="flex items-center justify-end gap-1.5 shrink-0">
                <!-- Print Individual Sticker Button (Vector SVG) -->
                <button type="button" onclick="printPrimaryBarcode()" title="Print"
                  class="h-7 w-7 rounded-lg bg-white dark:bg-white/[0.06] hover:bg-slate-100 dark:hover:bg-white/[0.12] text-slate-700 dark:text-slate-200 text-xs flex items-center justify-center border border-slate-200/80 dark:border-white/[0.08] transition-all cursor-pointer active:scale-90 shadow-2xs">
                  <svg class="w-3.5 h-3.5 pointer-events-none" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z"/>
                  </svg>
                </button>
                <!-- Remove Primary Barcode Button (Vector SVG) -->
                <button type="button" onclick="removePrimaryBarcode()" title="${window.__t ? window.__t('products.btn_remove_primary', 'Remove primary barcode') : 'Remove primary barcode'}"
                  class="h-7 w-7 rounded-lg bg-white dark:bg-white/[0.06] hover:bg-rose-50 dark:hover:bg-rose-950/60 text-slate-400 hover:text-rose-500 dark:hover:text-rose-400 text-xs flex items-center justify-center border border-slate-200/80 dark:border-white/[0.08] hover:border-rose-300 dark:hover:border-rose-500/30 transition-all cursor-pointer active:scale-90 shadow-2xs">
                  <svg class="w-3.5 h-3.5 pointer-events-none" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/>
                  </svg>
                </button>
              </div>
            </div>
          `;
          primaryCard.classList.remove('hidden');
        } else {
          primaryCard.innerHTML = '';
          primaryCard.classList.add('hidden');
        }
      }

      const totalCount = (hasPrimary ? 1 : 0) + currentProductSecondaryBarcodes.length;
      if (countBadge) {
        if (totalCount === 1) {
          countBadge.textContent = window.__t ? window.__t('products.count_codes_singular', '1 code') : '1 code';
        } else if (totalCount > 1) {
          countBadge.textContent = window.__t ? window.__t('products.count_codes_plural', '{count} codes', { count: totalCount }) : `${totalCount} codes`;
        } else {
          countBadge.textContent = window.__t ? window.__t('products.count_codes_plural', '{count} codes', { count: 0 }) : '0 codes';
        }
      }

      if (currentProductSecondaryBarcodes.length === 0) {
        if (hasPrimary) {
          container.innerHTML = `
            <div class="py-2 text-center text-[11px] text-slate-400 dark:text-slate-500 font-medium select-none" data-i18n="products.no_additional_secondary_barcodes">
              ${window.__t ? window.__t('products.no_additional_secondary_barcodes', 'No additional secondary barcodes registered.') : 'No additional secondary barcodes registered.'}
            </div>
          `;
        } else {
          container.innerHTML = `
            <div class="py-3 text-center text-xs text-slate-400 dark:text-slate-500 font-medium select-none" data-i18n="products.no_secondary_barcodes">
              ${window.__t ? window.__t('products.no_secondary_barcodes', 'No additional barcodes registered. Scan or add aliases above.') : 'No additional barcodes registered. Scan or add aliases above.'}
            </div>
          `;
        }
        return;
      }

      let html = '';
      currentProductSecondaryBarcodes.forEach((b, idx) => {
        const val = escapeHtml(b.barcode_value || b.barcode || '');
        const type = escapeHtml(b.barcode_type || b.type || 'CODE128');
        const label = b.label_tag || b.label || '';
        const escapedLabel = escapeHtml(label);
        const isSelected = !!(window._selectedEditingBarcode && !window._selectedEditingBarcode.isPrimary && window._selectedEditingBarcode.code.toUpperCase() === (b.barcode_value || b.barcode || '').toUpperCase());

        // Type color badge
        let badgeColor = 'bg-indigo-50 dark:bg-indigo-950/60 text-indigo-700 dark:text-indigo-300 border-indigo-200/60 dark:border-indigo-800/60';
        if (type === 'QR') {
          badgeColor = 'bg-emerald-50 dark:bg-emerald-950/60 text-emerald-700 dark:text-emerald-300 border-emerald-200/60 dark:border-emerald-800/60';
        } else if (type === 'EAN13') {
          badgeColor = 'bg-amber-50 dark:bg-amber-950/60 text-amber-700 dark:text-amber-300 border-amber-200/60 dark:border-amber-800/60';
        }

        const activeBorder = isSelected
          ? 'ring-2 ring-indigo-500 bg-indigo-50/90 dark:bg-indigo-950/60 shadow-md border-indigo-400 dark:border-indigo-600'
          : 'border-slate-200/70 dark:border-white/[0.05] hover:border-slate-300 dark:hover:border-white/10';

        html += `
          <div onclick="if (!event.target.closest('button')) onBarcodeCardClick('${escapeJsString(b.barcode_value || b.barcode || '')}', false)"
            title="${window.__t ? window.__t('products.click_to_edit_note_hint', 'Click to edit note / tag') : 'Click to edit note / tag'}"
            class="group p-2 sm:p-2.5 rounded-xl bg-slate-50/90 dark:bg-black/25 border flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-2 transition-all cursor-pointer hover:bg-slate-100/80 dark:hover:bg-white/[0.04] ${activeBorder}">
            <!-- Tier 1: Identity & Format -->
            <div class="flex items-center gap-2 min-w-0 flex-1">
              <span class="px-1.5 py-0.5 rounded text-[9px] font-mono font-black uppercase border ${badgeColor} shrink-0">
                ${type}
              </span>
              <span class="font-mono text-xs font-bold tracking-wider text-slate-900 dark:text-slate-100 select-all truncate tabular-nums" dir="ltr">
                ${val}
              </span>
              ${escapedLabel ? `<span class="px-2 py-0.5 rounded-md text-[10px] font-medium bg-slate-200/70 dark:bg-white/[0.06] text-slate-700 dark:text-slate-300 border border-slate-300/50 dark:border-white/[0.08] truncate max-w-[130px]" title="${escapedLabel}">${escapedLabel}</span>` : ''}
              ${isSelected ? `<span class="px-1.5 py-0.5 rounded text-[9px] font-bold bg-indigo-600 text-white shrink-0">✏️ ${window.__t ? window.__t('products.editing_note_for', 'Editing') : 'Editing'}</span>` : ''}
            </div>

            <!-- Tier 2: Ergonomic Decoupled Actions Rail -->
            <div class="flex items-center justify-end gap-1.5 shrink-0">
              <!-- Set as Primary Button (Subtle Outline Star SVG - Highlights Amber on Hover) -->
              <button type="button" onclick="setBarcodeAsPrimary(${idx})" title="${window.__t ? window.__t('products.btn_set_primary', 'Set Primary') : 'Set Primary'}"
                class="h-7 px-2 rounded-lg bg-white dark:bg-white/[0.06] hover:bg-amber-50 dark:hover:bg-amber-950/40 text-slate-500 hover:text-amber-500 dark:text-slate-400 dark:hover:text-amber-400 text-[10px] font-bold border border-slate-200/80 dark:border-white/[0.08] hover:border-amber-400/40 transition-all cursor-pointer flex items-center gap-1 active:scale-90 shadow-2xs group/star">
                <svg class="w-3.5 h-3.5 text-slate-400 group-hover/star:text-amber-400 group-hover/star:fill-amber-400/40 transition-colors pointer-events-none" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M11.049 2.927c.3-.921 1.603-.921 1.902 0l1.519 4.674a1 1 0 00.95.69h4.915c.969 0 1.371 1.24.588 1.81l-3.976 2.888a1 1 0 00-.363 1.118l1.518 4.674c.3.922-.755 1.688-1.538 1.118l-3.976-2.888a1 1 0 00-1.176 0l-3.976 2.888c-.783.57-1.838-.197-1.538-1.118l1.518-4.674a1 1 0 00-.363-1.118l-3.976-2.888c-.784-.57-.38-1.81.588-1.81h4.914a1 1 0 00.951-.69l1.519-4.674z"/>
                </svg>
                <span class="hidden sm:inline" data-i18n="products.btn_set_primary">${window.__t ? window.__t('products.btn_set_primary', 'Set Primary') : 'Set Primary'}</span>
              </button>

              <!-- Print Individual Sticker Button (Vector SVG) -->
              <button type="button" onclick="printSecondaryBarcode(${idx})" title="Print"
                class="h-7 w-7 rounded-lg bg-white dark:bg-white/[0.06] hover:bg-slate-100 dark:hover:bg-white/[0.12] text-slate-700 dark:text-slate-200 text-xs flex items-center justify-center border border-slate-200/80 dark:border-white/[0.08] transition-all cursor-pointer active:scale-90 shadow-2xs">
                <svg class="w-3.5 h-3.5 pointer-events-none" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z"/>
                </svg>
              </button>

              <!-- Remove / Delete Button (Vector SVG) -->
              <button type="button" onclick="removeSecondaryBarcode(${idx})" title="Delete"
                class="h-7 w-7 rounded-lg bg-white dark:bg-white/[0.06] hover:bg-rose-50 dark:hover:bg-rose-950/60 text-slate-400 hover:text-rose-500 dark:hover:text-rose-400 text-xs flex items-center justify-center border border-slate-200/80 dark:border-white/[0.08] hover:border-rose-300 dark:hover:border-rose-500/30 transition-all cursor-pointer active:scale-90 shadow-2xs">
                <svg class="w-3.5 h-3.5 pointer-events-none" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/>
                </svg>
              </button>
            </div>
          </div>
        `;
      });

      container.innerHTML = html;
    }
    window.renderProductBarcodesList = renderProductBarcodesList;

    function addSecondaryBarcodeFromInput() {
      const aliasInput = document.getElementById('product-alias-input');
      const barcodeInput = document.getElementById('product-barcode-input');
      const typeEl = document.getElementById('product-barcode-type') || document.getElementById('product-alias-type');
      const labelEl = document.getElementById('product-alias-label');
      const editId = document.getElementById('product-edit-id')?.value || null;

      // Read code value from either alias input or visible barcode input
      const codeVal = (aliasInput && aliasInput.value.trim()) || (barcodeInput ? barcodeInput.value.trim() : '');
      const codeType = typeEl ? typeEl.value : 'CODE128';
      const labelTag = labelEl ? labelEl.value.trim() : '';

      if (!codeVal) {
        showToast(window.__t ? window.__t('products.toast_barcode_required', 'Please enter a barcode or scan code first') : 'Please enter a barcode or scan code first', 'default');
        barcodeInput?.focus();
        return;
      }

      // Check if we are editing note for an existing barcode (or codeVal matches an existing barcode)
      const isEditingPrimary = (window._selectedEditingBarcode && window._selectedEditingBarcode.isPrimary) ||
        (window._registeredPrimaryBarcode && window._registeredPrimaryBarcode.barcode_value && window._registeredPrimaryBarcode.barcode_value.toUpperCase() === codeVal.toUpperCase());

      if (isEditingPrimary) {
        window._registeredPrimaryBarcode.label_tag = labelTag;
        window._productPrimaryBarcodeTag = labelTag;
        if (labelEl) labelEl.value = '';
        clearBarcodeNoteEditingSelection();
        renderProductBarcodesList();
        showToast(window.__t ? window.__t('products.toast_note_updated', 'Note updated successfully') : 'Note updated successfully', 'default');
        return;
      }

      const existingSecondaryIdx = currentProductSecondaryBarcodes.findIndex(b => (b.barcode_value || b.barcode || '').toUpperCase() === codeVal.toUpperCase());
      if (existingSecondaryIdx >= 0) {
        currentProductSecondaryBarcodes[existingSecondaryIdx].label_tag = labelTag;
        currentProductSecondaryBarcodes[existingSecondaryIdx].label = labelTag;
        if (labelEl) labelEl.value = '';
        clearBarcodeNoteEditingSelection();
        renderProductBarcodesList();
        showToast(window.__t ? window.__t('products.toast_note_updated', 'Note updated successfully') : 'Note updated successfully', 'default');
        return;
      }

      // Check duplicates across other products in database/cache
      const conflict = getConflictingBarcodeProduct(codeVal, editId);
      if (conflict) {
        const prodName = escapeHtml(conflict.name || 'Product');
        const prodUid = escapeHtml(conflict.uid || conflict.__backendId || conflict.id);
        const msg = window.__t ? window.__t('products.barcode_already_assigned_to', 'Barcode already assigned to {name} (#{uid})', { name: prodName, uid: prodUid }) : `Barcode already assigned to ${prodName} (#${prodUid})`;
        showToast(msg, 'default');
        return;
      }

      // Case 1: No primary barcode registered yet -> commit as primary!
      if (!window._registeredPrimaryBarcode || !window._registeredPrimaryBarcode.barcode_value) {
        window._registeredPrimaryBarcode = {
          barcode_value: codeVal,
          barcode_type: codeType,
          label_tag: labelTag,
          is_primary: 1
        };
        window._productPrimaryBarcodeTag = labelTag;
        if (aliasInput) aliasInput.value = '';
        if (labelEl) labelEl.value = '';

        renderProductBarcodesList();
        showToast(window.__t ? window.__t('products.toast_barcode_registered', 'Barcode registered as primary') : 'Barcode registered as primary', 'default');
        return;
      }

      // Case 2: Code is different from primary barcode -> add to secondary barcodes!
      currentProductSecondaryBarcodes.push({
        barcode_value: codeVal,
        barcode_type: codeType,
        label_tag: labelTag,
        is_primary: 0
      });

      if (aliasInput) aliasInput.value = '';
      if (labelEl) labelEl.value = '';

      renderProductBarcodesList();
      showToast(window.__t ? window.__t('products.toast_alias_added', 'Barcode alias added successfully') : 'Barcode alias added successfully', 'default');
    }
    window.addSecondaryBarcodeFromInput = addSecondaryBarcodeFromInput;

    async function removePrimaryBarcode() {
      const codeVal = window._registeredPrimaryBarcode?.barcode_value || '';
      const _t = (k, fb, params) => (window.i18n ? window.i18n.t(k, fb, params) : (typeof window.__t === 'function' ? window.__t(k, fb, params) : fb));

      const confirmed = await showSystemConfirmModal({
        title: _t('products.confirm_delete_primary_barcode_title', 'Delete Primary Barcode'),
        message: _t('products.confirm_delete_barcode_msg', 'Are you sure you want to remove barcode {code}? This will remove it from the product registry.', { code: codeVal }),
        confirmText: _t('products.btn_delete_barcode', 'Delete Barcode'),
        cancelText: _t('common.cancel', 'Cancel'),
        type: 'danger'
      });
      if (!confirmed) return;

      if (window._selectedEditingBarcode && window._selectedEditingBarcode.isPrimary) {
        clearBarcodeNoteEditingSelection();
      }
      window._registeredPrimaryBarcode = null;
      window._productPrimaryBarcodeTag = '';
      const barcodeInput = document.getElementById('product-barcode-input');
      if (barcodeInput) barcodeInput.value = '';
      renderProductModalBarcodePreview();
      renderProductBarcodesList();
      showToast(_t('products.toast_barcode_deleted', 'Barcode deleted successfully'), 'default');
    }
    window.removePrimaryBarcode = removePrimaryBarcode;

    function generateAndAddSecondaryBarcode() {
      const typeEl = document.getElementById('product-alias-type');
      const prefixEl = document.getElementById('product-barcode-prefix');
      const labelEl = document.getElementById('product-alias-label');
      const editId = document.getElementById('product-edit-id')?.value || null;

      const codeType = typeEl ? typeEl.value : 'CODE128';
      const prefix = prefixEl ? prefixEl.value.trim() : 'PHN';
      const labelTag = labelEl ? labelEl.value.trim() : (window.__t ? window.__t('products.alias_generated_tag', 'Auto-Generated') : 'Auto-Generated');

      // Generate a collision-free code
      let generatedCode = '';
      let attempts = 0;
      do {
        generatedCode = generateProductBarcode(codeType, prefix);
        attempts++;
      } while (
        (isBarcodeTaken(generatedCode, editId) ||
         currentProductSecondaryBarcodes.some(b => (b.barcode_value || b.barcode || '').toUpperCase() === generatedCode.toUpperCase()) ||
         ((window._registeredPrimaryBarcode?.barcode_value || document.getElementById('product-barcode-input')?.value.trim() || '').toUpperCase() === generatedCode.toUpperCase())) &&
        attempts < 20
      );

      // If no primary barcode yet, set as primary!
      if (!window._registeredPrimaryBarcode || !window._registeredPrimaryBarcode.barcode_value) {
        window._registeredPrimaryBarcode = {
          barcode_value: generatedCode,
          barcode_type: codeType,
          label_tag: labelTag,
          is_primary: 1
        };
        window._productPrimaryBarcodeTag = labelTag;
        const bInput = document.getElementById('product-barcode-input');
        if (bInput) bInput.value = generatedCode;
        renderProductModalBarcodePreview();
      } else {
        currentProductSecondaryBarcodes.push({
          barcode_value: generatedCode,
          barcode_type: codeType,
          label_tag: labelTag,
          is_primary: 0
        });
      }

      renderProductBarcodesList();
      showToast(window.__t ? window.__t('products.toast_alias_generated', 'Generated & saved new barcode alias') : 'Generated & saved new barcode alias', 'default');
    }
    window.generateAndAddSecondaryBarcode = generateAndAddSecondaryBarcode;

    async function removeSecondaryBarcode(idx) {
      if (idx < 0 || idx >= currentProductSecondaryBarcodes.length) return;
      const target = currentProductSecondaryBarcodes[idx];
      const codeVal = target.barcode_value || target.barcode || '';
      const _t = (k, fb, params) => (window.i18n ? window.i18n.t(k, fb, params) : (typeof window.__t === 'function' ? window.__t(k, fb, params) : fb));

      const confirmed = await showSystemConfirmModal({
        title: _t('products.confirm_delete_barcode_title', 'Delete Barcode'),
        message: _t('products.confirm_delete_barcode_msg', 'Are you sure you want to remove barcode {code}? This will remove it from the product registry.', { code: codeVal }),
        confirmText: _t('products.btn_delete_barcode', 'Delete Barcode'),
        cancelText: _t('common.cancel', 'Cancel'),
        type: 'danger'
      });
      if (!confirmed) return;

      if (window._selectedEditingBarcode && !window._selectedEditingBarcode.isPrimary && window._selectedEditingBarcode.code.toUpperCase() === codeVal.toUpperCase()) {
        clearBarcodeNoteEditingSelection();
      }
      currentProductSecondaryBarcodes.splice(idx, 1);
      renderProductBarcodesList();
      showToast(_t('products.toast_barcode_deleted', 'Barcode deleted successfully'), 'default');
    }
    window.removeSecondaryBarcode = removeSecondaryBarcode;

    function setBarcodeAsPrimary(idx) {
      if (idx < 0 || idx >= currentProductSecondaryBarcodes.length) return;
      const targetSecondary = currentProductSecondaryBarcodes[idx];

      const primaryInput = document.getElementById('product-barcode-input');
      const primaryTypeSelect = document.getElementById('product-barcode-type');
      const oldPrimary = window._registeredPrimaryBarcode;

      // Update registered primary
      window._registeredPrimaryBarcode = {
        barcode_value: targetSecondary.barcode_value || targetSecondary.barcode,
        barcode_type: targetSecondary.barcode_type || targetSecondary.type || 'CODE128',
        label_tag: targetSecondary.label_tag || targetSecondary.label || '',
        is_primary: 1
      };
      window._productPrimaryBarcodeTag = window._registeredPrimaryBarcode.label_tag;

      if (primaryInput) primaryInput.value = window._registeredPrimaryBarcode.barcode_value;
      if (primaryTypeSelect) primaryTypeSelect.value = window._registeredPrimaryBarcode.barcode_type;

      // Swap: Old primary (if valid) becomes the secondary slot
      if (oldPrimary && oldPrimary.barcode_value) {
        currentProductSecondaryBarcodes[idx] = {
          barcode_value: oldPrimary.barcode_value,
          barcode_type: oldPrimary.barcode_type || 'CODE128',
          label_tag: oldPrimary.label_tag || (window.__t ? window.__t('products.former_primary_tag', 'Former Primary') : 'Former Primary'),
          is_primary: 0
        };
      } else {
        currentProductSecondaryBarcodes.splice(idx, 1);
      }

      renderProductModalBarcodePreview();
      renderProductBarcodesList();
      showToast(window.__t ? window.__t('products.toast_primary_swapped', 'Barcode promoted to primary') : 'Barcode promoted to primary', 'default');
    }
    window.setBarcodeAsPrimary = setBarcodeAsPrimary;

    function printPrimaryBarcode() {
      const codeVal = window._registeredPrimaryBarcode ? window._registeredPrimaryBarcode.barcode_value : (document.getElementById('product-barcode-input')?.value.trim() || '');
      if (!codeVal) return;
      const codeType = window._registeredPrimaryBarcode ? (window._registeredPrimaryBarcode.barcode_type || 'CODE128') : (document.getElementById('product-barcode-type')?.value || 'CODE128');
      const editId = document.getElementById('product-edit-id')?.value || null;
      const prodName = document.getElementById('product-name')?.value.trim() || 'Product';

      let productObj = editId ? productsCache.find(p => p.__backendId === String(editId)) : null;
      if (!productObj) {
        productObj = {
          __backendId: editId || 'temp',
          name: prodName,
          barcode: codeVal,
          barcode_type: codeType,
          price: '0',
          secondary_barcodes: currentProductSecondaryBarcodes
        };
      } else {
        productObj = {
          ...productObj,
          name: prodName,
          barcode: codeVal,
          barcode_type: codeType,
          secondary_barcodes: currentProductSecondaryBarcodes
        };
      }

      printProductBarcodeLabel(productObj.__backendId, { product: productObj, selectedBarcode: codeVal });
    }
    window.printPrimaryBarcode = printPrimaryBarcode;

    function printSecondaryBarcode(idx) {
      if (idx < 0 || idx >= currentProductSecondaryBarcodes.length) return;
      const b = currentProductSecondaryBarcodes[idx];
      const editId = document.getElementById('product-edit-id')?.value || null;
      const prodName = document.getElementById('product-name')?.value.trim() || 'Product';

      let productObj = editId ? productsCache.find(p => p.__backendId === String(editId)) : null;
      if (!productObj) {
        productObj = {
          __backendId: editId || 'temp',
          name: prodName,
          barcode: b.barcode_value || b.barcode,
          barcode_type: b.barcode_type || b.type || 'CODE128',
          price: '0',
          secondary_barcodes: currentProductSecondaryBarcodes
        };
      } else {
        productObj = {
          ...productObj,
          name: prodName,
          barcode: b.barcode_value || b.barcode,
          barcode_type: b.barcode_type || b.type || 'CODE128',
          secondary_barcodes: currentProductSecondaryBarcodes
        };
      }

      printProductBarcodeLabel(productObj.__backendId, { product: productObj, selectedBarcode: b.barcode_value || b.barcode });
    }
    window.printSecondaryBarcode = printSecondaryBarcode;

    function resetProductModalBarcodeSection() {
      const toggle = document.getElementById('product-has-barcode-toggle');
      const container = document.getElementById('product-barcode-controls-container');
      const statusPill = document.getElementById('product-barcode-status-pill');
      const statusDot = document.getElementById('product-barcode-status-dot');
      const statusText = document.getElementById('product-barcode-status-text');
      const barcodeInput = document.getElementById('product-barcode-input');
      const prefixInput = document.getElementById('product-barcode-prefix');
      const typeSelect = document.getElementById('product-barcode-type');
      const target = document.getElementById('product-barcode-svg-target');
      const placeholder = document.getElementById('product-barcode-empty-placeholder');
      const feedback = document.getElementById('product-barcode-feedback');

      if (toggle) toggle.checked = false;
      if (container) container.classList.add('hidden');
      if (statusPill) statusPill.className = 'inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full text-[10px] font-bold bg-slate-200/60 dark:bg-white/[0.06] text-slate-500 dark:text-slate-400 border border-slate-300/40 dark:border-white/[0.06] transition-all';
      if (statusDot) statusDot.className = 'w-1.5 h-1.5 rounded-full bg-slate-400';
      if (statusText) statusText.textContent = window.__t ? window.__t('products.barcode_status_disabled', 'Disabled') : 'Disabled';
      if (barcodeInput) barcodeInput.value = '';
      if (prefixInput) prefixInput.value = (typeof config !== 'undefined' && config.barcode_prefix) ? config.barcode_prefix : 'PHN';
      if (typeSelect) typeSelect.value = 'CODE128';
      if (target) target.innerHTML = '';
      if (placeholder) placeholder.classList.remove('hidden');
      if (feedback) feedback.classList.add('hidden');

      // Mission 52 Phase 3.5: Reset Multi-Barcode Aliases
      clearBarcodeNoteEditingSelection();
      window._registeredPrimaryBarcode = null;
      window._productPrimaryBarcodeTag = '';
      currentProductSecondaryBarcodes = [];
      const aliasInput = document.getElementById('product-alias-input');
      if (aliasInput) aliasInput.value = '';
      const aliasLabel = document.getElementById('product-alias-label');
      if (aliasLabel) aliasLabel.value = '';
      renderProductBarcodesList();
    }
    window.resetProductModalBarcodeSection = resetProductModalBarcodeSection;

    function hydrateProductModalBarcodeSection(product) {
      if (!product) return;
      clearBarcodeNoteEditingSelection();
      const toggle = document.getElementById('product-has-barcode-toggle');
      const container = document.getElementById('product-barcode-controls-container');
      const statusPill = document.getElementById('product-barcode-status-pill');
      const statusDot = document.getElementById('product-barcode-status-dot');
      const statusText = document.getElementById('product-barcode-status-text');
      const barcodeInput = document.getElementById('product-barcode-input');
      const prefixInput = document.getElementById('product-barcode-prefix');
      const typeSelect = document.getElementById('product-barcode-type');

      const hasBarcode = !!(product.has_barcode == 1 || product.barcode);
      const barcodeVal = product.barcode || '';
      const barcodeType = product.barcode_type || 'CODE128';

      if (toggle) toggle.checked = hasBarcode;
      if (barcodeInput) barcodeInput.value = barcodeVal;
      if (typeSelect) typeSelect.value = barcodeType;

      if (prefixInput) {
        if (barcodeVal && barcodeVal.includes('-')) {
          prefixInput.value = barcodeVal.split('-')[0];
        } else {
          prefixInput.value = (typeof config !== 'undefined' && config.barcode_prefix) ? config.barcode_prefix : 'PHN';
        }
      }

      if (hasBarcode) {
        if (container) container.classList.remove('hidden');
        if (statusPill) statusPill.className = 'inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full text-[10px] font-bold bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border border-emerald-500/20 transition-all';
        if (statusDot) statusDot.className = 'w-1.5 h-1.5 rounded-full bg-emerald-500';
        if (statusText) statusText.textContent = window.__t ? window.__t('products.barcode_status_active', 'Active') : 'Active';
        renderProductModalBarcodePreview();
      } else {
        if (container) container.classList.add('hidden');
        if (statusPill) statusPill.className = 'inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full text-[10px] font-bold bg-slate-200/60 dark:bg-white/[0.06] text-slate-500 dark:text-slate-400 border border-slate-300/40 dark:border-white/[0.06] transition-all';
        if (statusDot) statusDot.className = 'w-1.5 h-1.5 rounded-full bg-slate-400';
        if (statusText) statusText.textContent = window.__t ? window.__t('products.barcode_status_disabled', 'Disabled') : 'Disabled';
      }

      // Mission 52 Phase 3.5: Hydrate Registered Primary & Secondary Barcodes
      const primaryObj = Array.isArray(product.barcodes) ? product.barcodes.find(b => b.is_primary === 1) : null;
      const primaryTag = (primaryObj ? (primaryObj.label_tag || primaryObj.label) : '') || product.barcode_label || product.barcode_tag || '';
      window._productPrimaryBarcodeTag = primaryTag;
      if (hasBarcode && barcodeVal) {
        window._registeredPrimaryBarcode = {
          barcode_value: barcodeVal,
          barcode_type: barcodeType,
          label_tag: primaryTag,
          is_primary: 1
        };
      } else {
        window._registeredPrimaryBarcode = null;
      }

      currentProductSecondaryBarcodes = Array.isArray(product.secondary_barcodes)
        ? JSON.parse(JSON.stringify(product.secondary_barcodes))
        : (Array.isArray(product.barcodes) ? product.barcodes.filter(b => b.is_primary === 0) : []);
      renderProductBarcodesList();
    }
    window.hydrateProductModalBarcodeSection = hydrateProductModalBarcodeSection;

    function triggerProductModalLabelPrint() {
      const editId = document.getElementById('product-edit-id')?.value || null;
      const barcodeInput = document.getElementById('product-barcode-input');
      const barcodeVal = barcodeInput ? barcodeInput.value.trim() : '';
      const barcodeType = document.getElementById('product-barcode-type')?.value || 'CODE128';
      const prodName = document.getElementById('product-name')?.value.trim() || 'Product';

      if (!barcodeVal) {
        showToast(window.__t ? window.__t('products.toast_barcode_required', 'Please enter or generate a barcode first') : 'Please enter or generate a barcode first', 'default');
        return;
      }

      let productObj = editId ? productsCache.find(p => p.__backendId === String(editId)) : null;
      if (!productObj) {
        productObj = {
          __backendId: editId || 'temp',
          name: prodName,
          barcode: barcodeVal,
          barcode_type: barcodeType,
          price: '0',
          secondary_barcodes: currentProductSecondaryBarcodes
        };
      } else {
        productObj = {
          ...productObj,
          name: prodName,
          barcode: barcodeVal,
          barcode_type: barcodeType,
          secondary_barcodes: currentProductSecondaryBarcodes
        };
      }

      printProductBarcodeLabel(productObj.__backendId, { product: productObj, selectedBarcode: barcodeVal });
    }
    window.triggerProductModalLabelPrint = triggerProductModalLabelPrint;

    // ═══════════════════════════════════════════════════════════════════════════
    // ── Dedicated Barcode & QR Label Printing Studio Controller (Mission 52) ──
    // ═══════════════════════════════════════════════════════════════════════════
    let _labelStudioState = {
      format: '50x30',
      mode: 'barcode', // 'barcode' or 'shelf'
      product: null,
      quantity: 1,
      offset: 0
    };
    window._labelStudioState = _labelStudioState;

    function printProductBarcodeLabel(productId, opts = {}) {
      let product = opts.product || null;
      if (!product && productId) {
        product = productsCache.find(p => String(p.__backendId || p.id) === String(productId));
      }
      if (!product) {
        showToast(window.__t ? window.__t('products.toast_product_not_found', 'Product not found') : 'Product not found', 'default');
        return;
      }

      _labelStudioState.product = product;
      _labelStudioState.format = opts.format || '50x30';
      _labelStudioState.mode = opts.mode || 'barcode';
      _labelStudioState.quantity = opts.quantity || 1;
      _labelStudioState.offset = 0;

      // Populate Modal Fields
      const idInput = document.getElementById('label-studio-product-id');
      if (idInput) idInput.value = product.__backendId || product.id || '';
      
      const titleEl = document.getElementById('label-studio-title');
      if (titleEl) titleEl.textContent = `${window.__t ? window.__t('labels.studio_modal_title', 'Label Studio') : 'Label Studio'} - ${product.name}`;
      
      const codeInput = document.getElementById('label-studio-code-input');
      if (codeInput) codeInput.value = product.barcode || product.uid || '';

      const symbologySelect = document.getElementById('label-studio-symbology');
      if (symbologySelect) symbologySelect.value = product.barcode_type || 'CODE128';

      const qtyInput = document.getElementById('label-studio-quantity');
      if (qtyInput) qtyInput.value = _labelStudioState.quantity;

      const offsetInput = document.getElementById('label-studio-a4-offset');
      if (offsetInput) offsetInput.value = 0;

      // Configure Stock button
      const stockBtn = document.getElementById('label-studio-stock-qty-btn');
      const stockQty = typeof getProductAvailableQuantity === 'function' ? getProductAvailableQuantity(product.__backendId) : 0;
      if (stockBtn) {
        if (stockQty && exactCompare(String(stockQty), '0') > 0) {
          stockBtn.textContent = `${window.__t ? window.__t('products.lbl_stock', 'Stock') : 'Stock'} (${Math.floor(Number(stockQty))})`;
          stockBtn.classList.remove('hidden');
        } else {
          stockBtn.classList.add('hidden');
        }
      }

      setLabelStudioMode(_labelStudioState.mode);
      setLabelStudioFormat(_labelStudioState.format);

      // Populate Barcode Selector (Mission 52 Phase 3.5)
      const selectorEl = document.getElementById('label-studio-barcode-selector');
      const multiDock = document.getElementById('label-studio-multi-barcode-dock');
      const allBarcodes = [];
      const primaryVal = (product.barcode || product.uid || '').trim();
      const primaryType = product.barcode_type || 'CODE128';
      if (primaryVal) {
        allBarcodes.push({
          value: primaryVal,
          type: primaryType,
          label: window._productPrimaryBarcodeTag || (window.__t ? window.__t('products.lbl_primary', 'Primary') : 'Primary'),
          is_primary: 1
        });
      }

      // Check secondaries from product or cache
      const secondaries = product.secondary_barcodes || (Array.isArray(product.barcodes) ? product.barcodes.filter(b => b.is_primary === 0) : (Array.isArray(currentProductSecondaryBarcodes) ? currentProductSecondaryBarcodes : []));
      if (Array.isArray(secondaries)) {
        secondaries.forEach(sb => {
          const val = (sb.barcode_value || sb.barcode || '').trim();
          if (val && !allBarcodes.some(item => item.value.toUpperCase() === val.toUpperCase())) {
            allBarcodes.push({
              value: val,
              type: sb.barcode_type || sb.type || 'CODE128',
              label: sb.label_tag || sb.label || '',
              is_primary: 0
            });
          }
        });
      }

      // Determine which barcode to select
      const initialSelected = opts.selectedBarcode || primaryVal || (allBarcodes[0] ? allBarcodes[0].value : '');

      // Populate Selector (hidden select for 100% backward contract parity)
      if (selectorEl) {
        selectorEl.innerHTML = '';
        allBarcodes.forEach(b => {
          const opt = document.createElement('option');
          opt.value = b.value;
          opt.dataset.type = b.type;
          const tagPart = b.label ? ` (${b.label})` : '';
          const prefixPart = b.is_primary ? `[${window.__t ? window.__t('products.lbl_primary', 'Primary') : 'Primary'}] ` : '';
          opt.textContent = `${prefixPart}${b.type}: ${b.value}${tagPart}`;
          selectorEl.appendChild(opt);
        });

        if (initialSelected) {
          selectorEl.value = initialSelected;
          const matched = allBarcodes.find(b => b.value === initialSelected) || allBarcodes[0];
          if (matched) {
            if (codeInput) codeInput.value = matched.value;
            if (symbologySelect) symbologySelect.value = matched.type === 'QR' ? 'QR' : 'CODE128';
          }
        }
      }

      // Populate Interactive Clickable Chips Container (Obsidian Bento Architecture)
      const chipsContainer = document.getElementById('label-studio-barcode-chips-container');
      const countBadge = document.getElementById('label-studio-barcode-count-badge');
      if (countBadge) {
        if (allBarcodes.length === 1) {
          countBadge.textContent = window.__t ? window.__t('products.count_codes_singular', '1 code') : '1 code';
        } else {
          countBadge.textContent = window.__t ? window.__t('products.count_codes_plural', '{count} codes', { count: allBarcodes.length }) : `${allBarcodes.length} codes`;
        }
      }

      if (chipsContainer) {
        const rowsClass = allBarcodes.length >= 4 ? 'grid-rows-2' : 'grid-rows-1';
        chipsContainer.className = `label-studio-chips-rail grid ${rowsClass} grid-flow-col auto-cols-max gap-2 overflow-x-auto overflow-y-hidden pb-2.5 pt-0.5 px-0.5 select-none min-w-0`;

        if (!chipsContainer._hasWheelListener) {
          chipsContainer._hasWheelListener = true;
          chipsContainer.addEventListener('wheel', (e) => {
            if (e.deltaY !== 0 && chipsContainer.scrollWidth > chipsContainer.clientWidth) {
              e.preventDefault();
              chipsContainer.scrollLeft += e.deltaY;
            }
          }, { passive: false });
        }

        let chipsHtml = '';
        allBarcodes.forEach((b) => {
          const isSelected = (b.value === initialSelected);
          const activeClass = isSelected
            ? 'bg-gradient-to-r from-emerald-500 to-teal-600 text-white shadow-sm ring-2 ring-emerald-400/60 dark:ring-emerald-500/60 border border-emerald-500'
            : 'bg-white/90 dark:bg-[#080b10] border border-slate-200/80 dark:border-white/[0.08] text-slate-700 dark:text-slate-300 hover:border-emerald-400 dark:hover:border-emerald-600 hover:bg-slate-50 dark:hover:bg-white/[0.04]';

          const primaryBadge = b.is_primary ? `<span class="text-amber-300 text-xs font-bold shrink-0">⭐</span>` : '';
          const tagText = b.label ? `<span class="px-1.5 py-0.5 rounded-full text-[9px] font-medium bg-black/10 dark:bg-white/10 border border-black/10 dark:border-white/10 truncate max-w-[120px]">${escapeHtml(b.label)}</span>` : '';

          let typeColor = 'bg-slate-100 dark:bg-white/10 text-slate-600 dark:text-slate-300 border-slate-200/60 dark:border-white/10';
          if (b.type === 'QR') typeColor = 'bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border-emerald-500/20';
          else if (b.type === 'EAN13') typeColor = 'bg-amber-500/10 text-amber-600 dark:text-amber-400 border-amber-500/20';

          chipsHtml += `
            <button type="button" onclick="onLabelStudioBarcodeChipClick('${escapeJsString(b.value)}')"
              data-barcode-val="${escapeHtml(b.value)}"
              class="label-studio-chip h-9 min-h-[36px] px-3 rounded-xl text-xs font-bold transition-all cursor-pointer flex items-center gap-2 active:scale-95 shrink-0 ${activeClass}">
              ${primaryBadge}
              <span class="px-1 py-0.5 rounded text-[9px] font-mono font-black uppercase border ${typeColor} shrink-0">${escapeHtml(b.type || '128')}</span>
              <span class="font-mono text-xs font-bold tracking-tight">${escapeHtml(b.value)}</span>
              ${tagText}
            </button>
          `;
        });
        chipsContainer.innerHTML = chipsHtml;
      }

      // Reset batch toggle
      const batchToggle = document.getElementById('label-studio-batch-all-toggle');
      if (batchToggle) batchToggle.checked = false;

      const modal = document.getElementById('product-label-studio-modal');
      if (modal) {
        if (typeof ModalManager !== 'undefined' && typeof ModalManager.bringToFront === 'function') {
          ModalManager.bringToFront(modal);
        }
        modal.classList.remove('hidden');
        if (typeof syncServicePrintModalHeights === 'function') {
          if (typeof requestAnimationFrame === 'function') {
            requestAnimationFrame(() => {
              syncServicePrintModalHeights();
            });
          } else {
            setTimeout(syncServicePrintModalHeights, 50);
          }
        }
      }
    }
    window.printProductBarcodeLabel = printProductBarcodeLabel;

    function closeProductLabelStudioModal() {
      const modal = document.getElementById('product-label-studio-modal');
      if (modal) modal.classList.add('hidden');
    }
    window.closeProductLabelStudioModal = closeProductLabelStudioModal;

    function setLabelStudioFormat(format) {
      _labelStudioState.format = format;
      const f50x30 = document.getElementById('label-format-btn-50x30');
      const f40x25 = document.getElementById('label-format-btn-40x25');
      const fa4 = document.getElementById('label-format-btn-a4');
      const a4Offset = document.getElementById('label-studio-a4-offset-container');
      const badge = document.getElementById('label-studio-dimensions-badge');
      const badgeBarcode = document.getElementById('label-studio-dimensions-badge-barcode');
      const badgeShelf = document.getElementById('label-studio-dimensions-badge-shelf');

      const activeClass = 'label-format-btn h-11 min-h-[44px] px-3 rounded-xl border border-emerald-500 bg-emerald-50 dark:bg-emerald-950/40 text-emerald-700 dark:text-emerald-300 font-bold text-xs flex flex-col items-center justify-center transition-all cursor-pointer shadow-2xs';
      const inactiveClass = 'label-format-btn h-11 min-h-[44px] px-3 rounded-xl border border-slate-200/80 dark:border-white/[0.08] bg-white dark:bg-[#080b10] text-slate-700 dark:text-slate-300 font-bold text-xs flex flex-col items-center justify-center transition-all cursor-pointer hover:border-slate-300 dark:hover:border-white/20';

      if (f50x30) f50x30.className = format === '50x30' ? activeClass : inactiveClass;
      if (f40x25) f40x25.className = format === '40x25' ? activeClass : inactiveClass;
      if (fa4) fa4.className = format === 'a4' ? activeClass : inactiveClass;

      if (a4Offset) {
        if (format === 'a4') a4Offset.classList.remove('hidden');
        else a4Offset.classList.add('hidden');
      }

      const dimText = format === '50x30' ? '50 × 30 mm' : (format === '40x25' ? '40 × 25 mm' : 'A4 (24 × 70×37 mm)');
      if (badge) badge.textContent = dimText;
      if (badgeBarcode) badgeBarcode.textContent = dimText;
      if (badgeShelf) badgeShelf.textContent = dimText;

      onLabelStudioConfigChange();
    }
    window.setLabelStudioFormat = setLabelStudioFormat;

    function setLabelStudioMode(mode) {
      _labelStudioState.mode = (mode === 'shelf') ? 'shelf' : 'barcode';
      const isShelf = _labelStudioState.mode === 'shelf';

      // Update Top Segmented Mode Buttons
      const btnBarcode = document.getElementById('label-mode-btn-barcode');
      const btnShelf = document.getElementById('label-mode-btn-shelf');
      if (btnBarcode && btnShelf) {
        const activeModeClass = 'h-9 min-h-[36px] px-3 rounded-xl font-black text-xs flex items-center justify-center gap-2 transition-all cursor-pointer bg-white dark:bg-[#080b10] text-emerald-600 dark:text-emerald-400 shadow-sm border border-emerald-500/30';
        const inactiveModeClass = 'h-9 min-h-[36px] px-3 rounded-xl font-bold text-xs flex items-center justify-center gap-2 transition-all cursor-pointer text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white';
        if (isShelf) {
          btnShelf.className = activeModeClass;
          btnBarcode.className = inactiveModeClass;
        } else {
          btnBarcode.className = activeModeClass;
          btnShelf.className = inactiveModeClass;
        }
      }

      // Update Right Column Preview Cards (Dual Stacked WYSIWYG Architecture - Mission 54)
      const cardBarcode = document.getElementById('label-studio-preview-card-barcode');
      const cardShelf = document.getElementById('label-studio-preview-card-shelf');
      const dotBarcode = document.getElementById('label-badge-barcode-dot');
      const dotShelf = document.getElementById('label-badge-shelf-dot');
      const statusBarcode = document.getElementById('label-status-badge-barcode');
      const statusShelf = document.getElementById('label-status-badge-shelf');

      const activeCardClass = 'p-4 sm:p-5 rounded-2xl bg-white/95 dark:bg-[#080b10]/95 border border-emerald-500/60 ring-2 ring-emerald-500/20 shadow-lg shadow-emerald-500/5 flex flex-col gap-3 transition-all cursor-pointer';
      const inactiveCardClass = 'p-4 sm:p-5 rounded-2xl bg-white/95 dark:bg-[#080b10]/95 border border-slate-200/80 dark:border-white/[0.08] hover:border-slate-300 dark:hover:border-white/20 flex flex-col gap-3 transition-all cursor-pointer opacity-85 hover:opacity-100';

      const activeBadgeClass = 'px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-wider bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border border-emerald-500/20';
      const inactiveBadgeClass = 'px-2 py-0.5 rounded-full text-[9px] font-bold uppercase tracking-wider bg-slate-100 dark:bg-white/[0.06] text-slate-500 dark:text-slate-400 border border-slate-200/60 dark:border-white/[0.06]';

      if (cardBarcode && cardShelf) {
        cardBarcode.classList.remove('hidden');
        cardShelf.classList.remove('hidden');

        if (isShelf) {
          cardShelf.className = activeCardClass;
          cardBarcode.className = inactiveCardClass;
          if (dotShelf) dotShelf.className = 'w-2.5 h-2.5 rounded-full bg-emerald-500 shadow-sm';
          if (dotBarcode) dotBarcode.className = 'w-2.5 h-2.5 rounded-full bg-slate-400/40 dark:bg-white/20';
          if (statusShelf) {
            statusShelf.className = activeBadgeClass;
            statusShelf.textContent = window.__t ? window.__t('labels.badge_active_for_print', 'Active for Print') : 'Active for Print';
          }
          if (statusBarcode) {
            statusBarcode.className = inactiveBadgeClass;
            statusBarcode.textContent = window.__t ? window.__t('labels.badge_click_to_select', 'Click to Select') : 'Click to Select';
          }
        } else {
          cardBarcode.className = activeCardClass;
          cardShelf.className = inactiveCardClass;
          if (dotBarcode) dotBarcode.className = 'w-2.5 h-2.5 rounded-full bg-emerald-500 shadow-sm';
          if (dotShelf) dotShelf.className = 'w-2.5 h-2.5 rounded-full bg-slate-400/40 dark:bg-white/20';
          if (statusBarcode) {
            statusBarcode.className = activeBadgeClass;
            statusBarcode.textContent = window.__t ? window.__t('labels.badge_active_for_print', 'Active for Print') : 'Active for Print';
          }
          if (statusShelf) {
            statusShelf.className = inactiveBadgeClass;
            statusShelf.textContent = window.__t ? window.__t('labels.badge_click_to_select', 'Click to Select') : 'Click to Select';
          }
        }
      }

      // Update Left Column Controls (Hide only barcode dock & symbology dock in Shelf Mode, leaving visible elements card visible!)
      const barcodeDock = document.getElementById('label-studio-multi-barcode-dock');
      const symbologyDock = document.getElementById('label-studio-symbology-dock');

      if (barcodeDock) {
        if (isShelf) {
          barcodeDock.classList.add('hidden');
        } else {
          barcodeDock.classList.remove('hidden');
        }
      }

      if (symbologyDock) {
        if (isShelf) symbologyDock.classList.add('hidden');
        else symbologyDock.classList.remove('hidden');
      }

      // Update Print CTA Button Text & Gradient
      const printBtn = document.getElementById('label-studio-execute-print-btn');
      const printText = document.getElementById('label-studio-execute-print-text');
      if (printBtn && printText) {
        printBtn.className = 'px-6 h-11 min-h-[44px] flex items-center justify-center gap-2 bg-gradient-to-r from-emerald-500 to-teal-600 hover:from-emerald-600 hover:to-teal-700 text-white font-black rounded-2xl text-xs shadow-lg shadow-emerald-500/25 transition-all cursor-pointer active:scale-[0.98]';
        if (isShelf) {
          printText.textContent = window.__t ? window.__t('labels.btn_print_shelf', 'Direct Print Shelf Tags') : 'Direct Print Shelf Tags';
        } else {
          printText.textContent = window.__t ? window.__t('labels.btn_print_thermal', 'Direct Print Labels') : 'Direct Print Labels';
        }
      }

      onLabelStudioConfigChange();
    }
    window.setLabelStudioMode = setLabelStudioMode;

    function onLabelStudioConfigChange() {
      const card = document.getElementById('label-studio-rendered-card');
      if (!card || !_labelStudioState.product) return;

      const p = _labelStudioState.product;
      const codeInput = document.getElementById('label-studio-code-input');
      const symbologySelect = document.getElementById('label-studio-symbology');
      const optShop = document.getElementById('label-opt-shop-name')?.checked !== false;
      const optProduct = document.getElementById('label-opt-product-name')?.checked !== false;
      const optUid = document.getElementById('label-opt-product-uid')?.checked !== false;
      const optPrice = document.getElementById('label-opt-price')?.checked !== false;
      const optCode = document.getElementById('label-opt-code-text')?.checked !== false;
      const optTag = document.getElementById('label-opt-tag-note')?.checked !== false;

      const codeVal = (codeInput?.value || p.barcode || p.uid || '').trim();
      const symbology = symbologySelect?.value || 'CODE128';
      const format = _labelStudioState.format;

      const shopName = (typeof config !== 'undefined' && config.business_name) ? config.business_name : 'Sizar POS';
      const labelUnitPrice = (p.price !== undefined && p.price !== null) ? p.price : 0;

      // Resolve tag / note for active barcode
      let activeTag = '';
      const allBarcodes = [];
      if (p.barcode) {
        const primTag = (Array.isArray(p.barcodes) ? (p.barcodes.find(b => b.is_primary === 1)?.label_tag || p.barcodes.find(b => b.is_primary === 1)?.label) : '') || p.barcode_label || p.barcode_tag || window._productPrimaryBarcodeTag || (window._registeredPrimaryBarcode ? window._registeredPrimaryBarcode.label_tag : '') || '';
        allBarcodes.push({ barcode_value: p.barcode, label_tag: primTag });
      }
      const secSources = [
        ...(Array.isArray(p.barcodes) ? p.barcodes : []),
        ...(Array.isArray(p.secondary_barcodes) ? p.secondary_barcodes : []),
        ...(Array.isArray(currentProductSecondaryBarcodes) ? currentProductSecondaryBarcodes : [])
      ];
      secSources.forEach(s => {
        const val = (s.barcode_value || s.barcode || '').trim();
        if (val) allBarcodes.push({ barcode_value: val, label_tag: s.label_tag || s.label || '' });
      });
      const found = allBarcodes.find(s => s.barcode_value.toUpperCase() === codeVal.toUpperCase());
      if (found && found.label_tag) {
        activeTag = found.label_tag;
      }
      if (!activeTag && (p.barcode || '').toUpperCase() === codeVal.toUpperCase()) {
        activeTag = p.barcode_label || p.barcode_tag || window._productPrimaryBarcodeTag || (window._registeredPrimaryBarcode ? window._registeredPrimaryBarcode.label_tag : '') || '';
      }
      if (!activeTag && document.getElementById('product-alias-label')?.value.trim()) {
        activeTag = document.getElementById('product-alias-label').value.trim();
      }

      // Render Barcode Vector inside Preview
      let barcodeMarkup = '';
      if (codeVal) {
        if (symbology === 'QR') {
          barcodeMarkup = `<div id="label-studio-qr-temp" class="flex justify-center items-center py-1"></div>`;
        } else {
          barcodeMarkup = BarcodeVectorEngine.renderCode128Svg(codeVal, {
            moduleWidth: format === '40x25' ? 1.5 : 2,
            barHeight: format === '40x25' ? 32 : 44,
            showText: false,
            quietZone: 5
          });
        }
      } else {
        barcodeMarkup = `<div class="py-2 text-[10px] text-slate-400 font-mono text-center">NO BARCODE</div>`;
      }

      // Format dimensions in preview pixels
      let previewWidth = '320px';
      let previewHeight = '192px'; // 50x30 ratio

      if (format === '40x25') {
        previewWidth = '280px';
        previewHeight = '175px';
      } else if (format === 'a4') {
        previewWidth = '320px';
        previewHeight = '169px'; // 70x37 ratio
      }

      card.style.width = previewWidth;
      card.style.minHeight = previewHeight;
      card.style.padding = format === '40x25' ? '8px' : '12px';

      card.innerHTML = `
        <div class="w-full h-full flex flex-col justify-between text-black font-sans leading-tight select-none">
          <!-- Top Row: Shop & Price -->
          <div class="flex items-center justify-between gap-1 pb-1 border-b border-black/15">
            ${optShop ? `<span class="text-[10px] font-extrabold uppercase tracking-tight truncate max-w-[60%]">${escapeHtml(shopName)}</span>` : `<span></span>`}
            ${optPrice ? `<span class="text-xs font-black font-mono tracking-tight">${formatPrice(labelUnitPrice, p.displayDecimals)}</span>` : `<span></span>`}
          </div>

          <!-- Middle Row: Product Name -->
          ${optProduct ? `<div class="text-xs font-black text-center truncate py-0.5 text-slate-900">${escapeHtml(p.name)}</div>` : ''}

          <!-- Barcode Core -->
          <div class="w-full flex justify-center items-center py-0.5">
            ${barcodeMarkup}
          </div>

          <!-- Bottom Row: Barcode Monospace String, Tag & Product UID -->
          <div class="flex items-center justify-between text-[9px] font-mono font-bold text-slate-700 pt-0.5 border-t border-black/15">
            <div class="flex items-center gap-1 truncate max-w-[65%]">
              ${optCode ? `<span class="truncate">${escapeHtml(codeVal)}</span>` : `<span></span>`}
              ${(optTag && activeTag) ? `<span class="text-[8px] font-sans px-1 py-0.2 rounded bg-black/5 border border-black/10 shrink-0">[${escapeHtml(activeTag)}]</span>` : ''}
            </div>
            ${optUid ? `<span class="text-[8px] text-slate-500 shrink-0">#${escapeHtml(p.uid || p.__backendId)}</span>` : `<span></span>`}
          </div>
        </div>
      `;

      if (symbology === 'QR' && codeVal) {
        const qrTemp = card.querySelector('#label-studio-qr-temp');
        if (qrTemp) {
          BarcodeVectorEngine.renderQrCode(qrTemp, codeVal, format === '40x25' ? 56 : 72);
        }
      }

      // Render Dedicated Shelf Price Tag Preview (Shelf Talker - High-Visibility Pricing)
      const shelfCard = document.getElementById('label-studio-rendered-shelf-card');
      if (shelfCard) {
        shelfCard.style.width = previewWidth;
        shelfCard.style.minHeight = previewHeight;
        shelfCard.style.padding = format === '40x25' ? '6px' : '10px';

        const priceFormatted = formatPrice(labelUnitPrice, p.displayDecimals);
        const priceSize = format === '40x25' ? 'text-xl' : 'text-3xl';

        shelfCard.innerHTML = `
          <div class="w-full h-full flex flex-col justify-between text-black font-sans leading-tight select-none border border-black/30 rounded-md p-1.5 bg-white shadow-2xs">
            <!-- Top Header: Shop Name & Live Date -->
            <div class="flex items-center justify-between gap-1 pb-1 border-b border-black/20 text-[9px] font-black uppercase tracking-wider text-slate-800">
              ${optShop ? `<span class="truncate max-w-[65%]">${escapeHtml(shopName)}</span>` : `<span></span>`}
              <span class="text-slate-500 font-mono text-[8px]">${formatDate(new Date())}</span>
            </div>

            <!-- Shelf Center: GIANT HIGH-CONTRAST BOLD PRICE (Easily readable from distance on shelf) -->
            <div class="py-1 flex flex-col items-center justify-center text-center my-auto">
              ${optPrice ? `
                <span class="${priceSize} font-black font-mono tracking-tight text-slate-950 tabular-nums leading-none drop-shadow-2xs">
                  ${priceFormatted}
                </span>
              ` : `
                <span class="text-xs font-bold text-slate-400 italic">No Price Tag</span>
              `}
            </div>

            <!-- Shelf Bottom: Bold Product Name & Monospace Barcode String -->
            <div class="pt-1 border-t border-black/20">
              ${optProduct ? `<div class="text-[11px] font-black text-center text-slate-900 truncate leading-snug" title="${escapeHtml(p.name)}">${escapeHtml(p.name)}</div>` : ''}
              <div class="flex items-center justify-between text-[8px] font-mono text-slate-600 pt-0.5">
                ${optCode ? `<span class="truncate max-w-[70%]">${escapeHtml(codeVal)}</span>` : `<span></span>`}
                ${optUid ? `<span class="shrink-0 text-slate-400">#${escapeHtml(p.uid || p.__backendId)}</span>` : `<span></span>`}
              </div>
            </div>
          </div>
        `;
      }
    }
    window.onLabelStudioConfigChange = onLabelStudioConfigChange;

    function adjustLabelQuantity(delta) {
      const input = document.getElementById('label-studio-quantity');
      if (!input) return;
      let val = parseInt(input.value, 10) || 1;
      val = Math.max(1, Math.min(500, val + delta));
      input.value = val;
      _labelStudioState.quantity = val;
    }
    window.adjustLabelQuantity = adjustLabelQuantity;

    function setLabelQuantity(n) {
      const input = document.getElementById('label-studio-quantity');
      if (!input) return;
      input.value = Math.max(1, Math.min(500, n));
      _labelStudioState.quantity = input.value;
    }
    window.setLabelQuantity = setLabelQuantity;

    function setLabelQuantityFromStock() {
      if (!_labelStudioState.product) return;
      const stock = typeof getProductAvailableQuantity === 'function' ? getProductAvailableQuantity(_labelStudioState.product.__backendId) : 1;
      const qty = Math.max(1, Math.min(500, Math.floor(Number(stock) || 1)));
      setLabelQuantity(qty);
    }
    window.setLabelQuantityFromStock = setLabelQuantityFromStock;

    function onLabelStudioBarcodeChipClick(val) {
      const selectorEl = document.getElementById('label-studio-barcode-selector');
      if (selectorEl) {
        selectorEl.value = val;
      }
      onLabelStudioBarcodeSelectorChange(val);
    }
    window.onLabelStudioBarcodeChipClick = onLabelStudioBarcodeChipClick;

    function onLabelStudioBarcodeSelectorChange(val) {
      const selectorEl = document.getElementById('label-studio-barcode-selector');
      const codeInput = document.getElementById('label-studio-code-input');
      const symbologySelect = document.getElementById('label-studio-symbology');
      if (!val) return;

      if (selectorEl && selectorEl.value !== val) {
        selectorEl.value = val;
      }

      const selectedOpt = selectorEl ? selectorEl.options[selectorEl.selectedIndex] : null;
      const optType = selectedOpt?.dataset?.type || (_labelStudioState.product?.barcode_type || 'CODE128');

      if (codeInput) codeInput.value = val;
      if (symbologySelect) symbologySelect.value = optType === 'QR' ? 'QR' : 'CODE128';

      // Update active chip styling in container
      const chips = document.querySelectorAll('.label-studio-chip');
      chips.forEach(chip => {
        const chipVal = chip.dataset.barcodeVal;
        if (chipVal === val) {
          chip.className = 'label-studio-chip h-9 min-h-[36px] px-3 rounded-xl text-xs font-bold transition-all cursor-pointer flex items-center gap-2 active:scale-95 shrink-0 bg-gradient-to-r from-emerald-500 to-teal-600 text-white shadow-sm ring-2 ring-emerald-400/60 dark:ring-emerald-500/60 border border-emerald-500';
          if (typeof chip.scrollIntoView === 'function') {
            chip.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'nearest' });
          }
        } else {
          chip.className = 'label-studio-chip h-9 min-h-[36px] px-3 rounded-xl text-xs font-bold transition-all cursor-pointer flex items-center gap-2 active:scale-95 shrink-0 bg-white/90 dark:bg-[#080b10] border border-slate-200/80 dark:border-white/[0.08] text-slate-700 dark:text-slate-300 hover:border-emerald-400 dark:hover:border-emerald-600 hover:bg-slate-50 dark:hover:bg-white/[0.04]';
        }
      });

      onLabelStudioConfigChange();
    }
    window.onLabelStudioBarcodeSelectorChange = onLabelStudioBarcodeSelectorChange;

    async function executeBarcodeLabelPrint() {
      if (!_labelStudioState.product) return;
      const p = _labelStudioState.product;
      const isShelfMode = (_labelStudioState.mode === 'shelf');
      const codeInput = document.getElementById('label-studio-code-input');
      const symbologySelect = document.getElementById('label-studio-symbology');
      const qtyInput = document.getElementById('label-studio-quantity');
      const offsetInput = document.getElementById('label-studio-a4-offset');

      const optShop = document.getElementById('label-opt-shop-name')?.checked !== false;
      const optProduct = document.getElementById('label-opt-product-name')?.checked !== false;
      const optUid = document.getElementById('label-opt-product-uid')?.checked !== false;
      const optPrice = document.getElementById('label-opt-price')?.checked !== false;
      const optCode = document.getElementById('label-opt-code-text')?.checked !== false;
      const optTag = document.getElementById('label-opt-tag-note')?.checked !== false;

      const codeVal = (codeInput?.value || p.barcode || p.uid || '').trim();
      const symbology = symbologySelect?.value || 'CODE128';
      const quantity = Math.max(1, Math.min(500, parseInt(qtyInput?.value, 10) || 1));
      const offset = Math.max(0, Math.min(23, parseInt(offsetInput?.value, 10) || 0));
      const format = _labelStudioState.format;

      // Mission 52 Phase 3.5: Batch Print All Saved Barcodes Mode
      const isBatchAll = document.getElementById('label-studio-batch-all-toggle')?.checked === true;
      let targetList = [];

      if (isBatchAll) {
        // Collect all distinct saved barcodes for this product
        const primaryCode = (p.barcode || p.uid || '').trim();
        const primaryType = p.barcode_type || 'CODE128';
        if (primaryCode) {
          targetList.push({
            code: primaryCode,
            type: primaryType,
            label: window.__t ? window.__t('products.lbl_primary', 'Primary') : 'Primary'
          });
        }

        const secondaries = p.secondary_barcodes || (Array.isArray(p.barcodes) ? p.barcodes.filter(b => b.is_primary === 0) : (Array.isArray(currentProductSecondaryBarcodes) ? currentProductSecondaryBarcodes : []));
        if (Array.isArray(secondaries)) {
          secondaries.forEach(sb => {
            const val = (sb.barcode_value || sb.barcode || '').trim();
            if (val && !targetList.some(item => item.code.toUpperCase() === val.toUpperCase())) {
              targetList.push({
                code: val,
                type: sb.barcode_type || sb.type || 'CODE128',
                label: sb.label_tag || sb.label || ''
              });
            }
          });
        }
      }

      if (targetList.length === 0) {
        if (!codeVal) {
          showToast(window.__t ? window.__t('products.toast_barcode_required', 'Barcode is required for printing') : 'Barcode is required for printing', 'default');
          return;
        }

        let singleTag = '';
        const allBarcodes = [];
        if (p.barcode) {
          const primTag = (Array.isArray(p.barcodes) ? (p.barcodes.find(b => b.is_primary === 1)?.label_tag || p.barcodes.find(b => b.is_primary === 1)?.label) : '') || p.barcode_label || p.barcode_tag || window._productPrimaryBarcodeTag || (window._registeredPrimaryBarcode ? window._registeredPrimaryBarcode.label_tag : '') || '';
          allBarcodes.push({ barcode_value: p.barcode, label_tag: primTag });
        }
        const secSources = [
          ...(Array.isArray(p.barcodes) ? p.barcodes : []),
          ...(Array.isArray(p.secondary_barcodes) ? p.secondary_barcodes : []),
          ...(Array.isArray(currentProductSecondaryBarcodes) ? currentProductSecondaryBarcodes : [])
        ];
        secSources.forEach(s => {
          const val = (s.barcode_value || s.barcode || '').trim();
          if (val) allBarcodes.push({ barcode_value: val, label_tag: s.label_tag || s.label || '' });
        });
        const found = allBarcodes.find(s => s.barcode_value.toUpperCase() === codeVal.toUpperCase());
        if (found && found.label_tag) singleTag = found.label_tag;
        if (!singleTag && (p.barcode || '').toUpperCase() === codeVal.toUpperCase()) {
          singleTag = p.barcode_label || p.barcode_tag || window._productPrimaryBarcodeTag || (window._registeredPrimaryBarcode ? window._registeredPrimaryBarcode.label_tag : '') || '';
        }
        if (!singleTag && document.getElementById('product-alias-label')?.value.trim()) {
          singleTag = document.getElementById('product-alias-label').value.trim();
        }

        targetList.push({
          code: codeVal,
          type: symbology,
          label: singleTag
        });
      }

      const shopName = (typeof config !== 'undefined' && config.business_name) ? config.business_name : 'Sizar POS';
      const labelUnitPrice = (p.price !== undefined && p.price !== null) ? p.price : 0;

      // Generate HTML for each label in targetList
      const labelItemsHtmlArray = [];
      for (const t of targetList) {
        let barcodeHtml = '';
        if (t.type === 'QR') {
          const qrDataUrl = typeof generateQRDataURL === 'function' ? await generateQRDataURL(t.code) : '';
          const qrSize = format === '40x25' ? '18mm' : '22mm';
          barcodeHtml = `<img src="${qrDataUrl}" style="width:${qrSize}; height:${qrSize}; display:block; margin:0 auto;" alt="QR">`;
        } else {
          barcodeHtml = BarcodeVectorEngine.renderCode128Svg(t.code, {
            moduleWidth: format === '40x25' ? 1.4 : 1.8,
            barHeight: format === '40x25' ? 30 : 42,
            showText: false,
            quietZone: 4
          });
        }

        let singleItemHtml = '';

        if (isShelfMode) {
          const priceFontSize = (format === '40x25') ? '15pt' : '20pt';
          singleItemHtml = `
            <div class="shelf-inner">
              <div class="shelf-header">
                ${optShop ? `<span class="shelf-shop">${escapeHtml(shopName)}</span>` : `<span></span>`}
                <span class="shelf-date">${formatDate(new Date())}</span>
              </div>
              <div class="shelf-price-box">
                <span class="shelf-price-val" style="font-size: ${priceFontSize};">${optPrice ? formatPrice(labelUnitPrice, p.displayDecimals) : ''}</span>
              </div>
              ${optProduct ? `<div class="shelf-name">${escapeHtml(p.name)}</div>` : ''}
              <div class="shelf-footer">
                ${optCode ? `<span class="shelf-code">${escapeHtml(t.code)}</span>` : `<span></span>`}
                ${optUid ? `<span class="shelf-uid">#${escapeHtml(p.uid || p.__backendId)}</span>` : `<span></span>`}
              </div>
            </div>
          `;
        } else {
          singleItemHtml = `
            <div class="label-inner">
              <div class="label-header">
                ${optShop ? `<span class="label-shop">${escapeHtml(shopName)}</span>` : `<span></span>`}
                ${optPrice ? `<span class="label-price">${formatPrice(labelUnitPrice, p.displayDecimals)}</span>` : `<span></span>`}
              </div>
              ${optProduct ? `<div class="label-name">${escapeHtml(p.name)}</div>` : ''}
              <div class="label-barcode">${barcodeHtml}</div>
              <div class="label-footer">
                ${optCode ? `<span class="label-code">${escapeHtml(t.code)}${(optTag && t.label) ? ` (${escapeHtml(t.label)})` : ''}</span>` : `<span></span>`}
                ${optUid ? `<span class="label-uid">#${escapeHtml(p.uid || p.__backendId)}</span>` : `<span></span>`}
              </div>
            </div>
          `;
        }

        for (let q = 0; q < quantity; q++) {
          labelItemsHtmlArray.push(singleItemHtml);
        }
      }

      let printHtml = '';

      if (format === 'a4') {
        const totalSlotsNeeded = offset + labelItemsHtmlArray.length;
        const totalSheets = Math.ceil(totalSlotsNeeded / 24);
        let itemsPrinted = 0;
        let sheetsHtml = '';

        for (let s = 0; s < totalSheets; s++) {
          let sheetCells = '';
          for (let c = 0; c < 24; c++) {
            const currentSlot = s * 24 + c;
            if (currentSlot < offset || itemsPrinted >= labelItemsHtmlArray.length) {
              sheetCells += `<div class="a4-cell empty"></div>`;
            } else {
              sheetCells += `<div class="a4-cell">${labelItemsHtmlArray[itemsPrinted]}</div>`;
              itemsPrinted++;
            }
          }
          sheetsHtml += `<div class="a4-sheet">${sheetCells}</div>`;
        }

        printHtml = `<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <title>${isShelfMode ? 'A4 Shelf Tag Sheet' : 'A4 Label Sheet'} - ${escapeHtml(p.name)}</title>
  <style>
    @page { size: 210mm 297mm; margin: 0mm; }
    * { box-sizing: border-box; margin: 0; padding: 0; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
    body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif; background: #fff; color: #000; }
    .a4-sheet { width: 210mm; height: 297mm; display: grid; grid-template-columns: repeat(3, 70mm); grid-template-rows: repeat(8, 37.1mm); page-break-after: always; break-after: page; }
    .a4-sheet:last-child { page-break-after: avoid; break-after: avoid; }
    .a4-cell { width: 70mm; height: 37.1mm; padding: 2mm 3mm; overflow: hidden; display: flex; flex-direction: column; justify-content: center; }
    .a4-cell.empty { visibility: hidden; }
    .label-inner { width: 100%; height: 100%; display: flex; flex-direction: column; justify-content: space-between; overflow: hidden; }
    .label-header { display: flex; justify-content: space-between; align-items: center; border-bottom: 0.5pt solid #bbb; padding-bottom: 1mm; font-size: 7pt; font-weight: 800; }
    .label-shop { max-width: 60%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
    .label-price { font-family: monospace; font-size: 8pt; font-weight: 900; }
    .label-name { font-size: 8pt; font-weight: 900; text-align: center; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; padding: 0.5mm 0; }
    .label-barcode { display: flex; justify-content: center; align-items: center; max-height: 18mm; overflow: hidden; }
    .label-barcode svg { width: 100%; height: auto; max-height: 18mm; }
    .label-footer { display: flex; justify-content: space-between; align-items: center; border-top: 0.5pt solid #bbb; padding-top: 0.5mm; font-size: 6pt; font-family: monospace; font-weight: 700; color: #333; }
    .shelf-inner { width: 100%; height: 100%; border: 1pt solid #000; border-radius: 2mm; padding: 1.5mm; display: flex; flex-direction: column; justify-content: space-between; overflow: hidden; text-align: center; }
    .shelf-header { display: flex; justify-content: space-between; align-items: center; border-bottom: 0.5pt solid #888; padding-bottom: 0.5mm; font-size: 6.5pt; font-weight: 800; text-transform: uppercase; }
    .shelf-price-box { display: flex; align-items: center; justify-content: center; margin: auto 0; padding: 0.5mm 0; }
    .shelf-price-val { font-family: monospace; font-weight: 900; letter-spacing: -0.5pt; color: #000; }
    .shelf-name { font-size: 7.5pt; font-weight: 900; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; border-top: 0.5pt solid #888; padding-top: 0.5mm; }
    .shelf-footer { display: flex; justify-content: space-between; align-items: center; font-size: 5pt; font-family: monospace; color: #333; padding-top: 0.5mm; }
  </style>
</head>
<body>
  ${sheetsHtml}
</body>
</html>`;
      } else {
        const widthMm = format === '40x25' ? '40mm' : '50mm';
        const heightMm = format === '40x25' ? '25mm' : '30mm';
        const padMm = format === '40x25' ? '1.5mm' : '2mm';
        const barMaxH = format === '40x25' ? '13mm' : '17mm';

        let labelsRepeated = labelItemsHtmlArray.map(itemHtml => `<div class="${isShelfMode ? 'thermal-shelf-tag' : 'thermal-label'}">${itemHtml}</div>`).join('');

        printHtml = `<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <title>${isShelfMode ? 'Thermal Shelf Tag' : 'Thermal Label'} - ${escapeHtml(p.name)}</title>
  <style>
    @page { size: ${widthMm} ${heightMm}; margin: 0mm; }
    * { box-sizing: border-box; margin: 0; padding: 0; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
    body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif; background: #fff; color: #000; width: ${widthMm}; }
    .thermal-label, .thermal-shelf-tag { width: ${widthMm}; height: ${heightMm}; max-width: ${widthMm}; max-height: ${heightMm}; padding: ${padMm}; display: flex; flex-direction: column; justify-content: space-between; overflow: hidden; page-break-after: always; break-after: page; }
    .thermal-label:last-child, .thermal-shelf-tag:last-child { page-break-after: avoid; break-after: avoid; }
    .label-inner { width: 100%; height: 100%; display: flex; flex-direction: column; justify-content: space-between; overflow: hidden; }
    .label-header { display: flex; justify-content: space-between; align-items: center; border-bottom: 0.5pt solid #ccc; padding-bottom: 0.5mm; font-size: 6.5pt; font-weight: 800; }
    .label-shop { max-width: 60%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
    .label-price { font-family: monospace; font-size: 7.5pt; font-weight: 900; }
    .label-name { font-size: 7.5pt; font-weight: 900; text-align: center; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; padding: 0.5mm 0; }
    .label-barcode { display: flex; justify-content: center; align-items: center; max-height: ${barMaxH}; overflow: hidden; }
    .label-barcode svg { width: 100%; height: auto; max-height: ${barMaxH}; }
    .label-footer { display: flex; justify-content: space-between; align-items: center; border-top: 0.5pt solid #ccc; padding-top: 0.5mm; font-size: 5.5pt; font-family: monospace; font-weight: 700; color: #333; }
    .shelf-inner { width: 100%; height: 100%; border: 1pt solid #000; border-radius: 2mm; padding: 1.5mm; display: flex; flex-direction: column; justify-content: space-between; overflow: hidden; text-align: center; }
    .shelf-header { display: flex; justify-content: space-between; align-items: center; border-bottom: 0.5pt solid #888; padding-bottom: 0.5mm; font-size: 6.5pt; font-weight: 800; text-transform: uppercase; }
    .shelf-price-box { display: flex; align-items: center; justify-content: center; margin: auto 0; padding: 0.5mm 0; }
    .shelf-price-val { font-family: monospace; font-weight: 900; letter-spacing: -0.5pt; color: #000; }
    .shelf-name { font-size: 7.5pt; font-weight: 900; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; border-top: 0.5pt solid #888; padding-top: 0.5mm; }
    .shelf-footer { display: flex; justify-content: space-between; align-items: center; font-size: 5pt; font-family: monospace; color: #333; padding-top: 0.5mm; }
  </style>
</head>
<body>
  ${labelsRepeated}
</body>
</html>`;
      }

      closeProductLabelStudioModal();
      printHtmlDirectly(printHtml, isShelfMode ? `Shelf Tag - ${p.name}` : `Label - ${p.name}`);
      const totalPrinted = labelItemsHtmlArray.length;
      if (isShelfMode) {
        showToast(window.__t ? window.__t('labels.toast_print_shelf_started', `Printing ${totalPrinted} shelf tag(s)...`, { count: totalPrinted }) : `Printing ${totalPrinted} shelf tag(s)...`, 'default');
      } else if (isBatchAll && targetList.length > 1) {
        showToast(window.__t ? window.__t('labels.batch_print_summary', `Batch printing ${targetList.length} codes (${totalPrinted} stickers)...`, { count: targetList.length, total: totalPrinted }) : `Batch printing ${targetList.length} codes (${totalPrinted} stickers)...`, 'default');
      } else {
        showToast(window.__t ? window.__t('labels.toast_print_started', `Printing ${totalPrinted} label(s)...`, { count: totalPrinted }) : `Printing ${totalPrinted} label(s)...`, 'default');
      }
    }
    window.executeBarcodeLabelPrint = executeBarcodeLabelPrint;

    // =========================================================================
    // MISSION 52 PHASE 3: POS HARDWARE WEDGE SCANNER ENGINE
    // Layout-invariant (e.code decoding), <50ms timing threshold, anti-bleed
    // =========================================================================
    let _scannerBuffer = '';
    let _scannerLastKeyTime = 0;
    let _scannerLeakedEl = null;
    let _scannerLeakedOriginalVal = null;

    function decodeWedgeKeystroke(e) {
      if (!e) return '';
      if (e.code && e.code.startsWith('Digit')) {
        return e.code.replace('Digit', '');
      }
      if (e.code && e.code.startsWith('Numpad') && e.code.length === 7) {
        return e.code.replace('Numpad', '');
      }
      if (e.code === 'Minus' || e.code === 'NumpadSubtract') {
        return '-';
      }
      if (e.key && e.key.length === 1) {
        return e.key;
      }
      return '';
    }

    function playScannerChime(isSuccess = true) {
      try {
        const AudioCtx = window.AudioContext || window.webkitAudioContext;
        if (!AudioCtx) return;
        const ctx = new AudioCtx();
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.connect(gain);
        gain.connect(ctx.destination);
        if (isSuccess) {
          osc.type = 'sine';
          osc.frequency.setValueAtTime(880, ctx.currentTime);
          gain.gain.setValueAtTime(0.12, ctx.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.08);
          osc.start();
          osc.stop(ctx.currentTime + 0.08);
        } else {
          osc.type = 'sawtooth';
          osc.frequency.setValueAtTime(320, ctx.currentTime);
          gain.gain.setValueAtTime(0.15, ctx.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.14);
          osc.start();
          osc.stop(ctx.currentTime + 0.14);
        }
      } catch (e) {
        // Audio output muted or blocked
      }
    }
    window.playScannerChime = playScannerChime;

    function handleHardwareBarcodeScanned(rawCode) {
      if (!rawCode) return;
      const code = String(rawCode).trim();
      if (!code) return;

      const lower = code.toLowerCase();
      const products = (typeof getProducts === 'function' ? getProducts() : productsCache) || [];
      const product = products.find(p => {
        if (p.deletedAt) return false;
        if (p.barcode && String(p.barcode).trim().toLowerCase() === lower) return true;
        if (p.uid && String(p.uid).trim().toLowerCase() === lower) return true;
        if (Array.isArray(p.barcodes)) {
          return p.barcodes.some(b => String(b.barcode_value || b.barcode || '').trim().toLowerCase() === lower);
        }
        return false;
      });

      if (!product) {
        playScannerChime(false);
        if (typeof showToast === 'function') {
          showToast(window.__t ? window.__t('products.barcode_not_found', `Barcode not found: ${code}`, { barcode: code }) : `Barcode not found: ${code}`, 'default');
        }
        return;
      }

      // Success chime
      playScannerChime(true);

      const isCustomProductModalOpen = document.getElementById('custom-sale-product-modal') && !document.getElementById('custom-sale-product-modal').classList.contains('hidden');
      const isCustomSaleModalOpen = document.getElementById('custom-sale-modal') && !document.getElementById('custom-sale-modal').classList.contains('hidden');
      const isPosPage = !document.getElementById('page-pos')?.classList.contains('hidden');

      if (isCustomProductModalOpen) {
        const sel = document.getElementById('custom-sale-product-select');
        if (sel) {
          sel.value = product.__backendId;
          if (typeof onCustomProductSelectionChanged === 'function') onCustomProductSelectionChanged();
          else if (typeof onCustomProductSelected === 'function') onCustomProductSelected();
        }
        return;
      }

      if (isCustomSaleModalOpen) {
        if (typeof openCustomSaleProductModal === 'function') {
          openCustomSaleProductModal();
          setTimeout(() => {
            const sel = document.getElementById('custom-sale-product-select');
            if (sel) {
              sel.value = product.__backendId;
              if (typeof onCustomProductSelectionChanged === 'function') onCustomProductSelectionChanged();
              else if (typeof onCustomProductSelected === 'function') onCustomProductSelected();
            }
          }, 60);
        }
        return;
      }

      if (isPosPage) {
        if (typeof showSalePriceModal === 'function') {
          showSalePriceModal(product.__backendId, 'product');
        }
        return;
      }

      // On products page or other views: filter or switch to POS
      const searchInput = document.getElementById('product-search');
      if (searchInput && !document.getElementById('page-products')?.classList.contains('hidden')) {
        searchInput.value = product.name;
        if (typeof filterProducts === 'function') filterProducts();
      } else {
        if (typeof navigateTo === 'function') {
          navigateTo('pos');
          setTimeout(() => {
            if (typeof showSalePriceModal === 'function') showSalePriceModal(product.__backendId, 'product');
          }, 100);
        }
      }
    }
    window.handleHardwareBarcodeScanned = handleHardwareBarcodeScanned;
    window.decodeWedgeKeystroke = decodeWedgeKeystroke;

    // Attach capture listener once
    if (!window._hardwareScannerInitialized) {
      window._hardwareScannerInitialized = true;
      window.addEventListener('keydown', function (e) {
        if (e.key === 'Tab' || e.key === 'Escape' || e.key === 'Shift' || e.key === 'Control' || e.key === 'Alt') {
          return;
        }

        const now = performance.now();
        const elapsed = now - _scannerLastKeyTime;
        _scannerLastKeyTime = now;

        const char = decodeWedgeKeystroke(e);

        if (e.key === 'Enter') {
          if (_scannerBuffer.length >= 3 && elapsed < 85) {
            e.preventDefault();
            e.stopPropagation();

            const scanned = _scannerBuffer.trim();
            _scannerBuffer = '';

            // If actively typing into a dedicated barcode registration field, allow the scan to persist directly
            if (_scannerLeakedEl && (_scannerLeakedEl.id === 'product-barcode' || _scannerLeakedEl.id === 'scan-barcode-input')) {
              _scannerLeakedEl.value = scanned;
              _scannerLeakedEl.dispatchEvent(new Event('input', { bubbles: true }));
              _scannerLeakedEl = null;
              _scannerLeakedOriginalVal = null;
              playScannerChime(true);
              return;
            }

            // Anti-bleed rollback for general inputs
            if (_scannerLeakedEl && typeof _scannerLeakedEl.value === 'string' && _scannerLeakedOriginalVal !== null) {
              _scannerLeakedEl.value = _scannerLeakedOriginalVal;
            }
            _scannerLeakedEl = null;
            _scannerLeakedOriginalVal = null;

            handleHardwareBarcodeScanned(scanned);
            return;
          }
          _scannerBuffer = '';
          _scannerLeakedEl = null;
          _scannerLeakedOriginalVal = null;
          return;
        }

        if (elapsed < 50 && char) {
          _scannerBuffer += char;
        } else if (char) {
          _scannerBuffer = char;
          const activeEl = document.activeElement;
          if (activeEl && (activeEl.tagName === 'INPUT' || activeEl.tagName === 'TEXTAREA')) {
            _scannerLeakedEl = activeEl;
            _scannerLeakedOriginalVal = activeEl.value;
          } else {
            _scannerLeakedEl = null;
            _scannerLeakedOriginalVal = null;
          }
        } else {
          _scannerBuffer = '';
          _scannerLeakedEl = null;
          _scannerLeakedOriginalVal = null;
        }
      }, true);
    }

    function updateProductModalPresetLayout() {
      const activePreset = window.currentBusinessPreset || (typeof config !== 'undefined' && (config.business_preset || config.store_preset)) || 'phone_repair';
      const isPhoneRepair = (activePreset === 'phone_repair');
      
      const dialog = document.getElementById('product-modal-dialog');
      const grid = document.getElementById('product-modal-grid');
      const leftCol = document.getElementById('product-modal-left-col');
      const rightCol = document.getElementById('product-modal-right-col');
      const priceSection = document.getElementById('product-price-section');
      const barcodeWrapper = document.getElementById('product-barcode-wrapper');

      if (isPhoneRepair) {
        if (dialog) {
          dialog.classList.remove('max-w-xl');
          dialog.classList.add('max-w-4xl', 'lg:max-w-5xl', 'xl:max-w-6xl');
        }
        if (grid) {
          grid.className = 'grid grid-cols-1 lg:grid-cols-12 gap-5 items-start';
        }
        if (leftCol) {
          leftCol.className = 'lg:col-span-6 space-y-4';
        }
        if (rightCol) {
          rightCol.className = 'lg:col-span-6 space-y-4';
          rightCol.classList.remove('hidden');
        }
        if (priceSection) {
          priceSection.classList.remove('hidden');
        }
        if (barcodeWrapper) {
          barcodeWrapper.classList.remove('hidden');
        }
      } else {
        // crypto_cash mode: compact single-column layout, no barcode workstation, no default selling price
        if (dialog) {
          dialog.classList.remove('max-w-4xl', 'lg:max-w-5xl', 'xl:max-w-6xl');
          dialog.classList.add('max-w-xl');
        }
        if (grid) {
          grid.className = 'grid grid-cols-1 gap-4 items-start';
        }
        if (leftCol) {
          leftCol.className = 'col-span-12 space-y-4';
        }
        if (rightCol) {
          rightCol.classList.add('hidden');
        }
        if (priceSection) {
          priceSection.classList.add('hidden');
        }
        if (barcodeWrapper) {
          barcodeWrapper.classList.add('hidden');
        }
      }
    }
    window.updateProductModalPresetLayout = updateProductModalPresetLayout;

