    function editProduct(id) {
      const product = productsCache.find(p => p.__backendId === id);
      if (!product) return;

      document.getElementById('product-edit-id').value = id;
      const modalTitle = document.getElementById('product-modal-title');
      if (modalTitle) modalTitle.textContent = window.__t ? window.__t('products.modal_title_edit', 'Edit Product Details') : 'Edit Product Details';
      document.getElementById('product-name').value = product.name;
      document.getElementById('product-description').value = product.description || '';
      document.getElementById('product-picture-data').value = product.picture || '';
      const prodPicName = product.picture_name || product.pictureName || '';
      document.getElementById('product-picture-name').value = prodPicName;
      const prodChosenText = document.getElementById('product-file-chosen-text');
      if (prodChosenText) prodChosenText.textContent = prodPicName || (product.picture ? 'Image attached' : 'No file chosen');
      if (document.getElementById('product-barcode')) document.getElementById('product-barcode').value = product.barcode || '';
      if (document.getElementById('product-price')) {
        document.getElementById('product-price').value = (product.price !== undefined && product.price !== null && parseFloat(product.price) > 0)
          ? (typeof formatDecimalInput === 'function' ? formatDecimalInput(product.price, product.displayDecimals) : String(product.price).replace(/\.?0+$/, ''))
          : '';
      }
      if (document.getElementById('product-price-currency-badge')) {
        document.getElementById('product-price-currency-badge').textContent = (typeof config !== 'undefined' && config.currency_symbol) || 'DZD';
      }
      document.getElementById('product-display-decimals').value = product.displayDecimals !== null && product.displayDecimals !== undefined ? product.displayDecimals : '';
      document.getElementById('product-display-decimals').disabled = false;
      document.getElementById('product-display-decimals').dataset.originalValue = document.getElementById('product-display-decimals').value;
      document.getElementById('product-display-decimals-create-hint').classList.add('hidden');
      // Enable stock addition section when editing existing product
      const stockWrapper = document.getElementById('product-initial-stock-wrapper');
      if (stockWrapper) stockWrapper.classList.remove('hidden');
      const stockContent = document.getElementById('product-initial-stock-content');
      if (stockContent) stockContent.classList.add('hidden');
      const stockBtnIcon = document.getElementById('product-initial-stock-btn-icon');
      if (stockBtnIcon) stockBtnIcon.textContent = '+';
      const stockBtnText = document.getElementById('product-initial-stock-btn-text');
      if (stockBtnText) stockBtnText.textContent = window.__t ? window.__t('products.btn_restock', 'Restock') : 'Restock';
      if (document.getElementById('product-initial-qty')) document.getElementById('product-initial-qty').value = '';
      if (document.getElementById('product-initial-cost')) document.getElementById('product-initial-cost').value = '';
      if (document.getElementById('product-initial-total-val')) document.getElementById('product-initial-total-val').textContent = '0.00 ' + ((typeof config !== 'undefined' && config.currency_symbol) || 'DZD');

      const pColor = product.color || '#10b981';
      document.getElementById('product-color-picker').value = pColor;
      document.getElementById('product-color-hex').value = pColor.toUpperCase();

      if (product.picture) {
        document.getElementById('product-image-img').src = product.picture;
        document.getElementById('product-image-img').classList.remove('hidden');
        document.getElementById('product-default-icon').classList.add('hidden');
        document.getElementById('product-image-remove-btn').classList.remove('hidden');
      } else {
        document.getElementById('product-image-img').classList.add('hidden');
        document.getElementById('product-default-icon').classList.remove('hidden');
        document.getElementById('product-image-remove-btn').classList.add('hidden');
      }

      // Mission 52: Hydrate Barcode Section 2.5
      hydrateProductModalBarcodeSection(product);

      // Mission 53.6: Dynamic preset adaptation (Phone Repair: 2-column wide; Crypto: 1-column compact)
      updateProductModalPresetLayout();

      updateCategorySelects();
      document.getElementById('product-category').value = product.categoryId;

      document.getElementById('product-modal').classList.remove('hidden');
    }

