    function handleProductImageUpload(event) {
      const file = event.target.files[0];
      if (!file) return;

      if (file.size > 25 * 1024 * 1024) {
        showToast(_t('products.toast_image_size_exceeded', 'Image file size exceeds 25MB limit. Please select a smaller photo.'), 'default');
        return;
      }
      // Reset so re-selecting the same file fires change again.
      event.target.value = '';

      const reader = new FileReader();
      reader.onload = async function (e) {
        try {
          // Same crop UI as the logo (square): zoom, drag, grid, background fill.
          const data = await openCropModal(e.target.result, 'square');
          document.getElementById('product-picture-data').value = data;
          document.getElementById('product-picture-name').value = file.name;
          document.getElementById('product-image-img').src = data;
          document.getElementById('product-image-img').classList.remove('hidden');
          document.getElementById('product-default-icon').classList.add('hidden');
          document.getElementById('product-image-remove-btn').classList.remove('hidden');
          const chosenLabel = document.getElementById('product-file-chosen-text');
          if (chosenLabel) chosenLabel.textContent = file.name;
        } catch (err) {
          if (err.message !== 'cancelled') showToast(_t('products.toast_image_process_failed', 'Failed to process image. Please try another.'));
        }
      };
      reader.onerror = () => showToast(_t('products.toast_image_read_failed', 'Failed to read file.'));
      reader.readAsDataURL(file);
    }

