    function formatAuditFieldName(field) {
      if (!field) return '';
      const key = `audit.field_${field}`;
      const fallbacks = {
        barcode: 'Barcode',
        has_barcode: 'Barcode Toggle',
        color: 'Color',
        secondary_barcodes: 'Secondary Barcodes',
        secondary_barcodes_updated: 'Secondary Barcodes Updated',
        name: 'Name',
        category: 'Category',
        category_id: 'Category',
        picture: 'Picture',
        picture_name: 'Picture Name',
        price: 'Price',
        description: 'Description',
        display_decimals: 'Display Decimals',
        hidden_residual: 'Hidden Residual'
      };
      const fallback = fallbacks[field] || field.replace(/_/g, ' ');
      return window.__t ? window.__t(key, fallback) : fallback;
    }
    window.formatAuditFieldName = formatAuditFieldName;

    function formatAuditValue(val, field) {
      if (val === 'empty' || val === '' || val === null || val === undefined) {
        return window.__t ? window.__t('audit.val_empty', '(empty)') : '(empty)';
      }
      if (val === 'unset') {
        return window.__t ? window.__t('audit.val_unset', '(unset)') : '(unset)';
      }
      if (field === 'has_barcode') {
        if (val == 1 || val === '1') {
          return window.__t ? window.__t('audit.val_enabled', '(enabled)') : '(enabled)';
        }
        return window.__t ? window.__t('audit.val_disabled', '(disabled)') : '(disabled)';
      }
      return val;
    }
    window.formatAuditValue = formatAuditValue;

    function renderProductHistory(history) {
      const tbody = document.getElementById('product-history-table');
      const mobileFeed = document.getElementById('product-history-mobile-feed');
      if (!history || history.length === 0) {
        const noHistMsg = window.__t ? window.__t('common.no_history', 'No history available') : 'No history available';
        if (tbody) tbody.innerHTML = `<tr><td colspan="4" class="px-4 py-8 text-center text-slate-400">${noHistMsg}</td></tr>`;
        if (mobileFeed) mobileFeed.innerHTML = `<div class="p-6 text-center text-slate-400 text-xs bg-slate-50/50 dark:bg-[#0d1117] rounded-2xl border border-slate-200/80 dark:border-white/[0.06]">${noHistMsg}</div>`;
        return;
      }

      const arrow = '<span class="rtl-flip rtl:rotate-180 inline-block">&rarr;</span>';
      const tableRows = [];
      const mobileCards = [];

      history.forEach(item => {
        let details = '';
        if (item.action === 'updated') {
          let changes = {};
          try {
            changes = typeof item.changes === 'string' ? JSON.parse(item.changes || '{}') : (item.changes || {});
          } catch (e) {
            changes = {};
          }

          details = Object.entries(changes).map(([field, delta]) => {
            let fromVal = delta.from || 'empty';
            let toVal = delta.to || 'empty';

            if (field === 'picture' || field === 'picture_name') {
              if (field === 'picture' && changes.picture_name) return '';

              const fromName = changes.picture_name ? (changes.picture_name.from || 'empty') : (delta.from || 'empty');
              const toName = changes.picture_name ? (changes.picture_name.to || 'empty') : (delta.to || 'empty');

              fromVal = fromName !== '' && fromName !== null ? fromName : 'empty';
              toVal = toName !== '' && toName !== null ? toName : 'empty';

              if (fromVal === toVal && fromVal === 'empty') return '';

              const fieldLabel = formatAuditFieldName('picture');
              if (fromVal === 'empty') {
                return `<div class="inline-flex items-center gap-1.5 whitespace-nowrap"><span class="font-semibold text-slate-700 dark:text-slate-300">${fieldLabel}:</span> <span class="text-slate-400 italic">${formatAuditValue(fromVal, 'picture')}</span> <span class="text-slate-400 font-mono inline-block rtl:rotate-180">&rarr;</span> <span class="text-emerald-600 dark:text-emerald-400 font-bold bg-emerald-500/10 px-1.5 py-0.5 rounded">"${escapeHtml(toVal)}"</span></div>`;
              }

              if (toVal === 'empty') {
                return `<div class="inline-flex items-center gap-1.5 whitespace-nowrap"><span class="font-semibold text-slate-700 dark:text-slate-300">${fieldLabel}:</span> <span class="text-rose-500 font-bold line-through bg-rose-500/10 px-1.5 py-0.5 rounded">"${escapeHtml(fromVal)}"</span> <span class="text-slate-400 font-mono inline-block rtl:rotate-180">&rarr;</span> <span class="text-slate-400 italic">${formatAuditValue(toVal, 'picture')}</span></div>`;
              }

              return `<div class="inline-flex items-center gap-1.5 whitespace-nowrap"><span class="font-semibold text-slate-700 dark:text-slate-300">${fieldLabel}:</span> <span class="text-slate-400 line-through bg-slate-500/10 px-1.5 py-0.5 rounded">"${escapeHtml(fromVal)}"</span> <span class="text-slate-400 font-mono inline-block rtl:rotate-180">&rarr;</span> <span class="text-emerald-600 dark:text-emerald-400 font-bold bg-emerald-500/10 px-1.5 py-0.5 rounded">"${escapeHtml(toVal)}"</span></div>`;
            }

            if (field === 'category_id' || field === 'category') {
              if (fromVal === toVal) return '';
              const mapCat = (cid) => {
                if (!cid || cid === 'empty' || cid === 'None') return window.__t ? window.__t('audit.val_none', 'None') : 'None';
                const cat = categoriesCache.find(c => String(c.__backendId) === String(cid) || String(c.id) === String(cid));
                return cat ? `${cat.name} (#${cat.uid || cid})` : (cid || (window.__t ? window.__t('audit.val_none', 'None') : 'None'));
              };
              const fromCat = (delta.from && typeof delta.from === 'string' && delta.from.includes('#')) ? delta.from : mapCat(fromVal);
              const toCat = (delta.to && typeof delta.to === 'string' && delta.to.includes('#')) ? delta.to : mapCat(toVal);
              const fieldLabel = formatAuditFieldName('category');
              return `<div class="inline-flex items-center gap-1.5 whitespace-nowrap"><span class="font-semibold text-slate-700 dark:text-slate-300">${fieldLabel}:</span> <span class="text-slate-400 line-through">"${escapeHtml(fromCat)}"</span> <span class="text-slate-400 font-mono inline-block rtl:rotate-180">&rarr;</span> <span class="text-emerald-600 dark:text-emerald-400 font-bold">"${escapeHtml(toCat)}"</span></div>`;
            }

            const fieldLabel = formatAuditFieldName(field);
            const formattedFrom = formatAuditValue(fromVal, field);
            const formattedTo = formatAuditValue(toVal, field);
            return `<div class="inline-flex items-center gap-1.5 whitespace-nowrap"><span class="font-semibold text-slate-700 dark:text-slate-300">${fieldLabel}:</span> <span class="text-slate-400 line-through">"${escapeHtml(formattedFrom)}"</span> <span class="text-slate-400 font-mono inline-block rtl:rotate-180">&rarr;</span> <span class="text-emerald-600 dark:text-emerald-400 font-bold">"${escapeHtml(formattedTo)}"</span></div>`;
          }).filter(Boolean).join('<br>');
        } else if (item.action === 'deleted') {
          details = `<span class="text-rose-600 dark:text-rose-400 font-medium">${window.__t ? window.__t('common.deleted', 'Deleted') : 'Deleted'}</span><br><span class="text-xs text-slate-500 dark:text-slate-400 mt-1">${window.__t ? window.__t('common.reason', 'Reason:') : 'Reason:'} ${escapeHtml(item.reason || (window.__t ? window.__t('common.no_reason', 'No reason') : 'No reason'))}</span>`;
        } else if (item.action === 'restored') {
          details = `<span class="text-emerald-600 dark:text-emerald-400 font-medium">${window.__t ? window.__t('common.restored', 'Restored') : 'Restored'}</span><br><span class="text-xs text-slate-500 dark:text-slate-400 mt-1">${window.__t ? window.__t('common.reason', 'Reason:') : 'Reason:'} ${escapeHtml(item.reason || (window.__t ? window.__t('common.no_reason', 'No reason') : 'No reason'))}</span>`;
        } else if (item.action === 'decimals_changed') {
          try {
            const c = typeof item.changes === 'string' ? JSON.parse(item.changes || '{}') : (item.changes || {});
            let dirLabel = c.direction || '';
            if (c.direction === 'INCREASED') dirLabel = window.__t ? window.__t('audit.dir_increased', 'Increased') : 'Increased';
            else if (c.direction === 'DECREASED') dirLabel = window.__t ? window.__t('audit.dir_decreased', 'Decreased') : 'Decreased';
            else if (c.direction === 'UNCHANGED') dirLabel = window.__t ? window.__t('audit.dir_unchanged', 'Unchanged') : 'Unchanged';

            let line = `<strong>${formatAuditFieldName('display_decimals')}:</strong> <span class="text-slate-400 line-through">${formatAuditValue(c.from, 'display_decimals')}</span> ${arrow} <span class="text-emerald-600 dark:text-emerald-400 font-bold">${formatAuditValue(c.to, 'display_decimals')}</span> <span class="text-[10px] uppercase font-bold text-slate-500">(${dirLabel})</span>`;
            if (c.total_residual && exactCompare(String(c.total_residual), '0') > 0) {
              line += `<br><span class="text-amber-600 dark:text-amber-400 font-medium">${window.__t ? window.__t('audit.hidden_stock_created', 'Hidden stock created') : 'Hidden stock created'}: <span class="font-mono font-bold">${c.total_residual}</span></span>`;
            }
            details = line;
          } catch (e) {
            details = window.__t ? window.__t('audit.action_decimals_changed', 'Display decimals adjusted') : 'Display decimals adjusted';
          }
        } else if (item.action === 'hidden_stock_reclaimed') {
          try {
            const c = typeof item.changes === 'string' ? JSON.parse(item.changes || '{}') : (item.changes || {});
            details = `<span class="text-purple-600 dark:text-purple-400 font-medium">Hidden residual reclaimed: <span class="font-mono font-bold">${c.total_writeoff || c.reclaimed_quantity || '0'}</span></span><br><span class="text-xs text-slate-500 dark:text-slate-400">${window.__t ? window.__t('common.reason', 'Reason:') : 'Reason:'} ${escapeHtml(item.reason || (window.__t ? window.__t('common.no_reason', 'No reason') : 'No reason'))}</span>`;
          } catch (e) {
            details = `<span class="text-purple-600 dark:text-purple-400 font-medium">Hidden residual reclaimed</span><br><span class="text-xs text-slate-500 dark:text-slate-400">${window.__t ? window.__t('common.reason', 'Reason:') : 'Reason:'} ${escapeHtml(item.reason || (window.__t ? window.__t('common.no_reason', 'No reason') : 'No reason'))}</span>`;
          }
        } else {
          details = `<span class="text-emerald-600 dark:text-emerald-400 font-medium">${window.__t ? window.__t('products.history_initial_creation', 'Initial creation') : 'Initial creation'}</span>`;
        }

        const badgeColors = {
          created: 'bg-emerald-100 dark:bg-emerald-950/60 text-emerald-700 dark:text-emerald-300 border border-emerald-200 dark:border-emerald-800',
          updated: 'bg-blue-100 dark:bg-blue-950/60 text-blue-700 dark:text-blue-300 border border-blue-200 dark:border-blue-800',
          deleted: 'bg-red-100 dark:bg-red-950/60 text-red-700 dark:text-red-300 border border-red-200 dark:border-red-800',
          restored: 'bg-green-100 dark:bg-green-950/60 text-green-700 dark:text-green-300 border border-green-200 dark:border-green-800',
          decimals_changed: 'bg-amber-100 dark:bg-amber-950/60 text-amber-700 dark:text-amber-300 border border-amber-200 dark:border-amber-800',
          hidden_stock_reclaimed: 'bg-purple-100 dark:bg-purple-950/60 text-purple-700 dark:text-purple-300 border border-purple-200 dark:border-purple-800'
        };

        const actionLabels = {
          created: window.__t ? window.__t('common.created', 'Created') : 'Created',
          updated: window.__t ? window.__t('common.updated', 'Updated') : 'Updated',
          deleted: window.__t ? window.__t('common.deleted', 'Deleted') : 'Deleted',
          restored: window.__t ? window.__t('common.restored', 'Restored') : 'Restored',
          decimals_changed: window.__t ? window.__t('audit.action_decimals_changed', 'Decimals Adjusted') : 'Decimals Adjusted',
          hidden_stock_reclaimed: window.__t ? window.__t('audit.action_hidden_stock_reclaimed', 'Hidden Stock Reclaimed') : 'Hidden Stock Reclaimed'
        };

        const badgeClass = badgeColors[item.action] || 'bg-blue-100 dark:bg-blue-950/60 text-blue-700 dark:text-blue-300 border border-blue-200 dark:border-blue-800';
        const actionLabel = actionLabels[item.action] || (item.action || '').replace(/_/g, ' ');
        const formattedDate = formatDateTime(item.created_at);
        const editorName = escapeHtml(item.username || 'System');

        tableRows.push(`
          <tr class="hover:bg-slate-50/60 dark:hover:bg-white/[0.02] transition-colors">
            <td class="px-4 py-3 whitespace-nowrap text-slate-500 dark:text-slate-400 font-mono text-[11px] shrink-0">${formattedDate}</td>
            <td class="px-4 py-3 whitespace-nowrap font-bold text-slate-700 dark:text-slate-200 shrink-0 truncate">${editorName}</td>
            <td class="px-4 py-3 whitespace-nowrap shrink-0">
              <span class="px-2 py-0.5 rounded-full text-[10px] font-bold uppercase ${badgeClass}">${actionLabel}</span>
            </td>
            <td class="px-4 py-3 text-slate-600 dark:text-slate-300 text-xs min-w-0">
              <div class="overflow-x-auto custom-scrollbar max-w-full py-0.5">
                ${details}
              </div>
            </td>
          </tr>
        `);

        mobileCards.push(`
          <div class="p-3.5 rounded-2xl bg-white dark:bg-[#0d1117] border border-slate-200/80 dark:border-white/[0.08] shadow-2xs space-y-2">
            <div class="flex items-center justify-between gap-2">
              <div class="flex items-center gap-1.5 min-w-0">
                <span class="px-2 py-0.5 rounded-full text-[10px] font-bold uppercase ${badgeClass}">${actionLabel}</span>
                <span class="text-xs font-bold text-slate-800 dark:text-slate-200 truncate">@${editorName}</span>
              </div>
              <span class="text-[10px] font-mono text-slate-400 dark:text-slate-500 whitespace-nowrap shrink-0">${formattedDate}</span>
            </div>
            <div class="text-xs text-slate-600 dark:text-slate-300 pt-1.5 border-t border-slate-100 dark:border-white/[0.06] overflow-x-auto custom-scrollbar">
              ${details}
            </div>
          </div>
        `);
      });

      if (tbody) tbody.innerHTML = tableRows.join('');
      if (mobileFeed) mobileFeed.innerHTML = mobileCards.join('');
    }

    function updateCategorySelects() {
      const categories = getCategories();
      const select = document.getElementById('product-category');

      if (categories.length === 0) {
        const noCatText = window.__t ? window.__t('products.no_categories_available', 'No categories available') : 'No categories available';
        select.innerHTML = `<option value="">${noCatText}</option>`;
      } else {
        const selCatText = window.__t ? window.__t('products.select_category_placeholder', 'Select a category...') : 'Select a category...';
        select.innerHTML = `<option value="">${selCatText}</option>` +
          categories.map(c => `<option value="${escapeJsString(c.__backendId)}">${escapeHtml(c.name)}</option>`).join('');
      }
    }

    async function saveProduct(e) {
      e.preventDefault();

      const editId = document.getElementById('product-edit-id').value;
      const categoryId = document.getElementById('product-category').value;

      if (!categoryId) {
        showToast(_t('products.toast_select_category', 'Please select a category'), 'default');
        return;
      }

      const btn = document.getElementById('product-submit-btn');
      btn.disabled = true;
      btn.textContent = window.__t ? window.__t('products.btn_saving', 'Saving...') : 'Saving...';

      // Mission 52: Barcode Validation & Payload Packaging
      const hasBarcodeToggle = document.getElementById('product-has-barcode-toggle');
      const hasBarcode = hasBarcodeToggle ? (hasBarcodeToggle.checked ? 1 : 0) : 0;
      const barcodeInput = document.getElementById('product-barcode-input');
      const registeredPrimaryVal = window._registeredPrimaryBarcode ? window._registeredPrimaryBarcode.barcode_value : '';
      const barcodeVal = registeredPrimaryVal || (barcodeInput ? barcodeInput.value.trim() : (document.getElementById('product-barcode')?.value.trim() || ''));
      const barcodeTypeSelect = document.getElementById('product-barcode-type');
      const barcodeType = window._registeredPrimaryBarcode ? (window._registeredPrimaryBarcode.barcode_type || 'CODE128') : (barcodeTypeSelect ? barcodeTypeSelect.value : 'CODE128');

      if (hasBarcode && !barcodeVal) {
        showToast(window.__t ? window.__t('products.toast_barcode_required', 'Please enter or generate a barcode for this product') : 'Please enter or generate a barcode for this product', 'default');
        btn.disabled = false;
        btn.textContent = window.__t ? window.__t('products.btn_save', 'Save Product') : 'Save Product';
        return;
      }

      if (hasBarcode && isBarcodeTaken(barcodeVal, editId)) {
        showToast(window.__t ? window.__t('products.barcode_duplicate_warning', 'Barcode already assigned to another product') : 'Barcode already assigned to another product', 'default');
        btn.disabled = false;
        btn.textContent = window.__t ? window.__t('products.btn_save', 'Save Product') : 'Save Product';
        return;
      }

      const priceInput = document.getElementById('product-price');
      const rawPrice = priceInput ? priceInput.value.trim() : '';

      const primaryTagVal = (window._registeredPrimaryBarcode ? window._registeredPrimaryBarcode.label_tag : '') || window._productPrimaryBarcodeTag || '';
      const payload = {
        name: document.getElementById('product-name').value,
        category_id: categoryId,
        description: document.getElementById('product-description').value,
        color: document.getElementById('product-color-hex').value,
        picture: document.getElementById('product-picture-data').value,
        picture_name: document.getElementById('product-picture-name').value,
        price: (rawPrice !== '' && !isNaN(parseFloat(rawPrice))) ? rawPrice : '0',
        has_barcode: hasBarcode,
        barcode: hasBarcode ? barcodeVal : null,
        barcode_type: barcodeType,
        barcode_label: primaryTagVal,
        barcode_tag: primaryTagVal,
        secondary_barcodes: currentProductSecondaryBarcodes.map(b => ({
          ...b,
          label: b.label_tag || b.label || '',
          label_tag: b.label_tag || b.label || ''
        }))
      };

      const decimalsRaw = document.getElementById('product-display-decimals').value;
      const newDecimals = decimalsRaw !== '' ? parseInt(decimalsRaw) : null;

      try {
        if (editId) {
          const originalRaw = document.getElementById('product-display-decimals').dataset.originalValue || '';
          const originalDecimals = originalRaw !== '' ? parseInt(originalRaw) : null;
          const decimalsDecreased = (newDecimals !== null && originalDecimals !== null && newDecimals < originalDecimals);

          if (decimalsDecreased) {
            // Preview impact: if hidden stock would be created, show modal and pause submit.
            const preview = await apiRequest(`/api/products/${editId}/preview-decimals-change`, {
              method: 'POST',
              body: JSON.stringify({ display_decimals: newDecimals })
            }
);
            if (preview && preview.total_hidden && exactCompare(String(preview.total_hidden), '0') > 0) {
              btn.disabled = false;
              btn.textContent = 'Save Product';
              openDecimalsImpactModal({
                editId,
                payload: { ...payload, display_decimals: newDecimals },
                preview
              }
);
              return;
            }

          }


          const addStockQty = document.getElementById('product-initial-qty')?.value.trim() || '0';
          const addStockCost = document.getElementById('product-initial-cost')?.value.trim() || '0';

          const putPayload = { ...payload, display_decimals: newDecimals };
          if (isNumeric(addStockQty) && exactCompare(addStockQty, '0') > 0) {
            putPayload.initial_quantity = addStockQty;
            putPayload.initial_cost_price = (addStockCost && isNumeric(addStockCost)) ? addStockCost : '0';
          }


          const resp = await apiRequest(`/api/products/${editId}`, {
            method: 'PUT',
            body: JSON.stringify(putPayload)
          }
);
          if (resp && resp.decimals_changed) {
            const d = resp.decimals_changed;
            showToast(_t('orders.toast_decimals_d_direction_d_from', `Decimals ${d.direction}: ${d.from} → ${d.to}`, { direction: d.direction, from: d.from, to: d.to }), 'default');
          }
 else {
            showToast(_t('products.toast_updated', 'Product updated successfully!'), 'default');
          }

        }
 else {
          const initialQty = document.getElementById('product-initial-qty')?.value.trim() || '0';
          const initialCost = document.getElementById('product-initial-cost')?.value.trim() || '0';

          await apiRequest('/api/products', {
            method: 'POST',
            body: JSON.stringify({
              ...payload,
              display_decimals: newDecimals,
              price: 0,
              quantity: 0,
              initial_quantity: initialQty,
              initial_cost_price: initialCost
            }
)
          }
);
          showToast(_t('products.toast_added', 'Product added successfully!'), 'default');
        }

        closeProductModal();
        await loadAllData();
      } catch (e) {
        showToast(e.message || _t('products.toast_failed_save', 'Failed to save product'), 'default');
      }

      btn.disabled = false;
      btn.textContent = window.__t ? window.__t('products.btn_save', 'Save Product') : 'Save Product';
    }

    // ----- Decimals-change impact modal -----
    let pendingDecimalsChange = null;

    function openDecimalsImpactModal({ editId, payload, preview }) {
      pendingDecimalsChange = { editId, payload };
      const product = productsCache.find(p => p.__backendId === String(editId));
      const productName = product ? product.name : `#${editId}`;
      document.getElementById('decimals-impact-summary').innerHTML =
        `<div class="flex items-center gap-3">` +
          `<div class="w-9 h-9 rounded-xl bg-amber-500/20 text-amber-600 dark:text-amber-400 flex items-center justify-center shrink-0">` +
            `<svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 9v2m0 4h.01M5.07 19h13.86c1.54 0 2.5-1.67 1.73-3L13.73 4a2 2 0 00-3.46 0L3.34 16c-.77 1.33.19 3 1.73 3z"/></svg>` +
          `</div>` +
          `<div class="min-w-0 flex-1">` +
            `<div class="text-xs font-bold text-slate-800 dark:text-slate-100 flex items-center gap-2 flex-wrap">` +
              `<span class="truncate">${escapeHtml(productName)}</span>` +
              `<span class="px-2 py-0.5 rounded-full bg-amber-500/15 border border-amber-500/30 text-amber-600 dark:text-amber-400 text-[10px] font-mono font-bold">${preview.batches_affected || 0} batch${preview.batches_affected === 1 ? '' : 'es'}</span>` +
            `</div>` +
            `<p class="text-[11px] text-slate-600 dark:text-slate-400 mt-0.5">` +
              `Precision: <span class="font-mono font-bold text-slate-700 dark:text-slate-300">${preview.current_decimals}</span> &rarr; <span class="font-mono font-bold text-amber-600 dark:text-amber-400">${preview.new_decimals}</span> &bull; Stock hidden: <span class="font-mono font-black text-amber-600 dark:text-amber-400">${formatNumber(preview.total_hidden, 16)}</span>` +
            `</p>` +
          `</div>` +
        `</div>`;
      const rows = (preview.batches || []).map(b => `
        <tr class="border-b border-slate-100 dark:border-white/[0.04] last:border-0 hover:bg-white/50 dark:hover:bg-white/[0.02] transition-colors">
          <td class="px-3 py-2.5 text-xs font-mono text-slate-600 dark:text-slate-400">${b.uid || '#' + b.purchase_id}</td>
          <td class="px-3 py-2.5 text-xs text-right font-mono text-slate-700 dark:text-slate-300">${formatNumber(b.quantity_remaining, 16)}</td>
          <td class="px-3 py-2.5 text-xs text-right font-mono text-amber-600 dark:text-amber-400 font-bold">${formatNumber(b.residual, 16)}</td>
        </tr>`).join('');
      document.getElementById('decimals-impact-batches').innerHTML = `
        <table class="w-full">
          <thead class="bg-slate-100/70 dark:bg-white/[0.04] text-slate-500 dark:text-slate-400 border-b border-slate-200/60 dark:border-white/[0.06] sticky top-0 backdrop-blur-sm">
            <tr>
              <th class="px-3 py-2 text-left text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-wider">Batch</th>
              <th class="px-3 py-2 text-right text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-wider">Remaining</th>
              <th class="px-3 py-2 text-right text-[10px] font-black text-amber-600 dark:text-amber-400 uppercase tracking-wider">Will hide</th>
            </tr>
          </thead>
          <tbody>${rows}</tbody>
        </table>`;
      document.getElementById('decimals-impact-modal').classList.remove('hidden');
    }

    function closeDecimalsImpactModal() {
      document.getElementById('decimals-impact-modal').classList.add('hidden');
      pendingDecimalsChange = null;
    }

    async function confirmDecimalsChange() {
      if (!pendingDecimalsChange) return;
      const { editId, payload } = pendingDecimalsChange;
      const btn = document.getElementById('decimals-impact-confirm-btn');
      btn.disabled = true;
      btn.textContent = window.__t ? window.__t('products.btn_saving', 'Saving...') : 'Saving...';
      try {
        const resp = await apiRequest(`/api/products/${editId}`, {
          method: 'PUT',
          body: JSON.stringify(payload)
        }
);
        const d = resp && resp.decimals_changed;
        const hint = d && d.total_residual ? ` (${formatNumber(d.total_residual, 16)} hidden — see Stock page)` : '';
        showToast(_t('products.toast_decimals_decreased', 'Decimals decreased {from} → {to}{hint}', { from: d ? d.from : '', to: d ? d.to : '', hint: hint || '' }), 'default');
        closeDecimalsImpactModal();
        closeProductModal();
        await loadAllData();
        updateProductsGrid();
        if (typeof filterStock === 'function') filterStock();
      } catch (e) {
        showToast(e.message || _t('products.toast_failed_to_update_product', 'Failed to update product'), 'default');
      }
      btn.disabled = false;
      btn.textContent = window.__t ? window.__t('products.impact_btn_continue', 'Continue and hide') : 'Continue and hide';
    }

    // ----- Reclaim hidden-stock modal -----
    let pendingReclaim = null; // { productId }

    async function openReclaimHiddenModal(productId) {
      const product = productsCache.find(p => p.__backendId === String(productId));
      if (!product) return;
      try {
        const data = await apiRequest(`/api/products/${productId}/hidden-stock`, { method: 'GET' });
        if (!data || exactCompare(String(data.total_hidden || '0'), '0') <= 0) {
          showToast(_t('products.toast_no_hidden_reclaim', 'No hidden stock to reclaim'), 'default');
          return;
        }

        pendingReclaim = { productId, data };

        // Pre-fill: find smallest N >= current decimals that would zero out residual.
        // Strategy: count digits past the dot in each batch's residual; take the max.
        let neededDecimals = data.display_decimals || 2;
        (data.batches || []).forEach(b => {
          const qr = String(b.quantity_remaining || '0');
          const dotIdx = qr.indexOf('.');
          if (dotIdx >= 0) {
            // Find last non-zero digit position past the dot
            const frac = qr.slice(dotIdx + 1).replace(/0+$/, '');
            if (frac.length > neededDecimals) neededDecimals = frac.length;
          }

        }
);
        if (neededDecimals > 16) neededDecimals = 16;
        document.getElementById('reclaim-new-decimals').value = neededDecimals;
        document.getElementById('reclaim-new-decimals').min = (data.display_decimals || 0) + 1;
        document.getElementById('reclaim-new-decimals').max = 16;

        document.getElementById('reclaim-hidden-summary').innerHTML =
          `<div class="flex items-center gap-3">` +
            `<div class="w-9 h-9 rounded-xl bg-amber-500/20 text-amber-600 dark:text-amber-400 flex items-center justify-center shrink-0">` +
              `<svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"/></svg>` +
            `</div>` +
            `<div class="min-w-0 flex-1">` +
              `<div class="text-xs font-bold text-slate-800 dark:text-slate-100 flex items-center gap-2 flex-wrap">` +
                `<span class="truncate">${escapeHtml(product.name)}</span>` +
                `<span class="px-2 py-0.5 rounded-full bg-amber-500/15 border border-amber-500/30 text-amber-600 dark:text-amber-400 text-[10px] font-mono font-bold">${(data.batches || []).length} batch${(data.batches || []).length === 1 ? '' : 'es'}</span>` +
              `</div>` +
              `<p class="text-[11px] text-slate-600 dark:text-slate-400 mt-0.5">` +
                `${window.__t ? window.__t('products.total_hidden', 'Total hidden:') : 'Total hidden:'} <span class="font-mono font-black text-amber-600 dark:text-amber-400 text-xs">${formatNumber(data.total_hidden, 16)}</span> ${window.__t ? window.__t('products.units', 'units') : 'units'} ${window.__t ? window.__t('products.at_current_precision', 'at current precision') : 'at current precision'} <span class="font-mono font-bold text-slate-700 dark:text-slate-300">${data.display_decimals}</span>` +
              `</p>` +
            `</div>` +
          `</div>`;

        const rows = (data.batches || []).map(b => `
          <tr class="border-b border-slate-100 dark:border-white/[0.04] last:border-0 hover:bg-white/50 dark:hover:bg-white/[0.02] transition-colors">
            <td class="px-3 py-2.5 text-xs font-mono text-slate-600 dark:text-slate-400">${b.uid || '#' + b.purchase_id}</td>
            <td class="px-3 py-2.5 text-xs text-right font-mono text-slate-700 dark:text-slate-300">${formatNumber(b.quantity_remaining, 16)}</td>
            <td class="px-3 py-2.5 text-xs text-right font-mono text-amber-600 dark:text-amber-400 font-bold">${formatNumber(b.residual, 16)}</td>
          </tr>`).join('');
        document.getElementById('reclaim-hidden-batches').innerHTML = `
          <table class="w-full">
            <thead class="bg-slate-100/70 dark:bg-white/[0.04] text-slate-500 dark:text-slate-400 border-b border-slate-200/60 dark:border-white/[0.06] sticky top-0 backdrop-blur-sm">
              <tr>
                <th class="px-3 py-2 text-left text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-wider">Batch</th>
                <th class="px-3 py-2 text-right text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-wider">Remaining</th>
                <th class="px-3 py-2 text-right text-[10px] font-black text-amber-600 dark:text-amber-400 uppercase tracking-wider">Hidden</th>
              </tr>
            </thead>
            <tbody>${rows}</tbody>
          </table>`;

        document.querySelector('input[name="reclaim-mode"][value="increase"]').checked = true;
        document.getElementById('reclaim-reason').classList.add('hidden');
        document.getElementById('reclaim-reason').value = '';
        document.getElementById('reclaim-hidden-modal').classList.remove('hidden');
      } catch (e) {
        showToast(e.message || _t('stock.modals_forms_failed_to_load_hidden_stock', 'Failed to load hidden stock'), 'default');
      }
    }

    function closeReclaimHiddenModal() {
      document.getElementById('reclaim-hidden-modal').classList.add('hidden');
      pendingReclaim = null;
    }

    function updateReclaimMode() {
      const mode = document.querySelector('input[name="reclaim-mode"]:checked').value;
      document.getElementById('reclaim-reason').classList.toggle('hidden', mode !== 'writeoff');
    }

    async function confirmReclaimHidden() {
      if (!pendingReclaim || !pendingReclaim.productId) return;
      const { productId, data } = pendingReclaim;
      const mode = document.querySelector('input[name="reclaim-mode"]:checked')?.value || 'increase';
      const btn = document.getElementById('reclaim-hidden-confirm-btn');
      if (btn) {
        btn.disabled = true;
        btn.textContent = window.__t ? window.__t('products.reclaim_btn_applying', 'Applying...') : 'Applying...';
      }

      try {
        if (mode === 'increase') {
          const newDecimals = parseInt(document.getElementById('reclaim-new-decimals').value, 10);
          if (isNaN(newDecimals) || newDecimals < 0 || newDecimals > 16) {
            showToast(_t('products.toast_invalid_decimals', 'Invalid decimals value (0-16)'), 'default');
            if (btn) { btn.disabled = false; btn.textContent = window.__t ? window.__t('products.reclaim_btn_apply', 'Apply Correction') : 'Apply Correction'; }
            return;
          }

          await apiRequest(`/api/products/${productId}`, {
            method: 'PUT',
            body: JSON.stringify({ display_decimals: newDecimals })
          });
          showToast(_t('orders.toast_display_decimals_increased_to_new', `Display decimals increased to ${newDecimals}. Residual stock revealed!`, { decimals: newDecimals }), 'default');
        } else {
          const reason = document.getElementById('reclaim-reason').value.trim();
          if (!reason) {
            showToast(_t('products.toast_writeoff_reason_required', 'Write-off reason is required'), 'default');
            document.getElementById('reclaim-reason').focus();
            if (btn) { btn.disabled = false; btn.textContent = window.__t ? window.__t('products.reclaim_btn_apply', 'Apply Correction') : 'Apply Correction'; }
            return;
          }

          const res = await apiRequest(`/api/products/${productId}/reclaim-hidden`, {
            method: 'POST',
            body: JSON.stringify({ reason })
          });
          showToast(_t('orders.toast_wrote_off_formatquantity_res_tota', `Wrote off ${formatQuantity(res.total_writeoff, 16)} units across ${res.batches_affected} batches.`, { quantity: formatQuantity(res.total_writeoff, 16), batches: res.batches_affected }), 'default');
        }

        closeReclaimHiddenModal();
        await loadAllData();
        updateProductsGrid();
        if (typeof filterStock === 'function') filterStock();
      } catch (e) {
        showToast(e.message || _t('stock.modals_forms_failed_to_process_hidden_stock', 'Failed to process hidden stock correction'), 'default');
      } finally {
        if (btn) {
          btn.disabled = false;
          btn.textContent = window.__t ? window.__t('products.reclaim_btn_apply', 'Apply Correction') : 'Apply Correction';
        }
      }
    }

    let pendingDeleteProductId = null;

    function showDeleteProductModal(id) {
      pendingDeleteProductId = id;
      const product = getProducts().find(p => p.__backendId === id);
      const nameEl = document.getElementById('delete-product-name');
      if (nameEl && product) {
        nameEl.textContent = product.name;
      }
      const reasonInput = document.getElementById('delete-product-reason');
      if (reasonInput) reasonInput.value = '';
      const modal = document.getElementById('delete-product-modal');
      if (modal) modal.classList.remove('hidden');
    }

    function closeDeleteProductModal() {
      pendingDeleteProductId = null;
      const modal = document.getElementById('delete-product-modal');
      if (modal) modal.classList.add('hidden');
      const reasonInput = document.getElementById('delete-product-reason');
      if (reasonInput) reasonInput.value = '';
    }


    async function confirmDeleteProduct() {
      if (!pendingDeleteProductId) return;

      const reason = document.getElementById('delete-product-reason').value.trim();
      if (!reason) {
        showToast(_t('products.toast_delete_reason_required', 'Please provide a reason for deletion'), 'default');
        return;
      }

      const btn = document.getElementById('confirm-delete-product-btn');
      btn.disabled = true;
      btn.textContent = window.__t ? window.__t('products.delete_btn_deleting', 'Deleting...') : 'Deleting...';

      try {
        await apiRequest(`/api/products/${pendingDeleteProductId}`, {
          method: 'DELETE',
          body: JSON.stringify({ delete_reason: reason })
        }
);
        showToast(_t('products.toast_deleted', 'Product deleted successfully'), 'default');
        closeDeleteProductModal();
        await loadAllData();
        updateProductsGrid();
      } catch (e) {
        showToast(e.message || _t('products.toast_failed_delete', 'Failed to delete product'), 'default');
      }

      btn.disabled = false;
      btn.textContent = window.__t ? window.__t('products.delete_btn_confirm', 'Confirm Deletion') : 'Confirm Deletion';
    }

    async function deleteProduct(id) {
      showDeleteProductModal(id);
    }

    
