    function toggleCategoriesMobileKpis() {
      const container = document.getElementById('categories-kpi-container');
      const icon = document.getElementById('categories-kpi-toggle-icon');
      const label = document.getElementById('categories-kpi-toggle-label');
      if (!container) return;

      const isCollapsed = container.classList.toggle('is-collapsed');
      try {
        localStorage.setItem('pos_categories_kpi_collapsed', isCollapsed ? '1' : '0');
      } catch (e) {}

      if (icon) {
        if (isCollapsed) {
          icon.classList.remove('rotate-180');
          icon.classList.add('rotate-0');
        }
 else {
          icon.classList.remove('rotate-0');
          icon.classList.add('rotate-180');
        }

      }
      if (label) {
        label.textContent = isCollapsed ? 'Show' : 'Hide';
      }
    }
    window.toggleCategoriesMobileKpis = toggleCategoriesMobileKpis;

    function restoreCategoriesMobileKpiState() {
      try {
        const saved = localStorage.getItem('pos_categories_kpi_collapsed');
        if (saved === '1') {
          const container = document.getElementById('categories-kpi-container');
          const icon = document.getElementById('categories-kpi-toggle-icon');
          const label = document.getElementById('categories-kpi-toggle-label');
          if (container) container.classList.add('is-collapsed');
          if (icon) {
            icon.classList.remove('rotate-180');
            icon.classList.add('rotate-0');
          }

          if (label) label.textContent = 'Show';
        }

      } catch (e) {}
    }
    window.restoreCategoriesMobileKpiState = restoreCategoriesMobileKpiState;

    function clearCategoriesSearch() {
      const searchInput = document.getElementById('categories-search');
      if (searchInput) searchInput.value = '';
      const clearBtn = document.getElementById('categories-search-clear');
      if (clearBtn) clearBtn.classList.add('hidden');
      filterCategories();
    }

    // Categories KPI Calculation Decoupled from keystroke filter (Point 1)
    function updateCategoriesKpis() {
      const categories = getCategories() || [];
      const allProducts = getProducts() || [];

      let activeCategoriesCount = 0;
      let categorizedProductsCount = 0;
      let uncategorizedProductsCount = 0;
      let totalValuation = '0';

      const catMap = {};
      categories.forEach(c => {
        if (!c.deleted_at && !c.deletedAt) {
          activeCategoriesCount++;
          catMap[c.__backendId] = true;
        }

      });

      allProducts.forEach(p => {
        if (!p.deleted_at && !p.deletedAt) {
          if (p.categoryId && catMap[p.categoryId]) {
            categorizedProductsCount++;
            const pVal = getProductInventoryValue(p.__backendId);
            totalValuation = exactAdd(totalValuation, pVal);
          }
 else {
            uncategorizedProductsCount++;
          }

        }

      });

      const kpiCountEl = document.getElementById('categories-kpi-count');
      if (kpiCountEl) kpiCountEl.textContent = activeCategoriesCount;
      const kpiActiveDescEl = document.getElementById('categories-kpi-active-desc');
      if (kpiActiveDescEl) kpiActiveDescEl.textContent = `${activeCategoriesCount} ${window.__t ? window.__t('categories.kpi_active_desc', 'active departments') : 'active departments'}`;
      const kpiProdCountEl = document.getElementById('categories-kpi-products-count');
      if (kpiProdCountEl) kpiProdCountEl.textContent = categorizedProductsCount;
      const kpiUncatCountEl = document.getElementById('categories-kpi-uncat-count');
      if (kpiUncatCountEl) kpiUncatCountEl.textContent = uncategorizedProductsCount;
      const kpiValEl = document.getElementById('categories-kpi-valuation');
      if (kpiValEl) kpiValEl.textContent = formatPrice(totalValuation);
    }
    window.updateCategoriesKpis = updateCategoriesKpis;

    let _categorySearchDebounceTimer = null;
    function debouncedFilterCategories() {
      const searchInput = document.getElementById('categories-search');
      const clearBtn = document.getElementById('categories-search-clear');
      if (clearBtn && searchInput) {
        if (searchInput.value.trim()) clearBtn.classList.remove('hidden');
        else clearBtn.classList.add('hidden');
      }
      if (_categorySearchDebounceTimer) clearTimeout(_categorySearchDebounceTimer);
      _categorySearchDebounceTimer = setTimeout(() => {
        filterCategories();
      }, 250);
    }
    window.debouncedFilterCategories = debouncedFilterCategories;

    // Categories Pagination State & Controls (30 per page - Owner Rule)
    let categoriesCurrentPage = 1;
    const CATEGORIES_PAGE_SIZE = 30;
    window.categoriesCurrentPage = categoriesCurrentPage;

    function renderCategoriesPaginationControls(totalCount, totalPages, currentPage) {
      let container = document.getElementById('categories-pagination-container');
      if (!container) return;

      // RULE: Hide bar completely if items <= 30 or totalPages <= 1
      if (!totalCount || totalCount <= CATEGORIES_PAGE_SIZE || totalPages <= 1) {
        container.innerHTML = '';
        container.classList.add('hidden');
        return;
      }
      container.classList.remove('hidden');

      const startItem = (currentPage - 1) * CATEGORIES_PAGE_SIZE + 1;
      const endItem = Math.min(currentPage * CATEGORIES_PAGE_SIZE, totalCount);
      const hasPrev = currentPage > 1;
      const hasNext = currentPage < totalPages;

      const showingText = window.__t ? window.__t('common.pagination_showing', 'Showing') : 'Showing';
      const ofText = window.__t ? window.__t('common.pagination_of', 'of') : 'of';
      const categoriesText = window.__t ? window.__t('categories.kpi_categories_label', 'categories') : 'categories';
      const prevText = window.__t ? window.__t('common.pagination_prev', 'Prev') : 'Prev';
      const nextText = window.__t ? window.__t('common.pagination_next', 'Next') : 'Next';
      const pageText = window.__t ? window.__t('common.pagination_page', 'Page') : 'Page';

      container.innerHTML = `
        <div class="flex items-center gap-2 text-slate-500 dark:text-slate-400 font-semibold text-xs text-center sm:text-left">
          <span>${showingText} <strong class="text-slate-900 dark:text-white font-black">${startItem}–${endItem}</strong> ${ofText} <strong class="text-slate-900 dark:text-white font-black">${totalCount}</strong> ${categoriesText}</span>
        </div>
        <div class="flex items-center gap-2 select-none justify-center">
          <button type="button" id="categories-page-prev-btn" onclick="goToCategoriesPage(${currentPage - 1})"
            class="min-h-[36px] px-3.5 py-1.5 rounded-xl border flex items-center gap-1.5 text-xs font-bold transition-all ${hasPrev ? 'bg-white dark:bg-slate-800 text-slate-700 dark:text-slate-200 border-slate-200/80 dark:border-white/[0.08] hover:bg-slate-50 dark:hover:bg-slate-700 cursor-pointer shadow-xs active:scale-95' : 'opacity-40 cursor-not-allowed bg-slate-100 dark:bg-slate-900 text-slate-400 border-transparent'}"
            ${!hasPrev ? 'disabled' : ''}>
            <span class="text-sm rtl-flip rtl:rotate-180">←</span><span>${prevText}</span>
          </button>
          <span class="min-h-[36px] px-3 py-1.5 rounded-xl bg-slate-100 dark:bg-white/[0.06] font-black text-xs text-slate-700 dark:text-slate-300 border border-slate-200/60 dark:border-white/[0.06] flex items-center justify-center">
            ${pageText} ${currentPage} ${ofText} ${totalPages}
          </span>
          <button type="button" id="categories-page-next-btn" onclick="goToCategoriesPage(${currentPage + 1})"
            class="min-h-[36px] px-3.5 py-1.5 rounded-xl border flex items-center gap-1.5 text-xs font-bold transition-all ${hasNext ? 'bg-white dark:bg-slate-800 text-slate-700 dark:text-slate-200 border-slate-200/80 dark:border-white/[0.08] hover:bg-slate-50 dark:hover:bg-slate-700 cursor-pointer shadow-xs active:scale-95' : 'opacity-40 cursor-not-allowed bg-slate-100 dark:bg-slate-900 text-slate-400 border-transparent'}"
            ${!hasNext ? 'disabled' : ''}>
            <span>${nextText}</span><span class="text-sm rtl-flip rtl:rotate-180">→</span>
          </button>
        </div>
      `;
    }
    window.renderCategoriesPaginationControls = renderCategoriesPaginationControls;

    function goToCategoriesPage(page) {
      categoriesCurrentPage = page;
      window.categoriesCurrentPage = page;
      filterCategories(false);
      const scrollTarget = document.getElementById('categories-content-container') || document.getElementById('page-categories');
      if (scrollTarget && typeof scrollTarget.scrollIntoView === 'function') {
        scrollTarget.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      }
    }
    window.goToCategoriesPage = goToCategoriesPage;

    function filterCategories(resetPage = true) {
      if (resetPage) categoriesCurrentPage = 1;
      restoreCategoriesMobileKpiState();
      const categories = getCategories() || [];
      const allProducts = getProducts() || [];
      const grid = document.getElementById('categories-grid');
      const tableBody = document.getElementById('categories-table-tbody');
      if (!grid && !tableBody) return;

      const userFilter = document.getElementById('categories-user-filter')?.value || 'all';
      const sortFilter = document.getElementById('categories-sort-filter')?.value || 'name_asc';
      const searchQuery = (document.getElementById('categories-search')?.value || '').toLowerCase().trim();

      const clearBtn = document.getElementById('categories-search-clear');
      if (clearBtn) {
        if (searchQuery) clearBtn.classList.remove('hidden');
        else clearBtn.classList.add('hidden');
      }

      // Update KPIs only if active categories page is visible
      updateCategoriesKpis();

      // 2. Filter categories
      let filtered = showDeletedCategories
        ? categories.filter(c => c.deleted_at || c.deletedAt)
        : categories.filter(c => !c.deleted_at && !c.deletedAt);

      if (userFilter !== 'all') {
        if (userFilter === 'system') {
          filtered = filtered.filter(c => !c.created_by && !c.createdBy || String(c.created_by || c.createdBy).toLowerCase() === 'system');
        }
 else {
          filtered = filtered.filter(c => String(c.created_by || c.createdBy || '') === String(userFilter));
        }

      }

      if (searchQuery) {
        filtered = filtered.filter(c =>
          (c.name || '').toLowerCase().includes(searchQuery) ||
          (c.uid && c.uid.toLowerCase().includes(searchQuery)) ||
          (c.description && c.description.toLowerCase().includes(searchQuery))
        );
      }

      // 3. Sort categories with precomputed O(P) counts (Point 2)
      if (sortFilter === 'products_desc') {
        const counts = {};
        allProducts.forEach(p => {
          if (p.categoryId && !p.deleted_at && !p.deletedAt) {
            counts[p.categoryId] = (counts[p.categoryId] || 0) + 1;
          }

        }
);
        filtered.sort((a, b) => (counts[b.__backendId] || 0) - (counts[a.__backendId] || 0));
      } else if (sortFilter === 'name_asc') {
        filtered.sort((a, b) => (a.name || '').localeCompare(b.name || ''));
      } else if (sortFilter === 'newest') {
        filtered.sort((a, b) => new Date((b.created_at || b.createdAt || '').replace(' ', 'T')) - new Date((a.created_at || a.createdAt || '').replace(' ', 'T')));
      }

      // Slicing by 30 Items Per Page (Owner Rule)
      const totalFiltered = filtered.length;
      const totalPages = Math.max(1, Math.ceil(totalFiltered / CATEGORIES_PAGE_SIZE));
      if (categoriesCurrentPage > totalPages) categoriesCurrentPage = totalPages;
      if (categoriesCurrentPage < 1) categoriesCurrentPage = 1;

      const pageStart = (categoriesCurrentPage - 1) * CATEGORIES_PAGE_SIZE;
      const paginatedCategories = filtered.slice(pageStart, pageStart + CATEGORIES_PAGE_SIZE);

      updateCategoriesGrid(paginatedCategories);
      renderCategoriesPaginationControls(totalFiltered, totalPages, categoriesCurrentPage);
    }

    function updateCategoriesUserFilter() {
      const allUsers = getUsers() || [];
      const userFilter = document.getElementById('categories-user-filter');
      if (!userFilter) return;
      const currentValue = userFilter.value || 'all';
      const allUsersLabel = window.__t ? window.__t('categories.filter_user_all', 'All Users') : 'All Users';
      const systemLabel = window.__t ? window.__t('products.system_user', 'System') : 'System';
      const myUid = (typeof currentUser !== 'undefined' && currentUser) ? String(currentUser.__backendId || currentUser.id || '') : '';
      const visibleUsers = allUsers.filter(u => {
        if (u.deleted_at || u.deletedAt) return false;
        const isSelf = (myUid && String(u.__backendId || u.id) === myUid) || (currentUser && u.username === currentUser.username);
        if (!isSelf && isUserFilterHidden(u, 'purchases')) return false;
        return true;
      });

      userFilter.innerHTML = `<option value="all" data-i18n="categories.filter_user_all">${escapeHtml(allUsersLabel)}</option>` +
        `<option value="system">@${systemLabel}</option>` +
        visibleUsers.map(u => `<option value="${u.id}">@${escapeHtml(u.username)}</option>`).join('');
      if (currentValue === 'all' || currentValue === 'system' || visibleUsers.some(u => String(u.id) === String(currentValue))) {
        userFilter.value = currentValue;
      } else {
        userFilter.value = 'all';
      }
    }
    window.updateCategoriesUserFilter = updateCategoriesUserFilter;

    let categoriesViewMode = 'grid'; // 'grid' | 'table'
    try {
      const savedCatMode = localStorage.getItem('pos_categories_view_mode');
      if (savedCatMode === 'table' || savedCatMode === 'grid') {
        categoriesViewMode = savedCatMode;
      }
    } catch (e) {}

    function syncCategoriesViewModeUi() {
      const gridBtn = document.getElementById('categories-view-grid-btn');
      const tableBtn = document.getElementById('categories-view-table-btn');
      const gridContainer = document.getElementById('categories-grid');
      const tableContainer = document.getElementById('categories-table-container');

      if (categoriesViewMode === 'grid') {
        if (gridBtn) gridBtn.className = 'h-8 w-8 flex items-center justify-center rounded-lg text-xs font-bold transition-all bg-white dark:bg-[#151b26] text-purple-600 dark:text-purple-300 shadow-xs cursor-pointer';
        if (tableBtn) tableBtn.className = 'h-8 w-8 flex items-center justify-center rounded-lg text-xs font-bold transition-all text-slate-500 dark:text-slate-400 hover:text-slate-800 dark:hover:text-slate-200 cursor-pointer';
        if (gridContainer) gridContainer.classList.remove('hidden');
        if (tableContainer) tableContainer.classList.add('hidden');
      } else {
        if (tableBtn) tableBtn.className = 'h-8 w-8 flex items-center justify-center rounded-lg text-xs font-bold transition-all bg-white dark:bg-[#151b26] text-purple-600 dark:text-purple-300 shadow-xs cursor-pointer';
        if (gridBtn) gridBtn.className = 'h-8 w-8 flex items-center justify-center rounded-lg text-xs font-bold transition-all text-slate-500 dark:text-slate-400 hover:text-slate-800 dark:hover:text-slate-200 cursor-pointer';
        if (gridContainer) gridContainer.classList.add('hidden');
        if (tableContainer) tableContainer.classList.remove('hidden');
      }
    }

    function setCategoriesViewMode(mode) {
      categoriesViewMode = mode;
      try {
        localStorage.setItem('pos_categories_view_mode', mode);
      } catch (e) {}
      syncCategoriesViewModeUi();
      filterCategories();
    }
    window.setCategoriesViewMode = setCategoriesViewMode;

    function renderCategoryTableRow(c) {
      const allProducts = getProducts() || [];
      const productCount = allProducts.filter(p => p.categoryId === c.__backendId && !p.deleted_at).length;
      const isDeleted = !!(c.deleted_at || c.deletedAt);
      const hexColor = c.color || '#8b5cf6';

      const catThumb = c.picture
        ? `<img src="${c.picture}" class="w-full h-full object-cover" alt="${escapeHtml(c.name)}">`
        : `<div class="w-full h-full flex items-center justify-center text-white font-black" style="background:${hexColor}">
             <svg class="w-5 h-5 text-white/90" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M7 7h.01M7 3h5c.512 0 1.024.195 1.414.586l7 7a2 2 0 010 2.828l-7 7a2 2 0 01-2.828 0l-7-7A1.994 1.994 0 013 12V7a4 4 0 014-4z"></path></svg>
           </div>`;

      return `
        <tr class="hover:bg-slate-50/80 dark:hover:bg-white/[0.04] transition-colors ${isDeleted ? 'opacity-75 bg-rose-500/10' : ''}">
          <!-- Department / Category -->
          <td class="px-5 py-4 border-r border-slate-100 dark:border-white/[0.06]">
            <div class="flex items-center gap-3">
              <div class="w-10 h-10 rounded-xl flex items-center justify-center shrink-0 overflow-hidden shadow-xs border border-slate-200 dark:border-white/[0.08] bg-slate-100 dark:bg-[#080b10]">
                ${catThumb}
              </div>
              <div class="min-w-0">
                <p class="font-black text-slate-900 dark:text-white text-xs truncate flex items-center gap-1.5">
                  <span class="w-2 h-2 rounded-full shrink-0" style="background-color:${hexColor}"></span>
                  <span>@${escapeHtml(c.name)}</span>
                </p>
                <p class="text-[11px] text-slate-400 dark:text-slate-500 truncate mt-0.5">${escapeHtml(c.description || (window.__t ? window.__t('categories.card_no_desc', 'No description provided for this department.') : 'No description'))}</p>
              </div>
            </div>
          </td>

          <!-- UID -->
          <td class="px-5 py-4 border-r border-slate-100 dark:border-white/[0.06]">
            <button onclick="copyCategoryUid('${escapeJsString(c.uid || c.__backendId)}', event)" title="${window.__t ? window.__t('categories.card_copy_uid_title', 'Click to copy UID: #{uid}').replace('{uid}', c.uid || c.__backendId) : `Click to copy UID: #${c.uid || c.__backendId}`}"
              class="flex items-center gap-1.5 px-2.5 py-1 rounded-lg bg-slate-100 hover:bg-purple-50 hover:text-purple-600 dark:bg-[#080b10] dark:hover:bg-white/[0.08] text-slate-700 dark:text-slate-300 font-mono text-xs font-bold transition-all border border-slate-200 dark:border-white/[0.08] cursor-pointer active:scale-95">
              <span class="text-purple-500 font-black">#</span>
              <span class="truncate max-w-[110px]">${c.uid || c.__backendId}</span>
            </button>
          </td>

          <!-- Assigned Items -->
          <td class="px-5 py-4 border-r border-slate-100 dark:border-white/[0.06] text-center">
            <span class="px-2.5 py-1 rounded-full text-xs font-black font-mono tabular-nums ${productCount > 0 ? 'bg-purple-500/15 text-purple-600 dark:text-purple-400 border border-purple-500/30' : 'bg-slate-100 dark:bg-white/[0.06] text-slate-500 dark:text-slate-400 border border-slate-200 dark:border-white/[0.08]'}">
              ${productCount} ${productCount === 1 ? (window.__t ? window.__t('categories.card_active_product_singular', 'Item') : 'Item') : (window.__t ? window.__t('categories.card_active_product_plural', 'Items') : 'Items')}
            </span>
          </td>

          <!-- Created By / Date -->
          <td class="px-5 py-4 border-r border-slate-100 dark:border-white/[0.06] text-xs">
            <p class="font-bold text-slate-800 dark:text-slate-200">@${escapeHtml(mapUserName(c.created_by || c.createdBy))}</p>
            <p class="text-[10px] text-slate-400 mt-0.5">📅 ${formatDate(c.created_at || c.createdAt || new Date())}</p>
          </td>

          <!-- Actions -->
          <td class="px-5 py-4 text-end">
            <div class="flex items-center justify-end gap-1.5">
              <button onclick="showCategoryDetails('${escapeJsString(c.__backendId)}')" title="${window.__t ? window.__t('categories.btn_details_title', 'Category Details & History') : 'Category Details & History'}"
                class="p-1.5 bg-slate-100 hover:bg-slate-200 dark:bg-white/[0.06] dark:hover:bg-white/[0.12] text-slate-600 dark:text-slate-300 rounded-xl transition-all border border-slate-200 dark:border-white/[0.08] cursor-pointer active:scale-95">
                <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
              </button>
              <button onclick="showCategoryProducts('${escapeJsString(c.__backendId)}')" title="${window.__t ? window.__t('categories.btn_view_list', 'View Assigned Products') : 'View Assigned Products'}"
                class="p-1.5 bg-purple-500/10 hover:bg-purple-500/20 text-purple-600 dark:text-purple-400 rounded-xl transition-all border border-purple-500/25 cursor-pointer active:scale-95">
                <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 6h16M4 10h16M4 14h16M4 18h16"></path></svg>
              </button>
              ${!isDeleted ? `
                <button onclick="editCategory('${escapeJsString(c.__backendId)}')" title="${window.__t ? window.__t('categories.btn_edit_title', 'Edit Category') : 'Edit Category'}"
                  class="p-1.5 bg-purple-500/10 hover:bg-purple-500/20 text-purple-600 dark:text-purple-400 rounded-xl transition-all border border-purple-500/25 cursor-pointer active:scale-95">
                  <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"></path></svg>
                </button>
                <button onclick="showDeleteCategoryModal('${escapeJsString(c.__backendId)}')" title="${window.__t ? window.__t('categories.btn_delete_title', 'Delete Category') : 'Delete Category'}"
                  class="p-1.5 bg-rose-500/10 hover:bg-rose-500/20 text-rose-600 dark:text-rose-400 rounded-xl transition-all border border-rose-500/25 cursor-pointer active:scale-95">
                  <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg>
                </button>
              ` : `
                <button onclick="showRestoreCategoryModal('${escapeJsString(c.__backendId)}')" title="${window.__t ? window.__t('categories.btn_restore_title', 'Restore Category') : 'Restore Category'}"
                  class="p-1.5 bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-600 dark:text-emerald-400 rounded-xl transition-all border border-emerald-500/25 cursor-pointer active:scale-95">
                  <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path></svg>
                </button>
              `}
            </div>
          </td>
        </tr>
      `;
    }

    function copyCategoryUid(uid, event) {
      if (event) event.stopPropagation();
      if (!uid) return;
      navigator.clipboard.writeText(uid).then(() => {
        showToast(window.__t ? window.__t('categories.copied_uid', 'Category UID copied!', { uid }) : 'Category UID copied!', 'success');
      }).catch(() => {
        showToast(window.__t ? window.__t('common.copy_failed', 'Failed to copy') : 'Failed to copy', 'error');
      });
    }
    window.copyCategoryUid = copyCategoryUid;

    // Reusable Apple/iOS Bento Category Card (With Big Hero Cover & Obsidian Velvet-Black Surface)
    function buildCategoryCardHtml(c) {
      const productCount = (getProducts() || []).filter(p => p.categoryId === c.__backendId && !p.deleted_at).length;
      const isDeleted = !!(c.deleted_at || c.deletedAt);
      const hexColor = c.color || '#8b5cf6';

      const catIcon = c.picture
        ? `<img src="${c.picture}" class="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300" alt="${escapeHtml(c.name)}">`
        : `<div class="w-full h-full flex items-center justify-center" style="background:${hexColor}">
            <svg class="w-16 h-16 text-white/90 drop-shadow-md group-hover:scale-110 transition-transform duration-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M7 7h.01M7 3h5c.512 0 1.024.195 1.414.586l7 7a2 2 0 010 2.828l-7 7a2 2 0 01-2.828 0l-7-7A1.994 1.994 0 013 12V7a4 4 0 014-4z"></path></svg>
           </div>`;

      return `
        <div class="category-card-obsidian overflow-hidden flex flex-col justify-between relative group ${isDeleted ? 'opacity-85 grayscale-[0.3] !border-rose-500/40' : ''}">
          
          <!-- BIG HERO COVER IMAGE / GRADIENT (h-44 / aspect-[16/9]) -->
          <div class="relative w-full h-44 flex items-center justify-center overflow-hidden bg-slate-100 dark:bg-[#080b10] border-b border-slate-100 dark:border-white/[0.06]">
            ${catIcon}
            
            <!-- Floating Info Button -->
            <button onclick="showCategoryDetails('${escapeJsString(c.__backendId)}')"
              class="absolute top-3 right-3 w-8 h-8 rounded-full bg-black/50 hover:bg-black/75 backdrop-blur-md text-white flex items-center justify-center transition-all shadow-md z-10 cursor-pointer active:scale-90" title="${window.__t ? window.__t('categories.details_modal_title', 'Category Details & History') : 'Category Details & History'}">
              <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
            </button>

            <!-- Floating Status Badge -->
            ${isDeleted ? `
              <div class="absolute top-3 left-3">
                <span class="px-2.5 py-0.5 bg-rose-600/90 backdrop-blur-md text-white text-[10px] font-black uppercase tracking-wider rounded-full shadow border border-white/10">${window.__t ? window.__t('common.deleted', 'Deleted') : 'Deleted'}</span>
              </div>
            ` : `
              <div class="absolute top-3 left-3">
                <span class="px-2.5 py-0.5 bg-black/40 backdrop-blur-md text-white text-[10px] font-bold uppercase tracking-wider rounded-full shadow border border-white/10 flex items-center gap-1.5">
                  <span class="w-2 h-2 rounded-full" style="background-color:${hexColor}"></span>
                  <span>${window.__t ? window.__t('categories.card_department_badge', 'Department') : 'Department'}</span>
                </span>
              </div>
            `}
          </div>

          <!-- Body Details -->
          <div class="p-5 flex flex-col flex-1 justify-between">
            <div>
              <!-- Category Name & Color Dot -->
              <div class="flex items-center gap-2 mb-2">
                <span class="w-3 h-3 rounded-full shrink-0 shadow-xs" style="background-color:${hexColor}"></span>
                <h4 class="font-black text-slate-900 dark:text-white text-base truncate">@${escapeHtml(c.name)}</h4>
              </div>

              <!-- Prominent Monospace UID Bar (Click to copy) -->
              <div class="mb-3">
                <button onclick="copyCategoryUid('${escapeJsString(c.uid || c.__backendId)}', event)" title="${window.__t ? window.__t('categories.card_copy_uid_title', 'Click to copy Category UID: #{uid}', { uid: c.uid || c.__backendId }) : `Click to copy Category UID: #${c.uid || c.__backendId}`}"
                  class="w-full flex items-center justify-between px-3 py-1.5 rounded-xl bg-slate-50 hover:bg-purple-50 hover:text-purple-600 hover:border-purple-300 dark:bg-[#080b10] dark:hover:bg-purple-950/30 text-slate-700 dark:text-slate-200 font-mono text-xs font-bold transition-all border border-slate-200/90 dark:border-white/[0.08] shadow-2xs group/uid cursor-pointer active:scale-98">
                  <div class="flex items-center gap-2 min-w-0">
                    <span class="text-purple-500 font-black text-sm">#</span>
                    <span class="tracking-wide font-black text-slate-900 dark:text-slate-100 text-xs truncate">${c.uid || c.__backendId}</span>
                  </div>
                  <div class="flex items-center gap-1 text-[10px] text-slate-400 group-hover/uid:text-purple-500 font-sans font-bold uppercase tracking-wider shrink-0">
                    <span>${window.__t ? window.__t('common.copy', 'Copy') : 'Copy'}</span>
                    <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z"></path></svg>
                  </div>
                </button>
              </div>

              <!-- Active Products & View List Pill Bar -->
              <div class="flex items-center justify-between p-2.5 rounded-2xl bg-slate-50/80 dark:bg-[#080b10] border border-slate-100 dark:border-white/[0.06] mb-3">
                <div>
                  <p class="text-[9px] font-black uppercase tracking-wider text-slate-400 dark:text-slate-500">${window.__t ? window.__t('categories.card_inventory_assigned', 'Inventory Assigned') : 'Inventory Assigned'}</p>
                  <p class="text-xs font-bold text-slate-800 dark:text-slate-200 mt-0.5">${productCount} ${window.__t ? (productCount === 1 ? window.__t('categories.card_active_product_singular', 'active product') : window.__t('categories.card_active_product_plural', 'active products')) : `active product${productCount !== 1 ? 's' : ''}`}</p>
                </div>
                <button onclick="event.stopPropagation(); showCategoryProducts('${escapeJsString(c.__backendId)}')"
                  class="px-3 py-1.5 bg-gradient-to-r from-purple-500 to-indigo-600 hover:from-purple-600 hover:to-indigo-700 text-white text-[10px] font-black uppercase tracking-wider rounded-xl shadow-xs flex items-center gap-1 group/btn transition-all transform hover:-translate-y-0.5 cursor-pointer active:scale-95">
                  <span>${window.__t ? window.__t('categories.card_btn_view_list', 'View List') : 'View List'}</span>
                  <svg class="w-3 h-3 transition-transform group-hover/btn:translate-x-0.5 rtl:group-hover/btn:-translate-x-0.5 rtl-flip rtl:rotate-180" style="${(document.documentElement.getAttribute('dir') === 'rtl' || (typeof window.__tLang === 'function' && window.__tLang() === 'ar')) ? 'transform: scaleX(-1) !important;' : ''}" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7"></path></svg>
                </button>
              </div>

              <!-- Description -->
              <p class="text-xs text-slate-500 dark:text-slate-400 line-clamp-2 min-h-[32px] mb-3 leading-relaxed">${escapeHtml(c.description || (window.__t ? window.__t('categories.card_no_desc', 'No description provided for this department.') : 'No description provided for this department.'))}</p>
            </div>

            <div>
              <!-- Creator & Edit Metadata -->
              <div class="pt-2 border-t border-slate-100 dark:border-white/[0.06] text-[11px] text-slate-500 dark:text-slate-400 mb-2.5 flex items-center justify-between" ${(c.edited_by || c.editedBy) ? `title="${window.__t ? window.__t('common.last_edited_tooltip', 'Last edited on ${date} by @${user}', { date: formatDate(c.updatedAt || c.updated_at), user: mapUserName(c.edited_by || c.editedBy) }) : `Last edited on ${formatDate(c.updatedAt || c.updated_at)} by @${escapeHtml(mapUserName(c.edited_by || c.editedBy))}`}"` : ''}>
                <div class="flex items-center gap-1">
                  <span>${window.__t ? window.__t('common.by_colon', 'By:') : 'By:'}</span>
                  <span class="font-bold text-purple-600 dark:text-purple-400 ml-1">@${escapeHtml(c.createdBy || mapUserName(c.created_by))}</span>
                </div>
                <div>
                  <span class="text-slate-400 dark:text-slate-500 font-medium">📅 ${formatDate(c.createdAt || c.created_at || new Date())}</span>
                </div>
              </div>

              <!-- Action Buttons Dock -->
              <div class="pt-2.5 border-t border-slate-100 dark:border-white/[0.06] flex items-center gap-2">
                ${!isDeleted ? `
                  <button onclick="editCategory('${escapeJsString(c.__backendId)}')"
                    class="flex-1 py-2 px-3 bg-purple-500/10 hover:bg-purple-500/20 text-purple-600 dark:text-purple-400 font-bold text-xs rounded-xl transition-all border border-purple-500/25 shadow-2xs flex items-center justify-center gap-1.5 cursor-pointer active:scale-95">
                    <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"></path></svg>
                    <span>${window.__t ? window.__t('common.edit', 'Edit') : 'Edit'}</span>
                  </button>
                  <button onclick="showDeleteCategoryModal('${escapeJsString(c.__backendId)}')" title="${window.__t ? window.__t('categories.card_btn_delete_title', 'Delete Category') : 'Delete Category'}"
                    class="p-2 bg-rose-500/10 hover:bg-rose-500/20 text-rose-600 dark:text-rose-400 rounded-xl transition-all border border-rose-500/25 shadow-2xs cursor-pointer active:scale-95">
                    <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg>
                  </button>
                ` : `
                  <button onclick="showRestoreCategoryModal('${escapeJsString(c.__backendId)}')"
                    class="flex-1 py-2 px-3 bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-600 dark:text-emerald-400 font-bold text-xs rounded-xl transition-all border border-emerald-500/25 shadow-2xs flex items-center justify-center gap-1.5 cursor-pointer active:scale-95">
                    <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path></svg>
                    <span>${window.__t ? window.__t('categories.card_btn_restore', 'Restore Category') : 'Restore Category'}</span>
                  </button>
                `}
              </div>
            </div>

          </div>
        </div>
      `;
    }

    function updateCategoriesGrid(categories) {
      syncCategoriesViewModeUi();
      const grid = document.getElementById('categories-grid');
      const tableBody = document.getElementById('categories-table-tbody');
      if (!grid && !tableBody) return;

      if (categories.length === 0) {
        const emptyHtml = `
          <div class="category-card-obsidian rounded-3xl p-12 text-center border border-slate-200 dark:border-white/[0.08] bg-white/70 dark:bg-[#0d1117] shadow-sm col-span-full w-full">
            <div class="w-16 h-16 rounded-3xl bg-purple-50 dark:bg-purple-950/60 border border-purple-100 dark:border-purple-800/80 flex items-center justify-center mx-auto mb-4 text-purple-500">
              <svg class="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M7 7h.01M7 3h5c.512 0 1.024.195 1.414.586l7 7a2 2 0 010 2.828l-7 7a2 2 0 01-2.828 0l-7-7A1.994 1.994 0 013 12V7a4 4 0 014-4z"></path></svg>
            </div>
            <h4 class="text-base font-bold text-slate-800 dark:text-slate-100">${window.__t ? window.__t('categories.empty_title', 'No categories found') : 'No categories found'}</h4>
            <p class="text-xs text-slate-400 dark:text-slate-500 mt-1 max-w-sm mx-auto">${window.__t ? window.__t('categories.empty_desc', 'No categories match your search keyword or active filter selection.') : 'No categories match your search keyword or active filter selection.'}</p>
            <button onclick="showCategoryModal()" class="mt-4 px-4 py-2 bg-purple-600 hover:bg-purple-700 text-white font-bold text-xs rounded-xl shadow-xs transition-all cursor-pointer">${window.__t ? window.__t('categories.empty_btn_create', 'Add New Category') : 'Add New Category'}</button>
          </div>
        `;
        if (grid) grid.innerHTML = emptyHtml;
        if (tableBody) tableBody.innerHTML = `<tr><td colspan="5" class="p-12 text-center">${emptyHtml}</td></tr>`;
        return;
      }

      if (categoriesViewMode === 'table') {
        if (tableBody) {
          tableBody.innerHTML = categories.map(renderCategoryTableRow).join('');
        }

        if (grid) grid.innerHTML = '';
      } else {
        if (grid) {
          grid.innerHTML = categories.map(buildCategoryCardHtml).join('');
        }

        if (tableBody) tableBody.innerHTML = '';
      }
    }

    function showCategoryModal() {
      document.getElementById('category-form').reset();
      document.getElementById('category-edit-id').value = '';
      document.getElementById('category-modal-title').textContent = window.__t ? window.__t('categories.modal_title_add', 'Add New Category') : 'Add New Category';
      document.getElementById('category-picture-data').value = '';
      const catPicName = document.getElementById('category-picture-name');
      if (catPicName) catPicName.value = '';
      const catChosenLabel = document.getElementById('category-file-chosen-text');
      if (catChosenLabel) catChosenLabel.textContent = window.__t ? window.__t('categories.no_file_chosen', 'No file chosen') : 'No file chosen';
      document.getElementById('category-image-img').classList.add('hidden');
      document.getElementById('category-default-icon').classList.remove('hidden');
      document.getElementById('category-image-remove-btn').classList.add('hidden');
      setColor('#3b82f6');
      document.getElementById('category-modal').classList.remove('hidden');
    }

    function closeCategoryModal() {
      document.getElementById('category-modal').classList.add('hidden');
    }


    let categoryProductsCache = []; // cached for toggle filtering
    let categoryProductsCategoryObj = null;

    async function showCategoryProducts(categoryId) {
      const category = getCategories().find(c => c.__backendId === categoryId);
      let categoryName = category ? category.name : 'Unknown Category';
      categoryProductsCategoryObj = category;

      const titleEl = document.getElementById('category-products-title');
      if (titleEl) {
        titleEl.textContent = (window.__t ? window.__t('categories.products_sheet_title', 'Products in Category') : 'Products in Category') + ': ' + categoryName;
      }

      // Pre-fill instantly from local products cache
      const localProducts = (getProducts() || []).filter(p => p.categoryId === categoryId);
      categoryProductsCache = localProducts;
      renderCategoryProductsTable(false);

      // Reset toggle to off (show active by default)
      const toggle = document.getElementById('category-products-show-deleted');
      if (toggle) toggle.checked = false;

      document.getElementById('category-products-modal').classList.remove('hidden');

      try {
        const response = await apiRequest(`/api/products?category_id=${encodeURIComponent(categoryId)}&show_deleted=true`);
        const allProducts = (response.products || []).map(normalizeProduct);
        categoryProductsCache = allProducts;
        renderCategoryProductsTable(false);
      } catch (e) {
        console.warn('Targeted category fetch error:', e);
      }
    }

    function toggleCategoryProductsDeleted() {
      const showDeleted = document.getElementById('category-products-show-deleted').checked;
      renderCategoryProductsTable(showDeleted);
    }

    function renderCategoryProductsTable(showDeletedOnly) {
      const tbody = document.getElementById('category-products-table');
      const countBadge = document.getElementById('category-products-count-badge');
      const category = categoryProductsCategoryObj;
      const products = categoryProductsCache.filter(p => {
        const isDeleted = !!(p.deleted_at || p.deletedAt);
        return showDeletedOnly ? isDeleted : !isDeleted;
      });

      if (countBadge) {
        const _t = (k, fb) => (window.__t ? window.__t(k, fb) : fb);
        let label = '';
        if (showDeletedOnly) {
          label = products.length === 1
            ? _t('categories.card_deleted_product_singular', 'deleted product')
            : _t('categories.card_deleted_product_plural', 'deleted products');
        }
 else {
          label = products.length === 1
            ? _t('categories.card_active_product_singular', 'active product')
            : _t('categories.card_active_product_plural', 'active products');
        }

        countBadge.textContent = `${products.length} ${label}`;
      }

      if (products.length === 0) {
        const msg = showDeletedOnly
          ? (window.__t ? window.__t('categories.products_empty_deleted', 'No deleted products in this category') : 'No deleted products in this category')
          : (window.__t ? window.__t('categories.products_empty_active', 'No active products in this category') : 'No active products in this category');
        tbody.innerHTML = `<tr><td colspan="5" class="px-4 py-12 text-center text-slate-400 dark:text-slate-500 font-medium">${msg}</td></tr>`;
        return;
      }

      const _t = (k, fb) => (window.__t ? window.__t(k, fb) : fb);
      const labelDeleted = _t('categories.status_deleted', 'DELETED');
      const labelInStock = _t('categories.status_instock', 'IN STOCK');
      const labelLow = _t('categories.status_low', 'LOW');
      const labelUrgent = _t('categories.status_urgent', 'URGENT');

      tbody.innerHTML = products.map(p => {
        const qty = getProductAvailableQuantity(p.__backendId);
        const inThreshold = toExactDecimalString(p.stockInThreshold || stockThresholds.inStock);
        const lowThreshold = toExactDecimalString(p.stockLowThreshold || stockThresholds.lowStock);

        const isDeleted = p.deleted_at || p.deletedAt;

        let statusBadge = '';
        if (isDeleted) {
          statusBadge = `<span class="px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase tracking-wider bg-slate-200 dark:bg-slate-700 text-slate-700 dark:text-slate-300">${labelDeleted}</span>`;
        }
 else if (exactCompare(qty, inThreshold) >= 0) {
          statusBadge = `<span class="px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase tracking-wider bg-emerald-100 dark:bg-emerald-950/60 text-emerald-700 dark:text-emerald-400">${labelInStock}</span>`;
        }
 else if (exactCompare(qty, lowThreshold) >= 0) {
          statusBadge = `<span class="px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase tracking-wider bg-amber-100 dark:bg-amber-950/60 text-amber-700 dark:text-amber-400">${labelLow}</span>`;
        }
 else {
          statusBadge = `<span class="px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase tracking-wider bg-rose-100 dark:bg-rose-950/60 text-rose-700 dark:text-rose-400">${labelUrgent}</span>`;
        }


        const imageHtml = p.picture ?
          `<img src="${p.picture}" class="w-full h-full object-cover" alt="${escapeHtml(p.name)}">` :
          `<svg class="w-4 h-4 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4"></path></svg>`;

        const colors = getColorStyles(p.color || (category ? category.color : '#64748b'));
        const addedOn = (p.createdAt || p.created_at) ? formatDate(p.createdAt || p.created_at) : '---';

        return `
          <tr class="hover:bg-slate-50/80 dark:hover:bg-slate-800/50 transition-colors ${isDeleted ? 'opacity-70' : ''}">
            <td class="w-2/5 px-4 py-3 font-semibold text-slate-800 dark:text-slate-100">
              <div class="flex items-center gap-3">
                <div class="w-8 h-8 rounded-lg flex items-center justify-center shrink-0 overflow-hidden shadow-2xs text-white" style="${colors.bg}">
                  ${imageHtml}
                </div>
                <span class="truncate ${isDeleted ? 'line-through text-slate-400' : ''}">${escapeHtml(p.name)}</span>
              </div>
            </td>
            <td class="w-1/6 px-4 py-3 font-mono text-xs text-slate-500 dark:text-slate-400">#${p.uid || '---'}</td>
            <td class="w-1/5 px-4 py-3 font-black text-center text-slate-900 dark:text-slate-100">${formatQuantity(qty, p.displayDecimals)}</td>
            <td class="w-1/6 px-4 py-3 text-center text-xs text-slate-500 dark:text-slate-400">${addedOn}</td>
            <td class="w-1/6 px-4 py-3 text-right">${statusBadge}</td>
          </tr>
        `;
      }).join('');
    }

    function closeCategoryProductsModal() {
      document.getElementById('category-products-modal').classList.add('hidden');
      categoryProductsCache = [];
    }

    async function editCategory(id) {
      const category = getCategories().find(c => c.__backendId === id);
      if (!category) return;

      document.getElementById('category-edit-id').value = id;
      document.getElementById('category-modal-title').textContent = window.__t ? window.__t('categories.modal_title_edit', 'Edit Category') : 'Edit Category';
      document.getElementById('category-name').value = category.name;
      document.getElementById('category-description').value = category.description || '';
      document.getElementById('category-picture-data').value = category.picture || '';
      document.getElementById('category-picture-name').value = category.picture_name || '';
      const catPicName = category.picture_name || category.pictureName || '';
      const catChosenText = document.getElementById('category-file-chosen-text');
      if (catChosenText) catChosenText.textContent = catPicName || (category.picture ? (window.__t ? window.__t('categories.file_attached', 'Image attached') : 'Image attached') : (window.__t ? window.__t('categories.no_file_chosen', 'No file chosen') : 'No file chosen'));

      // Set color
      setColor(category.color || '#3b82f6');

      // Set image preview
      if (category.picture) {
        document.getElementById('category-image-img').src = category.picture;
        document.getElementById('category-image-img').classList.remove('hidden');
        document.getElementById('category-default-icon').classList.add('hidden');
        document.getElementById('category-image-remove-btn').classList.remove('hidden');
      } else {
        document.getElementById('category-image-img').classList.add('hidden');
        document.getElementById('category-default-icon').classList.remove('hidden');
        document.getElementById('category-image-remove-btn').classList.add('hidden');
      }

      document.getElementById('category-modal').classList.remove('hidden');
    }

    async function saveCategory(e) {
      e.preventDefault();

      const btn = document.getElementById('category-submit-btn');
      btn.disabled = true;
      btn.textContent = window.__t ? window.__t('categories.btn_saving', 'Saving...') : 'Saving...';

      const editId = document.getElementById('category-edit-id').value;
      const isEdit = editId !== '';

      try {
        const data = {
          name: document.getElementById('category-name').value,
          color: document.getElementById('category-color-hex').value,
          description: document.getElementById('category-description').value,
          picture: document.getElementById('category-picture-data').value || null,
          picture_name: document.getElementById('category-picture-name').value || null
        }
;

        if (isEdit) {
          await apiRequest(`/api/categories/${editId}`, {
            method: 'PUT',
            body: JSON.stringify(data)
          }
);
          showToast(window.__t ? window.__t('categories.toast_updated', 'Category updated successfully!') : 'Category updated successfully!');
        }
 else {
          await apiRequest('/api/categories', {
            method: 'POST',
            body: JSON.stringify(data)
          }
);
          showToast(window.__t ? window.__t('categories.toast_added', 'Category added successfully!') : 'Category added successfully!');
        }


        closeCategoryModal();
        await loadAllData();
      } catch (e) {
        showToast(e.message || (window.__t ? window.__t('categories.toast_failed_save', 'Failed to save category') : 'Failed to save category'));
      }

      btn.disabled = false;
      btn.textContent = window.__t ? window.__t('categories.btn_save', 'Save Category') : 'Save Category';
    }

    // Delete Modal Functions
    function showDeleteCategoryModal(id) {
      categoryToDelete = id;
      const cat = (getCategories() || []).find(c => c.__backendId === id || String(c.id) === String(id));
      const nameEl = document.getElementById("delete-category-name");
      if (nameEl) nameEl.textContent = cat ? cat.name : "Category";
      const uidEl = document.getElementById("delete-category-uid");
      if (uidEl) uidEl.textContent = cat ? (cat.uid || "#" + (cat.__backendId || cat.id)) : "-";

      const productsUsingCategory = (getProducts() || []).filter(p => (p.categoryId === id || String(p.categoryId) === String(id)) && !p.deleted_at && !p.deletedAt);

      if (productsUsingCategory.length > 0) {
        document.getElementById("category-delete-warning")?.classList.remove("hidden");
        const countEl = document.getElementById("category-product-count");
        if (countEl) countEl.textContent = productsUsingCategory.length;
      } else {
        document.getElementById("category-delete-warning")?.classList.add("hidden");
      }

      const reasonEl = document.getElementById("category-delete-reason");
      if (reasonEl) reasonEl.value = "";
      document.getElementById("category-delete-modal")?.classList.remove("hidden");
    }

    function closeCategoryDeleteModal() {
      document.getElementById('category-delete-modal').classList.add('hidden');
      categoryToDelete = null;
    }

    async function confirmDeleteCategory(e) {
      e.preventDefault();

      if (!categoryToDelete) return;

      const reason = document.getElementById('category-delete-reason').value.trim();
      if (!reason) {
        showToast(window.__t ? window.__t('categories.toast_delete_reason_required', 'Please enter a reason for deletion') : 'Please enter a reason for deletion');
        return;
      }

      try {
        await apiRequest(`/api/categories/${categoryToDelete}`, {
          method: 'DELETE',
          body: JSON.stringify({ delete_reason: reason })
        }
);

        closeCategoryDeleteModal();
        await loadAllData();
        showToast(window.__t ? window.__t('categories.toast_deleted', 'Category deleted successfully') : 'Category deleted successfully');
      } catch (e) {
        showToast(e.message || (window.__t ? window.__t('categories.toast_failed_delete', 'Failed to delete category') : 'Failed to delete category'));
      }
    }

    let currentCategoryDetailsId = null;
    // Details/History Modal Functions
    async function showCategoryDetails(id) {
      currentCategoryDetailsId = id;
      const historyTable = document.getElementById('category-history-table');
      const mobileFeed = document.getElementById('category-history-mobile-feed');
      if (historyTable) {
        historyTable.innerHTML = `<tr><td colspan="4" class="px-4 py-8 text-center text-slate-400 animate-pulse category-details-history">${window.__t ? window.__t('categories.details_loading_history', 'Loading history...') : 'Loading history...'}</td></tr>`;
      }
      if (mobileFeed) {
        mobileFeed.innerHTML = `<div class="p-6 text-center text-slate-400 text-xs bg-slate-50/50 dark:bg-[#080b10] rounded-2xl border border-slate-200/80 dark:border-white/[0.06] animate-pulse">${window.__t ? window.__t('categories.details_loading_history', 'Loading history...') : 'Loading history...'}</div>`;
      }
      try {
        const response = await apiRequest(`/api/categories/${id}/history`);
        const category = response.category;
        const history = response.history;

        document.getElementById('category-details-name').textContent = category.name;
        const catUidEl = document.getElementById('category-details-uid');
        if (catUidEl) catUidEl.textContent = category.uid || `#${category.id}`;
        document.getElementById('category-details-created-by').textContent = category.creator_name || mapUserName(category.created_by);
        document.getElementById('category-details-created-at').textContent = formatDateTime(category.created_at);
        const catUpdatedByEl = document.getElementById('category-details-updated-by');
        if (catUpdatedByEl) catUpdatedByEl.textContent = category.editor_name || (window.__t ? window.__t('categories.details_never_updated', 'None (Original)') : 'None (Original)');
        const catUpdatedAtEl = document.getElementById('category-details-updated-at');
        if (catUpdatedAtEl) catUpdatedAtEl.textContent = category.updated_at ? formatDateTime(category.updated_at) : (window.__t ? window.__t('common.never', 'Never') : 'Never');

        // Show deletion info if deleted
        if (category.deleted_at) {
          document.getElementById('category-details-deletion').classList.remove('hidden');
          document.getElementById('category-details-deleted-by').textContent = category.deleted_by_name || mapUserName(category.deleted_by);
          document.getElementById('category-details-deleted-at').textContent = formatDateTime(category.deleted_at);
          document.getElementById('category-details-delete-reason').textContent = category.delete_reason || (window.__t ? window.__t('common.no_reason', 'No reason provided') : 'No reason provided');
        }
 else {
          document.getElementById('category-details-deletion').classList.add('hidden');
        }


        // Show Picture Box with Category Color styling
        const catPicContainer = document.getElementById('category-details-picture-container');
        if (catPicContainer) {
          const catColors = getColorStyles(category.color || '#8b5cf6');
          catPicContainer.style = catColors.bg;
        }


        const pictureImg = document.getElementById('category-details-picture');
        const defaultIcon = document.getElementById('category-details-default-icon');
        if (category.picture) {
          pictureImg.onload = () => {
            pictureImg.classList.remove('hidden');
            if (defaultIcon) defaultIcon.classList.add('hidden');
          }
;
          pictureImg.onerror = () => {
            pictureImg.classList.add('hidden');
            if (defaultIcon) defaultIcon.classList.remove('hidden');
          }
;
          pictureImg.src = resolveMediaUrl(category.picture);
        }
 else {
          pictureImg.src = '';
          pictureImg.classList.add('hidden');
          if (defaultIcon) defaultIcon.classList.remove('hidden');
        }


        // Display history
        if (!history || history.length === 0) {
          const noHistMsg = window.__t ? window.__t('common.no_history', 'No history available') : 'No history available';
          if (historyTable) historyTable.innerHTML = `<tr><td colspan="4" class="px-4 py-8 text-center text-slate-400">${noHistMsg}</td></tr>`;
          if (mobileFeed) mobileFeed.innerHTML = `<div class="p-6 text-center text-slate-400 text-xs bg-slate-50/50 dark:bg-[#080b10] rounded-2xl border border-slate-200/80 dark:border-white/[0.06]">${noHistMsg}</div>`;
        } else {
          const tableRows = [];
          const mobileCards = [];

          history.forEach(h => {
            let changesHtml = '-';
            if (h.action === 'created') {
              changesHtml = `<span class="text-green-600 font-medium">${window.__t ? window.__t('categories.history_created', 'Category created') : 'Category created'}</span>`;
            } else if (h.action === 'updated' && h.changes) {
              try {
                const changes = typeof h.changes === 'string' ? JSON.parse(h.changes || '{}') : (h.changes || {});
                changesHtml = Object.keys(changes).map(key => {
                  const change = changes[key];
                  let fromVal = change.from || 'empty';
                  let toVal = change.to || 'empty';

                  if (key === 'picture' || key === 'picture_name') {
                    if (key === 'picture' && changes.picture_name) return '';

                    const fromName = changes.picture_name ? (changes.picture_name.from || 'empty') : (change.from || 'empty');
                    const toName = changes.picture_name ? (changes.picture_name.to || 'empty') : (change.to || 'empty');

                    fromVal = fromName !== '' && fromName !== null ? fromName : 'empty';
                    toVal = toName !== '' && toName !== null ? toName : 'empty';

                    if (fromVal === toVal && fromVal === 'empty') return '';

                    const fieldLabel = formatAuditFieldName('picture');
                    if (fromVal === 'empty') {
                      return `<div class="inline-flex items-center gap-1.5 whitespace-nowrap"><span class="font-semibold text-slate-700 dark:text-slate-300">${fieldLabel}:</span> <span class="text-slate-400 italic">${formatAuditValue(fromVal, 'picture')}</span> <span class="text-slate-400 font-mono inline-block rtl:rotate-180">&rarr;</span> <span class="text-emerald-600 dark:text-emerald-400 font-mono font-bold bg-emerald-500/10 px-1.5 py-0.5 rounded">"${escapeHtml(toVal)}"</span></div>`;
                    }

                    if (toVal === 'empty') {
                      return `<div class="inline-flex items-center gap-1.5 whitespace-nowrap"><span class="font-semibold text-slate-700 dark:text-slate-300">${fieldLabel}:</span> <span class="text-rose-500 font-mono font-bold line-through bg-rose-500/10 px-1.5 py-0.5 rounded">"${escapeHtml(fromVal)}"</span> <span class="text-slate-400 font-mono inline-block rtl:rotate-180">&rarr;</span> <span class="text-slate-400 italic">${formatAuditValue(toVal, 'picture')}</span></div>`;
                    }

                    return `<div class="inline-flex items-center gap-1.5 whitespace-nowrap"><span class="font-semibold text-slate-700 dark:text-slate-300">${fieldLabel}:</span> <span class="text-slate-400 font-mono line-through bg-slate-500/10 px-1.5 py-0.5 rounded">"${escapeHtml(fromVal)}"</span> <span class="text-slate-400 font-mono inline-block rtl:rotate-180">&rarr;</span> <span class="text-emerald-600 dark:text-emerald-400 font-mono font-bold bg-emerald-500/10 px-1.5 py-0.5 rounded">"${escapeHtml(toVal)}"</span></div>`;
                  }

                  const fieldLabel = formatAuditFieldName(key);
                  const formattedFrom = formatAuditValue(fromVal, key);
                  const formattedTo = formatAuditValue(toVal, key);

                  return `<div class="inline-flex items-center gap-1.5 whitespace-nowrap"><span class="font-semibold text-slate-700 dark:text-slate-300">${fieldLabel}:</span> <span class="text-slate-400 line-through">"${escapeHtml(formattedFrom)}"</span> <span class="text-slate-400 font-mono inline-block rtl:rotate-180">&rarr;</span> <span class="text-emerald-600 dark:text-emerald-400 font-bold">"${escapeHtml(formattedTo)}"</span></div>`;
                }).filter(Boolean).join('<br>');
              } catch (e) {
                changesHtml = window.__t ? window.__t('common.updated', 'Updated') : 'Updated';
              }
            } else if (h.action === 'deleted') {
              changesHtml = `<div class="text-red-600 font-medium">${window.__t ? window.__t('common.deleted', 'Deleted') : 'Deleted'}</div><div class="text-xs text-slate-600 mt-1">${window.__t ? window.__t('common.reason', 'Reason:') : 'Reason:'} ${escapeHtml(h.reason || (window.__t ? window.__t('common.no_reason', 'No reason') : 'No reason'))}</div>`;
            } else if (h.action === 'restored') {
              changesHtml = `<div class="text-green-600 font-medium">${window.__t ? window.__t('common.restored', 'Restored') : 'Restored'}</div><div class="text-xs text-slate-600 mt-1">${window.__t ? window.__t('common.reason', 'Reason:') : 'Reason:'} ${escapeHtml(h.reason || (window.__t ? window.__t('common.no_reason', 'No reason') : 'No reason'))}</div>`;
            }

            const badgeColors = {
              created: 'bg-green-100 text-green-700 dark:bg-green-950/60 dark:text-green-400',
              updated: 'bg-blue-100 text-blue-700 dark:bg-blue-950/60 dark:text-blue-400',
              deleted: 'bg-red-100 text-red-700 dark:bg-red-950/60 dark:text-red-400',
              restored: 'bg-emerald-100 text-emerald-700 dark:bg-emerald-950/60 dark:text-emerald-400'
            };

            const actionLabels = {
              created: window.__t ? window.__t('common.created', 'Created') : 'Created',
              updated: window.__t ? window.__t('common.updated', 'Updated') : 'Updated',
              deleted: window.__t ? window.__t('common.deleted', 'Deleted') : 'Deleted',
              restored: window.__t ? window.__t('common.restored', 'Restored') : 'Restored'
            };

            const badgeClass = badgeColors[h.action] || 'bg-slate-100 text-slate-700';
            const actionLabel = actionLabels[h.action] || h.action;
            const formattedDate = formatDateTime(h.created_at);
            const editorName = escapeHtml(h.username || 'System');

            tableRows.push(`
              <tr class="hover:bg-slate-50/80 dark:hover:bg-white/[0.05] transition-colors">
                <td class="px-4 py-3 whitespace-nowrap text-slate-700 dark:text-slate-300 font-mono text-[11px] shrink-0">${formattedDate}</td>
                <td class="px-4 py-3 whitespace-nowrap text-slate-800 dark:text-slate-200 font-semibold shrink-0 truncate">${editorName}</td>
                <td class="px-4 py-3 whitespace-nowrap shrink-0"><span class="px-2 py-0.5 rounded-full text-xs font-bold ${badgeClass}">${actionLabel}</span></td>
                <td class="px-4 py-3 text-slate-600 dark:text-slate-300 text-xs min-w-0">
                  <div class="overflow-x-auto custom-scrollbar max-w-full py-0.5">
                    ${changesHtml}
                  </div>
                </td>
              </tr>
            `);

            mobileCards.push(`
              <div class="p-3.5 rounded-2xl bg-white dark:bg-[#080b10] border border-slate-200/80 dark:border-white/[0.08] shadow-2xs space-y-2">
                <div class="flex items-center justify-between gap-2">
                  <div class="flex items-center gap-1.5 min-w-0">
                    <span class="px-2 py-0.5 rounded-full text-xs font-bold ${badgeClass}">${actionLabel}</span>
                    <span class="text-xs font-bold text-slate-800 dark:text-slate-200 truncate">@${editorName}</span>
                  </div>
                  <span class="text-[10px] font-mono text-slate-400 dark:text-slate-500 whitespace-nowrap shrink-0">${formattedDate}</span>
                </div>
                <div class="text-xs text-slate-600 dark:text-slate-300 pt-1.5 border-t border-slate-100 dark:border-white/[0.06] overflow-x-auto custom-scrollbar">
                  ${changesHtml}
                </div>
              </div>
            `);
          });

          if (historyTable) historyTable.innerHTML = tableRows.join('');
          if (mobileFeed) mobileFeed.innerHTML = mobileCards.join('');
        }

        // Show/hide restore button
        if (category.deleted_at) {
          document.getElementById('category-details-restore-btn').classList.remove('hidden');
          document.getElementById('category-details-restore-btn').classList.add('flex');
        }
 else {
          document.getElementById('category-details-restore-btn').classList.add('hidden');
          document.getElementById('category-details-restore-btn').classList.remove('flex');
        }


        const catModal = document.getElementById('category-details-modal');
        if (catModal) {
          if (typeof ModalManager !== 'undefined' && typeof ModalManager.bringToFront === 'function') {
            ModalManager.bringToFront(catModal);
          }

          catModal.classList.remove('hidden');
        }

      } catch (e) {
        showToast(e.message || (window.__t ? window.__t('categories.toast_details_load_failed', 'Failed to load category details') : 'Failed to load category details'));
      }
    }

    function closeCategoryDetailsModal() {
      const catModal = document.getElementById('category-details-modal');
      if (catModal) {
        catModal.classList.add('hidden');
        const catImg = document.getElementById('category-details-picture');
        if (catImg) catImg.src = '';
        if (typeof ModalManager !== 'undefined' && typeof ModalManager.resetZIndex === 'function') {
          ModalManager.resetZIndex(catModal);
        }

      }
      currentCategoryDetailsId = null;
    }

    let pendingRestoreCategoryId = null;

    function showRestoreCategoryModal(id) {
      const category = getCategories().find(c => c.__backendId === id);
      if (!category) return;
      pendingRestoreCategoryId = id;
      document.getElementById('restore-category-name').textContent = category.name;
      document.getElementById('restore-category-reason').value = '';
      const modal = document.getElementById('category-restore-modal');
      if (modal) {
        if (typeof ModalManager !== 'undefined' && typeof ModalManager.bringToFront === 'function') {
          ModalManager.bringToFront(modal);
        }

        modal.classList.remove('hidden');
      }
    }
    window.showRestoreCategoryModal = showRestoreCategoryModal;
    window.showCategoryRestoreModal = showRestoreCategoryModal;

    function closeRestoreCategoryModal() {
      const modal = document.getElementById('category-restore-modal');
      if (modal) {
        if (typeof ModalManager !== 'undefined' && typeof ModalManager.resetZIndex === 'function') {
          ModalManager.resetZIndex(modal);
        }

        modal.classList.add('hidden');
      }
      pendingRestoreCategoryId = null;
    }
    window.closeRestoreCategoryModal = closeRestoreCategoryModal;
    window.closeCategoryRestoreModal = closeRestoreCategoryModal;

    async function confirmRestoreCategory(event) {
      event.preventDefault();
      if (!pendingRestoreCategoryId) return;

      const reason = document.getElementById('restore-category-reason').value.trim();
      if (!reason) {
        showToast(window.__t ? window.__t('categories.toast_restore_reason_required', 'Please provide a reason for restoration') : 'Please provide a reason for restoration');
        return;
      }

      const btn = document.getElementById('confirm-restore-category-btn');
      btn.disabled = true;
      btn.textContent = window.__t ? window.__t('categories.restore_btn_restoring', 'Restoring...') : 'Restoring...';

      try {
        await apiRequest(`/api/categories/${pendingRestoreCategoryId}/restore`, {
          method: 'POST',
          body: JSON.stringify({ restore_reason: reason })
        }
);
        showToast(window.__t ? window.__t('categories.toast_restored', 'Category restored successfully') : 'Category restored successfully');
        closeRestoreCategoryModal();
        if (currentCategoryDetailsId === pendingRestoreCategoryId) {
          closeCategoryDetailsModal();
        }

        await loadAllData();
      } catch (e) {
        showToast(e.message || (window.__t ? window.__t('categories.toast_failed_restore', 'Failed to restore category') : 'Failed to restore category'));
      }

      btn.disabled = false;
      btn.textContent = window.__t ? window.__t('categories.restore_btn_confirm', 'Confirm Restore') : 'Confirm Restore';
    }

