    // Image Upload Functions
    function handleCategoryImageUpload(event) {
      const file = event.target.files[0];
      if (!file) return;

      if (!file.type.startsWith('image/')) {
        showToast(window.__t ? window.__t('categories.toast_select_image', 'Please select an image file') : 'Please select an image file');
        return;
      }
      // Reset so re-selecting the same file fires change again.
      event.target.value = '';

      const reader = new FileReader();
      reader.onload = async function (e) {
        try {
          // Same crop UI as the logo (square): zoom, drag, grid, background fill.
          const base64 = await openCropModal(e.target.result, 'square');
          document.getElementById('category-picture-name').value = file.name;
          document.getElementById('category-picture-data').value = base64;
          document.getElementById('category-image-img').src = base64;
          document.getElementById('category-image-img').classList.remove('hidden');
          document.getElementById('category-default-icon').classList.add('hidden');
          document.getElementById('category-image-remove-btn').classList.remove('hidden');
          const catChosenLabel = document.getElementById('category-file-chosen-text');
          if (catChosenLabel) catChosenLabel.textContent = file.name;
        }
 catch (err) {
          if (err.message !== 'cancelled') showToast(window.__t ? window.__t('categories.toast_image_process_failed', 'Failed to process image. Please try another.') : 'Failed to process image. Please try another.');
        }

      };
      reader.onerror = () => showToast(window.__t ? window.__t('categories.toast_image_read_failed', 'Failed to read file.') : 'Failed to read file.');
      reader.readAsDataURL(file);
    }

    function previewUserPicture(event) {
      const file = event.target.files[0];
      if (!file) return;

      if (!file.type.startsWith('image/')) {
        showToast(_t('categories.toast_select_image', 'Please select an image file'), 'default');
        return;
      }
      // Reset so re-selecting the same file fires change again.
      event.target.value = '';

      const reader = new FileReader();
      reader.onload = async function (e) {
        try {
          // Unified Pro Image Studio Crop Modal (Square 1:1)
          const base64 = await openCropModal(e.target.result, 'square');
          document.getElementById('user-current-picture').value = base64;
          document.getElementById('user-current-picture-name').value = file.name;
          document.getElementById('user-picture-img').src = base64;
          document.getElementById('user-picture-img').classList.remove('hidden');
          document.getElementById('user-picture-initials').classList.add('hidden');
          document.getElementById('remove-user-picture-btn').classList.remove('hidden');
          const chosenLabel = document.getElementById('user-file-chosen-text');
          if (chosenLabel) chosenLabel.textContent = file.name;
        }
 catch (err) {
          if (err.message !== 'cancelled') showToast('Failed to process image. Please try another.');
        }

      };
      reader.onerror = () => showToast('Failed to read file.');
      reader.readAsDataURL(file);
    }

