    async function loadPurchases(refreshUI = true) {
      try {
        const res = await apiRequest('/api/purchases?all=1&show_deleted=1');
        if (res && Array.isArray(res.purchases)) {
          purchasesCache = res.purchases.map(normalizePurchase);
          setAllData();
          if (refreshUI) {
            if (typeof updatePurchasesGrid === 'function') updatePurchasesGrid();
            if (typeof filterPurchases === 'function') filterPurchases();
            if (typeof updatePOSGrids === 'function') updatePOSGrids();
          }

        }

      } catch (e) {
        console.warn('Failed to refresh purchasesCache:', e);
      }
    }
    window.loadPurchases = loadPurchases;

    function updatePurchasesGrid() {
      updatePurchasesTable();
    }
    window.updatePurchasesGrid = updatePurchasesGrid;

    function updatePurchasesTable() {
      const _t = (k, d, params) => (window.__t ? window.__t(k, d, params) : (d !== undefined ? d : k));
      updatePurchaseProductFilter();

      // Populate category filter
      const categories = getCategories();
      const categoryFilter = document.getElementById('purchases-category-filter');
      const currentCategoryFilter = categoryFilter.value;
      const allCatLabel = _t('purchases.main_views_all_categories', 'All Categories');
      categoryFilter.innerHTML = `<option value="all" data-i18n="purchases.main_views_all_categories">${escapeHtml(allCatLabel)}</option>` +
        categories.map(c => `<option value="${c.__backendId}">${escapeHtml(c.name)}</option>`).join('');
      categoryFilter.value = currentCategoryFilter;

      // Populate user filter
      const users = getUsers().filter(u => {
        if (u.deletedAt || u.deleted_at) return false;
        const isSelf = (currentUser && (String(u.__backendId || u.id) === String(currentUser.__backendId || currentUser.id) || u.username === currentUser.username));
        if (!isSelf && isUserFilterHidden(u, 'purchases')) return false;
        return true;
      });
      const userFilter = document.getElementById('purchases-user-filter');
      if (userFilter) {
        const currentUserFilter = userFilter.value;
        const allUsersLabel = _t('purchases.main_views_all_users', 'All Users');
        userFilter.innerHTML = `<option value="all" data-i18n="purchases.main_views_all_users">${escapeHtml(allUsersLabel)}</option>` +
          users.map(u => {
            const isSelf = currentUser && (u.username === currentUser.username || String(u.__backendId || u.id) === String(currentUser.__backendId || currentUser.id));
            const youTag = isSelf ? ` (${window.__t ? window.__t('purchases.main_views_you', 'You') : 'You'})` : '';
            return `<option value="${u.username}">👤 ${escapeHtml(u.username)}${youTag}</option>`;
          }
).join('');

        // Maintain selection if explicitly chosen in session, otherwise default to current logged-in user
        if (userFilter.dataset.userChosen === 'true' && currentUserFilter && Array.from(userFilter.options).some(opt => opt.value === currentUserFilter)) {
          userFilter.value = currentUserFilter;
        }
 else if (currentUser && currentUser.username && Array.from(userFilter.options).some(opt => opt.value === currentUser.username)) {
          userFilter.value = currentUser.username;
        }
 else {
          userFilter.value = 'all';
        }

      }

      // Populate supplier filter (active suppliers + a "no supplier / cash" option)
      const supplierFilter = document.getElementById('purchases-supplier-filter');
      if (supplierFilter) {
        const currentSupplierFilter = supplierFilter.value;
        const suppliers = getSuppliers().filter(s => !s.deletedAt);
        const allSuppliersLabel = _t('purchases.main_views_all_suppliers', 'All Suppliers');
        supplierFilter.innerHTML = `<option value="all" data-i18n="purchases.main_views_all_suppliers">${escapeHtml(allSuppliersLabel)}</option>` +
          suppliers.map(s => `<option value="${s.__backendId}">${escapeHtml(s.name)}</option>`).join('');
        supplierFilter.value = currentSupplierFilter;
      }

      filterPurchases();
    }
    function onPurchasesCategoryChange() {
      selectedPurchaseProduct = 'all';
      updatePurchaseProductFilter();
      filterPurchases();
    }

    function updatePurchaseProductFilter() {
      const allProducts = getProducts() || [];
      const categoryFilter = document.getElementById('purchases-category-filter')?.value || 'all';
      const container = document.getElementById('purchases-product-filter');
      if (!container) return;

      // Filter products by selected category
      let products = allProducts;
      if (categoryFilter !== 'all') {
        products = allProducts.filter(p => String(p.categoryId) === String(categoryFilter));
      }

      const allActive = selectedPurchaseProduct === 'all';
      const allProductsText = window.__t ? window.__t('purchases.main_views_all_products', 'All Products') : 'All Products';
      const allButton = `
        <button type="button" onclick="selectPurchaseProduct('all')" class="liquid-bubble-pill ${allActive ? 'is-active' : ''}">
          <span>${allProductsText}</span>
          <span class="liquid-bubble-chip bg-slate-500/15 text-slate-600 dark:text-slate-300 border border-slate-500/25">${products.length}</span>
        </button>
      `;

      if (products.length === 0) {
        container.innerHTML = allButton;
        return;
      }

      const productButtons = products.map(p => {
        const category = getCategoryById(p.categoryId);
        const isActive = String(selectedPurchaseProduct) === String(p.__backendId);
        return `
          <button type="button" onclick="selectPurchaseProduct('${p.__backendId}')" class="liquid-bubble-pill ${isActive ? 'is-active' : ''}">
            <span class="truncate max-w-[140px] sm:max-w-[200px]">${escapeHtml(p.name)}</span>
            ${category ? `<span class="liquid-bubble-chip bg-amber-500/15 text-amber-600 dark:text-amber-400 border border-amber-500/25">${escapeHtml(category.name)}</span>` : ''}
          </button>
        `;
      }).join('');

      container.innerHTML = allButton + productButtons;
    }

    function selectPurchaseProduct(productId) {
      selectedPurchaseProduct = productId;
      purchaseProductScrollIndex = 0;
      updatePurchaseProductFilter();
      filterPurchases();
    }

    function scrollPurchaseProducts(direction) {
      const list = document.getElementById('purchases-product-filter');
      if (!list) return;

      const buttons = list.querySelectorAll('button');
      if (buttons.length <= 5) return;

      purchaseProductScrollIndex += direction;

      // Limit scroll range
      const maxScroll = Math.max(0, buttons.length - 5);
      purchaseProductScrollIndex = Math.max(0, Math.min(maxScroll, purchaseProductScrollIndex));

      // Calculate transform
      const buttonWidth = 180; // approximate width + gap
      const translateX = -purchaseProductScrollIndex * buttonWidth;
      list.style.transform = `translateX(${translateX}px)`;
    }

