    async function confirmOrderCredit(finishSale = true) {
      let paid = '0';
      try { paid = toExactDecimalString(document.getElementById('order-credit-paid').value || '0'); } catch (e) { paid = '0'; }
      if (Decimal.comp(paid, '0') < 0) paid = '0';

      const total = orderCreditTotal || '0';
      const isOverpaid = Decimal.comp(paid, total) > 0;
      const isExactPaid = Decimal.comp(paid, total) === 0 && Decimal.comp(paid, '0') > 0;
      const isFullyPaidOrOver = isOverpaid || isExactPaid;
      const extraProfit = isOverpaid ? Decimal.sub(paid, total) : '0';

      const dueEl = document.getElementById('order-credit-due');
      let due = null;
      if ((!isFullyPaidOrOver || !finishSale) && dueEl && dueEl.value) {
        due = dueEl.value.trim();
        if (due) {
          const dueIso = String(due).replace(' ', 'T').slice(0, 16);
          const nowMinuteIso = getLocalIsoMinute();
          if (dueIso < nowMinuteIso) {
            showToast(_t('pos.toast_due_date_past', 'Due date & time cannot be in the past'), 'default');
            return;
          }

          if (due.length === 16) {
            due = due + ':00';
          }

          lastOrderDueDate = due;
        }

      }

      const activeBtn = finishSale 
        ? (document.getElementById('confirm-order-credit-btn') || document.activeElement)
        : (document.getElementById('confirm-order-credit-only-btn') || document.getElementById('confirm-order-credit-btn'));
      const prevText = activeBtn ? activeBtn.textContent : _t('common.saving', 'Saving...');
      if (activeBtn) { activeBtn.disabled = true; activeBtn.textContent = _t('common.saving', 'Saving...'); }

      try {
        if (orderCreditMode === 'sale') {
          const saleStatus = (isFullyPaidOrOver && finishSale) ? 'completed' : 'pending_money';
          const creditInfo = {
            amount_paid: paid,
            due_date: (isFullyPaidOrOver && finishSale) ? null : due,
            extra_profit: extraProfit,
            finish_sale: !!finishSale
          }
;
          const ok = await completeSale(saleStatus, creditInfo);
          if (ok) {
            closeOrderCreditModal();
          }

        }
 else if (orderCreditMode === 'status' && orderCreditOrderId) {
          const oid = orderCreditOrderId;
          if (isFullyPaidOrOver && finishSale) {
            await apiRequest(`/api/orders/${oid}/status`, {
              method: 'PUT',
              body: JSON.stringify({
                status: 'completed',
                amount_paid: paid,
                final_payment: paid,
                actual_paid: paid,
                extra_profit: extraProfit,
                due_date: null,
                finish_sale: true
              }
)
            }
);
            closeOrderCreditModal();
            await loadAllData();
            showToast(_t('orders.toast_order_completed_with_formatprice', `Order completed with +${formatPrice(extraProfit)} extra profit!`, { profit: formatPrice(extraProfit) }), 'default');
            refreshCustomerHistoryIfOpen();
          }
 else {
            await apiRequest(`/api/orders/${oid}/status`, {
              method: 'PUT',
              body: JSON.stringify({
                status: 'pending_money',
                amount_paid: paid,
                extra_profit: extraProfit,
                due_date: due,
                finish_sale: false
              }
)
            }
);
            closeOrderCreditModal();
            await loadAllData();
            showToast(isOverpaid 
              ? _t('orders.toast_order_recorded_in_pending_payment_w', `Order recorded in pending payment with +${formatPrice(extraProfit)} extra profit!`, { profit: formatPrice(extraProfit) })
              : (isExactPaid 
                  ? _t('orders.toast_order_payment_recorded_pending', 'Order payment recorded — kept in pending payment.') 
                  : _t('orders.toast_marked_pending_payment', 'Marked as Pending Payment — goods delivered, money owed.')));
            refreshCustomerHistoryIfOpen();
          }

        }

      } catch (e) {
        showToast(e.message || _t('orders.toast_failed_to_save', 'Failed to save'), 'default');
      } finally {
        if (activeBtn) { activeBtn.disabled = false; activeBtn.textContent = prevText; }
      }
    }
    window.confirmOrderCredit = confirmOrderCredit;

    // ── Resubmit normal-order terms after partner refusal ──
    // Mirrors CS resubmit pattern (editCustomSale L54143-54167) but as a
    // standalone global function for non-custom consignment orders.
    window.resubmitOrderAfterRefusal = async function(orderId) {
      if (!orderId) return;
      // Find the button that triggered this to show loading state
      const btn = document.querySelector(`[onclick*="resubmitOrderAfterRefusal('${orderId}')"]`);
      if (btn) {
        btn.disabled = true;
        btn.innerHTML = '<span>🔄</span> <span>Resubmitting…</span>';
      }
      try {
        const o = (window.ordersCache || []).find(x => String(x.__backendId || x.id) === String(orderId)) || (typeof findItem === 'function' ? findItem(orderId, 'order') : null);
        const isCustom = o && (o.customSale === true || o.custom_sale == 1);
        const endpoint = isCustom ? `/api/custom-services/${orderId}/resubmit` : `/api/orders/${orderId}/resubmit-after-refusal`;
        const res = await apiRequest(endpoint, { method: 'POST' });
        if (res && res.ok) {
          showToast(_t('custom_service.toast_resubmitted_success', 'Terms resubmitted to all partners for approval'), 'default');
          await loadAllData();
          showOrderDetails(orderId);
        }
 else {
          showToast(res?.message || _t('orders.toast_failed_to_resubmit_terms', 'Failed to resubmit terms'), 'error');
        }

      } catch (e) {
        showToast(e.message || _t('custom_service.toast_resubmit_failed', 'Failed to resubmit terms', 'error'), 'error');
      }
      if (btn) {
        btn.disabled = false;
        btn.innerHTML = '<span>🔄</span> <span>Resubmit Terms</span>';
      }
    };

    // ── Record a customer installment toward an owed order (mirror of the
    // supplier "Record payment" modal). ──
    let pendingOrderPaymentId = null;

    function showOrderPaymentModal(id) {
      const o = findItem(id, 'order');
      if (!o) return;
      const total = o.total || '0';
      const paid = o.amountPaid || '0';
      let rawOwed = Decimal.sub(total, paid);
      if (Decimal.comp(rawOwed, '0') < 0) rawOwed = '0';
      const owed = rawOwed;
      const isZeroDebt = Decimal.comp(owed, '0') <= 0;

      pendingOrderPaymentId = id;
      const customer = o.customerId ? findItem(o.customerId, 'customer') : null;
      let custName = customer ? customer.name : _t('common.customer', 'Customer');
      if (customer && customer.isWalkin && o.customerNote) custName = o.customerNote + _t('orders.payment_walkin_suffix', ' — walk-in');
      document.getElementById('order-payment-customer').textContent = custName;
      document.getElementById('order-payment-uid').textContent = o.uid || ('#' + id);
      document.getElementById('order-payment-total').textContent = formatPrice(total);
      document.getElementById('order-payment-paid').textContent = formatPrice(paid);
      document.getElementById('order-payment-owed').textContent = isZeroDebt ? _t('orders.payment_fully_paid_badge', '0.00 — Fully Paid ✓') : formatPrice(owed);

      const zeroBanner = document.getElementById('order-payment-zero-debt-banner');
      const amountHelp = document.getElementById('order-payment-amount-help');
      if (zeroBanner) zeroBanner.classList.toggle('hidden', !isZeroDebt);
      if (amountHelp) {
        amountHelp.textContent = isZeroDebt 
          ? _t('orders.payment_amount_help_zero_debt', 'Order debt is 0.00. Any payment entered will be credited as Extra Net Profit.')
          : _t('orders.payment_amount_help', 'Defaults to remaining debt. Partial payments are automatically tracked.');
      }

      // Reset payment method to cash
      if (typeof setOrderPaymentMethod === 'function') {
        setOrderPaymentMethod('cash');
      }

      // Reset print receipt checkbox
      const printReceiptCheck = document.getElementById('order-payment-print-receipt');
      if (printReceiptCheck) printReceiptCheck.checked = true;

      const amtInput = document.getElementById('order-payment-amount');
      if (amtInput) {
        amtInput.value = isZeroDebt ? '' : owed;
        amtInput.placeholder = isZeroDebt ? '0.00' : owed;
      }

      var dueRow = document.getElementById('order-payment-due-row');
      if (dueRow) {
        if (o.dueDate) {
          dueRow.classList.remove('hidden');
          var dd = parseLocalDate(o.dueDate);
          var t = new Date(); t.setHours(0, 0, 0, 0);
          var overdue = dd && dd < t;
          var dueEl = document.getElementById('order-payment-due');
          dueEl.textContent = (dd ? dd.toLocaleDateString() : o.dueDate) + (overdue ? _t('orders.payment_overdue_suffix', ' — overdue') : '');
          dueEl.className = 'font-semibold ' + (overdue ? 'text-red-600' : 'text-slate-700 dark:text-slate-300');
        }
 else {
          dueRow.classList.add('hidden');
        }

      }
      var newDue = document.getElementById('order-payment-new-due');
      if (newDue) {
        let defDate = '';
        if (o.dueDate) {
          const oDueIso = String(o.dueDate).replace(' ', 'T').slice(0, 16);
          const nowMinuteIso = getLocalIsoMinute();
          defDate = oDueIso >= nowMinuteIso ? oDueIso : '';
        }

        initFlatpickr24h('order-payment-new-due', { minDate: 'today', defaultDate: defDate });
      }

      onOrderPaymentAmountChange();
      const modal = document.getElementById('order-payment-modal');
      if (modal) {
        if (typeof ModalManager !== 'undefined' && typeof ModalManager.bringToFront === 'function') {
          ModalManager.bringToFront(modal);
        }

        modal.classList.remove('hidden');
      }
    }


    function onOrderPaymentAmountChange() {
      if (!pendingOrderPaymentId) return;
      var o = findItem(pendingOrderPaymentId, 'order');
      if (!o) return;
      var total = o.total || '0';
      var paid = o.amountPaid || '0';
      var rawOwed = Decimal.sub(total, paid);
      if (Decimal.comp(rawOwed, '0') < 0) rawOwed = '0';
      var owed = rawOwed;
      var isZeroDebt = Decimal.comp(owed, '0') <= 0;

      var amt = '0';
      try { amt = toExactDecimalString(document.getElementById('order-payment-amount').value || '0'); } catch (e) { amt = '0'; }

      var remAfter = '0';
      var extraProfit = '0';

      if (isZeroDebt) {
        remAfter = '0';
        extraProfit = amt;
      } else if (Decimal.comp(amt, owed) < 0) {
        remAfter = Decimal.sub(owed, amt);
        extraProfit = '0';
      } else if (Decimal.comp(amt, owed) === 0) {
        remAfter = '0';
        extraProfit = '0';
      } else {
        remAfter = '0';
        extraProfit = Decimal.sub(amt, owed);
      }

      // Live feedback indicators
      var remEl = document.getElementById('order-payment-rem-after');
      if (remEl) {
        if (Decimal.comp(remAfter, '0') === 0) {
          remEl.textContent = _t('orders.payment_rem_fully_paid', '0.00 ✓ — Fully Paid');
          remEl.className = 'font-mono font-black text-emerald-600 dark:text-emerald-400';
        }
 else {
          remEl.textContent = formatPrice(remAfter);
          remEl.className = 'font-mono font-black text-amber-700 dark:text-amber-300';
        }

      }

      var extraWrap = document.getElementById('order-payment-extra-profit-wrap');
      var extraEl = document.getElementById('order-payment-extra-profit');
      if (extraWrap && extraEl) {
        var hasExtra = Decimal.comp(extraProfit, '0') > 0;
        extraWrap.classList.toggle('hidden', !hasExtra);
        if (hasExtra) {
          extraEl.textContent = '+' + formatPrice(extraProfit);
        }

      }

      var newTotalWrap = document.getElementById('order-payment-new-total-wrap');
      var newTotalEl = document.getElementById('order-payment-new-total');
      if (newTotalWrap && newTotalEl) {
        var hasExtra2 = Decimal.comp(extraProfit, '0') > 0;
        newTotalWrap.classList.toggle('hidden', !hasExtra2);
        if (hasExtra2) {
          newTotalEl.textContent = formatPrice(Decimal.add(total, extraProfit));
        }

      }

      // Rolling due date picker only applicable for partial payments
      var willOwe = Decimal.comp(remAfter, '0') > 0;
      var wrap = document.getElementById('order-payment-newdue-wrap');
      if (wrap) wrap.classList.toggle('hidden', !willOwe);

      // Declarative button state toggling (eliminates DOM wiping on keystroke)
      // Preserves onclick="confirmOrderPayment(event, false)" and onclick="confirmOrderPayment(event, true)"
      const payBtn = document.getElementById('confirm-order-payment-btn');
      const finishBtn = document.getElementById('confirm-order-finish-btn');
      if (payBtn && finishBtn) {
        payBtn.setAttribute('onclick', 'confirmOrderPayment(event, false)');
        finishBtn.setAttribute('onclick', 'confirmOrderPayment(event, true)');
        const hasExtraProfit = Decimal.comp(extraProfit, '0') > 0;
        const isExactFull = Decimal.comp(remAfter, '0') === 0 && Decimal.comp(amt, '0') > 0 && !hasExtraProfit;

        if (hasExtraProfit) {
          payBtn.textContent = _t('orders.payment_btn_extra_only', 'Record Extra Only');
          payBtn.classList.remove('hidden');
          finishBtn.textContent = _t('orders.payment_btn_extra_finish', 'Record Extra & Finish Order');
          finishBtn.classList.remove('hidden');
        }
 else if (isExactFull) {
          payBtn.textContent = _t('orders.payment_btn_payment_only', 'Record Payment Only');
          payBtn.classList.remove('hidden');
          finishBtn.textContent = _t('orders.payment_btn_payment_finish', 'Record Payment & Finish Order');
          finishBtn.classList.remove('hidden');
        }
 else {
          payBtn.textContent = _t('orders.payment_btn_record_payment', 'Record Payment');
          payBtn.classList.remove('hidden');
          finishBtn.classList.add('hidden');
        }

      }
    }

    function closeOrderPaymentModal() {
      pendingOrderPaymentId = null;
      const modal = document.getElementById('order-payment-modal');
      if (modal) {
        modal.classList.add('hidden');
        if (typeof ModalManager !== 'undefined' && typeof ModalManager.resetZIndex === 'function') {
          ModalManager.resetZIndex(modal);
        }

      }
    }

    async function confirmOrderPayment(e, finishOrder = false) {
      if (e && e.preventDefault) e.preventDefault();
      if (!pendingOrderPaymentId) return;
      const amtRaw = document.getElementById('order-payment-amount').value || '0';
      let amt = '0';
      try { amt = toExactDecimalString(amtRaw); } catch (err) { amt = '0'; }
      if (Decimal.comp(amt, '0') <= 0) { showToast(_t('orders.payment_enter_amount_gt_zero', 'Enter an amount greater than zero')); return; }

      const btn = (finishOrder && document.getElementById('confirm-order-finish-btn'))
        ? document.getElementById('confirm-order-finish-btn')
        : (document.getElementById('confirm-order-payment-btn') || document.activeElement);
      const originalText = btn ? btn.textContent : _t('orders.payment_btn_record_payment', 'Record Payment');
      if (btn) {
        btn.disabled = true;
        btn.textContent = finishOrder ? _t('orders.payment_finishing_order', 'Finishing Order...') : _t('orders.payment_saving_payment', 'Saving Payment...');
      }

      const oid = pendingOrderPaymentId;
      const payload = { 
        amount_paid_now: amt,
        finish_order: !!finishOrder
      };

      const pm = document.getElementById('order-payment-method')?.value;
      if (pm) payload.payment_method = pm;

      const newDueEl = document.getElementById('order-payment-new-due');
      const wrap = document.getElementById('order-payment-newdue-wrap');
      if (!finishOrder && newDueEl && newDueEl.value && wrap && !wrap.classList.contains('hidden')) {
        const dueStr = newDueEl.value.replace('T', ' ');
        const nowStr = getLocalIsoMinute().replace('T', ' ');
        if (dueStr < nowStr) {
          showToast(_t('orders.payment_due_not_past', 'New due date & time cannot be in the past'), 'default');
          if (btn) { btn.disabled = false; btn.textContent = originalText; }
          return;
        }

        payload.new_due_date = dueStr;
      }
      try {
        const res = await apiRequest(`/api/orders/${oid}/pay`, { method: 'POST', body: JSON.stringify(payload) });
        const shouldPrintReceipt = !!document.getElementById('order-payment-print-receipt')?.checked;
        closeOrderPaymentModal();
        await loadAllData();
        showToast(_t('orders.payment_recorded_finished', 'Payment recorded & order completed!'), 'default');
        if (shouldPrintReceipt) {
          try {
            openPrintStudioFromOrder(oid);
          }
 catch (pe) {
            console.warn('Auto print receipt warning:', pe);
          }

        }

        if (currentOrderPaymentsId === oid) { try { showOrderPaymentsModal(oid); } catch (e2) { } }
        try { updateDashboard(); } catch (e2) { }
        try { loadSettlementHubData(); } catch (e3) { }
        refreshCustomerHistoryIfOpen();
        const detailsModal = document.getElementById('order-details-modal');
        if (detailsModal && !detailsModal.classList.contains('hidden') && lastViewedOrder && String(lastViewedOrder.__backendId || lastViewedOrder.id) === String(oid)) {
          const freshOrder = ordersCache.find(o => String(o.__backendId || o.id) === String(oid));
          if (freshOrder) {
            showOrderDetails(oid, freshOrder);
          }

        }

      } catch (err) {
        if (err?.payload?.order_deleted || /already deleted|not found/i.test(err?.message || '')) {
          handleRemoteOrderDeleted(oid);
        }
 else {
          showToast(err.message || _t('purchases.modals_forms_failed_to_record_payment', 'Failed to record payment'), 'default');
        }

      }
      if (btn) { btn.disabled = false; btn.textContent = originalText; }
    }

