    function getCustomerMetricsMap() {
      const metrics = new Map();
      const allOrders = typeof getOrders === 'function' ? getOrders() : [];
      const allCustomers = typeof getCustomers === 'function' ? getCustomers() : [];
      allCustomers.forEach(c => {
        const custOrders = allOrders.filter(o => o.customerId === c.__backendId);
        let totalRevenue = '0';
        let owedTotal = '0';
        custOrders.forEach(o => {
          const paid = (o.amountPaid !== undefined && o.amountPaid !== null && o.amountPaid !== '') ? String(o.amountPaid) : (o.status === 'completed' || o.status === 'paid' ? String(o.total || '0') : '0');
          if (Decimal.comp(paid, '0') > 0) totalRevenue = Decimal.add(totalRevenue, paid);
          if (o.status === 'pending_money') {
            const due = Decimal.sub(o.total || '0', o.amountPaid || '0');
            if (Decimal.comp(due, '0') > 0) owedTotal = Decimal.add(owedTotal, due);
          }

        }
);
        metrics.set(c.__backendId, { orderCount: custOrders.length, totalRevenue, owedTotal });
      });
      return metrics;
    }

    function renderCustomerPicker() {
      if (!customerPickerTargetId) return;
      const sel = document.getElementById(customerPickerTargetId);
      const selected = sel ? sel.value : '';
      let list = getCustomers().filter(c => !c.deletedAt);

      const search = (document.getElementById('customer-picker-search').value || '').trim().toLowerCase();
      const typeF = document.getElementById('customer-picker-type').value;
      const sortF = document.getElementById('customer-picker-sort').value;

      if (typeF === 'regular') list = list.filter(c => !c.isWalkin);
      else if (typeF === 'walkin') list = list.filter(c => c.isWalkin);

      if (search) {
        const cleanSearch = search.startsWith('#') ? search.slice(1).trim() : search;
        list = list.filter(c => [c.name || '', c.phone || '', c.email || '', c.address || '', c.uid || '', `#${c.uid || ''}`]
          .join(' ').toLowerCase().includes(search) || [c.name || '', c.phone || '', c.email || '', c.address || '', c.uid || '']
          .join(' ').toLowerCase().includes(cleanSearch));
      }

      const walkinList = list.filter(c => c.isWalkin);
      const regularList = list.filter(c => !c.isWalkin);

      if (sortF === 'newest') {
        regularList.sort((a, b) => new Date(String(b.createdAt || 0).replace(' ', 'T')) - new Date(String(a.createdAt || 0).replace(' ', 'T')));
      } else if (sortF === 'revenue_desc') {
        const metricsMap = getCustomerMetricsMap();
        regularList.sort((a, b) => {
          const revA = metricsMap.get(a.__backendId)?.totalRevenue || '0';
          const revB = metricsMap.get(b.__backendId)?.totalRevenue || '0';
          return Decimal.comp(revB, revA);
        }
);
      } else {
        regularList.sort((a, b) => (a.name || '').localeCompare(b.name || ''));
      }

      list = [...walkinList, ...regularList];

      const grid = document.getElementById('customer-picker-grid');
      const empty = document.getElementById('customer-picker-empty');

      const isAutoSelected = selected === '__auto_create__';
      const showAutoCard = typeF !== 'walkin';

      const autoCreateCardHtml = showAutoCard ? `
        <div onclick="selectAutoCreateCustomer()"
          class="relative group p-4 sm:p-5 rounded-2xl border-2 border-dashed ${isAutoSelected ? 'border-emerald-500 bg-emerald-500/15 ring-2 ring-emerald-500/30' : 'border-emerald-500/50 dark:border-emerald-500/40 bg-emerald-500/[0.04] hover:bg-emerald-500/[0.08] hover:border-emerald-400'} transition-all flex flex-col justify-between text-start rtl:text-right cursor-pointer shadow-[inset_0_1px_0_0_rgba(255,255,255,0.06),0_4px_16px_rgba(0,0,0,0.1)] backdrop-blur-xl">
          <div>
            <div class="flex items-center gap-3 mb-2.5">
              <div class="w-10 h-10 rounded-2xl bg-gradient-to-br from-emerald-500 to-teal-600 text-white flex items-center justify-center font-black text-lg shadow-md shadow-emerald-500/20 shrink-0 group-hover:scale-105 transition-transform">
                <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M12 4v16m8-8H4"/></svg>
              </div>
              <div class="min-w-0">
                <p class="font-black text-slate-900 dark:text-white text-sm truncate flex items-center gap-1.5">
                  <span class="text-emerald-500 font-bold">+</span> ${window.__t ? window.__t('pos.cust_card_create', 'Create Customer') : 'Create Customer'}
                </p>
                <span class="inline-block text-[9px] font-black uppercase tracking-wider text-emerald-600 dark:text-emerald-400 bg-emerald-100/80 dark:bg-emerald-950/80 px-2 py-0.5 rounded-full border border-emerald-300/60 dark:border-emerald-800/60 mt-0.5">${window.__t ? window.__t('pos.customer_autocreate_badge', 'NEW PROFILE') : 'NEW PROFILE'}</span>
              </div>
            </div>
            <p class="text-xs text-emerald-800/80 dark:text-emerald-200/80 font-medium leading-relaxed">${window.__t ? window.__t('pos.cust_card_create_hint', 'Type name on ticket to auto-create profile') : 'Type name on ticket to auto-create profile'}</p>
          </div>
          <div class="mt-4 pt-3 border-t border-emerald-500/20 flex items-center justify-between text-xs font-bold text-emerald-600 dark:text-emerald-400 group-hover:translate-x-0.5 transition-transform">
            <span>${isAutoSelected ? (window.__t ? window.__t('pos.cust_card_selected_auto', '✓ Selected for auto-create') : '✓ Selected for auto-create') : (window.__t ? window.__t('pos.cust_card_click_select', 'Click to select') : 'Click to select')}</span>
            <span class="text-sm font-black rtl:rotate-180 inline-block">→</span>
          </div>
        </div>` : '';

      const customerCardsHtml = list.map(c => {
        const isSel = selected && String(selected) === String(c.__backendId);
        const isWalkin = !!(c.isWalkin || String(c.__backendId) === '1' || (c.name && c.name.trim().toLowerCase().includes('walk-in')));
        const initial = isWalkin ? 'W' : (c.name || '?').trim().charAt(0).toUpperCase();
        const customerName = isWalkin
          ? (window.__t ? window.__t('customers.main_views_walk_in_one_off_customer', 'Walk-in (one-off customer)') : 'Walk-in (one-off customer)')
          : (c.name || 'Unnamed');
        return `
          <div onclick="selectCustomerFromPicker('${c.__backendId}')"
            class="relative text-start rtl:text-right rounded-2xl border ${isSel ? 'border-emerald-500 bg-emerald-50/50 dark:bg-emerald-950/30 ring-2 ring-emerald-500/40 shadow-emerald-500/10' : 'border-slate-200/80 dark:border-white/[0.08] bg-white/80 dark:bg-[#0d1117]/90 hover:border-emerald-400/80 dark:hover:border-emerald-500/60 hover:dark:bg-[#121620]'} p-4 transition-all flex flex-col justify-between cursor-pointer group shadow-[inset_0_1px_0_0_rgba(255,255,255,0.06),0_4px_16px_rgba(0,0,0,0.15)] backdrop-blur-xl transform hover:-translate-y-0.5">
            <div>
              <div class="flex items-center gap-3 mb-2.5">
                <div class="w-10 h-10 rounded-2xl ${isWalkin ? 'bg-emerald-100 dark:bg-emerald-950/60 text-emerald-700 dark:text-emerald-300 border border-emerald-200 dark:border-emerald-800' : 'bg-gradient-to-br from-indigo-500 via-blue-600 to-teal-500 text-white shadow-md shadow-indigo-500/20'} flex items-center justify-center font-black text-sm shrink-0">
                  ${escapeHtml(initial)}
                </div>
                <div class="flex-1 min-w-0">
                  <p class="font-black text-slate-900 dark:text-white text-sm truncate tracking-tight">${escapeHtml(customerName)}</p>
                  <div class="flex items-center gap-1.5 mt-0.5">
                    ${c.uid ? `<span class="text-[10px] font-mono font-semibold text-slate-400 dark:text-slate-500 truncate"><bdi dir="ltr">#${escapeHtml(c.uid)}</bdi></span>` : ''}
                    ${isWalkin ? `<span class="inline-flex items-center px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-wider bg-emerald-100 dark:bg-emerald-950/80 text-emerald-700 dark:text-emerald-300 border border-emerald-200 dark:border-emerald-800 whitespace-nowrap shrink-0">${window.__t ? window.__t('pos.cust_picker_walkin', 'Walk-in') : 'Walk-in'}</span>` : ''}
                  </div>
                </div>
              </div>
              <div class="space-y-1.5 text-xs text-slate-600 dark:text-slate-400 mt-2.5">
                ${c.phone ? `<p class="truncate flex items-center gap-1.5 font-mono text-[11px]"><span class="text-slate-400">📞</span> <span class="font-semibold text-slate-700 dark:text-slate-300"><bdi dir="ltr">${escapeHtml(c.phone)}</bdi></span></p>` : ''}
                ${c.email ? `<p class="truncate flex items-center gap-1.5"><span class="text-slate-400">✉️</span> <span class="truncate"><bdi dir="ltr">${escapeHtml(c.email)}</bdi></span></p>` : ''}
                ${c.address ? `<p class="truncate flex items-center gap-1.5"><span class="text-slate-400">📍</span> <span class="truncate">${escapeHtml(c.address)}</span></p>` : ''}
                ${!c.phone && !c.email && !c.address ? `<p class="text-slate-400 dark:text-slate-500 italic text-[11px]">${window.__t ? window.__t('pos.cust_card_no_contact', 'No contact details saved') : 'No contact details saved'}</p>` : ''}
              </div>
            </div>
            <div class="mt-3.5 pt-2.5 border-t border-slate-100 dark:border-white/[0.06] flex items-center justify-between text-[11px]">
              ${isSel
                ? `<span class="text-emerald-600 dark:text-emerald-400 font-black flex items-center gap-1"><svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M5 13l4 4L19 7"/></svg> ${window.__t ? window.__t('pos.cust_card_selected', 'Selected') : 'Selected'}</span>`
                : `<span class="text-slate-400 group-hover:text-emerald-500 transition-colors font-semibold">${window.__t ? window.__t('pos.cust_card_click_select', 'Click to select') : 'Click to select'}</span><span class="text-slate-300 dark:text-slate-600 group-hover:text-emerald-500 transition-colors rtl:rotate-180 inline-block">→</span>`
              }

            </div>
          </div>`;
      }).join('');

      grid.innerHTML = autoCreateCardHtml + customerCardsHtml;
      empty.classList.toggle('hidden', list.length > 0 || showAutoCard);
      grid.classList.remove('hidden');
    }

    function selectCustomerFromPicker(customerId) {
      const targetId = customerPickerTargetId;
      const sel = targetId ? document.getElementById(targetId) : null;
      if (sel) {
        if (!sel.querySelector(`option[value="${customerId}"]`)) {
          const opt = document.createElement('option');
          opt.value = String(customerId);
          opt.textContent = `Customer #${customerId}`;
          sel.appendChild(opt);
        }

        sel.value = String(customerId);
        sel.dispatchEvent(new Event('change'));
        syncCustomerChip(targetId);
      }
      closeCustomerPicker();
    }

    function selectAutoCreateCustomer() {
      const targetId = customerPickerTargetId;
      const sel = targetId ? document.getElementById(targetId) : null;
      if (sel) {
        if (!sel.querySelector('option[value="__auto_create__"]')) {
          const opt = document.createElement('option');
          opt.value = '__auto_create__';
          opt.textContent = '✨ New Customer (Auto-Create)';
          sel.appendChild(opt);
        }

        sel.value = '__auto_create__';
        sel.dispatchEvent(new Event('change'));
        syncCustomerChip(targetId);
      }
      closeCustomerPicker();
      if (targetId === 'cart-customer') {
        setTimeout(() => {
          const inp = document.getElementById('cart-autocreate-name');
          if (inp) { inp.focus(); inp.select(); }
        }
, 100);
      } else if (targetId === 'custom-customer') {
        setTimeout(() => {
          const inp = document.getElementById('custom-autocreate-name');
          if (inp) { inp.focus(); inp.select(); }
        }
, 100);
      } else if (targetId === 'coin-sale-customer') {
        setTimeout(() => {
          const inp = document.getElementById('coin-sale-autocreate-name');
          if (inp) { inp.focus(); inp.select(); }
        }
, 100);
      }
    }

    function syncCustomerChip(selectId) {
      if (!selectId) {
        ['cart-customer', 'custom-customer', 'coin-sale-customer'].forEach(id => syncCustomerChip(id));
        return;
      }
      const sel = document.getElementById(selectId);
      const chip = document.getElementById(selectId + '-summary');
      if (!sel || !chip) return;
      if (sel.value === '__auto_create__') {
        chip.textContent = '✨ ' + (window.__t ? window.__t('pos.customer_autocreate_chip', 'New Customer (Auto-Create)') : 'New Customer (Auto-Create)');
        chip.classList.remove('text-slate-500', 'dark:text-slate-400', 'text-slate-800', 'dark:text-slate-100', 'text-slate-900', 'dark:text-white');
        chip.classList.add('text-emerald-600', 'dark:text-emerald-400', 'font-bold');
        return;
      }
      const customer = sel.value ? findItem(sel.value, 'customer') : null;
      if (customer) {
        chip.textContent = `${customer.name}${customer.phone ? ' · ' + customer.phone : ''}`;
        chip.classList.remove('text-slate-500', 'dark:text-slate-400', 'text-emerald-600', 'dark:text-emerald-400');
        chip.classList.add('text-slate-900', 'dark:text-white', 'font-semibold');
      } else {
        chip.textContent = window.__t ? window.__t('pos.customer_summary_default', 'Choose a customer…') : 'Choose a customer…';
        chip.classList.add('text-slate-500', 'dark:text-slate-400');
        chip.classList.remove('text-slate-800', 'dark:text-slate-100', 'text-slate-900', 'dark:text-white', 'font-semibold', 'font-bold', 'text-emerald-600', 'dark:text-emerald-400');
      }
    }

    function addCustomerFromPos() {
      reselectCustomerTargetId = 'cart-customer';
      showCustomerModal();
    }

    function addCustomerFromCustomService() {
      reselectCustomerTargetId = 'custom-customer';
      showCustomerModal();
    }

    function addCustomerFromCoinSwap() {
      reselectCustomerTargetId = 'coin-sale-customer';
      showCustomerModal();
    }
    window.addCustomerFromCoinSwap = addCustomerFromCoinSwap;

    // Reveal the walk-in buyer note field or auto-create customer name field on the POS
    function onCartCustomerChange() {
      const sel = document.getElementById('cart-customer');
      const walkinWrap = document.getElementById('cart-walkin-wrap');
      const autoWrap = document.getElementById('cart-autocreate-wrap');
      if (!sel) return;
      const isAuto = sel.value === '__auto_create__';
      const customer = (!isAuto && sel.value) ? findItem(sel.value, 'customer') : null;
      const isWalkin = !!(customer && customer.isWalkin);

      if (autoWrap) {
        autoWrap.classList.toggle('hidden', !isAuto);
        if (!isAuto) {
          const inp = document.getElementById('cart-autocreate-name');
          if (inp) inp.value = '';
        }

      }
      if (walkinWrap) {
        walkinWrap.classList.toggle('hidden', !isWalkin);
        if (!isWalkin) {
          const inp = document.getElementById('cart-walkin-note');
          if (inp) inp.value = '';
        }

      }
      syncCustomerChip('cart-customer');
    }

    function onCustomCustomerChange() {
      const sel = document.getElementById('custom-customer');
      const walkinWrap = document.getElementById('custom-walkin-wrap');
      const autoWrap = document.getElementById('custom-autocreate-wrap');
      if (!sel) return;
      const isAuto = sel.value === '__auto_create__';
      const customer = (!isAuto && sel.value) ? findItem(sel.value, 'customer') : null;
      const isWalkin = !!(customer && customer.isWalkin);

      if (autoWrap) {
        autoWrap.classList.toggle('hidden', !isAuto);
        if (!isAuto) {
          const inp = document.getElementById('custom-autocreate-name');
          if (inp) inp.value = '';
        }

      }
      if (walkinWrap) {
        walkinWrap.classList.toggle('hidden', !isWalkin);
        if (!isWalkin) {
          const inp = document.getElementById('custom-walkin-note');
          if (inp) inp.value = '';
        }

      }
      syncCustomerChip('custom-customer');
    }
    window.onCartCustomerChange = onCartCustomerChange;
    window.onCustomCustomerChange = onCustomCustomerChange;

    // ---- Supplier Picker (cards + search & filter; opened from Purchases) ----
    let supplierPickerTargetId = null;

    function openSupplierPicker(selectId) {
      const sel = document.getElementById(selectId);
      if (!sel || sel.disabled) return;
      supplierPickerTargetId = selectId;
      document.getElementById('supplier-picker-search').value = '';
      document.getElementById('supplier-picker-type').value = 'all';
      document.getElementById('supplier-picker-sort').value = 'name';
      renderSupplierPicker();
      const suppModal = document.getElementById('supplier-picker-modal');
      if (suppModal) {
        suppModal.classList.remove('hidden');
        if (window.ModalManager && typeof window.ModalManager.bringToFront === 'function') {
          window.ModalManager.bringToFront(suppModal);
        }
        if (window.ModalManager && typeof window.ModalManager.updateScrollLock === 'function') {
          window.ModalManager.updateScrollLock();
        }
      }
      setTimeout(() => {
        const input = document.getElementById('supplier-picker-search');
        if (input) input.focus();
      }, 50);
    }

    function closeSupplierPicker() {
      const suppModal = document.getElementById('supplier-picker-modal');
      if (suppModal) {
        suppModal.classList.add('hidden');
        if (window.ModalManager && typeof window.ModalManager.resetZIndex === 'function') {
          window.ModalManager.resetZIndex(suppModal);
        }
        if (window.ModalManager && typeof window.ModalManager.updateScrollLock === 'function') {
          window.ModalManager.updateScrollLock();
        }
      }
      supplierPickerTargetId = null;
    }

    function renderSupplierPicker() {
    window.onSupplierPickerSearchInput = renderSupplierPicker;
      if (!supplierPickerTargetId) return;
      const sel = document.getElementById(supplierPickerTargetId);
      const selected = sel ? sel.value : '';
      let list = getSuppliers().filter(s => !s.deletedAt);

      const search = (document.getElementById('supplier-picker-search').value || '').trim().toLowerCase();
      const typeF = document.getElementById('supplier-picker-type').value;
      const sortF = document.getElementById('supplier-picker-sort').value;

      if (typeF === 'regular') list = list.filter(s => !s.isWalkby);
      else if (typeF === 'walkby') list = list.filter(s => s.isWalkby);

      if (search) {
        const cleanSearch = search.startsWith('#') ? search.slice(1).trim() : search;
        list = list.filter(s => [s.name || '', s.phone || '', s.email || '', s.address || '', s.uid || '', `#${s.uid || ''}`]
          .join(' ').toLowerCase().includes(search) || [s.name || '', s.phone || '', s.email || '', s.address || '', s.uid || '']
          .join(' ').toLowerCase().includes(cleanSearch));
      }

      const walkbyList = list.filter(s => s.isWalkby);
      const regularList = list.filter(s => !s.isWalkby);

      if (sortF === 'newest') {
        regularList.sort((a, b) => new Date(String(b.createdAt || 0).replace(' ', 'T')) - new Date(String(a.createdAt || 0).replace(' ', 'T')));
      } else if (sortF === 'purchases_desc') {
        regularList.sort((a, b) => {
          const countA = getPurchases().filter(p => String(p.supplierId) === String(a.__backendId) && !p.deletedAt).length;
          const countB = getPurchases().filter(p => String(p.supplierId) === String(b.__backendId) && !p.deletedAt).length;
          return countB - countA;
        }
);
      } else {
        regularList.sort((a, b) => (a.name || '').localeCompare(b.name || ''));
      }

      list = [...walkbyList, ...regularList];

      const grid = document.getElementById('supplier-picker-grid');
      const empty = document.getElementById('supplier-picker-empty');

      const isAutoSelected = selected === '__auto_create__';
      const showAutoCard = typeF !== 'walkby';

      const autoCreateCardHtml = showAutoCard ? `
        <div onclick="selectAutoCreateSupplier()"
          class="relative group p-4 sm:p-5 rounded-2xl border-2 border-dashed ${isAutoSelected ? 'border-violet-500 bg-violet-500/15 ring-2 ring-violet-500/30' : 'border-violet-500/60 dark:border-violet-500/50 bg-violet-500/5 hover:bg-violet-500/10 hover:border-violet-400'} transition-all flex flex-col justify-between text-start rtl:text-right cursor-pointer shadow-2xs">
          <div>
            <div class="flex items-center gap-3 mb-2.5">
              <div class="w-10 h-10 rounded-xl bg-violet-600 text-white flex items-center justify-center font-black text-lg shadow-sm shrink-0 group-hover:scale-105 transition-transform">
                <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M12 4v16m8-8H4"/></svg>
              </div>
              <div class="min-w-0">
                <p class="font-black text-slate-900 dark:text-white text-sm truncate flex items-center gap-1.5">
                  <span class="text-violet-500 font-bold">+</span> ${window.__t ? window.__t('purchases.supp_card_create', 'Create Supplier') : 'Create Supplier'}
                </p>
                <span class="inline-block text-[10px] font-black uppercase tracking-wider text-violet-600 dark:text-violet-400 bg-violet-100/80 dark:bg-violet-950/80 px-2 py-0.5 rounded-md border border-violet-300/60 dark:border-violet-800/60 mt-0.5">${window.__t ? window.__t('purchases.supp_card_new_vendor', 'NEW VENDOR') : 'NEW VENDOR'}</span>
              </div>
            </div>
            <p class="text-xs text-violet-800/80 dark:text-violet-200/80 font-medium leading-relaxed">${window.__t ? window.__t('purchases.supp_card_create_hint', 'Type name on purchase to auto-create supplier') : 'Type name on purchase to auto-create supplier'}</p>
          </div>
          <div class="mt-4 pt-3 border-t border-violet-500/20 flex items-center justify-between text-xs font-bold text-violet-600 dark:text-violet-400 group-hover:translate-x-0.5 transition-transform">
            <span>${isAutoSelected ? (window.__t ? window.__t('purchases.supp_card_selected_auto', '✓ Selected for auto-create') : '✓ Selected for auto-create') : (window.__t ? window.__t('purchases.supp_card_click_select', 'Click to select') : 'Click to select')}</span>
            <span class="text-sm font-black rtl:rotate-180 inline-block">→</span>
          </div>
        </div>` : '';

      const supplierCardsHtml = list.map(s => {
        const isSel = selected && String(selected) === String(s.__backendId);
        const initial = (s.name || '?').trim().charAt(0).toUpperCase();
        const owed = typeof getSupplierOwed === 'function' ? getSupplierOwed(s.__backendId) : '0';
        const hasDebt = (typeof Decimal !== 'undefined' && Decimal.comp) ? (Decimal.comp(owed || '0', '0') > 0) : (parseFloat(owed) > 0);
        return `
          <div onclick="selectSupplierFromPicker('${s.__backendId}')"
            class="relative text-start rtl:text-right rounded-2xl border-2 ${isSel ? 'border-amber-500 bg-amber-50/40 dark:bg-amber-950/30 ring-2 ring-amber-500/20' : 'border-slate-200/80 dark:border-slate-800 bg-white dark:bg-slate-900/60 hover:border-amber-300 hover:bg-slate-50/80 dark:hover:bg-slate-800/60'} p-4 transition-all flex flex-col justify-between cursor-pointer group shadow-2xs">
            <div>
              <div class="flex items-center gap-3 mb-2.5">
                <div class="w-10 h-10 rounded-xl ${s.isWalkby ? 'bg-amber-100 dark:bg-amber-950/60 text-amber-700 dark:text-amber-300 border border-amber-200 dark:border-amber-800' : 'bg-gradient-to-br from-violet-500 to-indigo-600 text-white shadow-sm'} flex items-center justify-center font-black text-sm shrink-0">
                  ${escapeHtml(initial)}
                </div>
                <div class="flex-1 min-w-0">
                  <p class="font-bold text-slate-900 dark:text-white text-sm truncate">${escapeHtml(s.name || (window.__t ? window.__t('common.unnamed', 'Unnamed') : 'Unnamed'))}</p>
                  <div class="flex items-center gap-1.5 mt-0.5">
                    ${s.uid ? `<span class="text-[10px] font-mono font-semibold text-slate-400 dark:text-slate-500 truncate">#${escapeHtml(s.uid)}</span>` : ''}
                    ${s.isWalkby ? `<span class="inline-block px-1.5 py-0.2 rounded text-[9px] font-black uppercase tracking-wider bg-amber-100 dark:bg-amber-950 text-amber-700 dark:text-amber-300 border border-amber-200 dark:border-amber-800">${window.__t ? window.__t('purchases.supp_card_walkby', 'Walk-by') : 'Walk-by'}</span>` : ''}
                  </div>
                </div>
              </div>
              <div class="space-y-1 text-xs text-slate-600 dark:text-slate-400 mt-2">
                ${s.phone ? `<p class="truncate flex items-center gap-1.5"><span class="text-slate-400">📞</span> <span class="font-medium">${escapeHtml(s.phone)}</span></p>` : ''}
                ${s.email ? `<p class="truncate flex items-center gap-1.5"><span class="text-slate-400">✉️</span> <span class="truncate">${escapeHtml(s.email)}</span></p>` : ''}
                ${s.address ? `<p class="truncate flex items-center gap-1.5"><span class="text-slate-400">📍</span> <span class="truncate">${escapeHtml(s.address)}</span></p>` : ''}
                ${!s.phone && !s.email && !s.address ? `<p class="text-slate-400 dark:text-slate-500 italic text-[11px]">${window.__t ? window.__t('purchases.supp_card_no_contact', 'No contact details saved') : 'No contact details saved'}</p>` : ''}
                ${hasDebt ? `<div class="mt-1.5 px-2 py-0.5 rounded-md bg-rose-50 dark:bg-rose-950/40 border border-rose-200 dark:border-rose-800 text-[10px] font-bold text-rose-600 dark:text-rose-400 inline-block">${window.__t ? window.__t('purchases.supp_card_owed', 'Owed:') : 'Owed:'} ${formatPrice(owed)}</div>` : ''}
              </div>
            </div>
            <div class="mt-3 pt-2.5 border-t border-slate-100 dark:border-slate-800/80 flex items-center justify-between text-[11px]">
              ${isSel
                ? `<span class="text-amber-600 dark:text-amber-400 font-black flex items-center gap-1"><svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M5 13l4 4L19 7"/></svg> ${window.__t ? window.__t('purchases.supp_card_selected', 'Selected') : 'Selected'}</span>`
                : `<span class="text-slate-400 group-hover:text-amber-500 transition-colors font-medium">${window.__t ? window.__t('purchases.supp_card_click_select', 'Click to select') : 'Click to select'}</span><span class="text-slate-300 dark:text-slate-600 group-hover:text-amber-500 transition-colors rtl:rotate-180 inline-block">→</span>`
              }

            </div>
          </div>`;
      }).join('');

      grid.innerHTML = autoCreateCardHtml + supplierCardsHtml;
      empty.classList.toggle('hidden', list.length > 0 || showAutoCard);
      grid.classList.remove('hidden');
    }

    function selectSupplierFromPicker(supplierId) {
      const targetId = supplierPickerTargetId;
      const sel = targetId ? document.getElementById(targetId) : null;
      if (sel) {
        if (!sel.querySelector(`option[value="${supplierId}"]`)) {
          const opt = document.createElement('option');
          opt.value = String(supplierId);
          opt.textContent = `Supplier #${supplierId}`;
          sel.appendChild(opt);
        }

        sel.value = String(supplierId);
        sel.dispatchEvent(new Event('change'));
        syncSupplierChip(targetId);
      }
      closeSupplierPicker();
    }

    function selectAutoCreateSupplier() {
      const targetId = supplierPickerTargetId;
      const sel = targetId ? document.getElementById(targetId) : null;
      if (sel) {
        if (!sel.querySelector('option[value="__auto_create__"]')) {
          const opt = document.createElement('option');
          opt.value = '__auto_create__';
          opt.textContent = '✨ New Supplier (Auto-Create)';
          sel.appendChild(opt);
        }

        sel.value = '__auto_create__';
        sel.dispatchEvent(new Event('change'));
        syncSupplierChip(targetId);
      }
      closeSupplierPicker();
      const autoInpId = targetId === 'purchase-barter-supplier' ? 'purchase-barter-autocreate-name' : 'purchase-autocreate-name';
      setTimeout(() => {
        const inp = document.getElementById(autoInpId);
        if (inp) { inp.focus(); inp.select(); }
      }, 100);
    }

    function syncSupplierChip(selectId) {
      const sel = document.getElementById(selectId);
      const chip = document.getElementById(selectId + '-summary');
      if (!sel || !chip) return;
      if (sel.value === '__auto_create__') {
        chip.textContent = '✨ New Supplier (Auto-Create)';
        chip.classList.remove('text-slate-500', 'dark:text-slate-400');
        chip.classList.add('text-violet-600', 'dark:text-violet-400', 'font-bold');
        return;
      }
      const supplier = sel.value ? findItem(sel.value, 'supplier') : null;
      if (supplier) {
        chip.textContent = `${supplier.name}${supplier.phone ? ' · ' + supplier.phone : ''}`;
        chip.classList.remove('text-slate-500', 'dark:text-slate-400', 'text-violet-600', 'dark:text-violet-400');
        chip.classList.add('text-slate-800', 'dark:text-slate-100', 'font-semibold');
      } else {
        chip.textContent = 'Choose a supplier…';
        chip.classList.add('text-slate-500', 'dark:text-slate-400');
        chip.classList.remove('text-slate-800', 'dark:text-slate-100', 'font-semibold', 'text-violet-600', 'dark:text-violet-400');
      }
    }

    // ════════════════════════════════════════════════════════════════════════════════════════
    // ── MINI POS PRODUCT PICKER STUDIO (Apple Obsidian Liquid Glass Tier 5 Picker) ──
    // ════════════════════════════════════════════════════════════════════════════════════════
    let productPickerTargetId = null;
    let productPickerActiveCategory = 'all';
    let productPickerDebounceTimer = null;
    const PRODUCT_PICKER_PAGE_SIZE = 30;
    let productPickerVisibleLimit = PRODUCT_PICKER_PAGE_SIZE;
    let productPickerFilteredCache = [];
    window.productPickerVisibleLimit = productPickerVisibleLimit;

    function openProductPicker(selectId) {
      productPickerTargetId = selectId || 'custom-sale-product-select';
      window.productPickerTargetId = productPickerTargetId;
      productPickerVisibleLimit = PRODUCT_PICKER_PAGE_SIZE;
      const searchInput = document.getElementById('product-picker-search');
      if (searchInput) searchInput.value = '';

      const isSideASell = (productPickerTargetId === 'coin-sale-sold-product' || productPickerTargetId === 'purchase-spend-product');
      const stockFilter = document.getElementById('product-picker-stock-filter');
      if (stockFilter) stockFilter.value = isSideASell ? 'in_stock' : 'all';
      window.productPickerStockFilter = isSideASell ? 'in_stock' : 'all';

      const sortSelect = document.getElementById('product-picker-sort');
      if (sortSelect) sortSelect.value = 'name_asc';

      productPickerActiveCategory = 'all';

      renderProductPickerCategories();
      renderProductPickerGrid();

      const modal = document.getElementById('product-picker-modal');
      if (modal) {
        modal.classList.remove('hidden');
        if (window.ModalManager && typeof window.ModalManager.bringToFront === 'function') {
          window.ModalManager.bringToFront(modal);
        }
        if (window.ModalManager && typeof window.ModalManager.updateScrollLock === 'function') {
          window.ModalManager.updateScrollLock();
        }
      }

      setTimeout(() => {
        if (searchInput) searchInput.focus();
      }, 60);
    }

    function closeProductPicker() {
      const modal = document.getElementById('product-picker-modal');
      if (modal) {
        modal.classList.add('hidden');
        if (window.ModalManager && typeof window.ModalManager.resetZIndex === 'function') {
          window.ModalManager.resetZIndex(modal);
        }
        if (window.ModalManager && typeof window.ModalManager.updateScrollLock === 'function') {
          window.ModalManager.updateScrollLock();
        }
      }
    }

    function debounceProductPickerSearch() {
      clearTimeout(productPickerDebounceTimer);
      productPickerDebounceTimer = setTimeout(() => {
        productPickerVisibleLimit = PRODUCT_PICKER_PAGE_SIZE;
        renderProductPickerGrid(false);
      }, 150);
    }

    function handleProductPickerCategoryWheel(event) {
      const ribbon = document.getElementById('product-picker-category-ribbon');
      if (ribbon) {
        event.preventDefault();
        const isRtl = document.documentElement.getAttribute('dir') === 'rtl';
        ribbon.scrollLeft += (isRtl ? -event.deltaY : event.deltaY);
      }
    }

    function renderProductPickerCategories() {
      const ribbon = document.getElementById('product-picker-category-ribbon');
      if (!ribbon) return;

      const allCategories = typeof getCategories === 'function' ? getCategories() : categoriesCache;
      let allProducts = (typeof getProducts === 'function' ? getProducts() : productsCache).filter(p => !p.deletedAt && !p.deleted_at);

      const isSideASell = (productPickerTargetId === 'coin-sale-sold-product' || productPickerTargetId === 'purchase-spend-product');
      if (isSideASell) {
        const myId = (currentUser && (currentUser.__backendId || currentUser.id)) ? String(currentUser.__backendId || currentUser.id) : '';
        const myBatches = (typeof getPurchases === 'function' ? getPurchases() : (purchasesCache || [])).filter(p => !p.deletedAt && (String(p.ownerUserId) === myId || !p.ownerUserId) && exactCompare(exactSubtract(p.quantityRemaining || '0', p.quantityReserved || '0'), '0') > 0);
        const ownedProductIds = new Set(myBatches.map(b => String(b.productId)));
        allProducts = allProducts.filter(p => ownedProductIds.has(String(p.__backendId)));
      }

      // Total count across all categories
      const totalCount = allProducts.length;
      const isAllActive = productPickerActiveCategory === 'all';

      const allPillHtml = `
        <button type="button" onclick="setProductPickerCategory('all')"
          class="shrink-0 px-3.5 py-1.5 rounded-full text-xs font-bold transition-all duration-200 cursor-pointer flex items-center gap-1.5 ${isAllActive ? 'bg-emerald-600 text-white shadow-xs font-black' : 'bg-white/80 dark:bg-[#0d1117]/80 text-slate-600 dark:text-slate-300 border border-slate-200/80 dark:border-white/[0.08] hover:border-emerald-500/50'}">
          <span data-i18n="pos.all_categories">All</span>
          <span class="px-1.5 py-0.2 rounded-full text-[10px] ${isAllActive ? 'bg-white/20 text-white' : 'bg-slate-100 dark:bg-white/[0.06] text-slate-500 dark:text-slate-400'}">${totalCount}</span>
        </button>
      `;

      const categoryPillsHtml = allCategories.map(cat => {
        const catId = String(cat.__backendId || cat.id);
        const isActive = productPickerActiveCategory === catId;
        const count = allProducts.filter(p => String(p.categoryId || p.category_id || '') === catId).length;

        return `
          <button type="button" onclick="setProductPickerCategory('${escapeJsString(catId)}')"
            class="shrink-0 px-3.5 py-1.5 rounded-full text-xs font-bold transition-all duration-200 cursor-pointer flex items-center gap-1.5 ${isActive ? 'bg-emerald-600 text-white shadow-xs font-black' : 'bg-white/80 dark:bg-[#0d1117]/80 text-slate-600 dark:text-slate-300 border border-slate-200/80 dark:border-white/[0.08] hover:border-emerald-500/50'}">
            <span class="truncate max-w-[120px]">${escapeHtml(cat.name)}</span>
            <span class="px-1.5 py-0.2 rounded-full text-[10px] ${isActive ? 'bg-white/20 text-white' : 'bg-slate-100 dark:bg-white/[0.06] text-slate-500 dark:text-slate-400'}">${count}</span>
          </button>
        `;
      }).join('');

      ribbon.innerHTML = allPillHtml + categoryPillsHtml;
    }

    function setProductPickerCategory(catId) {
      productPickerActiveCategory = String(catId);
      productPickerVisibleLimit = PRODUCT_PICKER_PAGE_SIZE;
      renderProductPickerCategories();
      renderProductPickerGrid(false);
    }

    function renderProductPickerGrid(preserveScroll = false) {
      const grid = document.getElementById('product-picker-grid');
      const emptyEl = document.getElementById('product-picker-empty');
      const totalBadge = document.getElementById('product-picker-total-badge');
      if (!grid) return;

      const rawSearch = (document.getElementById('product-picker-search')?.value || '').trim().toLowerCase();
      const cleanSearch = rawSearch.startsWith('#') ? rawSearch.slice(1).trim() : rawSearch;
      const stockFilter = document.getElementById('product-picker-stock-filter')?.value || 'all';
      const sortOption = document.getElementById('product-picker-sort')?.value || 'name_asc';

      let products = (typeof getProducts === 'function' ? getProducts() : productsCache).filter(p => !p.deletedAt && !p.deleted_at);

      const isSideASell = (productPickerTargetId === 'coin-sale-sold-product' || productPickerTargetId === 'purchase-spend-product');
      const myId = (currentUser && (currentUser.__backendId || currentUser.id)) ? String(currentUser.__backendId || currentUser.id) : '';
      let myBatches = [];
      let ownedProductIds = new Set();
      if (isSideASell) {
        myBatches = (typeof getPurchases === 'function' ? getPurchases() : (purchasesCache || [])).filter(p => !p.deletedAt && (String(p.ownerUserId) === myId || !p.ownerUserId) && exactCompare(exactSubtract(p.quantityRemaining || '0', p.quantityReserved || '0'), '0') > 0);
        ownedProductIds = new Set(myBatches.map(b => String(b.productId)));
        products = products.filter(p => ownedProductIds.has(String(p.__backendId)));
      }

      // Check if a coin is already chosen on the opposite side
      let oppositeCoinId = null;
      if (productPickerTargetId === 'coin-sale-sold-product') {
        oppositeCoinId = document.getElementById('coin-sale-received-product')?.value;
      } else if (productPickerTargetId === 'coin-sale-received-product') {
        oppositeCoinId = document.getElementById('coin-sale-sold-product')?.value;
      } else if (productPickerTargetId === 'purchase-spend-product') {
        oppositeCoinId = document.getElementById('purchase-barter-acq-product')?.value;
      } else if (productPickerTargetId === 'purchase-barter-acq-product') {
        oppositeCoinId = document.getElementById('purchase-spend-product')?.value;
      }

      // Filter by Category
      if (productPickerActiveCategory !== 'all') {
        products = products.filter(p => String(p.categoryId || p.category_id || '') === productPickerActiveCategory);
      }

      // Filter by Search Query (name, SKU, UID, category name, secondary barcodes)
      if (rawSearch) {
        products = products.filter(p => {
          const cat = typeof getCategoryById === 'function' ? getCategoryById(p.categoryId) : null;
          const catName = cat ? cat.name.toLowerCase() : '';
          const nameMatch = (p.name || '').toLowerCase().includes(rawSearch);
          const uidMatch = (p.uid || '').toLowerCase().includes(cleanSearch) || `#${p.uid || ''}`.includes(rawSearch);
          const skuMatch = (p.sku || '').toLowerCase().includes(cleanSearch);
          const catMatch = catName.includes(rawSearch);
          const secBarcodeMatch = Array.isArray(p.secondary_barcodes) && p.secondary_barcodes.some(b => (b.barcode_value || '').toLowerCase().includes(cleanSearch));
          return nameMatch || uidMatch || skuMatch || catMatch || secBarcodeMatch;
        });
      }

      // Filter by Stock Status
      products = products.filter(p => {
        let totalStock = typeof getProductAvailableQuantity === 'function' ? getProductAvailableQuantity(p.__backendId) : (p.quantity || '0');
        if (isSideASell) {
          totalStock = myBatches.filter(b => String(b.productId) === String(p.__backendId)).reduce((sum, b) => exactAdd(sum, exactSubtract(b.quantityRemaining || '0', b.quantityReserved || '0')), '0');
        }
        const isPos = exactCompare(totalStock, '0') > 0;
        const lowThreshold = String(p.stockLowThreshold || 5);
        const isLow = isPos && exactCompare(totalStock, lowThreshold) <= 0;

        if (stockFilter === 'in_stock') return isPos;
        if (stockFilter === 'low_stock') return isLow;
        if (stockFilter === 'out_of_stock') return !isPos;
        return true;
      });

      // Sort Products
      if (sortOption === 'name_asc') {
        products.sort((a, b) => (a.name || '').localeCompare(b.name || ''));
      } else if (sortOption === 'name_desc') {
        products.sort((a, b) => (b.name || '').localeCompare(a.name || ''));
      } else if (sortOption === 'stock_desc') {
        products.sort((a, b) => {
          const stockA = typeof getProductAvailableQuantity === 'function' ? getProductAvailableQuantity(a.__backendId) : (a.quantity || '0');
          const stockB = typeof getProductAvailableQuantity === 'function' ? getProductAvailableQuantity(b.__backendId) : (b.quantity || '0');
          return exactCompare(stockB, stockA);
        });
      } else if (sortOption === 'stock_asc') {
        products.sort((a, b) => {
          const stockA = typeof getProductAvailableQuantity === 'function' ? getProductAvailableQuantity(a.__backendId) : (a.quantity || '0');
          const stockB = typeof getProductAvailableQuantity === 'function' ? getProductAvailableQuantity(b.__backendId) : (b.quantity || '0');
          return exactCompare(stockA, stockB);
        });
      } else if (sortOption === 'newest') {
        products.sort((a, b) => new Date(String(b.createdAt || 0).replace(' ', 'T')) - new Date(String(a.createdAt || 0).replace(' ', 'T')));
      }

      productPickerFilteredCache = products;
      const totalMatching = productPickerFilteredCache.length;

      if (totalBadge) {
        if (totalMatching > productPickerVisibleLimit) {
          totalBadge.textContent = `${Math.min(productPickerVisibleLimit, totalMatching)} / ${totalMatching} Items`;
        } else {
          totalBadge.textContent = `${totalMatching} Items`;
        }
      }

      if (totalMatching === 0) {
        grid.innerHTML = '';
        if (emptyEl) emptyEl.classList.remove('hidden');
        return;
      }

      if (emptyEl) emptyEl.classList.add('hidden');

      const visibleProducts = productPickerFilteredCache.slice(0, productPickerVisibleLimit);
      const cardsHtml = visibleProducts.map(p => {
        let totalStock = typeof getProductAvailableQuantity === 'function' ? getProductAvailableQuantity(p.__backendId) : (p.quantity || '0');
        if (isSideASell) {
          totalStock = myBatches.filter(b => String(b.productId) === String(p.__backendId)).reduce((sum, b) => exactAdd(sum, exactSubtract(b.quantityRemaining || '0', b.quantityReserved || '0')), '0');
        }
        const reservedStock = p.quantityReserved || '0';
        const isPos = exactCompare(totalStock, '0') > 0;
        const lowThreshold = String(p.stockLowThreshold || 5);
        const isLow = isPos && exactCompare(totalStock, lowThreshold) <= 0;
        const isHiddenStock = exactCompare(String(p.hiddenStock || '0'), '0') > 0;
        const decimals = (p.displayDecimals !== null && p.displayDecimals !== undefined) ? p.displayDecimals : (config.display_decimals ?? 2);
        const cat = typeof getCategoryById === 'function' ? getCategoryById(p.categoryId) : null;
        const catName = cat ? cat.name : '';

        // Stock Badge Styling
        let stockBadgeHtml = '';
        if (!isPos) {
          stockBadgeHtml = `<span class="px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-wider bg-rose-600 text-white shadow-xs">${window.__t ? window.__t('pos.badge_out_of_stock', 'Out of Stock') : 'Out of Stock'}</span>`;
        } else if (isLow) {
          const txt = isHiddenStock ? (window.__t ? window.__t('pos.badge_in_stock', 'In Stock') : 'In Stock') : (window.__t ? window.__t('pos.stock_left_count', `${formatQuantity(totalStock, decimals)} left`, { count: formatQuantity(totalStock, decimals) }) : `${formatQuantity(totalStock, decimals)} left`);
          stockBadgeHtml = `<span class="px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-wider bg-amber-500 text-amber-950 shadow-xs">${txt}</span>`;
        } else {
          const txt = isHiddenStock ? (window.__t ? window.__t('pos.badge_in_stock', 'In Stock') : 'In Stock') : (window.__t ? window.__t('pos.stock_left_count', `${formatQuantity(totalStock, decimals)} in stock`, { count: formatQuantity(totalStock, decimals) }) : `${formatQuantity(totalStock, decimals)} in stock`);
          stockBadgeHtml = `<span class="px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-wider bg-emerald-600 text-white shadow-xs">${txt}</span>`;
        }

        // Reserved Stock Badge
        const hasReserved = exactCompare(reservedStock, '0') > 0;
        const reservedBadgeHtml = hasReserved ? `
          <span class="px-1.5 py-0.5 rounded-full text-[9px] font-bold bg-amber-500/90 text-amber-950 border border-amber-600/30 backdrop-blur-md shadow-xs flex items-center gap-1" title="${formatQuantity(reservedStock, decimals)} Reserved / On Hold">
            <span>🔒</span>
            <span>${formatQuantity(reservedStock, decimals)}</span>
          </span>
        ` : '';

        // Product Media
        let mediaHtml = '';
        if (p.picture) {
          mediaHtml = `<img src="${p.picture}" alt="${escapeHtml(p.name)}" loading="lazy" decoding="async" class="w-full h-full object-cover transition-transform duration-300 group-hover:scale-105">`;
        } else {
          const colorStyles = typeof getColorStyles === 'function' ? getColorStyles(p.color || '#10b981') : { bg: `background-color: ${p.color || '#10b981'}` };
          mediaHtml = `
            <div class="w-full h-full flex items-center justify-center transition-transform duration-300 group-hover:scale-105" style="${colorStyles.bg}">
              <svg class="w-8 h-8 text-white/90 drop-shadow" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4"></path></svg>
            </div>
          `;
        }

        // Price Reference String
        const priceStr = (p.price && parseFloat(p.price) > 0)
          ? `${typeof formatNumber === 'function' ? formatNumber(p.price, decimals) : p.price} DZD`
          : '';

        const isOppositeChosen = !!(oppositeCoinId && String(p.__backendId) === String(oppositeCoinId));
        const isPurchaseRestock = (productPickerTargetId === 'purchase-product' || productPickerTargetId === 'purchase-barter-acq-product' || productPickerTargetId === 'coin-sale-received-product');
        const disabledClass = isOppositeChosen ? 'opacity-50 cursor-not-allowed hover:border-amber-500/50' : ((!isPos && !isPurchaseRestock) ? 'opacity-60 cursor-not-allowed' : '');
        const clickAction = isOppositeChosen
          ? `showToast(window.__t ? window.__t('pos.swap_already_selected_opposite', 'This coin is already selected on the opposite side of the swap') : 'This coin is already selected on the opposite side of the swap')`
          : ((!isPos && !isPurchaseRestock) ? `showToast(window.__t ? window.__t('pos.product_out_of_stock_select', 'This product is out of stock') : 'This product is out of stock')` : `selectProductFromPicker('${escapeJsString(p.__backendId)}')`);

        const oppositeBadgeHtml = isOppositeChosen ? `
          <span class="px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-wider bg-amber-500/20 text-amber-600 dark:text-amber-400 border border-amber-500/30 shadow-xs">
            ${window.__t ? window.__t('pos.swap_selected_opposite', 'Selected on Opposite Side') : 'Selected on Opposite Side'}
          </span>
        ` : '';

        return `
          <button type="button" onclick="${clickAction}"
            class="group relative flex flex-col rounded-2xl border border-slate-200/80 dark:border-white/[0.08] bg-white/90 dark:bg-[#0d1117]/90 hover:border-emerald-500/60 dark:hover:border-emerald-400/60 hover:shadow-lg transition-all duration-200 overflow-hidden cursor-pointer text-start p-2 sm:p-2.5 active:scale-[0.98] ${disabledClass}">
            
            <!-- Thumbnail Media Box -->
            <div class="aspect-square w-full rounded-xl overflow-hidden relative mb-2 bg-slate-100 dark:bg-white/[0.04] flex items-center justify-center">
              ${mediaHtml}
              <!-- Apple Frosted Glass Hover Sheen -->
              <div class="absolute inset-0 bg-white/10 dark:bg-black/20 backdrop-blur-[2px] opacity-0 group-hover:opacity-100 transition-opacity duration-300 pointer-events-none z-10"></div>
              
              <!-- Badges Container -->
              <div class="absolute top-1.5 inset-x-1.5 flex items-center justify-between gap-1 z-20 pointer-events-none">
                <div class="truncate">${oppositeBadgeHtml || reservedBadgeHtml}</div>
                <div class="shrink-0">${stockBadgeHtml}</div>
              </div>
            </div>

            <!-- Bento Content Body -->
            <div class="flex-1 flex flex-col justify-between min-w-0 w-full">
              <div class="min-w-0">
                <div class="text-[10px] font-bold uppercase tracking-wider text-slate-400 dark:text-slate-500 truncate">${escapeHtml(catName || 'Catalog')}</div>
                <h4 class="text-xs font-black text-slate-900 dark:text-white truncate mt-0.5" title="${escapeHtml(p.name)}">${escapeHtml(p.name)}</h4>
              </div>
              <div class="flex items-center justify-between mt-1.5 pt-1.5 border-t border-slate-100 dark:border-white/[0.06] text-[11px] font-mono">
                <span class="font-black text-emerald-600 dark:text-emerald-400 truncate">${priceStr}</span>
                <span class="text-[10px] font-bold text-slate-400 dark:text-slate-500 shrink-0">${isPos ? formatQuantity(totalStock, decimals) + ' avail' : (isPurchaseRestock ? '0 stock' : '0 avail')}</span>
              </div>
            </div>
          </button>
        `;
      }).join('');

      let loadMoreHtml = '';
      if (totalMatching > productPickerVisibleLimit) {
        const remaining = totalMatching - productPickerVisibleLimit;
        const nextChunk = Math.min(PRODUCT_PICKER_PAGE_SIZE, remaining);
        const loadMoreText = window.__t
          ? window.__t('pos.load_more_btn', `Load More (+${nextChunk})`, { count: nextChunk })
          : `Load More (+${nextChunk})`;
        const showingStatus = window.__t
          ? window.__t('pos.load_more_showing', `Showing ${visibleProducts.length} of ${totalMatching} products`, { shown: visibleProducts.length, total: totalMatching })
          : `Showing ${visibleProducts.length} of ${totalMatching} products`;

        loadMoreHtml = `
          <div id="product-picker-load-more-dock" class="col-span-full pt-4 pb-2 flex flex-col items-center justify-center gap-1.5 select-none">
            <span class="text-[10.5px] font-medium text-slate-400 dark:text-slate-500">
              ${escapeHtml(showingStatus)}
            </span>
            <button type="button" id="product-picker-load-more-btn" onclick="loadMoreProductPickerProducts()"
              class="h-11 min-h-[44px] px-6 rounded-2xl bg-slate-100 hover:bg-slate-200 dark:bg-white/[0.06] dark:hover:bg-white/[0.12] text-slate-800 dark:text-slate-100 font-black text-xs border border-slate-200/80 dark:border-white/[0.08] shadow-xs hover:shadow-md transition-all active:scale-95 flex items-center justify-center gap-2 cursor-pointer group shrink-0">
              <svg class="w-4 h-4 text-emerald-500 group-hover:translate-y-0.5 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M19 9l-7 7-7-7"></path>
              </svg>
              <span>${escapeHtml(loadMoreText)}</span>
            </button>
          </div>
        `;
      } else if (totalMatching > PRODUCT_PICKER_PAGE_SIZE) {
        const allLoadedText = window.__t
          ? window.__t('pos.load_more_all_loaded', `All ${totalMatching} products displayed`, { count: totalMatching })
          : `All ${totalMatching} products displayed`;
        loadMoreHtml = `
          <div class="col-span-full py-3 text-center select-none">
            <span class="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[10px] font-bold bg-slate-100 dark:bg-white/[0.04] text-slate-400 border border-slate-200/60 dark:border-white/[0.06]">
              <span>✓</span>
              <span>${escapeHtml(allLoadedText)}</span>
            </span>
          </div>
        `;
      }

      const prevScroll = preserveScroll ? grid.scrollTop : 0;
      grid.innerHTML = cardsHtml + loadMoreHtml;
      if (preserveScroll) {
        grid.scrollTop = prevScroll;
      } else {
        grid.scrollTop = 0;
      }
    }

    function loadMoreProductPickerProducts() {
      if (productPickerVisibleLimit >= productPickerFilteredCache.length) return;
      const btn = document.getElementById('product-picker-load-more-btn');
      if (btn) {
        btn.disabled = true;
        btn.classList.add('opacity-80', 'pointer-events-none', 'cursor-wait');
        const loadingText = window.__t ? window.__t('pos.load_more_loading', 'Loading products...') : 'Loading products...';
        btn.innerHTML = `
          <svg class="animate-spin w-4 h-4 text-emerald-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
            <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="3"></circle>
            <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
          </svg>
          <span>${escapeHtml(loadingText)}</span>
        `;
      }
      setTimeout(() => {
        productPickerVisibleLimit += PRODUCT_PICKER_PAGE_SIZE;
        renderProductPickerGrid(true); // preserve scroll
      }, 60);
    }
    window.loadMoreProductPickerProducts = loadMoreProductPickerProducts;

    function selectProductFromPicker(productId) {
      const allProducts = typeof getProducts === 'function' ? getProducts() : productsCache;
      const product = allProducts.find(p => p.__backendId === String(productId));
      if (!product) return;

      const targetId = productPickerTargetId || 'custom-sale-product-select';

      if (targetId === 'coin-sale-sold-product') {
        const catSelect = document.getElementById('coin-sale-sell-category');
        if (catSelect && product.categoryId) catSelect.value = String(product.categoryId);
        const select = document.getElementById('coin-sale-sold-product');
        if (select) {
          select.innerHTML = `<option value="${product.__backendId}" selected>${escapeHtml(product.name)}</option>`;
          select.value = String(product.__backendId);
        }
        // If opposite side was holding this same product, reset opposite side
        const recvSel = document.getElementById('coin-sale-received-product');
        if (recvSel && String(recvSel.value) === String(product.__backendId)) {
          if (typeof resetCoinSaleRecvProductCard === 'function') resetCoinSaleRecvProductCard();
        }
        updateCoinSaleSellProductCard(product);
        if (typeof onCoinSwapProductChange === 'function') {
          onCoinSwapProductChange('sell', 'coin-sale');
        }
        closeProductPicker();
        return;
      }

      if (targetId === 'coin-sale-received-product') {
        const catSelect = document.getElementById('coin-sale-recv-category');
        if (catSelect && product.categoryId) catSelect.value = String(product.categoryId);
        const select = document.getElementById('coin-sale-received-product');
        if (select) {
          select.innerHTML = `<option value="${product.__backendId}" selected>${escapeHtml(product.name)}</option>`;
          select.value = String(product.__backendId);
        }
        // If opposite side was holding this same product, reset opposite side
        const soldSel = document.getElementById('coin-sale-sold-product');
        if (soldSel && String(soldSel.value) === String(product.__backendId)) {
          if (typeof resetCoinSaleSellProductCard === 'function') resetCoinSaleSellProductCard();
        }
        updateCoinSaleRecvProductCard(product);
        if (typeof onCoinSwapProductChange === 'function') {
          onCoinSwapProductChange('recv', 'coin-sale');
        }
        closeProductPicker();
        return;
      }

      if (targetId === 'purchase-spend-product') {
        const catSelect = document.getElementById('purchase-spend-category');
        if (catSelect && product.categoryId) catSelect.value = String(product.categoryId);
        const select = document.getElementById('purchase-spend-product');
        if (select) {
          select.innerHTML = `<option value="${product.__backendId}" selected>${escapeHtml(product.name)}</option>`;
          select.value = String(product.__backendId);
        }
        // If opposite side was holding this same product, reset opposite side
        const acqSel = document.getElementById('purchase-barter-acq-product');
        if (acqSel && String(acqSel.value) === String(product.__backendId)) {
          if (typeof resetPurchaseAcqProductSelectionCard === 'function') resetPurchaseAcqProductSelectionCard();
        }
        updatePurchaseSpendProductSelectionCard(product);
        if (typeof onCoinSwapProductChange === 'function') {
          onCoinSwapProductChange('sell', 'purchase-swap');
        }
        closeProductPicker();
        return;
      }

      if (targetId === 'purchase-barter-acq-product') {
        const catSelect = document.getElementById('purchase-barter-acq-category');
        if (catSelect && product.categoryId) catSelect.value = String(product.categoryId);
        const select = document.getElementById('purchase-barter-acq-product');
        if (select) {
          select.innerHTML = `<option value="${product.__backendId}" selected>${escapeHtml(product.name)}</option>`;
          select.value = String(product.__backendId);
        }
        // If opposite side was holding this same product, reset opposite side
        const spendSel = document.getElementById('purchase-spend-product');
        if (spendSel && String(spendSel.value) === String(product.__backendId)) {
          if (typeof resetPurchaseSpendProductSelectionCard === 'function') resetPurchaseSpendProductSelectionCard();
        }
        updatePurchaseAcqProductSelectionCard(product);
        if (typeof onCoinSwapProductChange === 'function') {
          onCoinSwapProductChange('recv', 'purchase-swap');
        }
        closeProductPicker();
        return;
      }

      if (targetId === 'purchase-product') {
        // 1. Sync hidden backing category and product selects
        const catSelect = document.getElementById('purchase-category');
        if (catSelect && product.categoryId) {
          catSelect.value = String(product.categoryId);
        }
        const select = document.getElementById('purchase-product');
        if (select) {
          select.innerHTML = `<option value="${product.__backendId}" selected>${escapeHtml(product.name)}</option>`;
          select.value = String(product.__backendId);
        }

        // 2. Update Bento Selection Card
        updatePurchaseProductSelectionCard(product);

        // 3. Enforce step precision on pricing & quantity inputs
        const priceInput = document.getElementById('purchase-price');
        const quantityInput = document.getElementById('purchase-quantity');
        const decimals = (product.displayDecimals !== null && product.displayDecimals !== undefined)
          ? product.displayDecimals
          : (config.display_decimals !== undefined ? config.display_decimals : 2);

        if (priceInput) {
          priceInput.step = "any";
          enforcePrecision(priceInput, decimals);
        }
        if (quantityInput) {
          quantityInput.step = "any";
          quantityInput.placeholder = `Quantity (${decimals} decimals settings)`;
          enforcePrecision(quantityInput, decimals);
        }

        // 4. Trigger downstream calculations & barter refresh
        calcPurchaseTotal();
        if (typeof onPurchaseProductChange === 'function') {
          onPurchaseProductChange();
        }

        closeProductPicker();
        return;
      }

      const select = document.getElementById(targetId);
      const catSelect = document.getElementById('custom-sale-product-category');

      // Sync category dropdown
      if (catSelect && product.categoryId) {
        catSelect.value = String(product.categoryId);
      }

      // Sync product select
      if (select) {
        select.innerHTML = `<option value="${product.__backendId}">${escapeHtml(product.name)}</option>`;
        select.value = String(product.__backendId);
      }

      // Update selected product card in custom sale modal
      updateCustomProductSelectionCard(product);

      // Trigger standard downstream workflow (batch selection, price chips, margin split)
      if (typeof onCustomProductSelectionChanged === 'function') {
        onCustomProductSelectionChanged();
      }

      closeProductPicker();
    }

    function resetCustomProductSelectionCard() {
      const emptyCard = document.getElementById('custom-product-card-empty');
      const selectedCard = document.getElementById('custom-product-card-selected');
      const stockHint = document.getElementById('custom-product-stock-hint');

      if (emptyCard) emptyCard.classList.remove('hidden');
      if (selectedCard) selectedCard.classList.add('hidden');
      if (stockHint) stockHint.textContent = '';

      const nameEl = document.getElementById('custom-selected-product-name');
      if (nameEl) nameEl.textContent = '';
      const catEl = document.getElementById('custom-selected-product-category');
      if (catEl) catEl.textContent = '';
      const stockPill = document.getElementById('custom-selected-product-stock-pill');
      if (stockPill) { stockPill.textContent = ''; stockPill.className = 'inline-block px-2 py-0.5 rounded-full text-[10px] font-black uppercase tracking-wider'; }
      const holdBadge = document.getElementById('custom-selected-product-hold-badge');
      if (holdBadge) holdBadge.classList.add('hidden');
      const priceRef = document.getElementById('custom-selected-product-price-ref');
      if (priceRef) priceRef.textContent = '';
      const imgEl = document.getElementById('custom-selected-product-img');
      if (imgEl) { imgEl.src = ''; imgEl.classList.add('hidden'); }
      const fallbackEl = document.getElementById('custom-selected-product-fallback');
      if (fallbackEl) fallbackEl.classList.remove('hidden');
    }

    function updateCustomProductSelectionCard(product) {
      if (!product) return;
      const emptyCard = document.getElementById('custom-product-card-empty');
      const selectedCard = document.getElementById('custom-product-card-selected');
      if (emptyCard) emptyCard.classList.add('hidden');
      if (selectedCard) selectedCard.classList.remove('hidden');

      const nameEl = document.getElementById('custom-selected-product-name');
      if (nameEl) nameEl.textContent = product.name;

      const catEl = document.getElementById('custom-selected-product-category');
      const cat = typeof getCategoryById === 'function' ? getCategoryById(product.categoryId) : null;
      if (catEl) catEl.textContent = cat ? cat.name : 'Catalog';

      const totalStock = typeof getProductAvailableQuantity === 'function' ? getProductAvailableQuantity(product.__backendId) : (product.quantity || '0');
      const reservedStock = product.quantityReserved || '0';
      const isPos = exactCompare(totalStock, '0') > 0;
      const lowThreshold = String(product.stockLowThreshold || 5);
      const isLow = isPos && exactCompare(totalStock, lowThreshold) <= 0;
      const isHiddenStock = exactCompare(String(product.hiddenStock || '0'), '0') > 0;
      const decimals = (product.displayDecimals !== null && product.displayDecimals !== undefined) ? product.displayDecimals : (config.display_decimals ?? 2);

      const stockPill = document.getElementById('custom-selected-product-stock-pill');
      if (stockPill) {
        if (!isPos) {
          stockPill.className = 'inline-block px-2 py-0.5 rounded-full text-[10px] font-black uppercase tracking-wider bg-rose-500/10 text-rose-600 dark:text-rose-400 border border-rose-500/20';
          stockPill.textContent = window.__t ? window.__t('pos.badge_out_of_stock', 'Out of Stock') : 'Out of Stock';
        } else if (isLow) {
          stockPill.className = 'inline-block px-2 py-0.5 rounded-full text-[10px] font-black uppercase tracking-wider bg-amber-500/10 text-amber-600 dark:text-amber-400 border border-amber-500/20';
          stockPill.textContent = isHiddenStock
            ? (window.__t ? window.__t('pos.badge_in_stock', 'In Stock') : 'In Stock')
            : (window.__t ? window.__t('pos.stock_left_count', `${formatQuantity(totalStock, decimals)} left`, { count: formatQuantity(totalStock, decimals) }) : `${formatQuantity(totalStock, decimals)} left`);
        } else {
          stockPill.className = 'inline-block px-2 py-0.5 rounded-full text-[10px] font-black uppercase tracking-wider bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border border-emerald-500/20';
          stockPill.textContent = isHiddenStock
            ? (window.__t ? window.__t('pos.badge_in_stock', 'In Stock') : 'In Stock')
            : (window.__t ? window.__t('pos.stock_left_count', `${formatQuantity(totalStock, decimals)} in stock`, { count: formatQuantity(totalStock, decimals) }) : `${formatQuantity(totalStock, decimals)} in stock`);
        }
      }

      const holdBadge = document.getElementById('custom-selected-product-hold-badge');
      if (holdBadge) {
        if (exactCompare(reservedStock, '0') > 0) {
          holdBadge.classList.remove('hidden');
          holdBadge.textContent = window.__t
            ? window.__t('pos.on_hold_count', `${formatQuantity(reservedStock, decimals)} On Hold`, { count: formatQuantity(reservedStock, decimals) })
            : `${formatQuantity(reservedStock, decimals)} On Hold`;
        } else {
          holdBadge.classList.add('hidden');
        }
      }

      const priceRef = document.getElementById('custom-selected-product-price-ref');
      if (priceRef) {
        if (product.price && parseFloat(product.price) > 0) {
          const formattedP = typeof formatNumber === 'function' ? formatNumber(product.price, decimals) : product.price;
          priceRef.textContent = window.__t
            ? window.__t('pos.catalog_price_ref', `Catalog: ${formattedP} DZD`, { price: `${formattedP} DZD` })
            : `Catalog: ${formattedP} DZD`;
        } else {
          priceRef.textContent = '';
        }
      }

      const imgEl = document.getElementById('custom-selected-product-img');
      const fallbackEl = document.getElementById('custom-selected-product-fallback');
      if (product.picture) {
        if (imgEl) {
          imgEl.src = product.picture;
          imgEl.classList.remove('hidden');
        }
        if (fallbackEl) fallbackEl.classList.add('hidden');
      } else {
        if (imgEl) imgEl.classList.add('hidden');
        if (fallbackEl) {
          fallbackEl.classList.remove('hidden');
          const colorStyles = typeof getColorStyles === 'function' ? getColorStyles(product.color || '#10b981') : { bg: `background-color: ${product.color || '#10b981'}` };
          fallbackEl.style = colorStyles.bg;
        }
      }
    }

