    function updatePurchaseSpendProductSelectionCard(product) {
      if (!product) return;
      const emptyCard = document.getElementById('purchase-spend-product-card-empty');
      const selectedCard = document.getElementById('purchase-spend-product-card-selected');
      if (emptyCard) emptyCard.classList.add('hidden');
      if (selectedCard) selectedCard.classList.remove('hidden');

      const nameEl = document.getElementById('purchase-spend-selected-product-name');
      if (nameEl) nameEl.textContent = product.name;

      const catEl = document.getElementById('purchase-spend-selected-product-category');
      const cat = typeof getCategoryById === 'function' ? getCategoryById(product.categoryId) : null;
      if (catEl) catEl.textContent = cat ? cat.name : 'Catalog';

      const myId = (currentUser && (currentUser.__backendId || currentUser.id)) ? String(currentUser.__backendId || currentUser.id) : '';
      const myBatches = (typeof getPurchases === 'function' ? getPurchases() : (purchasesCache || [])).filter(p => !p.deletedAt && String(p.productId) === String(product.__backendId) && (String(p.ownerUserId) === myId || !p.ownerUserId) && exactCompare(exactSubtract(p.quantityRemaining || '0', p.quantityReserved || '0'), '0') > 0);
      const totalAvail = myBatches.reduce((sum, b) => exactAdd(sum, exactSubtract(b.quantityRemaining || '0', b.quantityReserved || '0')), '0');
      const decimals = (product.displayDecimals !== null && product.displayDecimals !== undefined) ? product.displayDecimals : (config.display_decimals ?? 2);

      const stockPill = document.getElementById('purchase-spend-selected-product-stock-pill');
      if (stockPill) {
        stockPill.textContent = `${formatQuantity(totalAvail, decimals)} owned`;
      }
      const hint = document.getElementById('purchase-spend-product-hint');
      if (hint) {
        hint.textContent = `Available: ${formatQuantity(totalAvail, decimals)}`;
      }

      const refEl = document.getElementById('purchase-spend-selected-product-ref');
      if (refEl) {
        const priceStr = (product.price && parseFloat(product.price) > 0)
          ? `${typeof formatNumber === 'function' ? formatNumber(product.price, decimals) : product.price} DZD`
          : '';
        refEl.textContent = priceStr ? `Ref: ${priceStr}` : '';
      }

      const imgEl = document.getElementById('purchase-spend-selected-product-img');
      const fallbackEl = document.getElementById('purchase-spend-selected-product-fallback');
      if (product.picture) {
        if (imgEl) { imgEl.src = product.picture; imgEl.classList.remove('hidden'); }
        if (fallbackEl) fallbackEl.classList.add('hidden');
      } else {
        if (imgEl) imgEl.classList.add('hidden');
        if (fallbackEl) {
          fallbackEl.classList.remove('hidden');
          const colorStyles = typeof getColorStyles === 'function' ? getColorStyles(product.color || '#f43f5e') : { bg: `background-color: ${product.color || '#f43f5e'}` };
          fallbackEl.style = colorStyles.bg;
        }
      }
    }

