          submitBtn.innerHTML = `<svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7"></path></svg><span>${window.__t ? window.__t('purchases.modals_forms_save_purchase', 'Save Purchase') : 'Save Purchase'}</span>`;
