    function toggleBatchMergeDrawer(forceOpen = null) {
      const drawer = document.getElementById('purchase-batch-merger-drawer');
      const chevron = document.getElementById('batch-merge-drawer-chevron');
      const toggleBtn = document.getElementById('purchases-multi-select-toggle-btn');
      if (!drawer) return;

      if (typeof forceOpen === 'boolean') {
        isBatchMergeDrawerOpen = forceOpen;
      } else {
        isBatchMergeDrawerOpen = !isBatchMergeDrawerOpen;
      }

      if (isBatchMergeDrawerOpen) {
        drawer.classList.remove('hidden');
        if (chevron) chevron.classList.add('rotate-180');
        if (toggleBtn) {
          toggleBtn.classList.add('bg-cyan-500/25', 'border-cyan-500/60', 'text-cyan-800', 'dark:text-cyan-200');
        }


        // Close Date Range Picker if open
        const datePicker = document.getElementById('purchase-date-range-picker');
        if (datePicker && !datePicker.classList.contains('hidden')) {
          datePicker.classList.add('hidden');
        }


        // Attach escape listener
        if (!batchMergeEscapeHandler) {
          batchMergeEscapeHandler = (e) => {
            if (e.key === 'Escape' || e.keyCode === 27) {
              if (typeof ModalManager !== 'undefined' && typeof ModalManager.getActiveModal === 'function') {
                const active = ModalManager.getActiveModal();
                if (active && active.id && active.id !== 'purchase-batch-merger-drawer') {
                  return;
                }

              }

              e.preventDefault();
              e.stopPropagation();
              toggleBatchMergeDrawer(false);
            }

          }
;
          document.addEventListener('keydown', batchMergeEscapeHandler);
        }


        setMergeStudioMode(currentMergeStudioMode || 'mode1');
      } else {
        drawer.classList.add('hidden');
        if (chevron) chevron.classList.remove('rotate-180');
        if (toggleBtn) {
          toggleBtn.classList.remove('bg-cyan-500/25', 'border-cyan-500/60', 'text-cyan-800', 'dark:text-cyan-200');
        }


        if (batchMergeEscapeHandler) {
          document.removeEventListener('keydown', batchMergeEscapeHandler);
          batchMergeEscapeHandler = null;
        }

      }

      if (typeof ModalManager !== 'undefined' && typeof ModalManager.updateScrollLock === 'function') {
        ModalManager.updateScrollLock();
      }
    }
    window.toggleBatchMergeDrawer = toggleBatchMergeDrawer;
    window.closeBatchMergeDrawer = () => toggleBatchMergeDrawer(false);

