    // Safely format native numbers avoiding scientific notation format `1e-15`
    function toExactDecimalString(val) {
      if (val === null || val === undefined) return '0';
      let strVal = String(val).toLowerCase();
      if (strVal.includes('e')) {
        let parts = strVal.split('e');
        let coeff = parts[0];
        let exp = parseInt(parts[1], 10);
        let [intPart, fracPart = ''] = coeff.split('.');
        if (exp < 0) {
          let numZeros = Math.abs(exp) - 1;
          return '0.' + '0'.repeat(numZeros) + intPart + fracPart;
        }
 else {
          let extraZeros = exp - fracPart.length;
          if (extraZeros >= 0) {
            return intPart + fracPart + '0'.repeat(extraZeros);
          }
 else {
            return intPart + fracPart.slice(0, exp) + '.' + fracPart.slice(exp);
          }

        }

      }
      return strVal;
    }

