    function parseDeviceUserAgent(ua) {
      if (!ua || typeof ua !== 'string') return { label: _tUsers('users.main_views_unknown_device', 'Unknown Device'), device: _tUsers('users.main_views_desktop', 'Desktop'), os: _tUsers('users.main_views_unknown_os', 'Unknown OS'), browser: _tUsers('users.main_views_browser', 'Browser'), icon: '💻' };
      const lower = ua.toLowerCase();
      let device = _tUsers('users.main_views_desktop', 'Desktop');
      let os = _tUsers('users.main_views_unknown_os', 'Unknown OS');
      let browser = _tUsers('users.main_views_browser', 'Browser');
      let icon = '💻';

      if (lower.includes('iphone') || lower.includes('ipad') || lower.includes('ipod')) {
        device = _tUsers('users.main_views_mobile', 'Mobile');
        os = 'iOS';
        icon = '📱';
      } else if (lower.includes('android')) {
        device = _tUsers('users.main_views_mobile', 'Mobile');
        os = 'Android';
        icon = '🤖';
      } else if (lower.includes('windows')) {
        os = 'Windows';
        icon = '💻';
      } else if (lower.includes('macintosh') || lower.includes('mac os')) {
        os = 'macOS';
        icon = '🍎';
      } else if (lower.includes('linux')) {
        os = 'Linux';
        icon = '🐧';
      }

      if (lower.includes('edg/')) {
        browser = 'Edge';
      } else if (lower.includes('chrome') && !lower.includes('edg')) {
        browser = 'Chrome';
      } else if (lower.includes('safari') && !lower.includes('chrome')) {
        browser = 'Safari';
      } else if (lower.includes('firefox')) {
        browser = 'Firefox';
      } else if (lower.includes('opera') || lower.includes('opr/')) {
        browser = 'Opera';
      }

      return {
        label: `${browser} · ${os}`,
        device,
        os,
        browser,
        icon
      };
    }
