    function maskIpAddress(ip) {
      if (!ip || ip === '0.0.0.0') return '127.0.0.1';
      const parts = ip.split('.');
      if (parts.length === 4) {
        return `${parts[0]}.${parts[1]}.***.***`;
      }
      if (ip.includes(':')) {
        const v6Parts = ip.split(':');
        return `${v6Parts[0]}:${v6Parts[1]}:****:****`;
      }
      return '***.***.***.***';
    }
    window.maskIpAddress = maskIpAddress;

    function getSessionDurationForEntry(entry, index, cache, isUserOnline) {
      const et = entry.event_type;
      if (et === 'blocked_attempt' || et === 'master_recovery' || et === 'user_recovery') {
        return null;
      }

      const parseTs = (ts) => {
        if (!ts) return null;
        if (typeof parseMySQLDate === 'function') {
          const d = parseMySQLDate(ts);
          if (d && !isNaN(d.getTime())) return d;
        }

        return new Date(String(ts).replace(' ', 'T'));
      };

      const currentTs = parseTs(entry.created_at);
      if (!currentTs || isNaN(currentTs.getTime())) return null;

      const formatDiff = (diffMs) => {
        if (diffMs < 0) return null;
        const mins = Math.floor(diffMs / 60000);
        const hrs = Math.floor(mins / 60);
        if (hrs > 0) return `${hrs}h ${mins % 60}m`;
        return `${Math.max(1, mins)}m`;
      };

      if (et === 'login') {
        for (let j = index - 1; j >= 0; j--) {
          const prev = cache[j];
          const prevEt = prev.event_type;
          if (prevEt === 'login') break;
          if (prevEt === 'logout' || prevEt === 'auto_logout' || prevEt === 'logout_browser_close') {
            const endTs = parseTs(prev.created_at);
            if (endTs) {
              const diff = endTs.getTime() - currentTs.getTime();
              const str = formatDiff(diff);
              if (str) return { label: `${str} ${_tUsers('users.history_ledgers_session', 'session')}`, type: 'completed', duration: str };
            }

            break;
          }

        }

        if (index === 0 && isUserOnline) {
          const liveDiff = Date.now() - currentTs.getTime();
          const str = formatDiff(liveDiff);
          return { label: _tUsers('users.status_pills_active_now', 'Active Now'), type: 'active', duration: str || _tUsers('users.history_ledgers_just_now', 'Just now') };
        }

        return null;
      }

      if (et === 'logout' || et === 'auto_logout' || et === 'logout_browser_close') {
        for (let j = index + 1; j < cache.length; j++) {
          const next = cache[j];
          if (next.event_type === 'login') {
            const startTs = parseTs(next.created_at);
            if (startTs) {
              const diff = currentTs.getTime() - startTs.getTime();
              const str = formatDiff(diff);
              if (str) return { label: `${str} ${_tUsers('users.main_views_active', 'active')}`, type: 'closed', duration: str };
            }

            break;
          }

          if (next.event_type === 'logout' || next.event_type === 'auto_logout' || next.event_type === 'logout_browser_close') {
            break;
          }

        }

        return null;
      }

      return null;
    }

