    // ── URL helper: all raw fetch calls must use the correct base path ──
    function getApiUrl(path) {
      const bp = window.location.pathname.replace(/\/index\.html$/, '').replace(/\/$/, '');
      return bp + path;
    }

    // When the tab/browser closes: clear the activity marker so re-login is instant.
    // sessionStorage survives refresh but dies on tab/browser close.
    // We set a flag so the next page load can detect "this was a refresh"
    // and clean up the false logout_browser_close log entry.
    window.addEventListener('pagehide', function(e) {
      if (typeof terminateAllAudioAndMediaSession === 'function') {
        try { terminateAllAudioAndMediaSession(); } catch (e) {}
      }
      if (e.persisted) return;
      if (currentUser) {
        sessionStorage.setItem('pos_pagehide', '1');
        navigator.sendBeacon(getApiUrl('/api/auth/mark-closed'));
      }
    });

    // ── Heartbeat + Inactivity system ──
    let heartbeatInterval    = null;
    let inactivityTimeout    = null;
    let inactivityCountdownInterval = null;
    let lastActivityTime     = 0;
    let lastUserInteractionTimestamp = Date.now();
    let heartbeatWorker      = null; // kept for compat
    let inactivityWarningShowing = false;

    const HEARTBEAT_DEBOUNCE_MS  = 30000;
    const FALLBACK_INTERVAL_MS   = 60000;
    const MAX_WARNING_SECS       = 60; // max warning countdown seconds
    let configuredTimeoutMs = 600000; // set from settings (default 10 min)

    function handleActivityResponse(data) {
      // SEC-05: Synchronize session role & permissions in real time from heartbeat
      if (data && data.is_admin !== undefined && currentUser) {
        const newIsAdmin = !!data.is_admin;
        const newIsSuperAdmin = !!data.is_super_admin;
        const newRole = data.role || (newIsSuperAdmin ? 'super_admin' : (newIsAdmin ? 'admin' : 'staff'));
        if (currentUser.is_admin !== newIsAdmin || currentUser.is_super_admin !== newIsSuperAdmin || currentUser.role !== newRole) {
          currentUser.is_admin = newIsAdmin;
          currentUser.isAdmin = newIsAdmin;
          currentUser.is_super_admin = newIsSuperAdmin;
          currentUser.isSuperAdmin = newIsSuperAdmin;
          currentUser.role = newRole;
          try { sessionStorage.setItem('pos_current_user', JSON.stringify(currentUser)); } catch(e) {}
          if (typeof updateCurrentUserDisplay === 'function') updateCurrentUserDisplay();
        }
      }
      handleLoginAttemptAlert(!!data.login_attempt_alert, {
        latest_attempt_id: data.latest_attempt_id || null,
        attempt_count: data.attempt_count || 1,
        target_username: data.target_username || null,
        target_uid: data.target_uid || null
      });
      // Sync auto-logout setting from server (admin may have changed it)
      if (data.auto_logout_minutes !== undefined) {
        const newMs = data.auto_logout_minutes === 0 ? 0 : Math.round(data.auto_logout_minutes * 60 * 1000);
        if (newMs !== configuredTimeoutMs) {
          configuredTimeoutMs = newMs;
          resetInactivityTimer();
        }

      }

      // Sync online users list from heartbeat
      if (Array.isArray(data.online_user_ids) && typeof syncUserPresence === 'function') {
        syncUserPresence(data.online_user_ids);
      }
      const warningOverlay = document.getElementById('deletion-warning-overlay');
      if (data.pending_deletion) {
        document.getElementById('target-deletion-reason').textContent = data.pending_reason || _tUsers('users.main_views_administrator_action', 'Administrator action');
        document.getElementById('target-deletion-deleter').textContent = data.pending_deleter_username || _tUsers('users.main_views_administrator', 'Administrator');
        const uidEl = document.getElementById('target-deletion-deleter-uid');
        uidEl.textContent = data.pending_deleter_uid ? `${_tUsers('users.modals_forms_user_uid_0000', 'User UID: #').replace('0000', '')}${data.pending_deleter_uid}` : '';
        warningOverlay.classList.remove('hidden');
      } else {
        warningOverlay.classList.add('hidden');
      }
    }

    // Calculate warning countdown seconds based on configured timeout
    function getWarningSeconds() {
      if (configuredTimeoutMs === 0) return 0;
      // Warning = 1/3 of timeout, clamped between 5s and 60s
      return Math.max(5, Math.min(MAX_WARNING_SECS, Math.round(configuredTimeoutMs / 3000)));
    }

    function showInactivityWarning() {
      if (inactivityWarningShowing || !currentUser || configuredTimeoutMs === 0) return;
      inactivityWarningShowing = true;
      const overlay = document.getElementById('inactivity-warning-overlay');
      const countdownEl = document.getElementById('inactivity-countdown');
      let remaining = getWarningSeconds();
      countdownEl.textContent = remaining;
      overlay.classList.remove('hidden');
      inactivityCountdownInterval = setInterval(() => {
        remaining--;
        countdownEl.textContent = remaining;
        if (remaining <= 0) {
          clearInterval(inactivityCountdownInterval);
          inactivityCountdownInterval = null;
          overlay.classList.add('hidden');
          inactivityWarningShowing = false;
          if (currentUser) autoLogoutInactivity();
        }

      }, 1000);
    }

    // Called by clicking the warning overlay — dismiss + restart cycle + heartbeat
    function dismissInactivityWarning() {
      if (!inactivityWarningShowing) return;
      inactivityWarningShowing = false;
      if (inactivityCountdownInterval) { clearInterval(inactivityCountdownInterval); inactivityCountdownInterval = null; }
      document.getElementById('inactivity-warning-overlay').classList.add('hidden');
      // Restart inactivity cycle from scratch
      setTimeout(() => {
        lastUserInteractionTimestamp = Date.now();
        resetInactivityTimer();
        lastActivityTime = Date.now();
        updateUserActivity();
      }, 0);
    }

    function resetInactivityTimer() {
      lastUserInteractionTimestamp = Date.now();
      // Clear existing timers
      if (inactivityTimeout) { clearTimeout(inactivityTimeout); inactivityTimeout = null; }
      // If warning is showing, hide it immediately (user did something)
      if (inactivityWarningShowing) {
        inactivityWarningShowing = false;
        if (inactivityCountdownInterval) { clearInterval(inactivityCountdownInterval); inactivityCountdownInterval = null; }
        document.getElementById('inactivity-warning-overlay').classList.add('hidden');
      }
      // 0 = "forever" — no timeout
      if (configuredTimeoutMs === 0) return;
      // Schedule warning: show it (warningSeconds) before the full timeout
      const warnSecs = getWarningSeconds();
      const warningAt = Math.max(configuredTimeoutMs - warnSecs * 1000, 1000);
      inactivityTimeout = setTimeout(() => {
        if (currentUser) showInactivityWarning();
      }, warningAt);
    }

    function checkInactivityWallClock() {
      if (!currentUser || configuredTimeoutMs === 0) return;
      const now = Date.now();
      const elapsedMs = now - lastUserInteractionTimestamp;
      const warnSecs = getWarningSeconds();
      const warnThresholdMs = Math.max(configuredTimeoutMs - warnSecs * 1000, 1000);

      if (elapsedMs >= configuredTimeoutMs) {
        // User was away longer than the entire timeout (e.g. screen off for 15+ min)
        if (inactivityWarningShowing) {
          if (inactivityCountdownInterval) clearInterval(inactivityCountdownInterval);
          inactivityCountdownInterval = null;
          document.getElementById('inactivity-warning-overlay').classList.add('hidden');
          inactivityWarningShowing = false;
        }

        autoLogoutInactivity();
      } else if (elapsedMs >= warnThresholdMs) {
        // User woke screen during the warning countdown window
        if (!inactivityWarningShowing) {
          showInactivityWarning();
        }

      } else {
        // User is still within active timeout — reschedule remaining time
        if (inactivityTimeout) { clearTimeout(inactivityTimeout); inactivityTimeout = null; }
        const remainingUntilWarn = warnThresholdMs - elapsedMs;
        inactivityTimeout = setTimeout(() => {
          if (currentUser) showInactivityWarning();
        }
, Math.max(remainingUntilWarn, 1000));
      }
    }

    function onUserActivity() {
      if (!currentUser || isAppInitializing) return;
      const now = Date.now();
      lastUserInteractionTimestamp = now;
      resetInactivityTimer();
      if (now - lastActivityTime >= HEARTBEAT_DEBOUNCE_MS) {
        lastActivityTime = now;
        updateUserActivity();
      }
    }

    function startHeartbeat() {
      if (heartbeatInterval) clearInterval(heartbeatInterval);
      if (inactivityTimeout) clearTimeout(inactivityTimeout);
      lastActivityTime = Date.now();
      lastUserInteractionTimestamp = Date.now();
      updateUserActivity();
      heartbeatInterval = setInterval(async () => {
        if (currentUser) {
          await updateUserActivity();
          if (currentPage === 'users') loadUsers();
        }

      }, FALLBACK_INTERVAL_MS);
      resetInactivityTimer();
    }

    function stopHeartbeat() {
      if (heartbeatInterval) { clearInterval(heartbeatInterval); heartbeatInterval = null; }
      if (inactivityTimeout) { clearTimeout(inactivityTimeout); inactivityTimeout = null; }
      if (inactivityCountdownInterval) { clearInterval(inactivityCountdownInterval); inactivityCountdownInterval = null; }
      if (typeof stopGlobalBackgroundSync === 'function') stopGlobalBackgroundSync();
      if (inactivityWarningShowing) {
        document.getElementById('inactivity-warning-overlay').classList.add('hidden');
        inactivityWarningShowing = false;
      }
    }

    // Activity listeners: scroll + touchmove added so scrolling counts as activity
    ['click', 'keydown', 'mousemove', 'scroll', 'touchstart', 'touchmove'].forEach(ev => {
      document.addEventListener(ev, onUserActivity, { passive: true });
    });

    // Tab comes back to foreground / screen wakes — check absolute wall-clock time
    document.addEventListener('visibilitychange', () => {
      if (!document.hidden && currentUser && !isAppInitializing) { checkInactivityWallClock(); }
    });
    window.addEventListener('focus', () => {
      if (currentUser && !isAppInitializing) { checkInactivityWallClock(); }
    });

    window.resetInactivityTimer = resetInactivityTimer;
    window.dismissInactivityWarning = dismissInactivityWarning;
    window.showInactivityWarning = showInactivityWarning;
    window.startHeartbeat = startHeartbeat;
    window.stopHeartbeat = stopHeartbeat;
    window.autoLogoutInactivity = autoLogoutInactivity;
    window.updateUserActivity = updateUserActivity;

    async function updateUserActivity() {
      if (!currentUser) return;
      try {
        const dt = (typeof getOrCreateDeviceToken === 'function') ? getOrCreateDeviceToken() : (localStorage.getItem('pos_device_token') || '');
        const response = await fetch(getApiUrl('/api/users/activity'), { method: 'POST', credentials: 'include', headers: { 'X-Device-Token': dt, 'X-Requested-With': 'XMLHttpRequest' } });
        if (response.status === 401) {
          // Account deleted or session taken over — full cleanup (preserve pos_device_token so same browser does not self-lock)
          if (typeof terminateAllAudioAndMediaSession === 'function') terminateAllAudioAndMediaSession();
          stopHeartbeat();
          sessionStorage.removeItem('tab_session');
          sessionStorage.removeItem('pos_active_page');
          sessionStorage.removeItem('pos_data_cache');
          currentUser = null;
          try { sessionStorage.removeItem('pos_current_user'); } catch(e) {}
          try { document.documentElement.setAttribute('data-pre-auth', '0'); } catch (e) {}
          usersCache = []; productsCache = []; customersCache = []; suppliersCache = [];
          purchasesCache = []; ordersCache = []; categoriesCache = [];
          setAllData();
          document.getElementById('app').classList.add('hidden');
          document.getElementById('login-page').classList.remove('hidden');
          document.getElementById('login-form').reset();
          let msg = 'Your session has ended.';
          try { const d = await response.json(); if (d.error) msg = d.error; } catch(e) {}
          showToast(msg);
          return;
        }

        if (response.status === 423) {
          let p = null;
          try { p = await response.json(); } catch(e) {}
          if (typeof triggerLicenseHardLockout === 'function') {
            triggerLicenseHardLockout(p || {});
          }

          return;
        }

        if (response.ok) {
          const data = await response.json();
          handleActivityResponse(data);
        }

      } catch (e) {
        // network error — next interval will retry
      }
    }

    async function saveUser(e) {
      e.preventDefault();

      const btn = document.getElementById('user-submit-btn');
      const isRecoverySession = sessionStorage.getItem('pos_can_set_password_once') === '1';
      const defaultBtnText = isRecoverySession ? _tUsers('users.modals_forms_update_password', 'Update Password') : (editingUserId ? _tUsers('users.main_views_save_changes', 'Save Changes') : _tUsers('users.main_views_create_user', '+ Create User'));

      const username = document.getElementById('user-username').value.trim();
      const passInput = document.getElementById('user-password');
      const password = passInput ? passInput.value : '';
      const isPassVisible = passInput && passInput.type === 'text';
      const confirmInput = document.getElementById('user-password-confirm');
      const confirmPassword = confirmInput ? confirmInput.value : '';
      const reason = document.getElementById('user-reason').value.trim();

      // Enforce reason, length, and confirmation matching
      const currentUserId = currentUser ? String(currentUser.id || currentUser.__backendId) : null;
      const isSelf = currentUserId && (String(editingUserId) === String(currentUserId) || username.toLowerCase() === (currentUser.username || '').toLowerCase());
      const currentPassword = document.getElementById('user-current-password')?.value || '';

      const origUsername = document.getElementById('user-username')?.dataset.originalUsername || '';
      const isUsernameChanging = !!(editingUserId && origUsername && username !== origUsername);

      // Username change validation in lockdown mode
      if (isUsernameChanging) {
        if (username.length < 3) {
          showToast(_tUsers('users.modals_forms_username_must_be_at_least_3_characters', 'Username must be at least 3 characters long'));
          document.getElementById('user-username')?.focus();
          return;
        }

        if (username.length > 50) {
          showToast(_tUsers('users.modals_forms_username_cannot_exceed_50_characters', 'Username cannot exceed 50 characters'));
          document.getElementById('user-username')?.focus();
          return;
        }

        if (!/^[a-zA-Z0-9_\-\.]+$/.test(username)) {
          showToast(_tUsers('users.modals_forms_username_can_only_contain_letters', 'Username can only contain letters, numbers, dots, hyphens, and underscores'));
          document.getElementById('user-username')?.focus();
          return;
        }

        if (!password) {
          showToast(isSelf ? _tUsers('users.modals_forms_please_enter_your_password_to_confirm', 'Please enter your password to confirm username change') : _tUsers('users.status_pills_please_enter_your_super_admin_password', 'Please enter your Super Admin password to confirm username change'));
          if (passInput) passInput.focus();
          return;
        }

      }

      // 1. Validation for Create Mode
      if (!editingUserId) {
        if (!password) {
          showToast(_tUsers('users.modals_forms_password_is_required_for_new_users', 'Password is required for new users'));
          if (passInput) passInput.focus();
          return;
        }

        if (password.length < 6) {
          showToast(_tUsers('users.modals_forms_password_must_be_at_least_6_characters', 'Password must be at least 6 characters'));
          if (passInput) passInput.focus();
          return;
        }

        // If password is masked/hidden, confirmation is required and must match
        if (!isPassVisible) {
          if (!confirmPassword) {
            showToast(_tUsers('users.modals_forms_please_re_enter_password_to_confirm', 'Please re-enter password to confirm'));
            if (confirmInput) confirmInput.focus();
            return;
          }

          if (password !== confirmPassword) {
            showToast(_tUsers('users.modals_forms_passwords_do_not_match_please_re_enter', 'Passwords do not match. Please re-enter.'));
            if (confirmInput) confirmInput.focus();
            return;
          }

        }

      }

      // 2. Validation for Edit Mode (when changing password and not in username change lockdown)
      if (editingUserId && password && !isUsernameChanging) {
        // Length check
        if (password.length < 6) {
          showToast(_tUsers('users.modals_forms_password_must_be_at_least_6_characters', 'Password must be at least 6 characters'));
          if (passInput) passInput.focus();
          return;
        }

        // If password is masked/hidden, confirmation is required and must match
        if (!isPassVisible) {
          if (!confirmPassword) {
            showToast(_tUsers('users.modals_forms_please_re_enter_password_to_confirm', 'Please re-enter password to confirm'));
            if (confirmInput) confirmInput.focus();
            return;
          }

          if (password !== confirmPassword) {
            showToast(_tUsers('users.modals_forms_passwords_do_not_match_please_re_enter', 'Passwords do not match. Please re-enter.'));
            if (confirmInput) confirmInput.focus();
            return;
          }

        }

        // Self-editing requires current password unless in recovery session
        if (isSelf && !isRecoverySession && !currentPassword) {
          showToast(_tUsers('users.modals_forms_current_password_is_required_to_change', 'Current password is required to change your password'));
          const curPassElem = document.getElementById('user-current-password');
          if (curPassElem) curPassElem.focus();
          return;
        }

        // Editing other user requires reason
        if (!isSelf && !reason) {
          showToast(_tUsers('users.modals_forms_please_provide_a_reason_for_password', 'Please provide a reason for password change'));
          const reasonElem = document.getElementById('user-reason');
          if (reasonElem) reasonElem.focus();
          return;
        }

      }

      // Check for duplicates
      const allOtherUsers = getUsers().filter(u => u.__backendId !== editingUserId);

      const duplicateUsername = allOtherUsers.find(u => u.username.toLowerCase() === username.toLowerCase());
      if (duplicateUsername) {
        showToast(_tUsers('users.modals_forms_username_already_exists', 'Username already exists'));
        return;
      }

      const emailValue = document.getElementById('user-email').value.trim();
      if (emailValue) {
        const duplicateEmail = allOtherUsers.find(u => u.email && u.email.toLowerCase() === emailValue.toLowerCase());
        if (duplicateEmail) {
          showToast(_tUsers('users.modals_forms_email_already_in_use', 'Email already in use'));
          return;
        }

      }

      const phoneValue = document.getElementById('user-phone').value.trim();
      if (phoneValue) {
        if (!/^[0-9+\-\s()]+$/.test(phoneValue)) {
          showToast(_tUsers('users.modals_forms_phone_number_can_only_contain_digits', 'Phone number can only contain digits, plus sign, hyphens, and spaces'));
          document.getElementById('user-phone')?.focus();
          return;
        }

        const duplicatePhone = allOtherUsers.find(u => u.phone && u.phone === phoneValue);
        if (duplicatePhone) {
          showToast(_tUsers('users.modals_forms_phone_number_already_in_use', 'Phone number already in use'));
          return;
        }

      }

      if (btn) {
        btn.disabled = true;
        btn.textContent = _tUsers('common.saving', 'Saving...');
      }

      const userData = {
        type: 'user',
        username: username,
        email: document.getElementById('user-email').value || '',
        phone: document.getElementById('user-phone').value || '',
        profile_picture: document.getElementById('user-current-picture').value || null,
        profile_picture_name: document.getElementById('user-current-picture-name').value || null,
        is_admin: document.getElementById('user-is-admin') ? document.getElementById('user-is-admin').checked : (editingUserId ? findItem(editingUserId, 'user').isAdmin : false)
      };

      // Authoritative profile picture from Image Studio Crop / existing state
      const profilePictureData = document.getElementById('user-current-picture').value || null;

      try {
        const currentUserId = currentUser?.__backendId;

        let apiResult = null;
        if (editingUserId) {
          const existingUser = findItem(editingUserId, 'user');
          let payload;

          if (isUsernameChanging) {
            // Strict Lockdown Payload: Only username, confirmation password, and audit metadata
            payload = {
              username: username,
              confirmation_password: password,
              edited_by: currentUserId,
              reason: reason || (isSelf ? _tUsers('users.history_ledgers_username_changed_by_account_owner', 'Username changed by account owner') : _tUsers('users.history_ledgers_username_changed_by_super_admin', 'Username changed by Super Admin')),
              uid: existingUser?.uid
            }
;
          }
 else {
            payload = {
              username: userData.username,
              email: userData.email || null,
              phone: userData.phone || null,
              department: document.getElementById('user-department')?.value || 'crypto_cash',
              is_admin: userData.is_admin,
              profile_picture: profilePictureData || null,
              profile_picture_name: userData.profile_picture_name || null,
              edited_by: currentUserId,
              reason: reason,
              uid: existingUser?.uid
            }
;

            if (password) {
              payload.password = password;
            }

            if (currentPassword) {
              payload.current_password = currentPassword;
            }

          }


          apiResult = await apiRequest(`/api/users/${editingUserId}`, {
            method: 'PUT',
            body: JSON.stringify(payload)
          }
);

          if (!isUsernameChanging) {
            const injectionContainer = document.getElementById('user-capital-injection-fields');
            const isUnlocked = injectionContainer && !injectionContainer.classList.contains('hidden');
            const depAmt = document.getElementById('user-deposit-amount')?.value.trim();
            const depNote = document.getElementById('user-deposit-note')?.value.trim() || _tUsers('users.history_ledgers_capital_injection_on_profile_update', 'Capital injection on profile update');
            if (isUnlocked && depAmt && isNumeric(depAmt) && exactCompare(depAmt, '0') > 0) {
              await apiRequest('/api/cash-vault/transaction', {
                method: 'POST',
                body: JSON.stringify({
                  type: 'deposit',
                  amount: depAmt,
                  note: depNote,
                  user_id: editingUserId
                }
)
              }
).catch(err => console.warn('Deposit error:', err));
            }

          }

        }
 else {
          await apiRequest('/api/users', {
            method: 'POST',
            body: JSON.stringify({
              username: userData.username,
              uid: generateUserUID(),
              email: userData.email || null,
              phone: userData.phone || null,
              department: document.getElementById('user-department')?.value || 'crypto_cash',
              starting_cash: toExactDecimalString(document.getElementById('user-starting-cash')?.value || '0'),
              password: password,
              is_admin: userData.is_admin,
              profile_picture: profilePictureData || null,
              profile_picture_name: userData.profile_picture_name || null,
              created_by: currentUserId
            }
)
          }
);
        }


        let wasRecoveryReset = false;
        if (editingUserId && password && !isUsernameChanging && isSelf && sessionStorage.getItem('pos_can_set_password_once') === '1') {
          sessionStorage.removeItem('pos_can_set_password_once');
          sessionStorage.removeItem('pos_recovery_session');
          sessionStorage.removeItem('pos_recovery_type');
          const banner = document.getElementById('user-recovery-mode-banner');
          if (banner) banner.classList.add('hidden');
          wasRecoveryReset = true;
        }


        if (isUsernameChanging) {
          const finalU = (apiResult && apiResult.username) ? apiResult.username : username;
          if (isSelf && currentUser) {
            currentUser.username = finalU;
            try { sessionStorage.setItem('pos_current_user', JSON.stringify(currentUser)); } catch (e) {}
            updateCurrentUserDisplay();
            updateSidebarAvatar();
          }

          const uInput = document.getElementById('user-username');
          if (uInput) uInput.dataset.originalUsername = finalU;
          setUserModalLockdownMode(false);
        }


        closeUserModal();
        await loadAllData();
        updateUsersGrid(); // Refresh the users grid
        updateSidebarAvatar(); // Update sidebar avatar after user changes
        showToast(
          wasRecoveryReset 
            ? _tUsers('users.modals_forms_new_password_saved_successfully_one', 'New password saved successfully! One-time recovery grant consumed.') 
            : (isUsernameChanging ? _tUsers('users.modals_forms_username_updated_successfully', 'Username updated successfully!') : (editingUserId ? _tUsers('users.modals_forms_user_edited_successfully', 'User edited successfully!') : _tUsers('users.modals_forms_user_created_successfully', 'User created successfully!')))
        );
      } catch (e) {
        showToast(e.message || _tUsers('users.modals_forms_failed_to_save_user', 'Failed to save user'));
      }

      if (btn) {
        btn.disabled = false;
        btn.textContent = defaultBtnText;
      }
    }

    let pendingDeleteUserId = null;

    let deletionTimer = null;
    let pendingDeletionId = null;
    let pendingDeletionPayload = null;

    let _onlineWarningTargetUserId = null;

    function closeOnlineUserWarning() {
      _onlineWarningTargetUserId = null;
      const modal = document.getElementById('online-user-warning-modal');
      if (modal) {
        if (typeof ModalManager !== 'undefined' && typeof ModalManager.resetZIndex === 'function') {
          ModalManager.resetZIndex(modal);
        }
        modal.classList.add('hidden');
      }
    }

    function proceedOnlineUserDelete() {
      const targetId = _onlineWarningTargetUserId;
      closeOnlineUserWarning();
      if (targetId && typeof showDeleteUserModal === 'function') {
        showDeleteUserModal(targetId, true);
      }
    }

    function showDeleteUserModal(id, bypassOnlineCheck = false) {
      const user = findItem(id, 'user') || usersCache.find(u => String(u.__backendId || u.id) === String(id));
      if (!user) {
        showToast(_tUsers('users.modals_forms_user_account_not_found', 'User account not found'));
        return;
      }

      const currentUserId = currentUser ? String(currentUser.id || currentUser.__backendId) : null;
      if (String(id) === currentUserId || String(user.id) === currentUserId || String(user.__backendId) === currentUserId) {
        showToast(_tUsers('users.modals_forms_you_cannot_delete_your_own_account', 'You cannot delete your own account'));
        return;
      }

      if ((user.isAdmin || user.username === 'admin') && !(currentUser && (currentUser.isSuperAdmin || String(currentUser.__backendId || currentUser.id) === '1'))) {
        showToast(_tUsers('users.modals_forms_cannot_delete_admin_user', 'Cannot delete admin user'));
        return;
      }

      if (!bypassOnlineCheck) {
        let isOnline = false;
        if (user.last_active_at) {
          const dateStr = String(user.last_active_at).replace(' ', 'T');
          const lastActive = new Date(dateStr).getTime();
          if (!isNaN(lastActive) && (Date.now() - lastActive < 5 * 60 * 1000)) {
            isOnline = true;
          }

        }

        if (isOnline) {
          _onlineWarningTargetUserId = id;
          const warningModal = document.getElementById('online-user-warning-modal');
          if (warningModal) {
            if (typeof ModalManager !== 'undefined' && typeof ModalManager.bringToFront === 'function') {
              ModalManager.bringToFront(warningModal);
            }
            warningModal.classList.remove('hidden');
            return;
          }

        }

      }

      pendingDeleteUserId = String(user.__backendId || user.id || id);

      const nameEl = document.getElementById('delete-user-name');
      if (nameEl) nameEl.textContent = user.username || _tUsers('users.main_views_unknown', 'Unknown');

      const avatarCharEl = document.getElementById('delete-user-avatar-char');
      if (avatarCharEl) avatarCharEl.textContent = (user.username || 'U')[0].toUpperCase();

      const roleBadgeEl = document.getElementById('delete-user-role-badge');
      if (roleBadgeEl) {
        const isSuper = user.isSuperAdmin || String(user.id) === '1' || user.username === 'admin';
        roleBadgeEl.textContent = isSuper ? _tUsers('users.history_ledgers_super_admin', 'Super Admin') : (user.isAdmin ? _tUsers('users.status_pills_admin', 'Admin') : _tUsers('users.status_pills_staff', 'Staff'));
        roleBadgeEl.className = isSuper
          ? 'px-2 py-0.5 rounded-full text-[10px] font-black uppercase tracking-wider bg-rose-500/10 text-rose-600 dark:text-rose-400 border border-rose-500/20'
          : (user.isAdmin
              ? 'px-2 py-0.5 rounded-full text-[10px] font-black uppercase tracking-wider bg-blue-500/10 text-blue-600 dark:text-blue-400 border border-blue-500/20'
              : 'px-2 py-0.5 rounded-full text-[10px] font-black uppercase tracking-wider bg-slate-200/70 dark:bg-white/[0.08] text-slate-700 dark:text-slate-300 border border-slate-300/40 dark:border-white/[0.08]');
      }

      const emailEl = document.getElementById('delete-user-email');
      if (emailEl) emailEl.textContent = user.email || _tUsers('users.modals_forms_no_email_configured', 'No email configured');

      const createdDt = parseMySQLDate(user.created_at || user.createdAt);
      const createdEl = document.getElementById('delete-user-created');
      if (createdEl) createdEl.textContent = createdDt ? createdDt.toLocaleDateString() : _tUsers('users.main_views_unknown', 'Unknown');

      // Check online status with cross-browser date parsing
      const statusBadgeEl = document.getElementById('delete-user-status-badge');
      if (statusBadgeEl) {
        let isOnline = false;
        if (user.last_active_at) {
          const dateStr = String(user.last_active_at).replace(' ', 'T');
          const lastActive = new Date(dateStr).getTime();
          if (!isNaN(lastActive) && (Date.now() - lastActive < 5 * 60 * 1000)) {
            isOnline = true;
          }

        }

        if (isOnline) {
          statusBadgeEl.innerHTML = `<span class="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span><span>` + _tUsers('users.main_views_online_now', 'Online Now') + `</span>`;
          statusBadgeEl.className = 'inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[11px] font-bold bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 border border-emerald-500/25';
        }
 else {
          statusBadgeEl.innerHTML = `<span class="w-2 h-2 rounded-full bg-slate-400"></span><span>` + _tUsers('users.status_pills_inactive', 'Inactive') + `</span>`;
          statusBadgeEl.className = 'inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[11px] font-bold bg-slate-100 dark:bg-white/[0.05] text-slate-600 dark:text-slate-400 border border-slate-200 dark:border-white/[0.08]';
        }

      }

      // Reset Reason and Errors
      const reasonEl = document.getElementById('delete-user-reason');
      if (reasonEl) {
        reasonEl.value = '';
        reasonEl.classList.remove('border-rose-500', 'ring-2', 'ring-rose-500/20');
        reasonEl.oninput = () => {
          const err = document.getElementById('delete-user-reason-error');
          if (err) err.classList.add('hidden');
          reasonEl.classList.remove('border-rose-500', 'ring-2', 'ring-rose-500/20');
        }
;
      }
      const reasonErrorEl = document.getElementById('delete-user-reason-error');
      if (reasonErrorEl) reasonErrorEl.classList.add('hidden');

      // Reset Dependencies Card
      const depWarningEl = document.getElementById('delete-user-dependencies-warning');
      const depListEl = document.getElementById('delete-user-dependencies-list');
      if (depWarningEl) depWarningEl.classList.add('hidden');
      if (depListEl) depListEl.innerHTML = '';

      // Reset Button State
      const btn = document.getElementById('confirm-delete-user-btn');
      if (btn) {
        btn.disabled = false;
        const btnText = document.getElementById('confirm-delete-user-btn-text');
        if (btnText) btnText.textContent = _tUsers('users.main_views_deactivate_account', 'Deactivate Account');
      }

      // Show Modal
      const modalEl = document.getElementById('delete-user-modal');
      if (modalEl) {
        if (typeof ModalManager !== 'undefined' && typeof ModalManager.bringToFront === 'function') {
          ModalManager.bringToFront(modalEl);
        }
        modalEl.classList.remove('hidden');
      }

      setTimeout(() => {
        if (reasonEl) reasonEl.focus();
      }, 100);

      // Fetch user dependencies asynchronously
      const backendId = user.__backendId || user.id || id;
      apiRequest(`/api/users/${backendId}/dependencies`).then(res => {
        if (!res || !res.ok) return;
        if (res.has_dependencies && depWarningEl && depListEl) {
          const d = res.dependencies;
          let items = [];
          if (d.stock_batches > 0) {
            items.push(`<li>📦 <strong>${d.stock_batches}</strong> ${_tUsers('users.modals_forms_active_inventory_batches', 'active inventory batches')} (${formatNumber(d.stock_qty)} units, ~${formatPrice(d.stock_value)})</li>`);
          }

          if (d.consignment_orders > 0) {
            items.push(`<li>🤝 <strong>${d.consignment_orders}</strong> ${_tUsers('users.main_views_active_consignment_orders_in_progress', 'active consignment orders in progress')}</li>`);
          }

          if (d.open_orders > 0) {
            items.push(`<li>🛒 <strong>${d.open_orders}</strong> ${_tUsers('users.print_tickets_open_in_progress_orders_or_service', 'open/in-progress orders or service tickets')}</li>`);
          }

          if (d.pending_settlements > 0) {
            let settleStr = `<li>⚖️ <strong>${d.pending_settlements}</strong> ${_tUsers('users.main_views_pending_settlements', 'pending settlements')}`;
            let parts = [];
            if (d.owed_to_user > 0) parts.push(`${_tUsers('users.modals_forms_receivable', 'Receivable:')} ${formatPrice(d.owed_to_user)}`);
            if (d.owed_by_user > 0) parts.push(`${_tUsers('users.modals_forms_payable', 'Payable:')} ${formatPrice(d.owed_by_user)}`);
            if (parts.length) settleStr += ` (${parts.join(', ')})`;
            settleStr += `</li>`;
            items.push(settleStr);
          }

          if (items.length) {
            depListEl.innerHTML = `<ul class="list-disc list-inside space-y-1">${items.join('')}</ul>`;
            depWarningEl.classList.remove('hidden');
          }

        }

      }).catch(err => {
        console.warn('Failed to load user dependencies:', err);
      });
    }

