    async function confirmDeleteUser() {
      if (!pendingDeleteUserId) return;

      const user = findItem(pendingDeleteUserId, 'user') || usersCache.find(u => String(u.__backendId || u.id) === String(pendingDeleteUserId));
      if (!user) {
        showToast(_tUsers('users.modals_forms_user_account_not_found', 'User account not found'));
        return;
      }

      const reasonEl = document.getElementById('delete-user-reason');
      const reasonErrorEl = document.getElementById('delete-user-reason-error');
      const reason = reasonEl ? reasonEl.value.trim() : '';

      if (!reason) {
        if (reasonErrorEl) reasonErrorEl.classList.remove('hidden');
        if (reasonEl) {
          reasonEl.classList.add('border-rose-500', 'ring-2', 'ring-rose-500/20');
          reasonEl.focus();
        }

        showToast(_tUsers('users.modals_forms_please_provide_a_reason_for_deactivation', 'Please provide a reason for deactivation'));
        return;
      }

      const btn = document.getElementById('confirm-delete-user-btn');
      const btnText = document.getElementById('confirm-delete-user-btn-text');
      if (btn) btn.disabled = true;
      if (btnText) btnText.textContent = _tUsers('users.main_views_deactivating', 'Deactivating...');

      try {
        const payload = {
          reason: reason,
          deleted_by: currentUser?.__backendId || currentUser?.id
        }
;

        const targetId = user.__backendId || user.id || pendingDeleteUserId;
        await apiRequest(`/api/users/${targetId}`, {
          method: 'DELETE',
          body: JSON.stringify(payload)
        }
);

        showToast(_tUsers('users.modals_forms_user_account_deactivated_successfully', 'User account deactivated successfully'));
        closeDeleteUserModal();
        await loadUsers();
        updateUsersGrid();
      } catch (e) {
        showToast(e.message || _tUsers('users.modals_forms_failed_to_deactivate_user', 'Failed to deactivate user'));
      } finally {
        if (btn) btn.disabled = false;
        if (btnText) btnText.textContent = _tUsers('users.main_views_deactivate_account', 'Deactivate Account');
      }
    }

    function startDeletionCountdown(id, payload) {
      if (deletionTimer) return;
      pendingDeletionId = id;
      pendingDeletionPayload = payload;
      const overlay = document.getElementById('deletion-pending-overlay');
      const text = document.getElementById('delete-countdown-text');
      const secondsTxt = document.getElementById('delete-timer-seconds');
      const circle = document.getElementById('delete-countdown-circle');

      overlay.classList.remove('hidden');
      let seconds = 60;
      text.textContent = seconds;
      secondsTxt.textContent = seconds;

      // Smooth animation for the circle
      circle.style.transition = 'none';
      circle.style.strokeDashoffset = '0';

      setTimeout(() => {
        circle.style.transition = 'stroke-dashoffset 60s linear';
        circle.style.strokeDashoffset = '113';
      }, 50);

      deletionTimer = setInterval(async () => {
        seconds--;
        text.textContent = seconds;
        secondsTxt.textContent = seconds;

        if (seconds <= 0) {
          clearInterval(deletionTimer);
          overlay.classList.add('hidden');
          await executeDeletion(pendingDeletionId, pendingDeletionPayload);
        }

      }, 1000);
    }

    async function undoDeletion() {
      if (deletionTimer) {
        clearInterval(deletionTimer);
        const canceledId = pendingDeletionId;
        deletionTimer = null;
        pendingDeletionId = null;
        pendingDeletionPayload = null;
        document.getElementById('deletion-pending-overlay').classList.add('hidden');
        showToast(_tUsers('users.modals_forms_deletion_canceled', 'Deletion canceled'));

        // Remove marker from server
        try {
          await apiRequest(`/api/users/${canceledId}/cancel-pending-deletion`, { method: 'POST' });
        }
 catch (e) {
          console.error('Failed to cancel pending deletion on server', e);
        }

      }
    }

    async function executeDeletion(id, payload) {
      if (!id) {
        showToast(_tUsers('users.modals_forms_error_deletion_id_is_missing_please_try', 'Error: Deletion ID is missing. Please try again.'));
        return;
      }
      try {
        console.log('Finalizing deletion for User ID:', id);
        await apiRequest(`/api/users/${id}`, {
          method: 'DELETE',
          body: JSON.stringify(payload)
        }
);
        showToast(_tUsers('users.modals_forms_user_deleted_successfully', 'User deleted successfully'));
        await loadAllData();
        updateUsersGrid();
      } catch (e) {
        showToast(_tUsers('users.modals_forms_failed_to_delete_user', 'Failed to delete user: ') + e.message);
      } finally {
        // CLEANUP STATE NO MATTER WHAT
        if (deletionTimer) clearInterval(deletionTimer);
        deletionTimer = null;
        pendingDeletionId = null;
        pendingDeletionPayload = null;
        document.getElementById('deletion-pending-overlay').classList.add('hidden');
      }
    }

