    async function confirmRestoreCustomer(e) {
      if (e) e.preventDefault();
      if (!pendingRestoreCustomerId) return;

      const customer = findItem(pendingRestoreCustomerId, 'customer');
      if (!customer) return;

      const restoreReason = (document.getElementById('restore-customer-reason').value || '').trim();
      if (!restoreReason) {
        showToast(window.__t ? window.__t('customers.modals_forms_please_provide_a_restore_reason', 'Please provide a restore reason') : 'Please provide a restore reason');
        return;
      }

      const btn = document.getElementById('confirm-restore-customer-btn');
      btn.disabled = true;
      btn.textContent = window.__t ? window.__t('customers.modals_forms_restoring', 'Restoring...') : 'Restoring...';

      try {
        await apiRequest(`/api/customers/${customer.__backendId}/restore`, {
          method: 'POST',
          body: JSON.stringify({ restore_reason: restoreReason })
        }
);
        const restoredMsg = window.__t
          ? window.__t('customers.modals_forms_customer_restored_successfully', 'Customer "{name}" restored successfully!', { name: customer.name })
          : `Customer "${customer.name}" restored successfully!`;
        showToast(restoredMsg);
        closeRestoreCustomerModal();
        await loadCustomers();
      } catch (err) {
        showToast(err.message || (window.__t ? window.__t('customers.modals_forms_failed_to_restore_customer', 'Failed to restore customer') : 'Failed to restore customer'));
      }

      btn.disabled = false;
      btn.textContent = window.__t ? window.__t('customers.main_views_confirm_restore', 'Confirm Restore') : 'Confirm Restore';
    }

