    // ───────────────────────── Suppliers (buying side / payables) ─────────────────────────
    function getSuppliers() {
      return suppliersCache;
    }

    function loadSuppliers() {
      apiRequest('/api/suppliers?show_deleted=' + showDeletedSuppliers)
        .then(res => {
          suppliersCache = (res.suppliers || []).map(normalizeSupplier);
          filterSuppliers();
          try { updateDashboard(); } catch (e) { }
        }
)
        .catch(() => showToast(_t('suppliers.modals_forms_failed_to_load_suppliers', 'Failed to load suppliers')));
    }

    function toggleShowDeletedSuppliers() {
      showDeletedSuppliers = !showDeletedSuppliers;
      loadSuppliers();
    }

    // Money we still owe a supplier = Σ (total − amount_paid) over their
    // non-deleted, not-fully-paid purchases. (purchases gain supplier_id +
    // payment fields in phase C2; until then this evaluates to 0.)
    function getSupplierOwed(supplierId) {
      let owed = '0';
      getPurchases().forEach(function (p) {
        if (String(p.supplierId) !== String(supplierId)) return;
        if (p.deletedAt) return;
        if ((p.paymentStatus || 'paid') === 'paid') return;
        const due = Decimal.sub(p.total || '0', p.amountPaid || '0');
        if (Decimal.comp(due, '0') > 0) owed = Decimal.add(owed, due);
      });
      return owed;
    }

    function updateSuppliersGrid() {
      const userFilter = document.getElementById('suppliers-user-filter');
      if (userFilter) {
        const users = getUsers();
        const currentUserFilter = userFilter.value;
        const myUid = (typeof currentUser !== 'undefined' && currentUser) ? String(currentUser.__backendId || currentUser.id || '') : '';
        const visibleUsers = users.filter(u => {
          if (u.deleted_at || u.deletedAt) return false;
          const isSelf = (myUid && String(u.__backendId || u.id) === myUid) || (currentUser && u.username === currentUser.username);
          if (!isSelf && isUserFilterHidden(u, 'purchases')) return false;
          return true;
        }
);
        userFilter.innerHTML = `<option value="all" data-i18n="suppliers.modals_forms_all_users_2">${escapeHtml(_t('suppliers.modals_forms_all_users_2', 'All Users'))}</option>` +
          visibleUsers.map(u => `<option value="${escapeHtml(u.username)}">${escapeHtml(u.username)}</option>`).join('');
        if (currentUserFilter && currentUserFilter !== 'all' && visibleUsers.some(u => u.username === currentUserFilter)) {
          userFilter.value = currentUserFilter;
        }
 else {
          userFilter.value = 'all';
        }

      }
      filterSuppliers();
    }


