    function toggleResumeDateInput(mode) {
      const cardMaintain = document.getElementById('resume-card-maintain');
      const cardRecent = document.getElementById('resume-card-recent');
      const cardManual = document.getElementById('resume-card-manual');

      const recentContainer = document.getElementById('resume-recent-bills-container');
      const manualContainer = document.getElementById('resume-manual-date-container');

      const setCardActive = (card, isActive) => {
        if (!card) return;
        if (isActive) {
          card.classList.add('border-2', 'border-emerald-500/80', 'bg-emerald-500/5', 'dark:bg-emerald-500/10', 'shadow-sm');
          card.classList.remove('border-slate-200', 'dark:border-slate-800', 'bg-slate-50/50', 'dark:bg-slate-900/50');
        }
 else {
          card.classList.remove('border-2', 'border-emerald-500/80', 'bg-emerald-500/5', 'dark:bg-emerald-500/10', 'shadow-sm');
          card.classList.add('border-slate-200', 'dark:border-slate-800', 'bg-slate-50/50', 'dark:bg-slate-900/50');
        }

      };

      if (mode === 'recent') {
        setCardActive(cardMaintain, false);
        setCardActive(cardRecent, true);
        setCardActive(cardManual, false);
        if (recentContainer) recentContainer.classList.remove('hidden');
        if (manualContainer) manualContainer.classList.add('hidden');
      } else if (mode === 'manual' || mode === 'new') {
        setCardActive(cardMaintain, false);
        setCardActive(cardRecent, false);
        setCardActive(cardManual, true);
        if (recentContainer) recentContainer.classList.add('hidden');
        if (manualContainer) manualContainer.classList.remove('hidden');
      } else {
        // maintain
        setCardActive(cardMaintain, true);
        setCardActive(cardRecent, false);
        setCardActive(cardManual, false);
        if (recentContainer) recentContainer.classList.add('hidden');
        if (manualContainer) manualContainer.classList.add('hidden');
      }
    }
