    async function submitResumeBill(e) {
      e.preventDefault();
      const id = document.getElementById('resume-bill-id')?.value;
      if (!id) return;

      const maintainRadio = document.getElementById('resume-mode-maintain');
      const recentRadio = document.getElementById('resume-mode-recent');
      const manualRadio = document.getElementById('resume-mode-manual');

      let payload = {
        resume_mode: 'maintain_anchor',
        new_anchor_date: null
      };

      if (recentRadio && recentRadio.checked) {
        const selectedRecent = document.querySelector('input[name="resume_recent_cycle_id"]:checked');
        if (!selectedRecent) {
          showToast(_t('bills.modals_forms_please_select_a_period_bill_from_the', 'Please select a period bill from the list.'), 'default');
          return;
        }

        const billDate = selectedRecent.getAttribute('data-date');
        const cycleId = selectedRecent.value;
        if (!billDate) {
          showToast(_t('bills.modals_forms_the_selected_period_bill_does_not_have', 'The selected period bill does not have a valid date.'), 'default');
          return;
        }

        payload = {
          resume_mode: 'new_anchor',
          resume_submode: 'recent_bill',
          new_anchor_date: billDate,
          source_cycle_id: cycleId
        }
;
      } else if (manualRadio && manualRadio.checked) {
        const manualDate = document.getElementById('resume-manual-anchor-date')?.value || document.getElementById('resume-new-anchor-date')?.value;
        if (!manualDate) {
          showToast(_t('bills.modals_forms_please_select_a_valid_start_date_for', 'Please select a valid start date for resuming this circle.'), 'default');
          return;
        }

        payload = {
          resume_mode: 'new_anchor',
          resume_submode: 'manual_date',
          new_anchor_date: manualDate
        }
;
      } else {
        // maintain_anchor
        payload = {
          resume_mode: 'maintain_anchor',
          new_anchor_date: null
        }
;
      }

      const btn = document.getElementById('btn-submit-resume-bill');
      if (btn) { btn.disabled = true; btn.textContent = 'Resuming...'; }

      try {
        await apiRequest(`/api/recurring-bills/${id}/resume`, {
          method: 'POST',
          body: JSON.stringify(payload)
        }
);
        showToast(_t('bills.modals_forms_recurring_circle_resumed_successfully', 'Recurring circle resumed successfully!'), 'default');
        closeResumeBillModal();
        await loadExpensesData();
      } catch (err) {
        showToast(err.message || _t('bills.modals_forms_failed_to_resume_recurring_circle', 'Failed to resume recurring circle'), 'default');
      } finally {
        if (btn) { btn.disabled = false; btn.textContent = '▶️ Resume Circle'; }
      }
    }
    window.submitResumeBill = submitResumeBill;

