    window.switchExpensesTab = switchExpensesTab;

    function applyExpensesDatePreset(preset) {
      expensesDatePreset = preset || 'all_time';
      const select = document.getElementById('expenses-date-preset-select');
      if (select && select.value !== expensesDatePreset) select.value = expensesDatePreset;

      const customInputs = document.getElementById('expenses-custom-date-inputs');
      const fromEl = document.getElementById('expenses-date-from');
      const toEl = document.getElementById('expenses-date-to');

      if (expensesDatePreset === 'custom') {
        if (customInputs) customInputs.classList.remove('hidden');
        return;
      } else {
        if (customInputs) customInputs.classList.add('hidden');
      }

      const now = new Date();
      const formatYMD = (d) => {
        const year = d.getFullYear();
        const month = String(d.getMonth() + 1).padStart(2, '0');
        const day = String(d.getDate()).padStart(2, '0');
        return `${year}-${month}-${day}`;
      };

      let fromDate = '';
      let toDate = '';

      if (expensesDatePreset === 'today') {
        fromDate = formatYMD(now);
        toDate = formatYMD(now);
      } else if (expensesDatePreset === 'yesterday') {
        const yest = new Date(now);
        yest.setDate(yest.getDate() - 1);
        fromDate = formatYMD(yest);
        toDate = formatYMD(yest);
      } else if (expensesDatePreset === 'this_week') {
        const d = new Date(now);
        const day = d.getDay();
        const diff = d.getDate() - day + (day === 0 ? -6 : 1);
        const monday = new Date(d.setDate(diff));
        fromDate = formatYMD(monday);
        toDate = formatYMD(now);
      } else if (expensesDatePreset === 'this_month') {
        const firstDay = new Date(now.getFullYear(), now.getMonth(), 1);
        fromDate = formatYMD(firstDay);
        toDate = formatYMD(now);
      } else if (expensesDatePreset === 'last_month') {
        const firstDay = new Date(now.getFullYear(), now.getMonth() - 1, 1);
        const lastDay = new Date(now.getFullYear(), now.getMonth(), 0);
        fromDate = formatYMD(firstDay);
        toDate = formatYMD(lastDay);
      } else if (expensesDatePreset === 'this_year') {
        const firstDay = new Date(now.getFullYear(), 0, 1);
        fromDate = formatYMD(firstDay);
        toDate = formatYMD(now);
      } else {
        // all_time
        fromDate = '';
        toDate = '';
      }

      if (fromEl) fromEl.value = fromDate;
      if (toEl) toEl.value = toDate;

      filterExpensesView();
    }
    window.applyExpensesDatePreset = applyExpensesDatePreset;

