      const rawSrcMeta = typeof getSettlementSourceMeta === 'function' ? getSettlementSourceMeta(primary) : {};

      const primaryUid = primary.uid ? (primary.uid.startsWith('#') ? primary.uid : '#' + primary.uid) : ('#STL-' + (primary.id || ''));

