        const displayUid = s.ticket_numbers ? s.ticket_numbers : ('#' + (billUidStr || expUidStr || (isPurchaseSettlement && purchaseUid ? purchaseUid : (s.uid ? (s.uid.startsWith('#') ? s.uid.substring(1) : s.uid) : ('SET-' + s.id)))));

