    // ── Cancel Bill Revision Modal (Obsidian Liquid Glass) ──
    let pendingCancelRevisionBillId = null;
    let pendingCancelRevisionOrigin = 'info';

    function showCancelBillRevisionModal(billId, origin = 'info') {
      pendingCancelRevisionBillId = billId;
      pendingCancelRevisionOrigin = origin;
      document.getElementById('cancel-bill-revision-modal')?.classList.remove('hidden');
    }
    window.showCancelBillRevisionModal = showCancelBillRevisionModal;

    function closeCancelBillRevisionModal() {
      document.getElementById('cancel-bill-revision-modal')?.classList.add('hidden');
      pendingCancelRevisionBillId = null;
    }
    window.closeCancelBillRevisionModal = closeCancelBillRevisionModal;

    async function executeCancelBillRevision() {
      if (!pendingCancelRevisionBillId) return;
      const bId = pendingCancelRevisionBillId;
      const origin = pendingCancelRevisionOrigin;
      const btn = document.getElementById('confirm-cancel-revision-btn');
      if (btn) { btn.disabled = true; btn.textContent = 'Discarding...'; }

      try {
        const res = await apiRequest(`/api/recurring-bills/${bId}/cancel-edit`, {
          method: 'POST',
          body: JSON.stringify({})
        }
);
        if (!res || !res.ok) throw new Error(res?.error || 'Failed to cancel revision');
        showToast(res.message || _t('purchases.toast_revision_cancelled_and_previous_ver', 'Revision cancelled and previous version restored'), 'default');
        closeCancelBillRevisionModal();
        if (origin === 'form') {
          closeBillModal();
        }
 else if (origin === 'archived') {
          closeArchivedBillModal();
        }
 else if (origin === 'circle') {
          closeCircleModal();
        }
 else {
          closeBillInfoModal();
        }

        await loadAllData();
        if (typeof loadSettlementHubData === 'function') loadSettlementHubData();
      } catch (err) {
        showToast(err.message || _t('bills.history_ledgers_failed_to_cancel', 'Failed to cancel revision'), 'default');
      } finally {
        if (btn) { btn.disabled = false; btn.textContent = 'Discard Revision'; }
      }
    }
