    async function executeConfirmedClaimPayout() {
      if (!_pendingClaimAction) return;
      const { id, data } = _pendingClaimAction;
      const btn = document.getElementById('claim-payout-confirm-btn');
      const btnTextEl = document.getElementById('claim-payout-btn-text');
      if (btn) btn.disabled = true;
      if (btnTextEl) btnTextEl.textContent = _t('bills.modals_forms_claiming', 'Claiming...');

      try {
        const isUnified = !!(data?.isUnifiedConsignment && data?.siblingId);
        const siblingId = data?.siblingId;

        let totalClaimAmount = data?.amount || '0';
        let costClaim = '0';
        let profitClaim = '0';

        if (isUnified) {
          costClaim = data?.costClaimable !== undefined && data?.costClaimable !== null
            ? data.costClaimable
            : (data?.costAmount || '0');
          profitClaim = data?.profitClaimable !== undefined && data?.profitClaimable !== null
            ? data.profitClaimable
            : (data?.profitAmount || '0');
          totalClaimAmount = exactAdd(String(costClaim || '0'), String(profitClaim || '0'));
        }


        await apiRequest(`/api/partner-settlements/${id}/settle`, {
          method: 'POST',
          body: JSON.stringify({
            amount: totalClaimAmount,
            target_source: 'vault',
            settled_source: 'vault',
            source: 'vault',
            force_overdraft: true
          }
)
        }
);

        showToast(_t('bills.modals_forms_consignment_payout_claimed_successfully', 'Consignment payout claimed successfully.'), 'default');
        closeClaimPayoutModal();

        // Optimistic UI updates in settlementHubCache
        if (Array.isArray(settlementHubCache)) {
          const targetOrderId = data?.related_entity_id || (settlementHubCache.find(x => String(x.id) === String(id))?.related_entity_id);
          if (targetOrderId && (isUnified || data?.orderRef)) {
            settlementHubCache.forEach(sib => {
              const isSameOrder = (sib.related_entity_type === 'orders' || sib.related_entity_type === 'order') && String(sib.related_entity_id) === String(targetOrderId);
              if (isSameOrder) {
                const rel = (sib.release_status === 'released' ? String(sib.amount || '0') : String(sib.released_amount || '0'));
                if (exactCompare(rel, '0') > 0) {
                  sib.settled_amount = rel;
                  if (exactCompare(sib.settled_amount, sib.amount || '0') >= 0) {
                    sib.status = 'settled';
                  }

                  sib.settled_at = new Date().toISOString();
                  sib.settled_source = 'vault';
                }

              }

            }
);
          }
 else if (isUnified) {
            const costS = settlementHubCache.find(x => String(x.id) === String(id));
            if (costS) {
              if (costClaim) costS.settled_amount = exactAdd(costS.settled_amount || '0', String(costClaim));
              if (exactCompare(costS.settled_amount || '0', costS.amount || '0') >= 0) costS.status = 'settled';
              costS.settled_at = new Date().toISOString();
              costS.settled_source = 'vault';
            }

            const profitS = settlementHubCache.find(x => String(x.id) === String(siblingId));
            if (profitS) {
              if (profitClaim) profitS.settled_amount = exactAdd(profitS.settled_amount || '0', String(profitClaim));
              if (exactCompare(profitS.settled_amount || '0', profitS.amount || '0') >= 0) profitS.status = 'settled';
              profitS.settled_at = new Date().toISOString();
              profitS.settled_source = 'vault';
            }

          }
 else {
            const singleS = settlementHubCache.find(x => String(x.id) === String(id));
            if (singleS) {
              singleS.settled_amount = exactAdd(singleS.settled_amount || '0', String(totalClaimAmount));
              if (exactCompare(singleS.settled_amount || '0', singleS.amount || '0') >= 0) singleS.status = 'settled';
              singleS.settled_at = new Date().toISOString();
              singleS.settled_source = 'vault';
            }

          }

        }


        if (typeof updateSettlementFilterBadges === 'function') updateSettlementFilterBadges();
        if (typeof renderSettlementHub === 'function') renderSettlementHub();

        // Parallel background data refreshes
        if (typeof loadAllData === 'function') {
          await loadAllData();
        }
 else {
          if (typeof loadSettlementHubData === 'function') loadSettlementHubData(false);
          if (typeof updateDashboardVault === 'function') updateDashboardVault();
        }


        // Auto-refresh order details modal if currently open
        const orderModal = document.getElementById('order-details-modal');
        if (orderModal && !orderModal.classList.contains('hidden')) {
          const orderIdToRefresh = data?.related_entity_id || (typeof lastViewedOrder !== 'undefined' && lastViewedOrder ? (lastViewedOrder.__backendId || lastViewedOrder.id) : null);
          if (orderIdToRefresh && typeof showOrderDetails === 'function') {
            showOrderDetails(orderIdToRefresh);
          }

        }

      } catch (e) {
        showToast(e.message || _t('bills.modals_forms_failed_to_claim_payout', 'Failed to claim payout'), 'error');
      } finally {
        if (btn) btn.disabled = false;
        if (btnTextEl) btnTextEl.textContent = _t('bills.modals_forms_claim_to_cash_safe', '📥 Claim to Cash Safe');
      }
    }

    window.openClaimPayoutModal = openClaimPayoutModal;
    window.closeClaimPayoutModal = closeClaimPayoutModal;
    window.executeConfirmedClaimPayout = executeConfirmedClaimPayout;

