    window.openReviewShareModal = openReviewShareModal;

    function closeReviewShareModal() {
      const modal = document.getElementById('settlement-review-share-modal');
      if (modal) {
        if (typeof ModalManager !== 'undefined' && typeof ModalManager.resetZIndex === 'function') {
          ModalManager.resetZIndex(modal);
        }

        modal.classList.add('hidden');
      }
      currentReviewShareSettlementId = null;
      currentReviewShareExpenseId = null;
    }
    window.closeReviewShareModal = closeReviewShareModal;

    async function executeReviewShareAccept() {
      const currentUserId = String(currentUser?.__backendId || currentUser?.id || '');
      if (!currentReviewShareSettlementId) {
        if (currentReviewShareExpenseId) {
          const s = await resolveSettlementForExpense(currentReviewShareExpenseId);
          if (s) currentReviewShareSettlementId = s.id;
        }

      }
      if (currentReviewShareSettlementId && Array.isArray(settlementHubCache) && currentUserId) {
        const checkTarget = settlementHubCache.find(x => String(x.id) === String(currentReviewShareSettlementId));
        if (checkTarget && String(checkTarget.payer_user_id) !== currentUserId) {
          const s = await resolveSettlementForExpense(currentReviewShareExpenseId);
          if (s) {
            currentReviewShareSettlementId = s.id;
          }
 else {
            showToast(_t('bills.history_ledgers_forbidden_this_settlement_does_not', 'Forbidden: This settlement does not belong to your account.'), 'error');
            return;
          }

        }

      }
      if (!currentReviewShareSettlementId) {
        showToast(_t('bills.history_ledgers_cannot_identify_settlement_record_to', 'Cannot identify settlement record to accept.'), 'default');
        return;
      }
      const sid = currentReviewShareSettlementId;
      closeReviewShareModal();
      await acceptSettlement(sid);
    }
    window.executeReviewShareAccept = executeReviewShareAccept;

    function executeReviewShareRefuse() {
      const sid = currentReviewShareSettlementId;
      const s = settlementHubCache.find(x => String(x.id) === String(sid));
      if (s) {
        if (s.status === 'settled') {
          showToast(_t('bills.history_ledgers_cannot_refuse_you_have_already_paid_and', 'Cannot refuse: You have already paid and settled this share.'), 'warning');
          return;
        }

        const info = getSettlementAgreementInfo(s, settlementHubCache);
        const isAllAccepted = info?.allAccepted || s.expense_agreement_status === 'all_accepted' || s.bill_agreement_status === 'all_accepted' || s.cycle_agreement_status === 'all_accepted';
        if (isAllAccepted && !info?.hasRefusal) {
          showToast(_t('bills.history_ledgers_cannot_refuse_100_agreement_reached_the', 'Cannot refuse: 100% agreement reached. The payment phase is active and shares are locked.'), 'warning');
          return;
        }

      }
      closeReviewShareModal();
      if (sid) {
        openRefuseSettlementModal(sid);
      } else {
        showToast(_t('bills.history_ledgers_cannot_identify_settlement_record_to_2', 'Cannot identify settlement record to refuse.'), 'default');
      }
    }
    window.executeReviewShareRefuse = executeReviewShareRefuse;

