    async function openPayShareModalForExpense(expenseId, settlementId = null) {
      const s = await resolveSettlementForExpense(expenseId, settlementId);
      if (s) {
        settleSettlement(s.id);
      } else {
        showToast(_t('bills.table_grids_cannot_identify_settlement_to_pay', 'Cannot identify settlement to pay.'), 'default');
      }
    }
    window.openPayShareModalForExpense = openPayShareModalForExpense;

    async function resolveSettlementForArchivedBill(billId, settlementId = null) {
      const currentUserId = String(currentUser?.__backendId || currentUser?.id || '');
      if (settlementId && Array.isArray(settlementHubCache)) {
        const directMatch = settlementHubCache.find(x => String(x.id) === String(settlementId));
        if (directMatch) return directMatch;
      }
      
      const bId = String(billId || '');
      const bill = (Array.isArray(recurringBillsCache) ? recurringBillsCache : []).find(b => String(b.id) === bId);
      const cycleId = (bill && Array.isArray(bill.cycles) && bill.cycles.length > 0) ? String(bill.cycles[0].id) : null;

      const isMatch = (x) => {
        if (!x || x.status === 'cancelled' || x.cancelled_at || x.status === 'voided') return false;
        if (cycleId) {
          if (x.cycle_id && String(x.cycle_id) === cycleId) return true;
          if (x.related_entity_type === 'recurring_bill_cycle' && String(x.related_entity_id) === cycleId) return true;
        }

        if (String(x.bill_id) === bId) return true;
        if ((x.related_entity_type === 'recurring_bills' || x.related_entity_type === 'recurring_bill') && String(x.related_entity_id) === bId) return true;
        return false;
      };

      if (Array.isArray(settlementHubCache)) {
        if (currentUserId) {
          const cachedUserMatch = settlementHubCache.find(x => isMatch(x) && String(x.payer_user_id) === currentUserId);
          if (cachedUserMatch) return cachedUserMatch;
        }

        const cachedAnyMatch = settlementHubCache.find(isMatch);
        if (cachedAnyMatch) return cachedAnyMatch;
      }

      try {
        const url = bId ? `/api/partner-settlements?bill_id=${encodeURIComponent(bId)}` : '/api/partner-settlements';
        const res = await apiRequest(url);
        const fetchedSettlements = Array.isArray(res?.settlements) ? res.settlements : (Array.isArray(res?.data) ? res.data : (Array.isArray(res) ? res : []));
        if (Array.isArray(settlementHubCache)) {
          fetchedSettlements.forEach(fs => {
            const idx = settlementHubCache.findIndex(x => String(x.id) === String(fs.id));
            if (idx >= 0) settlementHubCache[idx] = fs;
            else settlementHubCache.push(fs);
          }
);
        }
 else {
          settlementHubCache = fetchedSettlements;
        }


        if (currentUserId) {
          const freshUserMatch = fetchedSettlements.find(x => isMatch(x) && String(x.payer_user_id) === currentUserId);
          if (freshUserMatch) return freshUserMatch;
        }


        const freshAnyMatch = fetchedSettlements.find(isMatch);
        if (freshAnyMatch) return freshAnyMatch;

        return null;
      } catch (e) {
        console.error('Failed to resolve settlement for archived bill:', e);
        return null;
      }
    }
    window.resolveSettlementForArchivedBill = resolveSettlementForArchivedBill;

    async function openSettlementPartnersModalForArchivedBill(billId, settlementId = null) {
      let s = await resolveSettlementForArchivedBill(billId, settlementId);
      if (!s && billId) {
        try {
          const res = await apiRequest(`/api/recurring-bills/${billId}/details`);
          if (res && res.settlements && res.settlements.length > 0) {
            if (Array.isArray(settlementHubCache)) {
              res.settlements.forEach(newS => {
                const idx = settlementHubCache.findIndex(x => String(x.id) === String(newS.id));
                if (idx >= 0) settlementHubCache[idx] = newS;
                else settlementHubCache.push(newS);
              }
);
            }

            s = res.settlements[0];
          }

        }
 catch (err) {
          console.error('Error fetching details for archived bill settlements:', err);
        }

      }
      if (s) {
        showSettlementPartnersModal(s.id);
      } else {
        showToast(_t('bills.table_grids_no_active_partner_settlements_found_for_2', 'No active partner settlements found for this archived bill.'), 'default');
      }
    }
