      const q = (searchEl?.value || '').toLowerCase().trim();
      const cat = catEl?.value || 'all';
      const fromDate = fromDateEl?.value || '';
      const toDate = toDateEl?.value || '';
      const srcFilter = srcEl?.value || 'all';
      const rcptFilter = rcptEl?.value || 'all';
      const partnerFilter = partnerEl?.value || 'all';
      const provFilter = (provEl?.value || 'all').toLowerCase();
      const bucketFilter = window.expensesAmountBucketFilter || 'all';

