    function handleCircleDueDayChange(val) {
      const dayNum = parseInt(val, 10);
      if (isNaN(dayNum) || dayNum < 1 || dayNum > 31) return;
      const anchorInput = document.getElementById('circle-anchor-date');
      if (!anchorInput || !anchorInput.value) return;

      const parts = anchorInput.value.split('-');
      if (parts.length === 3) {
        const y = parseInt(parts[0], 10);
        const m = parseInt(parts[1], 10);
        const maxDays = new Date(y, m, 0).getDate();
        const safeDay = Math.min(dayNum, maxDays);
        anchorInput.value = `${y}-${String(m).padStart(2, '0')}-${String(safeDay).padStart(2, '0')}`;
      }
    }
    window.handleCircleDueDayChange = handleCircleDueDayChange;

