    function computeNextCycleDate(baseDateStr, frequency, targetDueDay) {
      if (!baseDateStr) return new Date().toISOString().split('T')[0];
      const str = String(baseDateStr).replace(' ', 'T');
      const parts = str.split('T')[0].split('-');
      let year = parseInt(parts[0], 10);
      let month = parseInt(parts[1], 10); // 1-12
      let day = parseInt(parts[2], 10);
      if (isNaN(year) || isNaN(month) || isNaN(day)) {
        const fallbackDate = new Date(str);
        if (isNaN(fallbackDate.getTime())) return new Date().toISOString().split('T')[0];
        year = fallbackDate.getFullYear();
        month = fallbackDate.getMonth() + 1;
        day = fallbackDate.getDate();
      }

      const targetDay = (targetDueDay !== undefined && targetDueDay !== null && !isNaN(parseInt(targetDueDay, 10)))
        ? Math.max(1, Math.min(31, parseInt(targetDueDay, 10)))
        : day;

      const d = new Date(year, month - 1, day);

      if (frequency === 'weekly') {
        d.setDate(d.getDate() + 7);
        const y = d.getFullYear();
        const m = String(d.getMonth() + 1).padStart(2, '0');
        const dayStr = String(d.getDate()).padStart(2, '0');
        return `${y}-${m}-${dayStr}`;
      } else if (frequency === 'fixed_30') {
        d.setDate(d.getDate() + 30);
        const y = d.getFullYear();
        const m = String(d.getMonth() + 1).padStart(2, '0');
        const dayStr = String(d.getDate()).padStart(2, '0');
        return `${y}-${m}-${dayStr}`;
      } else if (frequency === 'fixed_90') {
        d.setDate(d.getDate() + 90);
        const y = d.getFullYear();
        const m = String(d.getMonth() + 1).padStart(2, '0');
        const dayStr = String(d.getDate()).padStart(2, '0');
        return `${y}-${m}-${dayStr}`;
      } else if (frequency === 'fixed_180') {
        d.setDate(d.getDate() + 180);
        const y = d.getFullYear();
        const m = String(d.getMonth() + 1).padStart(2, '0');
        const dayStr = String(d.getDate()).padStart(2, '0');
        return `${y}-${m}-${dayStr}`;
      } else if (frequency === 'custom') {
        d.setDate(d.getDate() + 30);
        const y = d.getFullYear();
        const m = String(d.getMonth() + 1).padStart(2, '0');
        const dayStr = String(d.getDate()).padStart(2, '0');
        return `${y}-${m}-${dayStr}`;
      } else {
        // Calendar Cadences: monthly (+1), quarterly (+3), semi_annual (+6), yearly (+12) with End-of-Month (EOM) Clamping
        let monthsToAdd = 1;
        if (frequency === 'quarterly') monthsToAdd = 3;
        else if (frequency === 'semi_annual') monthsToAdd = 6;
        else if (frequency === 'yearly') monthsToAdd = 12;

        const totalMonths = (year * 12 + (month - 1)) + monthsToAdd;
        const targetYear = Math.floor(totalMonths / 12);
        const targetMonth = (totalMonths % 12) + 1; // 1-12
        const daysInTargetMonth = new Date(targetYear, targetMonth, 0).getDate();
        const actualDay = Math.min(targetDay, daysInTargetMonth);

        const yStr = String(targetYear).padStart(4, '0');
        const mStr = String(targetMonth).padStart(2, '0');
        const dStr = String(actualDay).padStart(2, '0');
        return `${yStr}-${mStr}-${dStr}`;
      }
    }
    window.computeNextCycleDate = computeNextCycleDate;

