    function openPeriodBillCycleQuickAttachModal(cycleId) {
      const _t = (k, d, p) => (window.__t ? window.__t(k, d, p) : (d !== undefined ? d : k));
      let c = null;
      if (typeof drilldownCyclesList !== 'undefined' && Array.isArray(drilldownCyclesList)) {
        c = drilldownCyclesList.find(x => String(x.id) === String(cycleId));
      }
      if (!c && typeof currentDrilldownCycles !== 'undefined' && Array.isArray(currentDrilldownCycles)) {
        c = currentDrilldownCycles.find(x => String(x.id) === String(cycleId));
      }
      if (!c) {
        for (const b of (recurringBillsCache || [])) {
          if (b.cycles) {
            c = b.cycles.find(x => String(x.id) === String(cycleId));
            if (c) break;
          }

        }

      }
      if (!c) {
        showToast(_t('bills.modals_forms_period_cycle_not_found', 'Period cycle not found'), 'warning');
        return;
      }
      const title = `${c.bill_name || currentDrilldownBill?.name || 'Recurring Period'} (${c.cycle_label || _t('bills.modals_forms_period', 'Period')})`;
      const amtStr = `${formatNumber(c.amount_paid || c.amount_expected || '0', 2)} ${config.currency_symbol || 'DZD'}`;
      openQuickAttachmentModal('cycle', c.id, title, amtStr, c.receipt_ref || '', c.receipt_image || '', c.receipt_image_name || '');
    }
    window.openPeriodBillCycleQuickAttachModal = openPeriodBillCycleQuickAttachModal;

    function openQuickAttachmentModal(type, id, title, amount, currentRef, currentImg, currentImgName) {
      const _t = (k, d, p) => (window.__t ? window.__t(k, d, p) : (d !== undefined ? d : k));
      const modal = document.getElementById('record-attachment-quick-modal');
      if (!modal) return;

      document.getElementById('quick-attach-type').value = type || 'expense';
      document.getElementById('quick-attach-id').value = id || '';

      const badge = document.getElementById('quick-attach-item-badge');
      if (badge) {
        badge.textContent = (type === 'bill') ? _t('bills.history_ledgers_archived_bill', 'Archived Bill') : (type === 'cycle' ? _t('bills.print_tickets_circle_period', 'Circle Period') : _t('bills.modals_forms_expense', 'Expense'));
        badge.className = (type === 'bill')
          ? 'px-2 py-0.5 rounded-md text-[10px] font-black uppercase tracking-wider bg-blue-500/15 text-blue-600 dark:text-blue-400'
          : (type === 'cycle'
            ? 'px-2 py-0.5 rounded-md text-[10px] font-black uppercase tracking-wider bg-purple-500/15 text-purple-600 dark:text-purple-400'
            : 'px-2 py-0.5 rounded-md text-[10px] font-black uppercase tracking-wider bg-indigo-500/15 text-indigo-600 dark:text-indigo-400');
      }

      const titleEl = document.getElementById('quick-attach-item-title');
      if (titleEl) titleEl.textContent = title || _t('bills.status_pills_item_4', 'Item');
      const amtEl = document.getElementById('quick-attach-item-amount');
      if (amtEl) amtEl.textContent = amount || '0.00 DZD';

      const refInput = document.getElementById('quick-attach-receipt-ref');
      if (refInput) refInput.value = currentRef || '';

      const clearToggle = document.getElementById('quick-attach-clear-toggle');
      if (clearToggle) clearToggle.checked = false;

      if (currentImg) {
        const isPdf = (typeof currentImg === 'string' && currentImg.startsWith('data:application/pdf')) || (currentImgName && currentImgName.toLowerCase().endsWith('.pdf'));
        setQuickAttachAttachment({
          fileName: currentImgName || 'receipt_document',
          fileType: isPdf ? 'application/pdf' : 'image/jpeg',
          fileData: currentImg,
          fileSize: Math.round((currentImg.length * 3) / 4)
        }
);
      } else {
        removeQuickAttachCurrent();
      }

      modal.classList.remove('hidden');
    }
