    async function submitQuickAttachment(e) {
      const _t = (k, d, p) => (window.__t ? window.__t(k, d, p) : (d !== undefined ? d : k));
      if (e && typeof e.preventDefault === 'function') e.preventDefault();
      const type = document.getElementById('quick-attach-type')?.value;
      const id = document.getElementById('quick-attach-id')?.value;
      const refVal = document.getElementById('quick-attach-receipt-ref')?.value.trim() || '';
      const clearToggle = document.getElementById('quick-attach-clear-toggle');
      const isClear = !!(clearToggle && clearToggle.checked) || quickAttachmentCleared;

      if (!id) {
        showToast(_t('bills.modals_forms_record_id_missing', 'Record ID missing'), 'warning');
        return;
      }

      const btn = document.getElementById('btn-save-quick-attach');
      if (btn) { btn.disabled = true; btn.textContent = _t('bills.history_ledgers_saving', 'Saving...'); }

      const payload = {
        receipt_ref: refVal,
        clear_receipt_ref: refVal === ''
      };

      if (isClear) {
        payload.clear_receipt_image = true;
      } else if (stagedQuickAttachment) {
        payload.receipt_image = stagedQuickAttachment.fileData;
        payload.receipt_image_name = stagedQuickAttachment.fileName;
      }

      let endpoint = `/api/expenses/${id}/attachment`;
      if (type === 'bill') {
        endpoint = `/api/recurring-bills/${id}/attachment`;
      } else if (type === 'cycle') {
        endpoint = `/api/recurring-bills/cycles/${id}/document-dates`;
      }

      try {
        const res = await apiRequest(endpoint, {
          method: 'POST',
          body: JSON.stringify(payload)
        }
);
        if (!res || !res.ok) throw new Error(res?.error || _t('bills.print_tickets_failed_to_save_attachment', 'Failed to update attachment'));

        showToast(res.message || _t('bills.print_tickets_receipt_attachment_updated_successfully', 'Receipt attachment updated successfully!'));
        closeQuickAttachmentModal();
        await loadExpensesData();
        if (type === 'cycle' && typeof currentDrilldownBillId !== 'undefined' && currentDrilldownBillId) {
          if (typeof openBillCyclesDrilldown === 'function') {
            await openBillCyclesDrilldown(currentDrilldownBillId);
          }

        }

      } catch (err) {
        showToast(err.message || _t('bills.print_tickets_failed_to_save_attachment', 'Failed to save attachment'), 'warning');
      } finally {
        if (btn) { btn.disabled = false; btn.innerHTML = `<span>💾</span> <span>${_t('bills.modals_forms_save_attachment', 'Save Attachment')}</span>`; }
      }
    }
    window.submitQuickAttachment = submitQuickAttachment;

