        const primarySourceEl = document.getElementById('bill-cycles-primary-source');
        if (primarySourceEl) primarySourceEl.textContent = summary.primary_cash_source === 'vault' ? _t('bills.status_pills_cash_safe_vault_2', '🏛️ Cash Safe Vault') : _t('bills.status_pills_personal_hand', '💵 Personal / Hand');

        filterBillCyclesTimeline('all');
