            const isRefused = (p.status === 'refused' || p.acceptance_status === 'refused');
            const pctFormatted = p.percent ? (String(p.percent).includes('%') ? p.percent : (parseFloat(p.percent).toFixed(1) + '%')) : (isSinglePayer ? '100%' : '—');

