      if (radio) radio.checked = true;

      const activeClass = 'bg-emerald-500/10 border-emerald-500/30 text-emerald-600 dark:text-emerald-400 shadow-2xs';
      const inactiveClass = 'bg-slate-100 hover:bg-slate-200 dark:bg-white/[0.04] dark:hover:bg-white/[0.08] border-slate-200/80 dark:border-white/[0.06] text-slate-600 dark:text-slate-400';

      ['fr', 'ar', 'en'].forEach(l => {
        const btn = document.getElementById(`voucher-lang-btn-${l}`);
        if (!btn) return;
        if (l === targetLang) {
          btn.className = `cursor-pointer relative flex items-center justify-center py-2.5 px-3 rounded-xl border transition-all font-bold text-xs ${activeClass}`;
        }
 else {
          btn.className = `cursor-pointer relative flex items-center justify-center py-2.5 px-3 rounded-xl border transition-all font-bold text-xs ${inactiveClass}`;
        }

      });
      refreshVoucherStudioPreview();
