    window.setVoucherStudioLanguage = setVoucherStudioLanguage;

    async function openBillVoucherStudio(cycleId) {
      const _t = (k, d, p) => (window.__t ? window.__t(k, d, p) : (d !== undefined ? d : k));
      try {
        const res = await apiRequest(`/api/recurring-bills/cycles/${cycleId}/voucher`);
        if (!res || !res.ok) throw new Error(res?.error || _t('bills.print_tickets_failed_to_fetch_voucher_details', 'Failed to fetch voucher details'));
        currentVoucherCycleId = cycleId;
        currentVoucherData = res;
        setVoucherStudioLanguage((window.i18n && window.i18n.currentLang) || 'en');
        setVoucherStudioFormat('thermal');
        document.getElementById('bill-voucher-studio-modal')?.classList.remove('hidden');
      } catch (err) {
        showToast(err.message || _t('bills.print_tickets_could_not_load_voucher_studio', 'Could not load voucher studio'));
      }
    }
    window.openBillVoucherStudio = openBillVoucherStudio;

