      currentVoucherFormat = format;
      const thermalBtn = document.getElementById('voucher-format-thermal-btn');
      const a4Btn = document.getElementById('voucher-format-a4-btn');
      const scaleBadge = document.getElementById('voucher-preview-scale-badge');

