      const isRtl = (targetLang === 'ar');
      const _t = (k, d, p) => (typeof getTicketTranslation === 'function')
        ? getTicketTranslation(targetLang, k, d, p)
        : (window.__t ? window.__t(k, d, p) : (d !== undefined ? d : k));
      if (!data || !data.cycle) return `<p class="text-xs text-slate-400">${_t('bills.print_tickets_no_voucher_data_available', 'No voucher data available')}</p>`;
