        let customerName = customer ? customer.name : (window.__t ? window.__t('custom_service.template_selector.unknown_customer', 'Unknown Customer') : 'Unknown Customer');
        if (customer && customer.isWalkin && order.customerNote) customerName = order.customerNote + ' (walk-in)';
