        // Calculate net profit from products revenue minus product costs minus manual costs
        let netProfit = null;
        try {
          const items = order.orderItemsData ? (typeof order.orderItemsData === 'string' ? JSON.parse(order.orderItemsData) : order.orderItemsData) : [];
          const productRevenue = items.reduce((s, i) => s + (parseFloat(i.price || 0) * parseFloat(i.quantity || 0)), 0);
          const productCost = items.reduce((s, i) => s + (parseFloat(i.cost || 0) * parseFloat(i.quantity || 0)), 0);
          const costs = order.manualCostsData ? (typeof order.manualCostsData === 'string' ? JSON.parse(order.manualCostsData) : order.manualCostsData) : [];
          const manualTotal = costs.reduce((s, c) => s + parseFloat(c.amount || 0), 0);
          netProfit = total - productCost - manualTotal;
        }
 catch (e) { netProfit = null; }

        const profitLabel = isCompleted ? (window.__t ? window.__t('custom_service.template_selector.net_profit', 'Net Profit') : 'Net Profit') : (window.__t ? window.__t('custom_service.template_selector.expected_profit', 'Expected Profit') : 'Expected Profit');
        const totalLabel = isCompleted ? (window.__t ? window.__t('custom_service.template_selector.total_received', 'Total Received') : 'Total Received') : (window.__t ? window.__t('custom_service.template_selector.expected_total', 'Expected Total') : 'Expected Total');
        const profitColor = netProfit !== null && netProfit < 0 ? 'text-rose-600 dark:text-rose-400' : 'text-emerald-600 dark:text-emerald-400';

        let statusBadgeCls = 'bg-amber-50 dark:bg-amber-950/60 text-amber-700 dark:text-amber-300 border border-amber-200/80 dark:border-amber-800/80';
        let statusLabel = window.__t ? window.__t('custom_service.template_selector.status_pending', 'Pending') : 'Pending';
