              <div class="flex gap-2">
                <button onclick="showOrderDetails('${order.__backendId}')"
                  class="flex-1 py-2.5 bg-slate-100 hover:bg-slate-200 dark:bg-white/[0.06] dark:hover:bg-white/[0.12] text-slate-700 dark:text-slate-200 font-bold rounded-xl border border-transparent dark:border-white/[0.06] transition-all text-xs flex items-center justify-center gap-1.5 cursor-pointer">
                  <svg class="w-4 h-4 flex-shrink-0 text-slate-500 dark:text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path>
                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"></path>
                  </svg>
                  <span>${window.__t ? window.__t('custom_service.template_selector.btn_view', 'View') : 'View'}</span>
                </button>
                <button onclick="useOrderAsTemplate('${order.__backendId}')"
                  class="flex-[1.5] py-2.5 bg-gradient-to-r from-violet-600 via-indigo-600 to-purple-600 hover:from-violet-500 hover:to-indigo-500 text-white font-black rounded-xl shadow-lg shadow-indigo-500/20 transition-all text-xs flex items-center justify-center gap-1.5 cursor-pointer active:scale-[0.98]">
                  <svg class="w-4 h-4 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 7v8a2 2 0 002 2h6M8 7V5a2 2 0 012-2h4.586a1 1 0 01.707.293l4.414 4.414a1 1 0 01.293.707V15a2 2 0 01-2 2h-2M8 7H6a2 2 0 00-2 2v10a2 2 0 002 2h8a2 2 0 002-2v-2"></path>
                  </svg>
                  <span>${window.__t ? window.__t('custom_service.template_selector.btn_use_template', 'Use Template') : 'Use Template'}</span>
                </button>
              </div>
