      if (label.length > 30) { showToast(window.__t ? window.__t('custom_service.name_too_long_toast', 'Name is too long (max 30 characters)') : 'Name is too long (max 30 characters)'); return; }
      if (!/^[\p{L}\p{N} .\-_&()\/]+$/u.test(label)) { showToast(window.__t ? window.__t('custom_service.invalid_chars_toast', 'Only letters, numbers, spaces and . - _ & ( ) / are allowed') : 'Only letters, numbers, spaces and . - _ & ( ) / are allowed'); return; }
      const list = kind === 'status' ? getCustomStatuses() : getCustomDocTypes();
