    function setCustomPaidPreset(preset) {
      const paidInput = document.getElementById('custom-customer-paid');
      if (!paidInput) return;
      if (preset === 'min') {
        const minVal = window._customServiceMinPayment || window._customServiceBaseFloor || '0';
        paidInput.value = exactCompare(minVal, '0') > 0 ? formatNumber(minVal, 2) : '0';
      } else if (preset === 'base') {
        const baseVal = window._customServiceBaseFloor || '0';
        paidInput.value = exactCompare(baseVal, '0') > 0 ? formatNumber(baseVal, 2) : '0';
      } else if (preset === 'full') {
        const baseVal = window._customServiceBaseFloor || '0';
        const extraLaborVal = toExactDecimalString(document.getElementById('custom-extra-labor-fee')?.value || '0');
        const targetFull = exactCompare(extraLaborVal, '0') > 0 ? exactAdd(baseVal, extraLaborVal) : baseVal;
        paidInput.value = exactCompare(targetFull, '0') > 0 ? formatNumber(targetFull, 2) : '0';
      }
      updateCustomSaleSummary();
    }
    window.setCustomPaidPreset = setCustomPaidPreset;

    function onCustomExtraLaborFeeInput(val) {
      const baseFloor = window._customServiceBaseFloor || '0';
      const cleanVal = toExactDecimalString(val || '0');
      const grandTotal = exactAdd(baseFloor, cleanVal);
      const grandInput = document.getElementById('custom-billing-grand-total-input');
      if (grandInput) {
        grandInput.value = exactCompare(grandTotal, '0') > 0 ? formatNumber(grandTotal, 2) : '';
      }
      updateCustomSaleSummary();
    }
    window.onCustomExtraLaborFeeInput = onCustomExtraLaborFeeInput;

    function onCustomGrandTotalInput(val) {
      const baseFloor = window._customServiceBaseFloor || '0';
      const cleanVal = toExactDecimalString(val || '0');
      const extraLaborInp = document.getElementById('custom-extra-labor-fee');
      if (extraLaborInp) {
        if (exactCompare(cleanVal, baseFloor) > 0) {
          const extra = exactSubtract(cleanVal, baseFloor);
          extraLaborInp.value = extra;
        }
 else {
          extraLaborInp.value = '0';
        }

      }
      updateCustomSaleSummary();
    }
    window.onCustomGrandTotalInput = onCustomGrandTotalInput;

    // Add event listeners for real-time calculation and shortcuts
    document.addEventListener('DOMContentLoaded', () => {
      const customerPaidInput = document.getElementById('custom-customer-paid');
      if (customerPaidInput) {
        sanitizeNumericInput(customerPaidInput, true);
        customerPaidInput.addEventListener('input', updateCustomSaleSummary);
      }

      // Delegated precision enforcer for all cost-row amount inputs (dynamic elements)
      const costsContainer = document.getElementById('manual-costs-rows');
      if (costsContainer) {
        costsContainer.addEventListener('input', (e) => {
          const input = e.target;
          if (input.type !== 'number') return;
          const precision = config && config.display_decimals !== undefined ? config.display_decimals : 2;
          const val = input.value;
          if (precision === 0) {
            // No decimals allowed at all
            input.value = val.replace(/\.\d*/, '');
            return;
          }

          const dotIndex = val.indexOf('.');
          if (dotIndex !== -1 && val.length - dotIndex - 1 > precision) {
            input.value = val.substring(0, dotIndex + 1 + precision);
          }

        }
);
      }

      // Bootstrap default rows display
      renderManualCostRows();
    });

    // Keyboard shortcut for quick order submission: Ctrl + Enter / Cmd + Enter
    document.addEventListener('keydown', (e) => {
      if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') {
        const servicesPage = document.getElementById('page-services');
        if (servicesPage && !servicesPage.classList.contains('hidden')) {
          const submitBtn = document.getElementById('custom-sale-submit-btn');
          if (submitBtn && !submitBtn.disabled) {
            e.preventDefault();
            const form = document.getElementById('custom-sale-form');
            if (form) {
              if (form.reportValidity && !form.reportValidity()) return;
              form.requestSubmit();
            }

          }

        }

      }
    });

    async function saveCustomSale(e) {
      e.preventDefault();

      const customerId = document.getElementById('custom-customer').value;
      if (!customerId) {
        showToast(window.__t ? window.__t('services.toast_select_customer', 'Please select a customer') : 'Please select a customer');
        return;
      }

      let finalCustomerId = customerId;
      if (customerId === '__auto_create__') {
        const autoName = (document.getElementById('custom-autocreate-name')?.value || '').trim();
        if (!autoName) {
          showToast(window.__t ? window.__t('services.toast_enter_customer_name', 'Please enter the new customer name') : 'Please enter the new customer name');
          const inp = document.getElementById('custom-autocreate-name');
          if (inp) inp.focus();
          return;
        }

        try {
          const res = await apiRequest('/api/customers', {
            method: 'POST',
            body: JSON.stringify({ type: 'customer', name: autoName })
          }
);
          if (res && res.id) {
            finalCustomerId = String(res.id);
          }
 else {
            showToast(_t('pos.toast_customer_create_failed', 'Failed to auto-create customer'), 'default');
            return;
          }

        }
 catch (err) {
          showToast(err.message || _t('pos.toast_customer_create_failed', 'Failed to auto-create customer'), 'default');
          return;
        }

      }

      // Walk-in buyer note (only for the built-in Walk-in customer).
      const _customCust = findItem(finalCustomerId, 'customer');
      const customWalkinNote = (_customCust && _customCust.isWalkin)
        ? (document.getElementById('custom-walkin-note')?.value || '').trim() : '';

      const btn = document.getElementById('custom-sale-submit-btn');
      const btnText = document.getElementById('custom-sale-submit-text');
      if (btn) btn.disabled = true;
      if (btnText) btnText.textContent = window.__t ? window.__t('services.btn_processing', 'Processing...') : 'Processing...';

      try {
        const leadOwnerId = String(document.getElementById('custom-owner')?.value || (customTeam && customTeam[0]?.user_id) || currentUser?.__backendId || currentUser?.id || '1');
        const providerName = document.getElementById('custom-provider-name').value;
        const serviceName = document.getElementById('custom-service-name').value;
        const description = document.getElementById('custom-service-description').value;
        const rawAgreedPrice = String(document.getElementById('custom-customer-paid')?.value || '').trim();
        const agreedPrice = toExactDecimalString(rawAgreedPrice || '0');

        if (exactCompare(agreedPrice, '0') <= 0) {
          showToast(window.__t ? window.__t('services.toast_enter_agreed_price', 'Please enter the agreed expected price for this custom service.') : 'Please enter the agreed expected price for this custom service.');
          if (btn) btn.disabled = false;
          if (btnText) btnText.textContent = editingCustomSaleId ? (window.__t ? window.__t('services.btn_update_order', 'Update Custom Service') : 'Update Custom Service') : (window.__t ? window.__t('services.btn_submit_order', 'Create Custom Service Order') : 'Create Custom Service Order');
          return;
        }


        // ── Cross-user payment protection: final guard before saving ──
        if (window._customServiceHasCrossUser && Decimal.comp(window._customServiceMinPayment || '0', '0') > 0) {
          if (Decimal.comp(agreedPrice, window._customServiceMinPayment) < 0) {
            const minErrMsg = window.__t ? window.__t('services.toast_below_partner_min_error', 'Cannot save: Agreed service price ({price}) is below the minimum owed to partners ({min})', { price: formatPrice(agreedPrice), min: formatPrice(window._customServiceMinPayment) }) : `Cannot save: Agreed service price (${formatPrice(agreedPrice)}) is below the minimum owed to partners (${formatPrice(window._customServiceMinPayment)})`;
            showToast(minErrMsg);
            if (btn) btn.disabled = false;
            if (btnText) btnText.textContent = editingCustomSaleId ? (window.__t ? window.__t('services.btn_update_order', 'Update Custom Service') : 'Update Custom Service') : (window.__t ? window.__t('services.btn_submit_order', 'Create Custom Service Order') : 'Create Custom Service Order');
            return;
          }

        }


        const isPhase2 = Boolean(isEditingPhase2Locked && editingCustomSaleId);

        // ── Process Phase 2 Staged Removals on Update ──
        let removalCount = 0;
        let hasStagedRemovals = false;

        if (isPhase2) {
          const stagedPartners = Array.from(window._stagedRemovedPartnerIds || []);
          const stagedProducts = (customSaleProducts || []).filter(item => item.removal_pending);
          const stagedCosts = (manualCostRows || []).filter(row => row.removal_pending);
          const stagedTeam = (customTeam || []).filter(m => m.removal_pending);

          hasStagedRemovals = stagedPartners.length > 0 || stagedProducts.length > 0 || stagedCosts.length > 0 || stagedTeam.length > 0;

          if (hasStagedRemovals) {
            let settlements = window._customTeamSettlements;
            if (!settlements || !settlements.length) {
              try {
                const sRes = await apiRequest(`/api/partner-settlements?order_id=${editingCustomSaleId}`);
                settlements = sRes?.settlements || sRes?.data || [];
                window._customTeamSettlements = settlements;
              }
 catch (e) {
                console.error('Could not fetch settlements for removal request', e);
                settlements = [];
              }

            }


            // 1. Process Staged Full Partner Removals
            for (const pId of stagedPartners) {
              const pStls = settlements.filter(s => String(s.payee_user_id) === String(pId) && s.status !== 'cancelled' && (s.removal_request_status !== 'pending' && s.removal_request_status !== 'accepted'));
              const pUser = (typeof usersCache !== 'undefined' ? usersCache : []).find(u => String(u.id) === String(pId) || String(u.__backendId) === String(pId));
              const pName = pUser ? pUser.username : `User #${pId}`;
              const partnerProducts = (customSaleProducts || []).filter(p => String(p.costOwnerId || p.cost_owner_id) === String(pId));
              const partnerCosts = (manualCostRows || []).filter(c => String(c.paid_by_user_id) === String(pId));
              const teamM = (customTeam || []).find(m => String(m.user_id) === String(pId));

              const removalMeta = {
                type: 'full_partner_removal',
                target_user_id: pId,
                partner_name: pName,
                service_name: serviceName,
                summary: `Full partner removal requested for ${pName} from "${serviceName}". All associated parts, outlays, and collaborator roles will be detached upon confirmation.`,
                products_count: partnerProducts.length,
                outlays_count: partnerCosts.length,
                collab_pct: teamM ? (teamM._savedSharePct || teamM.share_pct) : '0'
              }
;

              for (const stl of pStls) {
                try {
                  await apiRequest(`/api/partner-settlements/${stl.id}/request-removal`, {
                    method: 'POST',
                    body: JSON.stringify({ removal_metadata: removalMeta })
                  }
);
                  removalCount++;
                }
 catch (err) {
                  console.error(`Failed to request removal for settlement #${stl.id}`, err);
                }

              }

            }


            // 2. Process Individual Staged Products
            for (const prod of stagedProducts) {
              const ownerId = String(prod.costOwnerId || prod.cost_owner_id || '');
              if (stagedPartners.includes(ownerId)) continue;
              let prodStl = settlements.find(s => {
                if (String(s.payee_user_id) !== ownerId) return false;
                if (!['parts_cost_recovery', 'parts_profit_share'].includes(s.settlement_type)) return false;
                if (s.status === 'cancelled' || s.removal_request_status === 'pending') return false;
                let det = s.details;
                if (typeof det === 'string') {
                  try { det = JSON.parse(det); } catch (e) { det = {}; }
                }

                const pId = prod.productId || prod.product_id;
                const oiId = prod.id || prod.order_item_id;
                if (pId && det && String(det.product_id) === String(pId)) return true;
                if (oiId && det && String(det.order_item_id) === String(oiId)) return true;
                return false;
              }
);
              if (!prodStl) {
                prodStl = settlements.find(s => String(s.payee_user_id) === ownerId && ['parts_cost_recovery', 'parts_profit_share'].includes(s.settlement_type) && s.status !== 'cancelled' && s.removal_request_status !== 'pending');
              }

              if (prodStl) {
                const prodMeta = {
                  type: 'product_removal',
                  target_user_id: ownerId,
                  product_id: prod.productId || prod.product_id || null,
                  order_item_id: prod.id || prod.order_item_id || null,
                  product_name: prod.name,
                  quantity: prod.quantity,
                  service_name: serviceName,
                  summary: `Removal requested for product "${prod.name}" (Qty: ${prod.quantity}) from "${serviceName}". Stock will be restored upon confirmation.`
                }
;
                try {
                  await apiRequest(`/api/partner-settlements/${prodStl.id}/request-removal`, {
                    method: 'POST',
                    body: JSON.stringify({ removal_metadata: prodMeta })
                  }
);
                  removalCount++;
                }
 catch (err) {
                  console.error(`Failed to request removal for product ${prod.name}`, err);
                }

              }

            }


            // 3. Process Individual Staged Manual Costs
            for (let cIdx = 0; cIdx < stagedCosts.length; cIdx++) {
              const cost = stagedCosts[cIdx];
              const payerId = String(cost.paid_by_user_id || '');
              if (stagedPartners.includes(payerId)) continue;
              let costStl = settlements.find(s => {
                if (String(s.payee_user_id) !== payerId) return false;
                if (!['manual_cost_recovery', 'manual_cost_markup', 'manual_outlay_recovery'].includes(s.settlement_type)) return false;
                if (s.status === 'cancelled' || s.removal_request_status === 'pending') return false;
                let det = s.details;
                if (typeof det === 'string') {
                  try { det = JSON.parse(det); } catch (e) { det = {}; }
                }

                const costIndex = cost.costIndex !== undefined ? cost.costIndex : cIdx;
                if (det && det.cost_index !== undefined && String(det.cost_index) === String(costIndex)) return true;
                if (cost.description && det && (det.description === cost.description || det.item_name === cost.description)) return true;
                return false;
              }
);
              if (!costStl) {
                costStl = settlements.find(s => String(s.payee_user_id) === payerId && ['manual_cost_recovery', 'manual_cost_markup'].includes(s.settlement_type) && s.status !== 'cancelled' && s.removal_request_status !== 'pending');
              }

              if (costStl) {
                const costMeta = {
                  type: 'manual_cost_removal',
                  target_user_id: payerId,
                  cost_description: cost.description,
                  amount: cost.amount,
                  service_name: serviceName,
                  summary: `Removal requested for outlay "${cost.description}" (${formatPrice(cost.amount)}) from "${serviceName}". Safe refund will be issued upon confirmation if eligible.`
                }
;
                try {
                  await apiRequest(`/api/partner-settlements/${costStl.id}/request-removal`, {
                    method: 'POST',
                    body: JSON.stringify({ removal_metadata: costMeta })
                  }
);
                  removalCount++;
                }
 catch (err) {
                  console.error(`Failed to request removal for outlay ${cost.description}`, err);
                }

              }

            }


            // 4. Process Individual Staged Collaborators
            for (const member of stagedTeam) {
              const memberId = String(member.user_id || '');
              if (stagedPartners.includes(memberId)) continue;
              const teamStl = settlements.find(s => String(s.payee_user_id) === memberId && s.settlement_type === 'service_profit_share' && s.status !== 'cancelled' && s.removal_request_status !== 'pending');
              if (teamStl) {
                const collabMeta = {
                  type: 'collab_removal',
                  target_user_id: memberId,
                  share_pct: member._savedSharePct || member.share_pct,
                  service_name: serviceName,
                  summary: `Removal requested for collaborator share (${member._savedSharePct || member.share_pct}%) from "${serviceName}". Share will return to the Service Owner upon confirmation.`
                }
;
                try {
                  await apiRequest(`/api/partner-settlements/${teamStl.id}/request-removal`, {
                    method: 'POST',
                    body: JSON.stringify({ removal_metadata: collabMeta })
                  }
);
                  removalCount++;
                }
 catch (err) {
                  console.error(`Failed to request removal for collaborator #${memberId}`, err);
                }

              }

            }

          }

        }


        // ── Construct Order Payload ──
        // In Phase 1: removals are immediate/permanent -> omit removal_pending
        // In Phase 2: removals are consent-based -> preserve items/shares awaiting consent so contract remains valid in database until accepted
        const productsForPayload = isPhase2
          ? (customSaleProducts || [])
          : (customSaleProducts || []).filter(item => !item.removal_pending);

        const manualCostsArr = isPhase2
          ? getManualCostsData(true)
          : getManualCostsData(false);

        const manualCostTotal = isPhase2
          ? getTotalManualCost(true)
          : getTotalManualCost(false);

        let productsCost = '0';
        let productsRevenue = '0';
        let partsOwnerProfitSum = '0';
        let serviceOwnerProfitSum = '0';
        let partsCostReimbursementSum = '0';

        productsForPayload.forEach(item => {
          const qty = String(item.quantity || 0);
          const itemCost = exactMultiply(String(item.cost || 0), qty);
          const itemPrice = exactMultiply(String(item.price || 0), qty);
          productsCost = exactAdd(productsCost, itemCost);
          productsRevenue = exactAdd(productsRevenue, itemPrice);
          partsCostReimbursementSum = exactAdd(partsCostReimbursementSum, itemCost);
          partsOwnerProfitSum = exactAdd(partsOwnerProfitSum, String(item.product_owner_profit || 0));
          serviceOwnerProfitSum = exactAdd(serviceOwnerProfitSum, String(item.service_owner_profit || 0));
        }
);

        let manualMarkupSum = '0';
        (manualCostsArr || []).forEach(r => {
          const prf = toExactDecimalString(r.profit || '0');
          manualMarkupSum = exactAdd(manualMarkupSum, prf);
        }
);
        const outlaysBilledTotal = exactAdd(manualCostTotal, manualMarkupSum);
        const totalCost = exactAdd(productsCost, manualCostTotal);
        const baseFloor = exactAdd(productsRevenue, outlaysBilledTotal);

        // Expected Total Revenue / Agreed Price Architecture:
        let extraLaborFee = '0';
        let grandTotal = baseFloor;

        if (exactCompare(agreedPrice, '0') > 0) {
          grandTotal = agreedPrice;
          if (exactCompare(grandTotal, baseFloor) > 0) {
            extraLaborFee = exactSubtract(grandTotal, baseFloor);
          }
 else {
            extraLaborFee = '0';
          }

        }
 else {
          grandTotal = baseFloor;
          extraLaborFee = '0';
        }

        const contractNetProfit = exactSubtract(grandTotal, totalCost);

        // Build items summary
        const itemsSummary = `${serviceName} by ${providerName} ` +
          (productsForPayload.length > 0 ? ` (Parts: ${productsForPayload.map(p => `${p.name} x${formatQuantity(p.quantity, p.displayDecimals)}`).join(', ')})` : '');

        const items = productsForPayload.map(item => ({
          product_id: item.productId || null,
          purchase_id: item.batchId || null,
          category_id: item.categoryId || null,
          name: item.name,
          price: toExactDecimalString(item.price),
          quantity: toExactDecimalString(item.quantity),
          cost: toExactDecimalString(item.cost),
          description: item.description || '',
          cost_owner_id: item.cost_owner_id || null,
          profit_split_type: item.profit_split_type || 'none',
          product_owner_share_pct: item.product_owner_share_pct || '0',
          product_owner_profit: item.product_owner_profit || '0',
          service_owner_profit: item.service_owner_profit || '0'
        }
));

        const serviceLaborProfitPool = exactAdd(exactCompare(extraLaborFee, '0') > 0 ? extraLaborFee : '0', serviceOwnerProfitSum);

        const isCollabActive = Boolean(document.getElementById('custom-collab-toggle')?.classList.contains('active'));
        distributeCustomTeamProfits(serviceLaborProfitPool);

        let effectiveTeam;
        const teamForOrderSave = (customTeam || []).map((m, idx) => ({
          user_id: m.user_id,
          role: m.role || (idx === 0 ? 'Lead' : 'Collaborator'),
          split_mode: isPhase2 ? 'fixed' : (m.split_mode || 'pct'),
          share_pct: toExactDecimalString(m.share_pct || '0'),
          profit: toExactDecimalString(m.profit || '0'),
          labor_profit: toExactDecimalString(m.labor_profit || m.profit || '0'),
          baseline_profit: toExactDecimalString(m.baseline_profit || m.profit || '0'),
          ...(m.removal_pending !== undefined ? { removal_pending: m.removal_pending } : {}),
          ...(m.isAccepted !== undefined ? { is_accepted: m.isAccepted } : {})
        }
));

        const filteredTeam = isPhase2
          ? teamForOrderSave
          : teamForOrderSave.filter(m => !m.removal_pending);

        effectiveTeam = (isCollabActive && filteredTeam.length > 1)
          ? filteredTeam
          : [{
              user_id: leadOwnerId,
              role: 'Lead',
              split_mode: 'pct',
              share_pct: '100.00',
              profit: serviceLaborProfitPool,
              labor_profit: serviceLaborProfitPool,
              baseline_profit: serviceLaborProfitPool
            }
];

        const url = editingCustomSaleId ? `/api/orders/${editingCustomSaleId}` : '/api/orders';
        const method = editingCustomSaleId ? 'PUT' : 'POST';
        const existingOrdObj = editingCustomSaleId ? findItem(editingCustomSaleId, 'order') : null;
        const orderAmountPaid = editingCustomSaleId ? (existingOrdObj?.amount_paid || '0') : '0';

        const res = await apiRequest(url, {
          method: method,
          body: JSON.stringify({
            customer_id: finalCustomerId,
            items_summary: itemsSummary,
            items,
            total: grandTotal,
            amount_paid: orderAmountPaid,
            profit: contractNetProfit,
            status: existingOrdObj?.status || 'pending',
            custom_sale: true,
            provider_name: providerName,
            service_name: serviceName,
            service_description: description,
            customer_note: customWalkinNote,
            owner_user_id: leadOwnerId,
            service_owners: effectiveTeam,
            service_owners_data: JSON.stringify(effectiveTeam),
            manual_costs: manualCostsArr,
            manual_cost: manualCostTotal,
            products_cost: productsCost,
            parts_owner_profit: partsOwnerProfitSum,
            service_owner_profit: serviceLaborProfitPool,
            parts_cost_reimbursement: partsCostReimbursementSum,
            custom_checklist: customChecklist,
            device_model: (document.getElementById('custom-device-model')?.value || '').trim(),
            device_imei: (document.getElementById('custom-device-imei')?.value || '').trim(),
            device_passcode: (document.getElementById('custom-device-passcode')?.value || '').trim(),
            device_condition: (document.getElementById('custom-device-condition')?.value || '').trim(),
            device_custody_status: (document.getElementById('custom-device-custody-status')?.value || window.customDeviceCustodyStatus || 'on_me').trim(),
            diagnostic_matrix: JSON.stringify(window.customMultiStageMatrix || {}),
            handover_qc_matrix: JSON.stringify(window.customMultiStageMatrix?.handover || {}),
            ...(templateSourceOrderId && !editingCustomSaleId ? { created_from_order_id: templateSourceOrderId } : {})
          }
)
        }
);

        const wasEditing = Boolean(editingCustomSaleId);
        const savedOrderId = res?.id || res?.order_id || editingCustomSaleId;
        closeCustomSaleModal();
        templateSourceOrderId = null; // Reset after saving
        editingCustomSaleId = null;
        if (typeof resetCustomServicesForm === 'function') {
          resetCustomServicesForm(true);
        }

        await loadAllData();

        if (hasStagedRemovals && removalCount > 0) {
          showToast(window.__t ? window.__t('services.toast_phase2_removal_sent', 'Phase 2 removal request(s) sent to partner(s) for agreement confirmation') : 'Phase 2 removal request(s) sent to partner(s) for agreement confirmation', 'info');
        }
 else {
          showToast(wasEditing ? (window.__t ? window.__t('services.toast_service_updated', 'Custom service updated!') : 'Custom service updated!') : (window.__t ? window.__t('services.toast_service_created', 'Custom service created successfully!') : 'Custom service created successfully!'));
        }


        if (savedOrderId && typeof showOrderDetails === 'function') {
          if (typeof showPage === 'function') showPage('orders');
          setTimeout(() => {
            showOrderDetails(savedOrderId);
          }
, 60);
        }

      } catch (e) {
        showToast(e.message || (window.__t ? window.__t('services.toast_save_failed', 'Failed to record custom sale. Please try again.') : 'Failed to record custom sale. Please try again.'));
      } finally {
        if (btn) btn.disabled = false;
        if (btnText) {
          btnText.textContent = editingCustomSaleId ? (window.__t ? window.__t('services.btn_update_order', 'Update Custom Service') : 'Update Custom Service') : (window.__t ? window.__t('services.btn_submit_order', 'Create Custom Service Order') : 'Create Custom Service Order');
        }

      }
    }

    // ── Logo Crop State ──
    let cropState = null; // { shape, imgEl, naturalW, naturalH, resolve, reject }

    const CROP_CONFIGS = {
      square:      { w: 512, h: 512 },
      rectangular: { w: 768, h: 256 },
      circle:      { w: 512, h: 512 }
    };

    /**
     * Inspect a freshly loaded crop image on a small offscreen canvas:
     *  - hasAlpha: does the source contain any transparency? (drives the bg picker)
     *  - bbox: the bounding box of the "real" content (pixels that differ from the
     *    corner/background colour) in NATURAL coords — drives auto-centering so a
     *    logo with lopsided whitespace padding starts framed instead of off-centre.
     * Falls back to the full image on any error (e.g. a tainted canvas).
     */
    function analyzeCropImage(imgEl) {
      const natW = imgEl.naturalWidth, natH = imgEl.naturalHeight;
      const result = { hasAlpha: false, bbox: { x: 0, y: 0, w: natW, h: natH } };
      try {
        const maxDim = 100;
        const scale = Math.min(1, maxDim / Math.max(natW, natH));
        const sw = Math.max(1, Math.round(natW * scale));
        const sh = Math.max(1, Math.round(natH * scale));
        const c = document.createElement('canvas');
        c.width = sw; c.height = sh;
        const ctx = c.getContext('2d', { willReadFrequently: true });
        ctx.drawImage(imgEl, 0, 0, sw, sh);
        const data = ctx.getImageData(0, 0, sw, sh).data;

        // Background reference = average of the four corner pixels.
        const corners = [0, (sw - 1), (sh - 1) * sw, (sh - 1) * sw + (sw - 1)].map(i => i * 4);
        let br = 0, bg = 0, bb = 0, ba = 0;
        corners.forEach(i => { br += data[i]; bg += data[i + 1]; bb += data[i + 2]; ba += data[i + 3]; });
        br /= 4; bg /= 4; bb /= 4; ba /= 4;

        let minX = sw, minY = sh, maxX = -1, maxY = -1;
        for (let y = 0; y < sh; y++) {
          for (let x = 0; x < sw; x++) {
            const i = (y * sw + x) * 4;
            const a = data[i + 3];
            if (a < 250) result.hasAlpha = true;
            const visible = a > 24;
            const diff = Math.abs(data[i] - br) + Math.abs(data[i + 1] - bg) + Math.abs(data[i + 2] - bb) + Math.abs(a - ba);
            if (visible && diff > 60) {
              if (x < minX) minX = x;
              if (x > maxX) maxX = x;
              if (y < minY) minY = y;
              if (y > maxY) maxY = y;
            }

          }

        }

        if (maxX >= minX && maxY >= minY) {
          const inv = 1 / scale;
          result.bbox = { x: minX * inv, y: minY * inv, w: (maxX - minX + 1) * inv, h: (maxY - minY + 1) * inv };
        }

      } catch (e) { /* tainted/unsupported — keep the full-image fallback */ }
      return result;
    }

    /**
     * Instagram-style cropper. The image is laid out at its NATURAL size and all
     * zoom/pan is done with a single CSS transform (translate + scale, origin 0,0).
     * Using a transform — not width/height/left/top — means Tailwind preflight's
     * `img { max-width:100%; height:auto }` can't desync the rendered image from
     * our math (the old bug). Scale is clamped to >= cover and the pan is clamped
     * so the frame is ALWAYS fully covered — you can never expose empty edges.
     */
    function openCropModal(imgSrc, shape) {
      return new Promise((resolve, reject) => {
        const cfg = CROP_CONFIGS[shape] || CROP_CONFIGS.square;
        const viewport = document.getElementById('crop-viewport');
        const cropImg = document.getElementById('crop-image');
        const zoomSlider = document.getElementById('crop-zoom');

        // Frame size (max 300px on its long side), keeping the target aspect.
        const aspect = cfg.w / cfg.h;
        let vpW = 300, vpH = Math.round(300 / aspect);
        if (vpH > 300) { vpH = 300; vpW = Math.round(300 * aspect); }
        viewport.style.width = vpW + 'px';
        viewport.style.height = vpH + 'px';
        viewport.style.borderRadius = shape === 'circle' ? '50%' : '1.5rem';

        const labels = { square: 'Square', rectangular: 'Rectangular', circle: 'Circle' };
        document.getElementById('crop-shape-label').textContent = labels[shape] || 'Square';

        zoomSlider.value = 100;
        updateCropZoomLabel(100);

        cropImg.onload = () => {
          const natW = cropImg.naturalWidth;
          const natH = cropImg.naturalHeight;

          // Lay the image out at natural size; neutralise preflight; transform does the rest.
          cropImg.style.transition = 'none';
          cropImg.style.maxWidth = 'none';
          cropImg.style.maxHeight = 'none';
          cropImg.style.left = '0px';
          cropImg.style.top = '0px';
          cropImg.style.width = natW + 'px';
          cropImg.style.height = natH + 'px';
          cropImg.style.transformOrigin = '0 0';

          // "cover" scale = the minimum scale that fills the frame (this is 100% / Fit).
          const coverScale = Math.max(vpW / natW, vpH / natH);

          // #1 Auto-suggest the initial crop: centre on the content's bounding box
          // (handles lopsided whitespace padding) instead of the geometric centre.
          const analysis = analyzeCropImage(cropImg);
          const focalX = analysis.bbox.x + analysis.bbox.w / 2;
          const focalY = analysis.bbox.y + analysis.bbox.h / 2;

          cropState = {
            shape, natW, natH, vpW, vpH, coverScale,
            scale: coverScale, tx: 0, ty: 0, focalX, focalY,
            bg: 'transparent', hasAlpha: analysis.hasAlpha, resolve, reject
          }
;
          // Centre the focal point in the frame, then clamp so it still covers.
          cropState.tx = vpW / 2 - focalX * coverScale;
          cropState.ty = vpH / 2 - focalY * coverScale;
          clampCropTranslate();
          renderCrop();

          // #4 Background fill — offer it only when the source has transparency.
          const bgRow = document.getElementById('crop-bg-row');
          if (bgRow) bgRow.classList.toggle('hidden', !analysis.hasAlpha);
          setCropBg('transparent');

          const cropModalEl = document.getElementById('logo-crop-modal');
          cropModalEl.classList.remove('hidden');
          if (typeof ModalManager !== 'undefined' && typeof ModalManager.bringToFront === 'function') {
            ModalManager.bringToFront(cropModalEl);
          }
          // #3 Circle corner-clip warning.
          updateCircleClipWarning();
        }
;
        cropImg.onerror = () => reject(new Error('Failed to load image'));
        cropImg.src = imgSrc; // set last so onload always fires (even on cache hits)
      });
    }

    // Push the current transform to the DOM.
    function renderCrop() {
      if (!cropState) return;
      const img = document.getElementById('crop-image');
      img.style.transform = `translate(${cropState.tx}px, ${cropState.ty}px) scale(${cropState.scale})`;
    }

    // Current zoom as a percentage of the cover/fit scale (100% = Fit).
    function cropZoomPct() {
      return cropState ? (cropState.scale / cropState.coverScale) * 100 : 100;
    }

    // Keep the image covering the frame: tx/ty are pinned so no empty edge shows.
    function clampCropTranslate() {
      const s = cropState;
      if (!s) return;
      const dispW = s.natW * s.scale, dispH = s.natH * s.scale;
      s.tx = dispW <= s.vpW ? (s.vpW - dispW) / 2 : Math.min(0, Math.max(s.vpW - dispW, s.tx));
      s.ty = dispH <= s.vpH ? (s.vpH - dispH) / 2 : Math.min(0, Math.max(s.vpH - dispH, s.ty));
    }

    function updateCropZoomLabel(z) {
      const el = document.getElementById('crop-zoom-label');
      if (el) el.textContent = Math.round(z) + '%';
    }

    function showCropGrid(visible) {
      const g = document.getElementById('crop-grid');
      if (g) g.style.opacity = visible ? '1' : '0';
    }

    /**
     * Set zoom to `zoom` (% of the cover/fit scale; 100% = Fit, clamped 100..500).
     * Optionally pass an anchor in viewport coords so the image pixel under that
     * point stays put while resizing — that's what makes wheel/pinch zoom feel
     * natural ("zoom toward where I'm pointing").
     */
    function setCropZoom(zoom, anchorVpX, anchorVpY) {
      if (!cropState) return;
      const s = cropState;
      zoom = Math.max(100, Math.min(500, zoom));
      const newScale = s.coverScale * (zoom / 100);

      const ax = (anchorVpX == null) ? s.vpW / 2 : anchorVpX;
      const ay = (anchorVpY == null) ? s.vpH / 2 : anchorVpY;

      // Image point currently under the anchor (in natural px) — keep it fixed.
      const imgX = (ax - s.tx) / s.scale;
      const imgY = (ay - s.ty) / s.scale;

      s.scale = newScale;
      s.tx = ax - imgX * newScale;
      s.ty = ay - imgY * newScale;
      clampCropTranslate();
      renderCrop();

      const slider = document.getElementById('crop-zoom');
      if (slider && parseFloat(slider.value) !== zoom) slider.value = zoom;
      updateCropZoomLabel(zoom);
      updateCircleClipWarning();
    }

    function onCropZoom(val) { setCropZoom(parseFloat(val)); }
    function bumpCropZoom(delta) { if (cropState) setCropZoom(cropZoomPct() + delta); }
    function resetCrop() {
      if (!cropState) return;
      const s = cropState;
      s.scale = s.coverScale; // back to Fit
      s.tx = s.vpW / 2 - s.focalX * s.coverScale;
      s.ty = s.vpH / 2 - s.focalY * s.coverScale;
      clampCropTranslate();
      renderCrop();
      const slider = document.getElementById('crop-zoom');
      if (slider) slider.value = 100;
      updateCropZoomLabel(100);
      updateCircleClipWarning();
    }

    // #4 Choose the background fill ('transparent' keeps see-through; a hex flattens).
    function setCropBg(value) {
      if (cropState) cropState.bg = value;
      const isPreset = (value === 'transparent' || value === '#ffffff' || value === '#000000');
      document.querySelectorAll('.crop-bg-swatch').forEach(el => {
        const v = el.getAttribute('data-bg');
        const active = (v === value) || (v === 'custom' && !isPreset);
        el.classList.toggle('border-emerald-500', active);
        el.classList.toggle('border-transparent', !active);
      });
    }

    // #3 Show a warning when a CIRCLE crop would clip real content in the corners.
    function updateCircleClipWarning() {
      const warn = document.getElementById('crop-circle-warning');
      if (!warn) return;
      if (!cropState || cropState.shape !== 'circle') { warn.classList.add('hidden'); return; }
      warn.classList.toggle('hidden', !cropHasCornerContent());
    }

    // Render the current crop region (no clip) into a tiny canvas and look for
    // visible, non-background pixels in the four corners that fall OUTSIDE the
    // inscribed circle — i.e. content the circle mask would cut off.
    function cropHasCornerContent() {
      if (!cropState) return false;
      try {
        const s = cropState;
        const cropImg = document.getElementById('crop-image');
        const srcX = -s.tx / s.scale;
        const srcY = -s.ty / s.scale;
        const srcW = s.vpW / s.scale;
        const srcH = s.vpH / s.scale;

        const N = 48;
        const c = document.createElement('canvas'); c.width = N; c.height = N;
        const ctx = c.getContext('2d', { willReadFrequently: true });
        ctx.drawImage(cropImg, srcX, srcY, srcW, srcH, 0, 0, N, N);
        const data = ctx.getImageData(0, 0, N, N).data;

        const cors = [0, (N - 1), (N - 1) * N, (N - 1) * N + (N - 1)].map(i => i * 4);
        let br = 0, bg = 0, bb = 0, ba = 0;
        cors.forEach(i => { br += data[i]; bg += data[i + 1]; bb += data[i + 2]; ba += data[i + 3]; });
        br /= 4; bg /= 4; bb /= 4; ba /= 4;

        const r = N / 2, cx = (N - 1) / 2, cy = (N - 1) / 2;
        let hits = 0;
        for (let y = 0; y < N; y++) {
          for (let x = 0; x < N; x++) {
            const dx = x - cx, dy = y - cy;
            if (dx * dx + dy * dy <= r * r) continue; // inside the circle — kept
            const i = (y * N + x) * 4;
            if (data[i + 3] <= 32) continue;           // transparent — nothing to clip
            const diff = Math.abs(data[i] - br) + Math.abs(data[i + 1] - bg) + Math.abs(data[i + 2] - bb) + Math.abs(data[i + 3] - ba);
            if (diff > 70) hits++;
          }

        }

        return hits >= 6;
      } catch (e) { return false; }
    }

    // Drag + wheel + pinch handling for the crop viewport
    (function() {
      const vp = document.getElementById('crop-viewport');
      let dragging = false, startX, startY, startTx, startTy;
      let gridTimer = null;
      let pinch = null; // { startDist, startZoom, anchorVpX, anchorVpY }

      function flashGrid() {
        showCropGrid(true);
        if (gridTimer) clearTimeout(gridTimer);
        gridTimer = setTimeout(() => showCropGrid(false), 700);
      }

      function onDown(e) {
        if (!cropState) return;
        if (e.touches && e.touches.length === 2) {
          // Pinch start
          const r = vp.getBoundingClientRect();
          const t1 = e.touches[0], t2 = e.touches[1];
          const dx = t2.clientX - t1.clientX, dy = t2.clientY - t1.clientY;
          const cx = (t1.clientX + t2.clientX) / 2 - r.left;
          const cy = (t1.clientY + t2.clientY) / 2 - r.top;
          pinch = { startDist: Math.hypot(dx, dy), startZoom: cropZoomPct(), anchorVpX: cx, anchorVpY: cy };
          dragging = false;
          showCropGrid(true);
          e.preventDefault();
          return;
        }

        dragging = true;
        const pt = e.touches ? e.touches[0] : e;
        startX = pt.clientX; startY = pt.clientY;
        startTx = cropState.tx;
        startTy = cropState.ty;
        showCropGrid(true);
        e.preventDefault();
      }
      function onMove(e) {
        if (!cropState) return;
        if (pinch && e.touches && e.touches.length === 2) {
          const t1 = e.touches[0], t2 = e.touches[1];
          const dx = t2.clientX - t1.clientX, dy = t2.clientY - t1.clientY;
          const dist = Math.hypot(dx, dy);
          const newZoom = pinch.startZoom * (dist / pinch.startDist);
          setCropZoom(newZoom, pinch.anchorVpX, pinch.anchorVpY);
          e.preventDefault();
          return;
        }

        if (!dragging) return;
        const pt = e.touches ? e.touches[0] : e;
        cropState.tx = startTx + (pt.clientX - startX);
        cropState.ty = startTy + (pt.clientY - startY);
        clampCropTranslate();
        renderCrop();
        e.preventDefault();
      }
      function onUp() {
        dragging = false;
        pinch = null;
        flashGrid();
        updateCircleClipWarning();
      }
      function onWheel(e) {
        if (!cropState) return;
        e.preventDefault();
        const r = vp.getBoundingClientRect();
        const ax = e.clientX - r.left;
        const ay = e.clientY - r.top;
        // Smooth zoom: exponential so it feels right across the range
        const factor = Math.exp(-e.deltaY * 0.0015);
        setCropZoom(cropZoomPct() * factor, ax, ay);
        flashGrid();
      }

      vp.addEventListener('mousedown', onDown);
      vp.addEventListener('touchstart', onDown, { passive: false });
      vp.addEventListener('wheel', onWheel, { passive: false });
      document.addEventListener('mousemove', onMove);
      document.addEventListener('touchmove', onMove, { passive: false });
      document.addEventListener('mouseup', onUp);
      document.addEventListener('touchend', onUp);
      document.addEventListener('touchcancel', onUp);
    })();

    function applyCrop() {
      if (!cropState) return;
      const { shape, vpW, vpH, resolve, bg } = cropState;
      const cfg = CROP_CONFIGS[shape] || CROP_CONFIGS.square;
      const cropImg = document.getElementById('crop-image');

      // Map the frame back to natural image coords via the current transform.
      const srcX = -cropState.tx / cropState.scale;
      const srcY = -cropState.ty / cropState.scale;
      const srcW = vpW / cropState.scale;
      const srcH = vpH / cropState.scale;

      const canvas = document.createElement('canvas');
      canvas.width = cfg.w;
      canvas.height = cfg.h;
      const ctx = canvas.getContext('2d');
      // Better quality on downscale
      ctx.imageSmoothingEnabled = true;
      ctx.imageSmoothingQuality = 'high';

      if (shape === 'circle') {
        ctx.beginPath();
        ctx.arc(cfg.w / 2, cfg.h / 2, cfg.w / 2, 0, Math.PI * 2);
        ctx.closePath();
        ctx.clip();
      }

      // #4 Flatten transparency onto the chosen background (inside the clip for a
      // circle, so the corners stay transparent). 'transparent' keeps the alpha.
      if (bg && bg !== 'transparent') {
        ctx.fillStyle = bg;
        ctx.fillRect(0, 0, cfg.w, cfg.h);
      }

      ctx.drawImage(cropImg, srcX, srcY, srcW, srcH, 0, 0, cfg.w, cfg.h);
      let dataUrl = canvas.toDataURL('image/webp', 0.85);
      if (!dataUrl || !dataUrl.startsWith('data:image/webp')) {
        if (bg === 'transparent' || shape === 'circle') {
          dataUrl = canvas.toDataURL('image/png');
        }
 else {
          dataUrl = canvas.toDataURL('image/jpeg', 0.85);
        }

      }

      const cropModalEl = document.getElementById('logo-crop-modal');
      cropModalEl.classList.add('hidden');
      if (typeof ModalManager !== 'undefined' && typeof ModalManager.resetZIndex === 'function') {
        ModalManager.resetZIndex(cropModalEl);
      }
      const res = resolve;
      cropState = null;
      res(dataUrl);
    }

    function cancelCrop() {
      const cropModalEl = document.getElementById('logo-crop-modal');
      cropModalEl.classList.add('hidden');
      if (typeof ModalManager !== 'undefined' && typeof ModalManager.resetZIndex === 'function') {
        ModalManager.resetZIndex(cropModalEl);
      }
      if (cropState) {
        const rej = cropState.reject;
        cropState = null;
        rej(new Error('cancelled'));
      }
    }

    // Shape-specific logo upload handler — opens crop modal
    async function handleShapeLogoUpload(e, shape) {
      const file = e.target.files[0];
      if (!file) return;
      // Reset input so same file can be re-selected
      e.target.value = '';

      const reader = new FileReader();
      reader.onload = async (ev) => {
        try {
          const base64 = await openCropModal(ev.target.result, shape);
          const ids = getLogoShapeIds(shape);
          document.getElementById(ids.img).src = base64;
          document.getElementById(ids.img).classList.remove('hidden');
          document.getElementById(ids.placeholder).classList.add('hidden');
          document.getElementById(ids.base64).value = base64;
          document.getElementById(ids.removeBtn).classList.remove('hidden');

          // Auto-select this shape's radio
          const radio = document.querySelector(`input[name="logo_active_shape"][value="${shape}"]`);
          if (radio) radio.checked = true;
          onLogoShapeChange();

          const labels = { square: 'Square', rectangular: 'Rectangular', circle: 'Circle' };
          showToast(_t('services.toast_labels_shape_logo_cropped_succe', `${labels[shape]} logo cropped successfully!`, { shape: labels[shape] }), 'default');
        }
 catch (err) {
          if (err.message !== 'cancelled') {
            console.error('Logo processing failed:', err);
            showToast(_t('settings.logo_process_failed_try_another', 'Failed to process logo. Please try another image.'), 'default');
          }

        }

      };
      reader.onerror = () => showToast('Failed to read file.');
      reader.readAsDataURL(file);
    }

    function getLogoShapeIds(shape) {
      if (shape === 'square') return { img: 'settings-logo-img-square', placeholder: 'settings-logo-placeholder-square', base64: 'settings-logo-base64', removeBtn: 'remove-logo-btn-square', upload: 'settings-logo-upload-square' };
      if (shape === 'rectangular') return { img: 'settings-logo-img-rect', placeholder: 'settings-logo-placeholder-rect', base64: 'settings-logo-base64-rect', removeBtn: 'remove-logo-btn-rect', upload: 'settings-logo-upload-rect' };
      return { img: 'settings-logo-img-circle', placeholder: 'settings-logo-placeholder-circle', base64: 'settings-logo-base64-circle', removeBtn: 'remove-logo-btn-circle', upload: 'settings-logo-upload-circle' };
    }

    function removeShapeLogo(shape) {
      const ids = getLogoShapeIds(shape);
      document.getElementById(ids.img).src = '';
      document.getElementById(ids.img).classList.add('hidden');
      document.getElementById(ids.placeholder).classList.remove('hidden');
      document.getElementById(ids.base64).value = '';
      document.getElementById(ids.removeBtn).classList.add('hidden');
      const fileInput = document.getElementById(ids.upload);
      if (fileInput) fileInput.value = '';
      onLogoShapeChange();
    }

    async function handleFaviconUpload(e) {
      const file = e.target.files[0];
      if (!file) return;
      e.target.value = '';

      try {
        const img = new Image();
        const url = URL.createObjectURL(file);
        img.onload = () => {
          URL.revokeObjectURL(url);
          const canvas = document.createElement('canvas');
          canvas.width = 128;
          canvas.height = 128;
          const ctx = canvas.getContext('2d');
          ctx.imageSmoothingEnabled = true;
          ctx.imageSmoothingQuality = 'high';
          ctx.drawImage(img, 0, 0, 128, 128);
          const base64 = canvas.toDataURL('image/png');

          const imgEl = document.getElementById('settings-favicon-img');
          const phEl = document.getElementById('settings-favicon-placeholder');
          const b64El = document.getElementById('settings-favicon-base64');
          const rmBtn = document.getElementById('remove-favicon-btn');

          if (imgEl && phEl && b64El) {
            imgEl.src = base64;
            imgEl.classList.remove('hidden');
            phEl.classList.add('hidden');
            b64El.value = base64;
            if (rmBtn) rmBtn.classList.remove('hidden');

            const favLink = document.getElementById('app-favicon');
            if (favLink) favLink.href = base64;
            showToast(_t('settings.general_toast_favicon_updated', 'Favicon updated! Save settings to persist.'), 'default');
          }

        }
;
        img.onerror = () => {
          URL.revokeObjectURL(url);
          showToast(_t('settings.brand_asset_favicon_load_failed', 'Failed to load favicon image.'), 'default');
        }
;
        img.src = url;
      } catch (err) {
        console.error('Favicon processing failed:', err);
        showToast(_t('settings.brand_asset_favicon_process_failed', 'Failed to process favicon.'), 'default');
      }
    }

    function removeFavicon() {
      const imgEl = document.getElementById('settings-favicon-img');
      const phEl = document.getElementById('settings-favicon-placeholder');
      const b64El = document.getElementById('settings-favicon-base64');
      const rmBtn = document.getElementById('remove-favicon-btn');

      if (imgEl) { imgEl.src = ''; imgEl.classList.add('hidden'); }
      if (phEl) phEl.classList.remove('hidden');
      if (b64El) b64El.value = '';
      if (rmBtn) rmBtn.classList.add('hidden');
      const fileInput = document.getElementById('settings-favicon-upload');
      if (fileInput) fileInput.value = '';

      const favLink = document.getElementById('app-favicon');
      if (favLink) favLink.href = "data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'><rect width='100' height='100' rx='20' fill='%2310b981'/><text x='50%' y='55%' dominant-baseline='middle' text-anchor='middle' font-size='50' font-family='sans-serif' font-weight='900' fill='white'>P</text></svg>";
      showToast(_t('settings.favicon_removed_default_restored', 'Favicon removed. Default icon restored.'), 'default');
    }

    function getActiveLogoShape() {
      const checked = document.querySelector('input[name="logo_active_shape"]:checked');
      return checked ? checked.value : 'square';
    }

    function getActiveLogoBase64() {
      const shape = getActiveLogoShape();
      const ids = getLogoShapeIds(shape);
      return document.getElementById(ids.base64)?.value || '';
    }

    // Get active logo from config object (used in updateUI, tickets, PDFs)
    function getConfigActiveLogo() {
      const shape = config.logo_active_shape || 'square';
      if (shape === 'rectangular') return config.business_logo_rect || '';
      if (shape === 'circle') return config.business_logo_circle || '';
      return config.business_logo || '';
    }

    function onLogoShapeChange() {
      const activeLogo = getActiveLogoBase64();
      // Update sidebar preview immediately
      const sidebarLogoContainer = document.getElementById('sidebar-logo-container');
      const sidebarLogoImg = document.getElementById('sidebar-logo-img');
      const sidebarLogoFallback = document.getElementById('sidebar-logo-fallback');
      if (sidebarLogoContainer && sidebarLogoImg) {
        if (activeLogo) {
          sidebarLogoImg.src = activeLogo;
          sidebarLogoContainer.classList.remove('hidden');
          if (sidebarLogoFallback) sidebarLogoFallback.classList.add('hidden');
          // Adjust sidebar logo shape
          const shape = getActiveLogoShape();
          sidebarLogoContainer.className = sidebarLogoContainer.className
            .replace(/rounded-\S+/g, '')
            .replace(/w-\d+/g, '')
            .replace(/h-\d+/g, '');
          if (shape === 'circle') {
            sidebarLogoContainer.className += ' w-14 h-14 rounded-full';
          }
 else if (shape === 'rectangular') {
            sidebarLogoContainer.className += ' w-24 h-12 rounded-xl';
          }
 else {
            sidebarLogoContainer.className += ' w-14 h-14 rounded-2xl';
          }

        }
 else {
          sidebarLogoContainer.classList.add('hidden');
          if (sidebarLogoFallback) sidebarLogoFallback.classList.remove('hidden');
        }

      }

      // Highlight selected shape preview with ring
      ['square', 'rectangular', 'circle'].forEach(s => {
        const previewId = s === 'square' ? 'settings-logo-preview-square' : s === 'rectangular' ? 'settings-logo-preview-rect' : 'settings-logo-preview-circle';
        const el = document.getElementById(previewId);
        if (el) {
          if (s === getActiveLogoShape()) {
            el.classList.remove('border-slate-300');
            el.classList.add('border-emerald-500', 'ring-2', 'ring-emerald-200');
          }
 else {
            el.classList.add('border-slate-300');
            el.classList.remove('border-emerald-500', 'ring-2', 'ring-emerald-200');
          }

        }

      });
      updateLoginSettingsMiniPreview();
    }

