    // =========================================================================
    // APPLE DYNAMIC ISLAND & FLOATING ALERT BANNERS STUDIO (Mission 84)
    // =========================================================================
    let activeFloatingBanners = new Map(); // bannerId -> { element, timer }

    // Persistent Seen Registry to prevent re-toasting the same notification across auto-dismisses, page navigations, and reloads
    function getSeenFloatingBannerIds() {
      try {
        const stored = sessionStorage.getItem('pos_seen_floating_banners');
        return stored ? new Set(JSON.parse(stored)) : new Set();
      } catch (e) {
        return new Set();
      }
    }

    function markFloatingBannerAsSeen(id) {
      if (!id) return;
      try {
        const seen = getSeenFloatingBannerIds();
        seen.add(String(id));
        const arr = Array.from(seen).slice(-300); // Retain last 300 IDs
        sessionStorage.setItem('pos_seen_floating_banners', JSON.stringify(arr));
      } catch (e) {}
    }

    function isFloatingBannerSeen(id) {
      if (!id) return false;
      return getSeenFloatingBannerIds().has(String(id));
    }
    window.isFloatingBannerSeen = isFloatingBannerSeen;
    window.markFloatingBannerAsSeen = markFloatingBannerAsSeen;

    function getFloatingBannerConfig(fromLiveDom = false) {
      if (fromLiveDom && document.getElementById('settings-notif-floating-enabled')) {
        const enabledEl = document.getElementById('settings-notif-floating-enabled');
        const modeEl = document.getElementById('settings-notif-floating-mode');
        const durEl = document.getElementById('settings-notif-floating-duration');
        const posEl = document.getElementById('settings-notif-floating-position');

        return {
          enabled: enabledEl ? enabledEl.checked : true,
          mode: modeEl ? modeEl.value : 'all',
          duration: durEl ? parseInt(durEl.value, 10) : 6,
          position: posEl ? posEl.value : 'top_right',
          categories: {
            security: document.getElementById('settings-notif-floating-security') ? document.getElementById('settings-notif-floating-security').checked : true,
            schedules: document.getElementById('settings-notif-floating-schedules') ? document.getElementById('settings-notif-floating-schedules').checked : true,
            debts: document.getElementById('settings-notif-floating-debts') ? document.getElementById('settings-notif-floating-debts').checked : true,
            suppliers: document.getElementById('settings-notif-floating-suppliers') ? document.getElementById('settings-notif-floating-suppliers').checked : true,
            bills: document.getElementById('settings-notif-floating-bills') ? document.getElementById('settings-notif-floating-bills').checked : true,
            stock: document.getElementById('settings-notif-floating-stock') ? document.getElementById('settings-notif-floating-stock').checked : true,
            messages: document.getElementById('settings-notif-floating-messages') ? document.getElementById('settings-notif-floating-messages').checked : true
          }

        }
;
      }

      const u = window._posUserNotifSettings || {};
      const g = window._posGlobalSettings || config || {};

      const resolveBool = (userVal, globalVal, fallback = true) => {
        const val = (userVal !== undefined && userVal !== null) ? userVal : globalVal;
        return (val !== undefined && val !== null) ? !!parseInt(val) : fallback;
      };

      const resolveInt = (userVal, globalVal, fallback = 6) => {
        const val = (userVal !== undefined && userVal !== null) ? userVal : globalVal;
        const parsed = (val !== undefined && val !== null) ? parseInt(val, 10) : NaN;
        return isNaN(parsed) ? fallback : parsed;
      };

      const resolveStr = (userVal, globalVal, fallback = 'top_right') => {
        return (userVal || globalVal) || fallback;
      };

      return {
        enabled: resolveBool(u.notif_floating_enabled, g.notif_floating_enabled, true),
        mode: resolveStr(u.notif_floating_mode, g.notif_floating_mode, 'all'),
        duration: resolveInt(u.notif_floating_duration, g.notif_floating_duration, 6),
        position: resolveStr(u.notif_floating_position, g.notif_floating_position, 'top_right'),
        categories: {
          security: resolveBool(u.notif_floating_security, g.notif_floating_security, true),
          schedules: resolveBool(u.notif_floating_schedules, g.notif_floating_schedules, true),
          debts: resolveBool(u.notif_floating_debts, g.notif_floating_debts, true),
          suppliers: resolveBool(u.notif_floating_suppliers, g.notif_floating_suppliers, true),
          bills: resolveBool(u.notif_floating_bills, g.notif_floating_bills, true),
          stock: resolveBool(u.notif_floating_stock, g.notif_floating_stock, true),
          messages: resolveBool(u.notif_floating_messages, g.notif_floating_messages, true)
        }

      };
    }
    window.getFloatingBannerConfig = getFloatingBannerConfig;

