    async function handleLoginBgImageUpload(e) {
      const file = e.target.files && e.target.files[0];
      if (!file) return;
      if (!file.type.startsWith('image/')) {
        showToast(_t('settings.login_bg_invalid_image', 'Please select a valid image file'), 'default');
        return;
      }
      try {
        const compressed = await compressImageFile(file, { maxWidth: 1920, maxHeight: 1080, quality: 0.85, type: 'image/webp' });
        const base64 = compressed && compressed.fileData ? compressed.fileData : null;
        if (!base64) throw new Error('Compression produced empty output');
        document.getElementById('settings-login-bg-image-base64').value = base64;
        const img = document.getElementById('settings-login-bg-img');
        const ph = document.getElementById('settings-login-img-placeholder');
        const rm = document.getElementById('remove-login-bg-img-btn');
        if (img && ph) {
          img.src = base64;
          img.classList.remove('hidden');
          ph.classList.add('hidden');
        }

        if (rm) rm.classList.remove('hidden');
        updateLoginSettingsMiniPreview();
      } catch (err) {
        console.error('Login background compression failed:', err);
        showToast(_t('settings.login_bg_process_failed', 'Failed to process login background image'), 'default');
      }
    }

    function removeLoginBgImage() {
      document.getElementById('settings-login-bg-image-base64').value = '';
      const img = document.getElementById('settings-login-bg-img');
      const ph = document.getElementById('settings-login-img-placeholder');
      const rm = document.getElementById('remove-login-bg-img-btn');
      const fileInput = document.getElementById('settings-login-bg-upload');
      if (img && ph) {
        img.src = '';
        img.classList.add('hidden');
        ph.classList.remove('hidden');
      }
      if (rm) rm.classList.add('hidden');
      if (fileInput) fileInput.value = '';
      updateLoginSettingsMiniPreview();
    }

