          copyBtn.textContent = '✓ ' + window.__t('settings.recovery_btn_copied_state', 'Copied!');
          copyBtn.classList.replace('bg-indigo-600', 'bg-emerald-600');
          showToast(window.__t('settings.recovery_copied_toast', 'Recovery token copied to clipboard!'));
          // Log copy event to backend audit trail
