    function updateRecoveryWatermarkBanner() {
      const banner = document.getElementById('recovery-floating-watermark-banner');
      const pillsContainer = document.getElementById('recovery-watermark-pills-container');
      if (!banner || !pillsContainer) return;

      // Exclude recovery floating watermark on Messages page across all screen sizes (PC & Mobile)
      const activePg = (typeof currentPage !== 'undefined' && currentPage) ? currentPage : (window.currentPage || document.documentElement.getAttribute('data-active-page'));
      if (activePg === 'messages') {
        banner.classList.add('hidden');
        return;
      }

      // Honor session dismissal if user swiped it away in this session
      try {
        if (sessionStorage.getItem('pos_recovery_watermark_dismissed') === '1') {
          banner.classList.add('hidden');
          return;
        }
      } catch (e) {}

      const effectiveUser = (typeof currentUser !== 'undefined' && currentUser) ? currentUser : (window.currentUser || null);
      if (!effectiveUser) {
        banner.classList.add('hidden');
        return;
      }

      const isSuperAdmin = Boolean(
        effectiveUser.isSuperAdmin ||
        effectiveUser.is_super_admin === true ||
        effectiveUser.is_super_admin === 1 ||
        effectiveUser.is_super_admin === '1' ||
        effectiveUser.role === 'super_admin' ||
        String(effectiveUser.id || effectiveUser.__backendId || '') === '1'
      );

      // ZERO-FLASH INVARIANT: Never display the watermark before required recovery statuses are fetched & resolved!
      if (window._hasPersonalRecoveryCode === undefined) {
        banner.classList.add('hidden');
        return;
      }
      if (isSuperAdmin && window._hasMasterRecoveryCode === undefined) {
        banner.classList.add('hidden');
        return;
      }

      const personalHasCode = Boolean(window._hasPersonalRecoveryCode);
      const masterHasCode = Boolean(window._hasMasterRecoveryCode);

      let masterMissing = false;
      let personalMissing = !personalHasCode;

      if (isSuperAdmin) {
        masterMissing = !masterHasCode;
      }

      if (!masterMissing && !personalMissing) {
        banner.classList.add('hidden');
        return;
      }

      let pillsHtml = '';
      if (isSuperAdmin && masterMissing && personalMissing) {
        pillsHtml = `
          <div class="flex items-center gap-1.5 shrink-0">
            <span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-rose-500/20 text-rose-700 dark:text-rose-300 border border-rose-500/30 text-[10px] font-black uppercase">
              <span>👑</span> <span>${escapeHtml(window.__t ? window.__t('settings.recovery_watermark_tag_master', 'Root Master') : 'Root Master')}</span>
            </span>
            <span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-amber-500/20 text-amber-800 dark:text-amber-300 border border-amber-500/30 text-[10px] font-black uppercase">
              <span>🔑</span> <span>${escapeHtml(window.__t ? window.__t('settings.recovery_watermark_tag_personal', 'Personal') : 'Personal')}</span>
            </span>
          </div>
          <span class="text-xs font-semibold text-amber-900 dark:text-amber-200 line-clamp-2 sm:line-clamp-none break-words">${escapeHtml(window.__t ? window.__t('settings.recovery_watermark_dual_missing', 'Root Master & Personal Recovery Keys Unset') : 'Root Master & Personal Recovery Keys Unset')}</span>
        `;
      } else if (isSuperAdmin && masterMissing) {
        pillsHtml = `
          <div class="flex items-center gap-1.5 shrink-0">
            <span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-rose-500/20 text-rose-700 dark:text-rose-300 border border-rose-500/30 text-[10px] font-black uppercase">
              <span>👑</span> <span>${escapeHtml(window.__t ? window.__t('settings.recovery_watermark_tag_master', 'Root Master') : 'Root Master')}</span>
            </span>
          </div>
          <span class="text-xs font-semibold text-amber-900 dark:text-amber-200 line-clamp-2 sm:line-clamp-none break-words">${escapeHtml(window.__t ? window.__t('settings.recovery_watermark_master_missing', 'Root Master Recovery Key Missing / Consumed') : 'Root Master Recovery Key Missing / Consumed')}</span>
        `;
      } else {
        pillsHtml = `
          <div class="flex items-center gap-1.5 shrink-0">
            <span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-amber-500/20 text-amber-800 dark:text-amber-300 border border-amber-500/30 text-[10px] font-black uppercase">
              <span>🔑</span> <span>${escapeHtml(window.__t ? window.__t('settings.recovery_watermark_tag_personal', 'Personal') : 'Personal')}</span>
            </span>
          </div>
          <span class="text-xs font-semibold text-amber-900 dark:text-amber-200 line-clamp-2 sm:line-clamp-none break-words">${escapeHtml(window.__t ? window.__t('settings.recovery_watermark_personal_missing', 'Personal Recovery Key Unconfigured / Consumed') : 'Personal Recovery Key Unconfigured / Consumed')}</span>
        `;
      }

      pillsContainer.innerHTML = pillsHtml;
      banner.style.transform = '';
      banner.style.opacity = '';
      banner.style.transition = '';
      banner.classList.remove('hidden');

      // Attach universal swipe/grab physics engine to floating recovery banner
      if (!banner.__swipeEngine && typeof ToastSwipePhysicsEngine === 'function') {
        banner.__swipeEngine = new ToastSwipePhysicsEngine(banner, {
          thresholdX: 70,
          thresholdY: 45,
          flickVelocityThreshold: 0.35,
          onDismiss: () => {
            banner.classList.add('hidden');
            banner.style.transform = '';
            banner.style.opacity = '';
            banner.style.transition = '';
            try { sessionStorage.setItem('pos_recovery_watermark_dismissed', '1'); } catch (e) {}
          }
        });
      }
    }
    window.updateRecoveryWatermarkBanner = updateRecoveryWatermarkBanner;

