    function getSyslogModuleLabel(module) {
      if (!module) return '—';
      const modKeyMap = {
        auth: 'settings.syslog_mod_auth',
        users: 'settings.syslog_mod_users',
        products: 'settings.syslog_mod_products',
        categories: 'settings.syslog_mod_categories',
        customers: 'settings.syslog_mod_customers',
        orders: 'settings.syslog_mod_orders',
        purchases: 'settings.syslog_mod_purchases',
        settings: 'settings.syslog_mod_settings',
        service_templates: 'settings.syslog_mod_templates',
        prints: 'settings.syslog_mod_prints',
        bill_groups: 'settings.syslog_mod_groups',
        recurring_bills: 'settings.syslog_mod_circles',
        archived_bills: 'settings.syslog_mod_archived',
        recurring_bill_cycles: 'settings.syslog_mod_period',
        partner_settlements: 'settings.syslog_mod_settlements',
        expenses: 'settings.syslog_mod_expenses',
        operating_expenses: 'settings.syslog_mod_expenses',
        cash_vault: 'settings.syslog_mod_vault'
      };
      const key = modKeyMap[module];
      const fallback = SYSLOG_MODULE_LABELS[module] || module || '—';
      return (key && window.__t) ? window.__t(key, fallback) : fallback;
    }

