        const printedBy = (typeof currentUser !== 'undefined' && currentUser) ? currentUser.username : systemUserLabel;
        const businessName = config.business_name || 'POS System';
        const businessDesc = config.description || (window.__t ? window.__t('settings.syslog_pdf_report_desc', 'System Activity & Audit Log Report') : 'System Activity & Audit Log Report');
