                <div style="font-size:14px; font-weight:900; margin-bottom:4px;">
                  ${escapeHtml(product.name || purchase.name || _tTick('purchases.modals_forms_acquired_coin', _tTick('settings.ticket_acquired_coin_default', 'Acquired Coin')))}
                </div>
                <table>
                  <tr style="border-bottom:1px dashed #000;">
                    <td style="padding-bottom:3px;">${_tTick('settings.ticket_th_qty_valuation', 'QTY & VALUATION')}</td>
                    <td style="text-align:${isRtl ? 'left' : 'right'}; padding-bottom:3px;">${_tTick('settings.ticket_th_total_value', 'TOTAL VALUE')}</td>
                  </tr>
                  <tr>
                    <td style="padding-top:4px;"><bdi dir="ltr">${formatQuantity(purchase.quantity, product.displayDecimals)}</bdi> x <bdi dir="ltr">${formatPrice(purchase.price || 0, product.displayDecimals).replace(config.currency_symbol, '')}</bdi></td>
