              const sellerWholesaleCost = exactAdd(sellerStockCost, outlaysCost);
              let sellerTotalNetProfit = exactAdd(sellerStockProfit, totalSellerPartnerCommission);
              sellerTotalNetProfit = exactAdd(sellerTotalNetProfit, exactAdd(serviceLaborProfit, outlaysProfit));

              const isCompletedOrPaid = order.status === 'completed' || Decimal.comp(fi?.orderPaid || '0', fi?.actualRevenue || '0') >= 0;
              let extraProfitApplied = '0';
