                if (userSettlements && userSettlements.length > 0) {
                  if (userSettlements.some(s => s.acceptance_status === 'refused' || s.status === 'refused')) {
                    uStatus = 'refused';
                    const refStl = userSettlements.find(s => s.acceptance_status === 'refused' || s.status === 'refused');
                    refusalNote = refStl?.refusal_reason || order.refusal_reason || '';
                  }
 else if (userSettlements.every(s => s.acceptance_status === 'accepted' || s.status === 'settled' || s.status === 'claimed')) {
                    uStatus = 'accepted';
                  }
 else {
                    uStatus = 'pending';
                  }

                }
 else if (u.isOwner || String(u.userId) === String(order.created_by)) {
                  uStatus = 'accepted';
                }


                let statusBadge = `<span class="bento-pill amber">${_tRep('reports.pending_review_badge', '⏳ Pending Review')}</span>`;
