      // Bulletproof Chromium Print Lifecycle Engine:
      // 1. Keeps initiator window alive during Print Preview interaction (prevents Aw, Snap! / Sad Face crash on click)
      // 2. Awaits complete image decoding so base64 custody media renders crisply without rasterizer stalls
      // 3. Closes window cleanly via 'afterprint' ONLY after user finishes or cancels printing
      const printScript = `
      <scrip` + `t>
        (function() {
          var printed = false;
          function executePrint() {
            if (printed) return;
            printed = true;
            try {
              document.title = '${escapedBizName} — Order Report #${cleanUID}';
            }
 catch (e) {}

            // Chromium standard: Clean close ONLY after print dialog dismissal
            window.addEventListener('afterprint', function() {
              setTimeout(function() {
                try { window.close(); } catch (e) {}
              }
, 300);
            }
);

            setTimeout(function() {
              try { window.print(); } catch (e) {}
            }, 50);
          }


          window.addEventListener('load', function() {
            var imgs = Array.from(document.images);
            if (!imgs.length) {
              executePrint();
              return;
            }

            var loaded = 0;
            var total = imgs.length;
            function onImgDone() {
              loaded++;
              if (loaded >= total) executePrint();
            }

            imgs.forEach(function(img) {
              if (img.complete && img.naturalWidth !== 0) {
                onImgDone();
              }
 else {
                img.addEventListener('load', onImgDone);
                img.addEventListener('error', onImgDone);
              }

            }
);
            // Safety timeout: Never hang if an external resource or base64 stalls
            setTimeout(executePrint, 1200);
          }
);
        }
)();
      </scrip` + `t>`;

