    async function deleteBackup(id, uid) {
      const isAdmin = !!(currentUser && (currentUser.is_admin || currentUser.role === 'admin'));
      if (!isAdmin) {
        showToast(window.__t ? window.__t('settings.admin_privileges_required', 'Administrator privileges required') : 'Administrator privileges required', 'error');
        return;
      }

      const confirmed = await showSystemConfirmModal({
        title: window.__t('settings.backup_delete_modal_title', 'Delete Backup'),
        message: window.__t('settings.backup_delete_confirm_message', 'Delete backup {uid}? This action cannot be undone.', { uid }),
        confirmText: window.__t('settings.backup_delete_modal_title', 'Delete Backup'),
        type: 'danger',
        details: [
          { label: window.__t('settings.backup_delete_detail_uid_label', 'Backup UID'), value: uid }
        ]
      });
      if (!confirmed) return;
      try {
        const data = await apiRequest('/api/backups/' + id, { method: 'DELETE' });
        if (data.error) {
          showToast(data.error || data.message || (window.__t ? window.__t('settings.backup_operation_failed', 'Operation failed') : 'Operation failed'), 'error');
        }
 else {
          showToast(window.__t('settings.backup_toast_deleted_success', 'Backup deleted'), 'success');
          loadBackups();
        }

      } catch (e) { showToast(window.__t ? window.__t('settings.backup_toast_delete_failed_with_message', 'Delete failed: {message}', { message: e.message }) : 'Delete failed: ' + e.message, 'error'); }
    }

