    // POS Global Keyboard Shortcuts
    document.addEventListener('keydown', function(e) {
      const activeEl = document.activeElement;
      const isTyping = activeEl && (activeEl.tagName === 'INPUT' || activeEl.tagName === 'TEXTAREA' || activeEl.tagName === 'SELECT');

      // 0. ? key: Open POS Shortcuts Modal (when not typing in an input)
      if ((e.key === '?' || (e.shiftKey && e.key === '/')) && !isTyping && currentPage === 'pos') {
        e.preventDefault();
        showPOSShortcutsModal();
        return;
      }

      // 1. Escape: Close topmost modal
      if (e.key === 'Escape') {
        if (ModalManager.closeTopmost()) {
          e.preventDefault();
          return;
        }

        // If no modal open and in POS page, clear the product search input
        const searchInput = document.getElementById('pos-product-search');
        if (searchInput && document.activeElement === searchInput && searchInput.value) {
          searchInput.value = '';
          if (typeof filterPOSProducts === 'function') filterPOSProducts();
          e.preventDefault();
        }

      }

      // If not on POS page, do not trigger POS transaction shortcuts
      if (currentPage !== 'pos') return;

      // 2. F2: Focus and select POS Product Search
      if (e.key === 'F2') {
        const searchInput = document.getElementById('pos-product-search');
        if (searchInput) {
          e.preventDefault();
          searchInput.focus();
          searchInput.select();
        }

      }

      // 3. F4: Trigger Complete Sale (if cart has items and not currently typing in a modal)
      if (e.key === 'F4' && !ModalManager.isAnyModalOpen()) {
        e.preventDefault();
        const completeBtn = document.getElementById('complete-sale-btn');
        if (completeBtn && !completeBtn.disabled) {
          completeBtn.click();
        }
 else if (typeof showToast === 'function') {
          showToast(_t('pos.toast_cart_empty', 'Cart is empty'), 'warning');
        }

      }

      // 4. F8: Trigger Credit Sale (Pending Money) - guarded in Remake mode
      if (e.key === 'F8' && !ModalManager.isAnyModalOpen()) {
        e.preventDefault();
        if (window._activeRemakeOrderId) return;
        const creditBtn = document.getElementById('complete-sale-credit-btn');
        if (creditBtn && !creditBtn.disabled && !creditBtn.classList.contains('hidden')) {
          creditBtn.click();
        }
 else if (typeof showToast === 'function') {
          showToast(_t('pos.toast_cart_empty', 'Cart is empty'), 'warning');
        }

      }
    });

