    // ── Custom Services Full-Page Workspace Engine ───────────────────────────
    function updateServicesPage() {
      const currentUid = currentUser?.__backendId || currentUser?.id || 1;

      // 1. Ensure provider name is set to currentUser
      if (currentUser) {
        const provInput = document.getElementById('custom-provider-name');
        if (provInput && !provInput.value) {
          provInput.value = currentUser.username;
        }

      }

      // 2. Ensure customer dropdown is populated
      const select = document.getElementById('custom-customer');
      if (select && select.options.length <= 1) {
        const customers = getCustomers();
        if (customers.length === 0) {
          select.innerHTML = '<option value="">No customers available</option>';
        }
 else {
          select.innerHTML = '<option value="">Choose a customer...</option>' +
            customers.map(c => `<option value="${c.__backendId}">${escapeHtml(c.name)} - ${escapeHtml(c.phone || c.email || 'No contact')}</option>`).join('');
        }

        syncCustomerChip('custom-customer');
      }

      // 3. Ensure profit owner is populated and lead team is initialized
      const ownerSelect = document.getElementById('custom-owner');
      if (ownerSelect && (ownerSelect.options.length === 0 || !ownerSelect.value)) {
        populateUserSelect('custom-owner', currentUid);
      }
      if (!Array.isArray(customTeam) || customTeam.length === 0) {
        customTeam = [
          { user_id: currentUid, role: 'Lead', share_pct: '100', profit: '0' }
        ];
      }

      // 4. Setup precision for customer paid input
      const paidInput = document.getElementById('custom-customer-paid');
      if (paidInput) {
        const precision = config && config.display_decimals !== undefined ? config.display_decimals : 2;
        const stepValue = (1 / Math.pow(10, precision)).toFixed(precision);
        paidInput.step = stepValue;
        enforcePrecision(paidInput, precision);
      }

      // 5. Render active parts
      renderCustomTeam();
      renderChecklist();
      renderManualCostRows();
      updateCustomSaleProductsList();
      updateCustomSaleSummary();
      loadServiceTemplates();
      updateCustomServiceContextBanner();
      if (typeof resetDeviceIntakeForm === 'function') {
        resetDeviceIntakeForm();
      }
    }

