    // --- Dynamic Composer Button Swapper (Mic <-> Send) ---
    function handleChatInputChanged(el) {
      if (typeof recordChatActivity === 'function') recordChatActivity();
      autoResizeChatTextarea(el);
      const text = el.value.trim();
      const hasContent = text.length > 0 || stagedAttachments.length > 0;
      const voiceBtn = document.getElementById('chat-voice-start-btn');
      const sendBtn = document.getElementById('chat-send-btn');
      if (voiceBtn && sendBtn) {
        if (hasContent) {
          voiceBtn.classList.add('hidden');
          sendBtn.classList.remove('hidden');
        }
 else {
          voiceBtn.classList.remove('hidden');
          sendBtn.classList.add('hidden');
        }

      }
    }
    window.handleChatInputChanged = handleChatInputChanged;

    function resetComposerActionBtn() {
      const voiceBtn = document.getElementById('chat-voice-start-btn');
      const sendBtn = document.getElementById('chat-send-btn');
      if (voiceBtn && sendBtn) {
        const input = document.getElementById('chat-message-input');
        const hasContent = (input && input.value.trim().length > 0) || stagedAttachments.length > 0;
        if (hasContent) {
          voiceBtn.classList.add('hidden');
          sendBtn.classList.remove('hidden');
        }
 else {
          voiceBtn.classList.remove('hidden');
          sendBtn.classList.add('hidden');
        }

      }
    }
