    window.payManualCostFromOrder = async function(orderId, costIndex) {
      try {
        if (!orderId) return;
        const res = await apiRequest(`/api/partner-settlements?order_id=${orderId}`).catch(() => null);
        let targetId = null;
        let targetUid = null;
        if (res && res.settlements && Array.isArray(res.settlements)) {
          const mySettlements = res.settlements.filter(s => 
            String(s.payee_user_id) === String(currentUser?.id) &&
            (s.settlement_type === 'manual_cost_recovery' || s.settlement_type === 'manual_cost_markup') &&
            s.status !== 'cancelled' &&
            s.payment_demand_status !== 'paid'
          );
          // Match exact cost_index first if provided
          if (costIndex !== undefined && costIndex !== null) {
            const indexMatch = mySettlements.find(s => {
              const det = typeof s.details === 'string' ? JSON.parse(s.details || '{}') : (s.details || {});
              return det.cost_index !== undefined && String(det.cost_index) === String(costIndex);
            }
);
            if (indexMatch) {
              targetId = indexMatch.id;
              targetUid = indexMatch.uid || indexMatch.settlement_number;
            }

          }

          if (!targetId) {
            const awaiting = mySettlements.find(s => s.payment_demand_status === 'awaiting_payment');
            if (awaiting) {
              targetId = awaiting.id;
              targetUid = awaiting.uid || awaiting.settlement_number;
            }
 else if (mySettlements.length > 0) {
              targetId = mySettlements[0].id;
              targetUid = mySettlements[0].uid || mySettlements[0].settlement_number;
            }

          }

        }

        if (!targetId) {
          showToast(_t('notifications.history_ledgers_no_pending_manual_cost_statement_found', 'No pending manual cost statement found for this outlay'), 'info');
          return;
        }

        await window.handleCustomServicePayment(targetId, null, targetUid);
        if (typeof showOrderDetails === 'function') {
          showOrderDetails(orderId);
        }

      } catch (e) {
        console.error(e);
      }
    };

