    async function openPayBillCycleModalDirect(cycleId) {
      showPage('bills');
      try {
        await loadExpensesData();
        let found = null;
        for (const bill of recurringBillsCache) {
          if (bill.cycles) {
            const cyc = bill.cycles.find(c => c.id === cycleId);
            if (cyc) { found = { cycle: cyc, bill: bill }; break; }
          }

        }

        if (found) {
          openPayBillCycleModal(found.cycle, found.bill);
        }

      } catch (e) {
        console.error(e);
      }
    }

    async function handleNotificationAction(url, notifId) {
      if (notifId) {
        await markNotificationRead(notifId);
      }
      if (!url) return;

      if (url.startsWith('#order-details:')) {
        const raw = url.replace('#order-details:', '');
        const [orderIdPart, queryPart] = raw.split('?');
        const orderId = parseInt(orderIdPart, 10);

        let order = (typeof ordersCache !== 'undefined' && Array.isArray(ordersCache)) 
          ? ordersCache.find(o => String(o.__backendId) === String(orderId) || String(o.id) === String(orderId) || String(o.uid) === String(orderId)) 
          : null;
        if (!order && typeof loadAllData === 'function') {
          try { await loadAllData(); } catch (_) {}
        }

        if (typeof showOrderDetails === 'function') {
          showOrderDetails(orderId);
          setTimeout(() => {
            // GAP-11 fix: inspect queryPart to scroll to the correct section
            const params = new URLSearchParams(queryPart || '');
            const step = params.get('step');
            let targetEl = null;
            if (step === 'claim') {
              targetEl = document.getElementById('order-release-claim-timeline-dock');
            }

            if (!targetEl) {
              // Default: scroll to the consignment dock (covers step=approval and no step)
              targetEl = document.getElementById('order-partner-consignment-dock');
            }

            if (targetEl) {
              targetEl.scrollIntoView({ behavior: 'smooth', block: 'start' });
            }

          }
, 350);
        }

        return;
      }

      if (url === '#security-forensics' || url.startsWith('#security-forensics:')) {
        const target = url.includes(':') ? url.split(':')[1] : '';
        if (typeof openSecurityForensicsModal === 'function') {
          openSecurityForensicsModal(target);
        }
 else if (typeof window.openSecurityForensicsModal === 'function') {
          window.openSecurityForensicsModal(target);
        }
 else {
          showPage('settings?tab=security');
        }

        return;
      }

      let targetUrl = url;
      if (targetUrl.startsWith('#page-')) {
        targetUrl = targetUrl.replace('#page-', '');
      } else if (targetUrl.startsWith('#')) {
        targetUrl = targetUrl.substring(1);
      }

      if (targetUrl.startsWith('messages')) {
        const match = targetUrl.match(/conversation_id=(\d+)/);
        showPage('messages');
        if (match && match[1]) {
          setTimeout(() => { openConversation(parseInt(match[1])); }, 300);
        }

      } else {
        showPage(targetUrl);
      }
    }
    window.handleNotificationAction = handleNotificationAction;

