    let pendingNotificationPermanentDelete = null; // { mode: 'single'|'bulk'|'empty_trash', id: null, ids: [] }

    function openNotificationPermanentDeleteModal(mode, payload = {}) {
      pendingNotificationPermanentDelete = { mode, ...payload };
      const modal = document.getElementById('notif-permanent-delete-modal');
      const titleEl = document.getElementById('notif-delete-modal-title');
      const subEl = document.getElementById('notif-delete-modal-subtitle');
      const confirmBtnText = document.getElementById('notif-delete-modal-confirm-text');

      const _t = (k, def, p) => (typeof window.__t === 'function' ? window.__t(k, def, p) : (window.i18n && typeof window.i18n.t === 'function' ? window.i18n.t(k, def, p) : (def !== undefined ? def : k)));

      if (mode === 'empty_trash') {
        if (titleEl) titleEl.textContent = _t('notifications.modals_forms_empty_notification_trash', 'Empty Notification Trash?');
        if (subEl) subEl.textContent = _t('notifications.modals_forms_all_soft_deleted_notifications_in_your', 'All soft-deleted notifications in your Trash bin will be permanently erased. This action cannot be undone.');
        if (confirmBtnText) confirmBtnText.textContent = _t('notifications.modals_forms_empty_trash_now', 'Empty Trash Now');
      } else if (mode === 'bulk') {
        const count = payload.ids ? payload.ids.length : 0;
        if (titleEl) titleEl.textContent = _t('notifications.modals_forms_permanently_delete_notification_s', `Permanently Delete ${count} Notification(s)?`, { count });
        if (subEl) subEl.textContent = _t('notifications.modal_delete_bulk_sub', `You are about to permanently delete ${count} selected notification(s) from the database.`, { count });
        if (confirmBtnText) confirmBtnText.textContent = _t('notifications.main_views_delete_item_s', `Delete ${count} Item(s)`, { count });
      } else if (mode === 'single') {
        if (titleEl) titleEl.textContent = _t('notifications.modals_forms_permanently_delete_notification_2', 'Permanently Delete Notification?');
        if (subEl) subEl.textContent = _t('notifications.modals_forms_this_notification_will_be_permanently', 'This notification will be permanently erased from the database and suppressed from reappearing.');
        if (confirmBtnText) confirmBtnText.textContent = _t('notifications.main_views_delete_permanently', 'Delete Permanently');
      }

      if (modal) {
        modal.classList.remove('hidden');
      }
    }
    window.openNotificationPermanentDeleteModal = openNotificationPermanentDeleteModal;

    function closeNotificationPermanentDeleteModal() {
      pendingNotificationPermanentDelete = null;
      const modal = document.getElementById('notif-permanent-delete-modal');
      if (modal) {
        modal.classList.add('hidden');
      }
    }
    window.closeNotificationPermanentDeleteModal = closeNotificationPermanentDeleteModal;

    async function executeConfirmedNotificationPermanentDelete() {
      if (!pendingNotificationPermanentDelete) return;
      const { mode, id, ids } = pendingNotificationPermanentDelete;
      const confirmBtn = document.getElementById('notif-delete-modal-confirm-btn');
      if (confirmBtn) confirmBtn.disabled = true;

      try {
        if (mode === 'empty_trash') {
          const res = await apiRequest('/api/notifications/trash/empty', { method: 'DELETE' });
          if (res && res.ok) {
            showToast(_t('notifications.modals_forms_notification_trash_emptied_successfully', 'Notification trash emptied successfully'), 'success');
            clearNotificationSelection();
            closeNotificationPermanentDeleteModal();
            await loadNotificationsPageData();
          }
 else {
            showToast(res?.error || _t('notifications.modals_forms_failed_to_empty_trash', 'Failed to empty trash', 'error'), 'error');
          }

        }
 else if (mode === 'bulk') {
          const res = await apiRequest('/api/notifications/bulk-delete', {
            method: 'POST',
            body: JSON.stringify({ ids })
          }
);
          if (res && res.ok) {
            showToast(_t('notifications.toast_permanently_deleted_count', '{count} notification(s) permanently deleted', { count: ids.length }), 'success');
            clearNotificationSelection();
            closeNotificationPermanentDeleteModal();
            await loadNotificationsPageData();
          }
 else {
            showToast(res?.error || _t('notifications.modals_forms_failed_to_delete_notification', 'Failed to delete notifications permanently', 'error'), 'error');
          }

        }
 else if (mode === 'single') {
          const res = await apiRequest(`/api/notifications/${id}`, { method: 'DELETE' });
          if (res && res.ok) {
            showToast(_t('notifications.modals_forms_notification_permanently_deleted', 'Notification permanently deleted'), 'success');
            closeNotificationPermanentDeleteModal();
            await loadNotificationsPageData();
          }
 else {
            showToast(res?.error || _t('notifications.modals_forms_failed_to_delete_notification', 'Failed to delete notification', 'error'), 'error');
          }

        }

      } catch (e) {
        showToast(e.message || _t('notifications.modals_forms_failed_to_delete_notification', 'Failed to delete notification', 'error'), 'error');
      } finally {
        if (confirmBtn) confirmBtn.disabled = false;
      }
    }
