    // =========================================================================
    // PHASE 4: PHYSICAL CASH VAULT & DRAWER DASHBOARD ENGINE
    // =========================================================================
    let vaultSummaryCache = null;
    let _vaultSummaryInFlight = null;

    async function updateDashboardVault(scope = null) {
      if (!currentUser) return;
      try {
        if (!_vaultSummaryInFlight) {
          _vaultSummaryInFlight = apiRequest('/api/cash-vault/summary');
        }

        const res = await _vaultSummaryInFlight;
        if (!res) return;
        vaultSummaryCache = res;

        const cryptoSafeEl = document.getElementById('dash-vault-crypto-safe');
        const servicesSafeEl = document.getElementById('dash-vault-services-safe');
        const totalCashEl = document.getElementById('dash-vault-total-cash');

        const effectiveScope = scope || dashboardUserFilter || 'self';

        let cryptoBal = '0';
        let servicesBal = '0';
        let totalCash = '0';
        let targetDept = 'crypto_cash';

        if (effectiveScope === 'all') {
          cryptoBal = String(res.crypto_safe_balance || '0');
          servicesBal = String(res.services_safe_balance || '0');
          totalCash = String(res.total_closet_cash || res.grand_total_cash || '0');
        }
 else if (effectiveScope === 'role:crypto_cash') {
          const summary = res.role_summaries?.crypto_cash;
          cryptoBal = String(summary?.closet_balance || summary?.starting_capital || '0');
          servicesBal = '0';
          totalCash = cryptoBal;
          targetDept = 'crypto_cash';
        }
 else if (effectiveScope === 'role:custom_services') {
          const summary = res.role_summaries?.custom_services;
          cryptoBal = '0';
          servicesBal = String(summary?.closet_balance || summary?.starting_capital || '0');
          totalCash = servicesBal;
          targetDept = 'custom_services';
        }
 else {
          // User specific ('self' or backend user id)
          const targetUid = (effectiveScope === 'self')
            ? (currentUser?.__backendId || currentUser?.id)
            : effectiveScope;

          const userRow = (res.user_breakdown || []).find(u => String(u.user_id) === String(targetUid));
          targetDept = userRow?.role || currentUser?.department || 'crypto_cash';
          const userCloset = String(userRow?.closet_balance || '0');

          cryptoBal = String(userRow?.crypto_balance ?? (targetDept === 'custom_services' ? '0' : userCloset));
          servicesBal = String(userRow?.services_balance ?? (targetDept === 'custom_services' ? userCloset : '0'));
          totalCash = Decimal.add(cryptoBal, servicesBal);
        }


        if (cryptoSafeEl) cryptoSafeEl.textContent = formatPrice(cryptoBal);
        if (servicesSafeEl) servicesSafeEl.textContent = formatPrice(servicesBal);
        if (totalCashEl) totalCashEl.textContent = formatPrice(totalCash);

        renderDashboardSafes(cryptoBal, servicesBal, totalCash, effectiveScope, targetDept);

        if (typeof updateDashboardEquityStrip === 'function') {
          updateDashboardEquityStrip();
        }

      } catch (err) {
        console.error('Failed to load cash vault summary:', err);
      } finally {
        _vaultSummaryInFlight = null;
      }
    }

    function renderDashboardSafes(cryptoBal, servicesBal, totalCash, scope = 'all', targetDept = 'crypto_cash') {
      const deck = document.getElementById('dash-vault-deck');
      const cryptoCard = document.getElementById('dash-card-crypto-safe');
      const servicesCard = document.getElementById('dash-card-services-safe');
      const totalCard = document.getElementById('dash-card-total-cash');
      const cryptoBadge = document.getElementById('dash-badge-crypto');
      const servicesBadge = document.getElementById('dash-badge-services');
      const btnTransferCrypto = document.getElementById('dash-btn-transfer-crypto');
      const btnTransferServices = document.getElementById('dash-btn-transfer-services');
      const btnHistoryCrypto = document.getElementById('dash-btn-history-crypto');
      const btnHistoryServices = document.getElementById('dash-btn-history-services');

      if (!deck || !cryptoCard || !servicesCard || !totalCard) return;

      function syncSafeHistoryButtons() {
        const isTotalVisible = !totalCard.classList.contains('hidden');
        if (btnHistoryCrypto) {
          if (isTotalVisible) btnHistoryCrypto.classList.add('hidden');
          else btnHistoryCrypto.classList.remove('hidden');
        }

        if (btnHistoryServices) {
          if (isTotalVisible) btnHistoryServices.classList.add('hidden');
          else btnHistoryServices.classList.remove('hidden');
        }

      }

      const hasCrypto = Decimal.comp(cryptoBal || '0', '0') !== 0;
      const hasServices = Decimal.comp(servicesBal || '0', '0') !== 0;

      // Reset base modifier classes
      const resetClasses = ['hidden', 'lg:col-span-2', 'lg:col-span-3', 'col-span-full'];
      cryptoCard.classList.remove(...resetClasses);
      servicesCard.classList.remove(...resetClasses);
      totalCard.classList.remove(...resetClasses);
      if (cryptoBadge) cryptoBadge.classList.add('hidden');
      if (servicesBadge) servicesBadge.classList.add('hidden');
      if (btnTransferCrypto) btnTransferCrypto.classList.add('hidden');
      if (btnTransferServices) btnTransferServices.classList.add('hidden');

      deck.className = 'grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3 sm:gap-6 transition-all duration-300';

      // 1. All Business Mode -> Show all 3 cards side-by-side (Total card handles unified transfer & history)
      if (scope === 'all') {
        syncSafeHistoryButtons();
        return;
      }

      // 2. Crypto & Cash Desk Scope -> Show ONLY Crypto Safe (Hero Full Width), Hide Services & Total Card
      if (scope === 'role:crypto_cash') {
        servicesCard.classList.add('hidden');
        totalCard.classList.add('hidden');
        cryptoCard.classList.add('lg:col-span-3');
        if (cryptoBadge) cryptoBadge.classList.remove('hidden');
        if (btnTransferCrypto) btnTransferCrypto.classList.remove('hidden');
        syncSafeHistoryButtons();
        return;
      }

      // 3. Custom Services Desk Scope -> Show ONLY Services Safe (Hero Full Width), Hide Crypto & Total Card
      if (scope === 'role:custom_services') {
        cryptoCard.classList.add('hidden');
        totalCard.classList.add('hidden');
        servicesCard.classList.add('lg:col-span-3');
        if (servicesBadge) servicesBadge.classList.remove('hidden');
        if (btnTransferServices) btnTransferServices.classList.remove('hidden');
        syncSafeHistoryButtons();
        return;
      }

      // 4. User Scope ('self' or specific staff member)
      // Case A: User has funds in BOTH safes -> Show all 3 cards side-by-side
      if (hasCrypto && hasServices) {
        syncSafeHistoryButtons();
        return;
      }

      // Case B: User has funds in ONLY Crypto Safe
      if (hasCrypto && !hasServices) {
        servicesCard.classList.add('hidden');
        totalCard.classList.add('hidden');
        cryptoCard.classList.add('lg:col-span-3');
        if (cryptoBadge) cryptoBadge.classList.remove('hidden');
        if (btnTransferCrypto) btnTransferCrypto.classList.remove('hidden');
        syncSafeHistoryButtons();
        return;
      }

      // Case C: User has funds in ONLY Services Safe
      if (!hasCrypto && hasServices) {
        cryptoCard.classList.add('hidden');
        totalCard.classList.add('hidden');
        servicesCard.classList.add('lg:col-span-3');
        if (servicesBadge) servicesBadge.classList.remove('hidden');
        if (btnTransferServices) btnTransferServices.classList.remove('hidden');
        syncSafeHistoryButtons();
        return;
      }

      // Case D: Zero balance in both safes -> Department fallback
      totalCard.classList.add('hidden');
      if (targetDept === 'custom_services') {
        cryptoCard.classList.add('hidden');
        servicesCard.classList.add('lg:col-span-3');
        if (servicesBadge) servicesBadge.classList.remove('hidden');
        if (btnTransferServices) btnTransferServices.classList.remove('hidden');
      } else {
        servicesCard.classList.add('hidden');
        cryptoCard.classList.add('lg:col-span-3');
        if (cryptoBadge) cryptoBadge.classList.remove('hidden');
        if (btnTransferCrypto) btnTransferCrypto.classList.remove('hidden');
      }
      syncSafeHistoryButtons();
    }

    function updateVaultTxUserOptions() {
      const safeSelect = document.getElementById('vault-tx-safe-select');
      const userSelect = document.getElementById('vault-tx-user-select');
      if (!userSelect) return;

      const safeKey = safeSelect ? safeSelect.value : 'crypto_safe';
      const targetDept = (safeKey === 'services_safe') ? 'custom_services' : 'crypto_cash';

      const usersList = (typeof usersCache !== 'undefined' && usersCache.length) ? usersCache : (typeof getUsers === 'function' ? getUsers() : []);
      let filteredUsers = usersList.filter(u => {
        const dept = u.department || u.role;
        if (!dept || dept === targetDept) return true;
        if (u.is_admin || u.isAdmin) return true;
        return false;
      });

      if (filteredUsers.length === 0) {
        filteredUsers = usersList;
      }

      if (filteredUsers.length === 0) {
        userSelect.innerHTML = '<option value="">No staff members found</option>';
        return;
      }

      userSelect.innerHTML = filteredUsers.map(u => {
        const dept = u.department || u.role || 'crypto_cash';
        const label = getSafeLocalizedName(dept, 'badge_full');
        return `<option value="${u.id || u.__backendId}">${escapeHtml(u.username || u.name)} (${label})</option>`;
      }).join('');
    }

    let activeVaultTxAvailBal = '0';

    function setVaultTxMax() {
      const amountInput = document.getElementById('vault-tx-amount');
      if (amountInput && Decimal.comp(activeVaultTxAvailBal || '0', '0') > 0) {
        amountInput.value = activeVaultTxAvailBal;
      }
    }

    async function showVaultTransactionModal(type = 'deposit', targetSafeKey = null) {
      const form = document.getElementById('vault-tx-form');
      if (form) form.reset();

      const typeInput = document.getElementById('vault-tx-type');
      if (typeInput) typeInput.value = type;

      const titleEl = document.getElementById('vault-tx-title');
      const btnEl = document.getElementById('vault-tx-submit-btn');
      const iconWrap = document.getElementById('vault-tx-icon-wrap');
      const availWrap = document.getElementById('vault-tx-avail-wrap');
      const availValEl = document.getElementById('vault-tx-avail-val');
      const amountInput = document.getElementById('vault-tx-amount');

      // Determine safe side: explicit targetSafeKey takes precedence, fallback to user department
      const curUid = currentUser?.__backendId || currentUser?.id || 1;
      const userDept = currentUser?.department || currentUser?.role || 'crypto_cash';
      const safeKey = targetSafeKey || ((userDept === 'custom_services') ? 'services_safe' : 'crypto_safe');
      const isCustomServices = safeKey === 'services_safe';
      const safeName = isCustomServices
        ? (window.i18n ? window.i18n.t('dashboard.modal_tx_safe_services', 'Custom Services Safe (Safe 2)') : 'Custom Services Safe (Safe 2)')
        : (window.i18n ? window.i18n.t('dashboard.modal_tx_safe_crypto', 'Crypto & Cash Safe (Safe 1)') : 'Crypto & Cash Safe (Safe 1)');
      const safeIcon = isCustomServices ? '🛠️' : '🏛️';
      const safeDesc = isCustomServices
        ? (window.i18n ? window.i18n.t('dashboard.modal_tx_safe_services_desc', 'Physical cash desk for Custom Services Desk') : 'Physical cash desk for Custom Services Desk')
        : (window.i18n ? window.i18n.t('dashboard.modal_tx_safe_crypto_desc', 'Physical cash desk for Crypto & Cash Desk') : 'Physical cash desk for Crypto & Cash Desk');

      const safeInput = document.getElementById('vault-tx-safe-select');
      if (safeInput) safeInput.value = safeKey;

      const safeNameEl = document.getElementById('vault-tx-safe-name');
      if (safeNameEl) safeNameEl.textContent = safeName;
      const safeIconEl = document.getElementById('vault-tx-safe-icon');
      if (safeIconEl) safeIconEl.textContent = safeIcon;
      const safeDescEl = document.getElementById('vault-tx-safe-desc');
      if (safeDescEl) safeDescEl.textContent = safeDesc;

      const userDisplayEl = document.getElementById('vault-tx-user-display');
      const userHiddenInput = document.getElementById('vault-tx-user-select');
      const curUname = currentUser?.username || 'Active User';
      const deptSuffix = isCustomServices
        ? (window.i18n ? window.i18n.t('dashboard.scope_custom_services', 'Custom Services') : 'Custom Services')
        : (window.i18n ? window.i18n.t('dashboard.scope_crypto_desk', 'Crypto & Cash') : 'Crypto & Cash');
      if (userDisplayEl) userDisplayEl.textContent = `👤 ${curUname} (${deptSuffix})`;
      if (userHiddenInput) userHiddenInput.value = curUid;

      // Resolve user's available balance in target safe
      if (!vaultSummaryCache) {
        try {
          vaultSummaryCache = await apiRequest('/api/cash-vault/summary');
        }
 catch (e) {
          console.warn('Could not fetch vault summary', e);
        }

      }
      const userRow = (vaultSummaryCache?.user_breakdown || []).find(u => String(u.user_id) === String(curUid));
      const userCloset = String(userRow?.closet_balance || '0');
      const userCrypto = String(userRow?.crypto_balance ?? (userDept === 'custom_services' ? '0' : userCloset));
      const userServices = String(userRow?.services_balance ?? (userDept === 'custom_services' ? userCloset : '0'));
      activeVaultTxAvailBal = isCustomServices ? userServices : userCrypto;

      if (type === 'withdrawal') {
        if (titleEl) titleEl.textContent = window.i18n ? window.i18n.t('dashboard.modal_tx_withdraw_title', 'Withdraw Cash from Safe') : 'Withdraw Cash from Safe';
        if (btnEl) {
          btnEl.textContent = window.i18n ? window.i18n.t('dashboard.modal_tx_withdraw_btn', 'Confirm Withdrawal') : 'Confirm Withdrawal';
          btnEl.className = 'w-full sm:flex-1 py-3.5 sm:py-3 min-h-[48px] sm:min-h-[44px] bg-rose-600 hover:bg-rose-700 text-white font-bold text-sm sm:text-xs rounded-2xl sm:rounded-xl shadow-md transition-all cursor-pointer flex items-center justify-center active:scale-[0.98]';
        }

        if (iconWrap) {
          iconWrap.textContent = '📤';
          iconWrap.className = 'w-11 h-11 sm:w-10 sm:h-10 rounded-2xl bg-rose-50 dark:bg-rose-950/60 text-rose-600 dark:text-rose-400 flex items-center justify-center text-xl font-bold shrink-0';
        }

        if (availWrap) {
          availWrap.classList.remove('hidden');
          availWrap.className = 'mb-2 p-3 sm:p-3.5 rounded-2xl bg-rose-500/[0.07] dark:bg-rose-950/25 border border-rose-500/20 flex items-center justify-between gap-3 transition-all';
        }
        const availIcon = document.getElementById('vault-tx-avail-icon');
        const availLabel = document.getElementById('vault-tx-avail-label');
        const maxBtn = document.getElementById('vault-tx-max-btn');
        if (availIcon) {
          availIcon.textContent = '📤';
          availIcon.className = 'w-8 h-8 rounded-xl bg-rose-500/10 text-rose-600 dark:text-rose-400 flex items-center justify-center text-sm shrink-0 border border-rose-500/20';
        }
        if (availLabel) availLabel.textContent = window.i18n ? window.i18n.t('dashboard.modal_tx_available_withdraw', 'Available to Withdraw') : 'Available to Withdraw';
        if (availValEl) {
          availValEl.textContent = formatPrice(activeVaultTxAvailBal);
          availValEl.className = 'block text-xs sm:text-sm font-mono font-black text-rose-600 dark:text-rose-400 tabular-nums break-words';
        }
        if (maxBtn) {
          maxBtn.classList.remove('hidden');
          maxBtn.className = 'px-3 py-1.5 min-h-[36px] sm:min-h-[32px] rounded-xl text-xs font-black uppercase tracking-wider bg-rose-500/15 hover:bg-rose-500/25 active:scale-95 text-rose-700 dark:text-rose-300 border border-rose-500/30 cursor-pointer flex items-center justify-center gap-1 transition-all shrink-0';
        }
        if (amountInput) amountInput.setAttribute('max', activeVaultTxAvailBal);
      } else {
        if (titleEl) titleEl.textContent = window.i18n ? window.i18n.t('dashboard.modal_tx_deposit_title', 'Deposit Cash into Safe') : 'Deposit Cash into Safe';
        if (btnEl) {
          btnEl.textContent = window.i18n ? window.i18n.t('dashboard.modal_tx_deposit_btn', 'Confirm Deposit') : 'Confirm Deposit';
          btnEl.className = 'w-full sm:flex-1 py-3.5 sm:py-3 min-h-[48px] sm:min-h-[44px] bg-emerald-600 hover:bg-emerald-700 text-white font-bold text-sm sm:text-xs rounded-2xl sm:rounded-xl shadow-md transition-all cursor-pointer flex items-center justify-center active:scale-[0.98]';
        }

        if (iconWrap) {
          iconWrap.textContent = '📥';
          iconWrap.className = 'w-11 h-11 sm:w-10 sm:h-10 rounded-2xl bg-emerald-50 dark:bg-emerald-950/60 text-emerald-600 dark:text-emerald-400 flex items-center justify-center text-xl font-bold shrink-0';
        }

        if (availWrap) {
          availWrap.classList.remove('hidden');
          availWrap.className = 'mb-2 p-3 sm:p-3.5 rounded-2xl bg-emerald-500/[0.07] dark:bg-emerald-950/25 border border-emerald-500/20 flex items-center justify-between gap-3 transition-all';
        }
        const availIcon = document.getElementById('vault-tx-avail-icon');
        const availLabel = document.getElementById('vault-tx-avail-label');
        const maxBtn = document.getElementById('vault-tx-max-btn');
        if (availIcon) {
          availIcon.textContent = '🏦';
          availIcon.className = 'w-8 h-8 rounded-xl bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 flex items-center justify-center text-sm shrink-0 border border-emerald-500/20';
        }
        if (availLabel) availLabel.textContent = window.i18n ? window.i18n.t('dashboard.modal_tx_current_safe_balance', 'Current Safe Balance') : 'Current Safe Balance';
        if (availValEl) {
          availValEl.textContent = formatPrice(activeVaultTxAvailBal);
          availValEl.className = 'block text-xs sm:text-sm font-mono font-black text-emerald-600 dark:text-emerald-400 tabular-nums break-words';
        }
        if (maxBtn) maxBtn.classList.add('hidden');
        if (amountInput) amountInput.removeAttribute('max');
      }

      document.getElementById('vault-transaction-modal')?.classList.remove('hidden');
    }

    function closeVaultTransactionModal() {
      document.getElementById('vault-transaction-modal')?.classList.add('hidden');
    }

    async function saveVaultTransaction(e) {
      e.preventDefault();
      const btn = document.getElementById('vault-tx-submit-btn');
      if (btn) {
        btn.disabled = true;
        btn.textContent = window.i18n ? window.i18n.t('dashboard.modal_tx_processing', 'Processing...') : 'Processing...';
      }

      const type = document.getElementById('vault-tx-type')?.value || 'deposit';
      const amount = document.getElementById('vault-tx-amount')?.value.trim() || '0';
      const note = document.getElementById('vault-tx-note')?.value.trim() || '';
      const userId = currentUser?.__backendId || currentUser?.id || 1;
      const userDept = currentUser?.department || currentUser?.role || 'crypto_cash';
      const safeKey = document.getElementById('vault-tx-safe-select')?.value || ((userDept === 'custom_services') ? 'services_safe' : 'crypto_safe');

      if (type === 'withdrawal') {
        if (Decimal.comp(amount, '0') <= 0) {
          showToast(window.i18n ? window.i18n.t('dashboard.toast_tx_amount_positive', 'Amount must be greater than zero') : 'Amount must be greater than zero');
          if (btn) {
            btn.disabled = false;
            btn.textContent = window.i18n ? window.i18n.t('dashboard.modal_tx_withdraw_btn', 'Confirm Withdrawal') : 'Confirm Withdrawal';
          }

          return;
        }

        if (Decimal.comp(amount, activeVaultTxAvailBal || '0') > 0) {
          const balStr = formatPrice(activeVaultTxAvailBal);
          const exceedsMsg = (window.i18n ? window.i18n.t('dashboard.toast_tx_amount_exceeds', 'Withdrawal amount exceeds your available balance ({balance})') : 'Withdrawal amount exceeds your available balance ({balance})').replace('{balance}', balStr);
          showToast(exceedsMsg);
          if (btn) {
            btn.disabled = false;
            btn.textContent = window.i18n ? window.i18n.t('dashboard.modal_tx_withdraw_btn', 'Confirm Withdrawal') : 'Confirm Withdrawal';
          }

          return;
        }

      }

      try {
        await apiRequest('/api/cash-vault/transaction', {
          method: 'POST',
          body: JSON.stringify({ type, amount, note, user_id: userId, safe_key: safeKey })
        }
);
        showToast(type === 'withdrawal'
          ? (window.i18n ? window.i18n.t('dashboard.toast_tx_withdraw_success', 'Cash withdrawal recorded on your safe!') : 'Cash withdrawal recorded on your safe!')
          : (window.i18n ? window.i18n.t('dashboard.toast_tx_deposit_success', 'Cash deposit recorded on your safe!') : 'Cash deposit recorded on your safe!'));
        closeVaultTransactionModal();
        await updateDashboardVault();
        if (typeof loadExpensesData === 'function') loadExpensesData();
        if (typeof fetchAndRenderVaultHistory === 'function') fetchAndRenderVaultHistory();
      } catch (err) {
        showToast(err.message || (window.i18n ? window.i18n.t('dashboard.toast_tx_failed', 'Failed to record cash movement') : 'Failed to record cash movement'));
      } finally {
        if (btn) {
          btn.disabled = false;
          btn.textContent = (type === 'withdrawal'
            ? (window.i18n ? window.i18n.t('dashboard.modal_tx_withdraw_btn', 'Confirm Withdrawal') : 'Confirm Withdrawal')
            : (window.i18n ? window.i18n.t('dashboard.modal_tx_deposit_btn', 'Confirm Deposit') : 'Confirm Movement'));
        }

      }
    }

    // ═════════════════════════════════════════════════════════════════════════
    // PERSON-TO-PERSON & SAFE-TO-SAFE CASH TRANSFERS CONTROLLER
    // ═════════════════════════════════════════════════════════════════════════
    let activeTransferSourceSafe = 'crypto_safe';
    let activeTransferMaxBal = '0';
    let userBalancesForTransfer = { crypto: '0', services: '0' };

    function onVaultTransferSourceChange(safeKey) {
      activeTransferSourceSafe = safeKey;
      const safeHidden = document.getElementById('vault-transfer-source-safe');
      if (safeHidden) safeHidden.value = safeKey;

      const optCrypto = document.getElementById('vault-src-opt-crypto');
      const optServices = document.getElementById('vault-src-opt-services');
      const radioCrypto = optCrypto?.querySelector('input[type="radio"]');
      const radioServices = optServices?.querySelector('input[type="radio"]');

      if (safeKey === 'crypto_safe') {
        if (radioCrypto) radioCrypto.checked = true;
        optCrypto?.classList.add('border-emerald-500', 'bg-emerald-50/50', 'dark:bg-emerald-950/20');
        optCrypto?.classList.remove('border-slate-200', 'dark:border-slate-700');
        optServices?.classList.remove('border-cyan-500', 'bg-cyan-50/50', 'dark:bg-cyan-950/20');
        optServices?.classList.add('border-slate-200', 'dark:border-slate-700');
        activeTransferMaxBal = userBalancesForTransfer.crypto;
      } else {
        if (radioServices) radioServices.checked = true;
        optServices?.classList.add('border-cyan-500', 'bg-cyan-50/50', 'dark:bg-cyan-950/20');
        optServices?.classList.remove('border-slate-200', 'dark:border-slate-700');
        optCrypto?.classList.remove('border-emerald-500', 'bg-emerald-50/50', 'dark:bg-emerald-950/20');
        optCrypto?.classList.add('border-slate-200', 'dark:border-slate-700');
        activeTransferMaxBal = userBalancesForTransfer.services;
      }

      const availValEl = document.getElementById('vault-transfer-avail-val');
      if (availValEl) availValEl.textContent = formatPrice(activeTransferMaxBal);

      const amountInput = document.getElementById('vault-transfer-amount');
      if (amountInput) amountInput.setAttribute('max', activeTransferMaxBal);

      // Update opposite destination safe card in safe-to-safe mode
      const destSafeName = document.getElementById('vault-dest-safe-name');
      const destSafeIcon = document.getElementById('vault-dest-safe-icon');
      if (safeKey === 'crypto_safe') {
        if (destSafeName) {
          destSafeName.textContent = window.i18n ? window.i18n.t('dashboard.modal_transfer_dest_services', 'Custom Services Safe') : 'Custom Services Safe';
        }

        if (destSafeIcon) destSafeIcon.textContent = '🛠️';
      } else {
        if (destSafeName) {
          destSafeName.textContent = window.i18n ? window.i18n.t('dashboard.modal_transfer_dest_crypto', 'Crypto & Cash Safe') : 'Crypto & Cash Safe';
        }

        if (destSafeIcon) destSafeIcon.textContent = '🏛️';
      }
    }

    function setVaultTransferMax() {
      const amountInput = document.getElementById('vault-transfer-amount');
      if (amountInput && Decimal.comp(activeTransferMaxBal || '0', '0') > 0) {
        amountInput.value = activeTransferMaxBal;
      }
    }

    async function showVaultTransferModal(sourceSafeKey = null) {
      const modal = document.getElementById('vault-transfer-modal');
      const form = document.getElementById('vault-transfer-form');
      const recipientSelect = document.getElementById('vault-transfer-recipient');
      if (form) form.reset();

      const curUid = currentUser?.__backendId || currentUser?.id || 1;
      const userDept = currentUser?.department || currentUser?.role || 'crypto_cash';

      // 1. Fetch live vault summary if cache empty
      if (!vaultSummaryCache) {
        try {
          vaultSummaryCache = await apiRequest('/api/cash-vault/summary');
        }
 catch (e) {
          console.warn('Failed to load vault summary', e);
        }

      }

      const userRow = (vaultSummaryCache?.user_breakdown || []).find(u => String(u.user_id) === String(curUid));
      const userCloset = String(userRow?.closet_balance || '0');
      const userCrypto = String(userRow?.crypto_balance ?? (userDept === 'custom_services' ? '0' : userCloset));
      const userServices = String(userRow?.services_balance ?? (userDept === 'custom_services' ? userCloset : '0'));

      userBalancesForTransfer = {
        crypto: userCrypto,
        services: userServices
      };

      const cryptoBalEl = document.getElementById('vault-src-crypto-bal');
      const servicesBalEl = document.getElementById('vault-src-services-bal');
      if (cryptoBalEl) cryptoBalEl.textContent = formatPrice(userCrypto);
      if (servicesBalEl) servicesBalEl.textContent = formatPrice(userServices);

      const hasCrypto = Decimal.comp(userCrypto, '0') > 0;
      const hasServices = Decimal.comp(userServices, '0') > 0;

      // 2. Determine default selected source safe and lock states
      let effectiveSource = 'crypto_safe';
      if (sourceSafeKey) {
        effectiveSource = sourceSafeKey;
      } else if (hasCrypto && !hasServices) {
        effectiveSource = 'crypto_safe';
      } else if (!hasCrypto && hasServices) {
        effectiveSource = 'services_safe';
      } else if (userDept === 'custom_services') {
        effectiveSource = 'services_safe';
      } else {
        effectiveSource = 'crypto_safe';
      }

      // Configure visual lock state if explicit safe passed or user holds funds in only 1 safe
      const optCrypto = document.getElementById('vault-src-opt-crypto');
      const optServices = document.getElementById('vault-src-opt-services');
      if (sourceSafeKey || (hasCrypto && !hasServices) || (!hasCrypto && hasServices)) {
        if (effectiveSource === 'crypto_safe') {
          optCrypto?.classList.remove('opacity-40', 'pointer-events-none');
          optServices?.classList.add('opacity-40', 'pointer-events-none');
        }
 else {
          optServices?.classList.remove('opacity-40', 'pointer-events-none');
          optCrypto?.classList.add('opacity-40', 'pointer-events-none');
        }

      } else {
        optCrypto?.classList.remove('opacity-40', 'pointer-events-none');
        optServices?.classList.remove('opacity-40', 'pointer-events-none');
      }

      onVaultTransferSourceChange(effectiveSource);

      // 3. Populate recipient staff members (Excluding active user)
      const allUsers = (typeof usersCache !== 'undefined' && usersCache.length)
        ? usersCache
        : (typeof getUsers === 'function' ? getUsers() : []);

      const recipients = allUsers.filter(u => {
        const uid = u.__backendId || u.id;
        return String(uid) !== String(curUid);
      });

      if (recipientSelect) {
        if (recipients.length === 0) {
          const noRecipientsText = window.i18n ? window.i18n.t('dashboard.modal_transfer_no_recipients', 'No other staff members found') : 'No other staff members found';
          recipientSelect.innerHTML = `<option value="">${escapeHtml(noRecipientsText)}</option>`;
        }
 else {
          recipientSelect.innerHTML = recipients.map(u => {
            const uid = u.__backendId || u.id;
            const uname = u.username || u.name || 'Staff Member';
            const dept = u.department || u.role || 'crypto_cash';
            const deptLabel = dept === 'custom_services'
              ? (window.i18n ? window.i18n.t('dashboard.modal_transfer_dest_services', 'Custom Services Safe') : 'Custom Services Safe')
              : (window.i18n ? window.i18n.t('dashboard.modal_transfer_dest_crypto', 'Crypto & Cash Safe') : 'Crypto & Cash Safe');
            return `<option value="${uid}" data-dept="${escapeHtml(dept)}">${escapeHtml(uname)} (${deptLabel})</option>`;
          }
).join('');
        }

      }

      setVaultTransferMode('safe_to_safe');
      modal?.classList.remove('hidden');
    }

    function closeVaultTransferModal() {
      document.getElementById('vault-transfer-modal')?.classList.add('hidden');
    }

    function setVaultTransferMode(mode) {
      const modeInput = document.getElementById('vault-transfer-mode');
      const btnSafe = document.getElementById('vault-transfer-mode-safe');
      const btnStaff = document.getElementById('vault-transfer-mode-staff');
      const destSafeContainer = document.getElementById('vault-transfer-dest-safe-container');
      const recipientContainer = document.getElementById('vault-transfer-recipient-container');

      if (modeInput) modeInput.value = mode;

      if (mode === 'safe_to_staff') {
        destSafeContainer?.classList.add('hidden');
        recipientContainer?.classList.remove('hidden');

        btnStaff?.classList.add('bg-white', 'dark:bg-slate-700', 'text-slate-900', 'dark:text-white', 'shadow-sm', 'font-black');
        btnStaff?.classList.remove('text-slate-500', 'dark:text-slate-400', 'font-bold');

        btnSafe?.classList.remove('bg-white', 'dark:bg-slate-700', 'text-slate-900', 'dark:text-white', 'shadow-sm', 'font-black');
        btnSafe?.classList.add('text-slate-500', 'dark:text-slate-400', 'font-bold');
      } else {
        destSafeContainer?.classList.remove('hidden');
        recipientContainer?.classList.add('hidden');

        btnSafe?.classList.add('bg-white', 'dark:bg-slate-700', 'text-slate-900', 'dark:text-white', 'shadow-sm', 'font-black');
        btnSafe?.classList.remove('text-slate-500', 'dark:text-slate-400', 'font-bold');

        btnStaff?.classList.remove('bg-white', 'dark:bg-slate-700', 'text-slate-900', 'dark:text-white', 'shadow-sm', 'font-black');
        btnStaff?.classList.add('text-slate-500', 'dark:text-slate-400', 'font-bold');
      }
    }
    window.setVaultTransferMode = setVaultTransferMode;

    async function saveVaultTransfer(e) {
      e.preventDefault();
      const btn = document.getElementById('vault-transfer-submit-btn');
      const confirmLabel = window.i18n ? window.i18n.t('dashboard.modal_transfer_submit', 'Confirm Transfer') : 'Confirm Transfer';
      const transferringLabel = window.i18n ? window.i18n.t('dashboard.transferring_btn', 'Transferring...') : 'Transferring...';
      if (btn) { btn.disabled = true; btn.textContent = transferringLabel; }

      const curUid = currentUser?.__backendId || currentUser?.id || 1;
      const transferMode = document.getElementById('vault-transfer-mode')?.value || 'safe_to_safe';
      const fromSafe = document.getElementById('vault-transfer-source-safe')?.value || activeTransferSourceSafe || 'crypto_safe';
      const amount = document.getElementById('vault-transfer-amount')?.value.trim() || '0';
      const note = document.getElementById('vault-transfer-note')?.value.trim() || '';
      let recipientId = document.getElementById('vault-transfer-recipient')?.value;

      if (transferMode === 'safe_to_staff') {
        if (!recipientId) {
          showToast(window.i18n ? window.i18n.t('dashboard.toast_select_recipient', 'Please select a recipient staff member') : 'Please select a recipient staff member');
          if (btn) { btn.disabled = false; btn.textContent = confirmLabel; }
          return;
        }

      } else {
        recipientId = curUid;
      }

      if (Decimal.comp(amount, '0') <= 0) {
        showToast(window.i18n ? window.i18n.t('dashboard.toast_transfer_gt_zero', 'Transfer amount must be greater than zero') : 'Transfer amount must be greater than zero');
        if (btn) { btn.disabled = false; btn.textContent = confirmLabel; }
        return;
      }

      if (Decimal.comp(amount, activeTransferMaxBal || '0') > 0) {
        const balFmt = formatPrice(activeTransferMaxBal);
        const exceedMsg = (window.i18n ? window.i18n.t('dashboard.toast_transfer_exceeds', 'Transfer amount exceeds your available balance ({balance})') : 'Transfer amount exceeds your available balance ({balance})').replace('{balance}', balFmt);
        showToast(exceedMsg);
        if (btn) { btn.disabled = false; btn.textContent = confirmLabel; }
        return;
      }

      try {
        const toSafeKey = transferMode === 'safe_to_safe' ? ((fromSafe === 'crypto_safe') ? 'services_safe' : 'crypto_safe') : undefined;
        await apiRequest('/api/cash-vault/transfer', {
          method: 'POST',
          body: JSON.stringify({
            sender_id: curUid,
            from_safe: fromSafe,
            to_safe: toSafeKey,
            recipient_id: recipientId,
            amount: amount,
            note: note
          }
)
        }
);
        showToast(transferMode === 'safe_to_safe'
          ? (window.i18n ? window.i18n.t('dashboard.toast_transfer_safe_success', 'Cash transferred successfully between safes!') : 'Cash transferred successfully between safes!')
          : (window.i18n ? window.i18n.t('dashboard.toast_transfer_staff_success', 'Cash transferred successfully to staff member!') : 'Cash transferred successfully to staff member!'));
        closeVaultTransferModal();
        await updateDashboardVault();
        if (typeof loadExpensesData === 'function') loadExpensesData();
        if (typeof fetchAndRenderVaultHistory === 'function') fetchAndRenderVaultHistory();
      } catch (err) {
        showToast(err.message || (window.i18n ? window.i18n.t('dashboard.toast_transfer_failed', 'Failed to transfer cash') : 'Failed to transfer cash'));
      } finally {
        if (btn) { btn.disabled = false; btn.textContent = confirmLabel; }
      }
    }

    // Explicit Global Window Handlers for Cash Vault Modals (Rule 101 Pillar IV)
    window.showVaultTransactionModal = showVaultTransactionModal;
    window.closeVaultTransactionModal = closeVaultTransactionModal;
    window.setVaultTxMax = setVaultTxMax;
    window.saveVaultTransaction = saveVaultTransaction;
    window.showVaultTransferModal = showVaultTransferModal;
    window.closeVaultTransferModal = closeVaultTransferModal;
    window.setVaultTransferMax = setVaultTransferMax;
    window.saveVaultTransfer = saveVaultTransfer;
    window.onVaultTransferSourceChange = onVaultTransferSourceChange;

    // ═════════════════════════════════════════════════════════════════════════
    //  SAFE CASH HISTORY & FLOW LEDGER HUB CONTROLLER (Apple Liquid Glass)
    // ═════════════════════════════════════════════════════════════════════════
    const getVaultLocalIsoDate = (d = new Date()) => {
      const local = new Date(d.getTime() - d.getTimezoneOffset() * 60000);
      return local.toISOString().split('T')[0];
    };

    let currentVaultHistoryFilter = {
      vault_type: 'all',
      user_id: 'all',
      direction: 'all',
      type: 'all',
      tab: 'all',
      search: '',
      date_from: '',
      date_to: ''
    };
    let vaultHistorySearchTimeout = null;
    let _cachedVaultHistoryTransactions = [];
    let vaultHistoryOffset = 0;
    const vaultHistoryLimit = 50;
    let vaultHistoryHasMore = false;
    let vaultHistoryTotalCount = 0;
    let isVaultHistoryLoadingMore = false;

    function setVaultHistoryPreset(preset) {
      const now = new Date();
      const df = document.getElementById('vh-filter-date-from');
      const dt = document.getElementById('vh-filter-date-to');

      if (preset === 'today') {
        const todayStr = getVaultLocalIsoDate(now);
        if (df) df.value = todayStr;
        if (dt) dt.value = todayStr;
      } else if (preset === 'yesterday') {
        const yest = new Date(now);
        yest.setDate(yest.getDate() - 1);
        const yestStr = getVaultLocalIsoDate(yest);
        if (df) df.value = yestStr;
        if (dt) dt.value = yestStr;
      } else if (preset === 'last7' || preset === '7days') {
        const past = new Date(now);
        past.setDate(past.getDate() - 7);
        if (df) df.value = getVaultLocalIsoDate(past);
        if (dt) dt.value = getVaultLocalIsoDate(now);
      } else if (preset === 'last30') {
        const past = new Date(now);
        past.setDate(past.getDate() - 30);
        if (df) df.value = getVaultLocalIsoDate(past);
        if (dt) dt.value = getVaultLocalIsoDate(now);
      } else if (preset === 'thisMonth' || preset === 'month') {
        const firstDay = new Date(now.getFullYear(), now.getMonth(), 1);
        if (df) df.value = getVaultLocalIsoDate(firstDay);
        if (dt) dt.value = getVaultLocalIsoDate(now);
      } else if (preset === 'allTime') {
        if (df) df.value = '';
        if (dt) dt.value = '';
      }

      if (df && dt) {
        currentVaultHistoryFilter.date_from = df.value;
        currentVaultHistoryFilter.date_to = dt.value;
      }

      const allPresets = ['today', 'yesterday', 'last7', 'last30', 'thisMonth', 'allTime'];
      allPresets.forEach(p => {
        const btn = document.getElementById(`vh-btn-${p}`);
        if (!btn) return;
        if (p === preset) {
          btn.classList.add('bg-emerald-500/10', 'dark:bg-emerald-500/20', 'text-emerald-600', 'dark:text-emerald-400', 'border-emerald-500/40');
          btn.classList.remove('bg-white/60', 'dark:bg-white/[0.02]', 'text-slate-600', 'dark:text-slate-300', 'border-slate-200', 'dark:border-white/[0.08]');
        }
 else {
          btn.classList.remove('bg-emerald-500/10', 'dark:bg-emerald-500/20', 'text-emerald-600', 'dark:text-emerald-400', 'border-emerald-500/40');
          btn.classList.add('bg-white/60', 'dark:bg-white/[0.02]', 'text-slate-600', 'dark:text-slate-300', 'border-slate-200', 'dark:border-white/[0.08]');
        }

      });

      fetchAndRenderVaultHistory();
    }
    window.setVaultHistoryPreset = setVaultHistoryPreset;
    window.setVaultDatePreset = setVaultHistoryPreset;

    function clearVaultSearch() {
      const sInp = document.getElementById('vh-filter-search');
      if (sInp) sInp.value = '';
      const clearBtn = document.getElementById('vh-search-clear-btn');
      if (clearBtn) clearBtn.classList.add('hidden');
      fetchAndRenderVaultHistory();
    }
    window.clearVaultSearch = clearVaultSearch;

    function openVaultHistoryModal(options = {}) {
      vaultHistoryOffset = 0;
      _cachedVaultHistoryTransactions = [];
      vaultHistoryHasMore = false;
      vaultHistoryTotalCount = 0;
      isVaultHistoryLoadingMore = false;

      let vType = options.vault_type || 'all';
      if (vType === 'crypto') vType = 'crypto_safe';
      if (vType === 'services') vType = 'services_safe';

      const dateFrom = (options.date_from !== undefined && options.date_from !== null) ? options.date_from : '';
      const dateTo = (options.date_to !== undefined && options.date_to !== null) ? options.date_to : '';

      currentVaultHistoryFilter = {
        vault_type: vType,
        user_id: options.user_id !== undefined ? String(options.user_id) : 'all',
        direction: options.direction || 'all',
        type: options.type || 'all',
        tab: options.tab || 'all',
        search: options.search || '',
        date_from: dateFrom,
        date_to: dateTo
      };

      // Populate user selector in modal
      const userSelect = document.getElementById('vh-filter-user');
      if (userSelect) {
        const usersList = (typeof usersCache !== 'undefined' && usersCache.length) ? usersCache : (typeof getUsers === 'function' ? getUsers() : []);
        const allStaffText = window.i18n ? window.i18n.t('dashboard.vh_filter_all_staff', '👥 All Staff Members') : '👥 All Staff Members';
        const svcLabelText = window.i18n ? window.i18n.t('dashboard.modal_transfer_dest_services', '🛠️ Custom Services') : '🛠️ Custom Services';
        const cryptoLabelText = window.i18n ? window.i18n.t('dashboard.modal_transfer_dest_crypto', '💰 Crypto & Cash') : '💰 Crypto & Cash';
        userSelect.innerHTML = `<option value="all">${escapeHtml(allStaffText)}</option>` +
          usersList.filter(u => {
            if (u.deleted_at || u.deletedAt) return false;
            const isSelf = (currentUser && (String(u.__backendId || u.id) === String(currentUser.__backendId || currentUser.id) || u.username === currentUser.username));
            if (!isSelf && isUserFilterHidden(u, 'dashboard')) return false;
            return true;
          }
).map(u => {
            const uid = u.__backendId || u.id;
            const dept = u.department || u.role || 'crypto_cash';
            const label = dept === 'custom_services' ? svcLabelText : cryptoLabelText;
            return `<option value="${uid}">👤 ${escapeHtml(u.username || u.name)} (${label})</option>`;
          }
).join('');
        if (currentVaultHistoryFilter.user_id && currentVaultHistoryFilter.user_id !== 'all' && Array.from(userSelect.options).some(opt => opt.value === String(currentVaultHistoryFilter.user_id))) {
          userSelect.value = currentVaultHistoryFilter.user_id;
        }
 else {
          currentVaultHistoryFilter.user_id = 'all';
          userSelect.value = 'all';
        }

      }
      updateVaultScopeUserLabel(currentVaultHistoryFilter.user_id);

      // Populate safe selector in modal
      const safeSelect = document.getElementById('vh-filter-safe');
      if (safeSelect) {
        safeSelect.value = currentVaultHistoryFilter.vault_type;
      }

      // Populate inputs
      const sInp = document.getElementById('vh-filter-search');
      if (sInp) sInp.value = currentVaultHistoryFilter.search;
      const dfInp = document.getElementById('vh-filter-date-from');
      if (dfInp) dfInp.value = currentVaultHistoryFilter.date_from;
      const dtInp = document.getElementById('vh-filter-date-to');
      if (dtInp) dtInp.value = currentVaultHistoryFilter.date_to;

      // Update clear search button visibility
      const clearBtn = document.getElementById('vh-search-clear-btn');
      if (clearBtn) {
        if (currentVaultHistoryFilter.search) clearBtn.classList.remove('hidden');
        else clearBtn.classList.add('hidden');
      }

      const initialSection = options.section === 'hands' ? 'hands' : 'safe';
      switchVaultHistorySection(initialSection);

      // Update Tab highlight and directional sync
      if (initialSection === 'safe') {
        if (options.tab && options.tab !== 'all') {
          setVaultHistoryTab(options.tab);
        }
 else {
          applyVaultHistoryTabStyles(currentVaultHistoryFilter.tab);
        }

      } else {
        if (options.tab && options.tab !== 'all') {
          setVaultHandsTab(options.tab);
        }
 else {
          setVaultHandsTab(currentVaultHandsTab || 'all');
        }

      }

      // Show modal
      const modal = document.getElementById('vault-history-modal');
      if (modal) modal.classList.remove('hidden');
      restoreVaultHistoryFiltersState();

      // Restore collapsible KPI summary state (Apple Mobile Ergonomics)
      try {
        const isKpiCollapsed = localStorage.getItem('pos_vault_kpi_collapsed') === 'true';
        applyVaultHistoryKpiCollapsedState(isKpiCollapsed);
      } catch (e) {}
    }
    window.openVaultHistoryModal = openVaultHistoryModal;

    function toggleVaultHistoryKpiSummary(force) {
      const summary = document.getElementById('vh-collapsible-kpi-summary');
      const isCurrentlyCollapsed = summary ? summary.classList.contains('hidden') : false;
      const willCollapse = (typeof force === 'boolean') ? force : !isCurrentlyCollapsed;
      applyVaultHistoryKpiCollapsedState(willCollapse);
      try {
        localStorage.setItem('pos_vault_kpi_collapsed', willCollapse ? 'true' : 'false');
      } catch (e) {}
    }
    window.toggleVaultHistoryKpiSummary = toggleVaultHistoryKpiSummary;

    function applyVaultHistoryKpiCollapsedState(isCollapsed) {
      const summary = document.getElementById('vh-collapsible-kpi-summary');
      const icon = document.getElementById('vh-toggle-kpi-icon');
      const label = document.getElementById('vh-toggle-kpi-label');
      const btn = document.getElementById('vh-toggle-kpi-btn');

      if (!summary) return;

      if (isCollapsed) {
        summary.classList.add('hidden');
        if (icon) icon.classList.add('rotate-180');
        if (label) label.textContent = window.i18n ? window.i18n.t('dashboard.vh_show_kpis', 'Show Summary') : 'Show Summary';
        if (btn) btn.title = window.i18n ? window.i18n.t('dashboard.vh_show_kpis', 'Show Summary') : 'Show Summary';
      } else {
        summary.classList.remove('hidden');
        if (icon) icon.classList.remove('rotate-180');
        if (label) label.textContent = window.i18n ? window.i18n.t('dashboard.vh_hide_kpis', 'Hide Summary') : 'Hide Summary';
        if (btn) btn.title = window.i18n ? window.i18n.t('dashboard.vh_hide_kpis', 'Hide Summary') : 'Hide Summary';
      }
    }
    window.applyVaultHistoryKpiCollapsedState = applyVaultHistoryKpiCollapsedState;

