        if (userFilterLabel) userFilterLabel.textContent = window.i18n ? window.i18n.t('dashboard.vh_filter_staff_label', 'Staff Drawer') : 'Staff Drawer';
        if (badgeText) badgeText.textContent = window.i18n ? window.i18n.t('dashboard.vh_badge_safe_tracking', 'Vault & Physical Cash Drawer Tracking') : 'Vault & Physical Cash Drawer Tracking';
