    let isVaultHistoryFiltersCollapsed = false;

    function toggleVaultHistoryFilters(forceState) {
      const body = document.getElementById('vh-collapsible-filter-body');
      const icon = document.getElementById('vh-toggle-filters-icon');
      const label = document.getElementById('vh-toggle-filters-label');
      const _t = (k, fb) => (window.i18n && typeof window.i18n.t === 'function') ? window.i18n.t(k, fb) : fb;

      if (typeof forceState === 'boolean') {
        isVaultHistoryFiltersCollapsed = forceState;
      } else {
        isVaultHistoryFiltersCollapsed = !isVaultHistoryFiltersCollapsed;
      }

      if (body) {
        if (isVaultHistoryFiltersCollapsed) {
          body.classList.add('hidden');
        }
 else {
          body.classList.remove('hidden');
        }

      }

      if (icon) {
        if (isVaultHistoryFiltersCollapsed) {
          icon.classList.add('rotate-180');
        }
 else {
          icon.classList.remove('rotate-180');
        }

      }

      if (label) {
        const key = isVaultHistoryFiltersCollapsed ? 'dashboard.vh_show_filters' : 'dashboard.vh_hide_filters';
        const fallback = isVaultHistoryFiltersCollapsed ? 'Show Filters' : 'Hide Filters';
        label.setAttribute('data-i18n', key);
        label.textContent = (window.i18n && typeof window.i18n.t === 'function') ? window.i18n.t(key, fallback) : _t(key, fallback);
      }

      try {
        localStorage.setItem('pos_vault_filters_collapsed', isVaultHistoryFiltersCollapsed ? '1' : '0');
      } catch (e) {}

      updateVaultHistoryActiveFiltersBadge();
    }
    window.toggleVaultHistoryFilters = toggleVaultHistoryFilters;

    function restoreVaultHistoryFiltersState() {
      try {
        const saved = localStorage.getItem('pos_vault_filters_collapsed');
        if (saved === '1') {
          toggleVaultHistoryFilters(true);
        }
 else {
          toggleVaultHistoryFilters(false);
        }

      } catch (e) {
        toggleVaultHistoryFilters(false);
      }
    }
    window.restoreVaultHistoryFiltersState = restoreVaultHistoryFiltersState;

    function updateVaultHistoryActiveFiltersBadge() {
      const badge = document.getElementById('vh-active-filters-badge');
      if (!badge) return;

      const isCollapsed = isVaultHistoryFiltersCollapsed;
      if (!isCollapsed) {
        badge.classList.add('hidden');
        badge.classList.remove('inline-flex');
        return;
      }

      let isFiltered = false;
      if (typeof currentVaultHistoryFilter !== 'undefined' && currentVaultHistoryFilter) {
        if (currentVaultHistoryFilter.vault_type && currentVaultHistoryFilter.vault_type !== 'all') isFiltered = true;
        if (currentVaultHistoryFilter.user_id && currentVaultHistoryFilter.user_id !== 'all') isFiltered = true;
        if (currentVaultHistoryFilter.direction && currentVaultHistoryFilter.direction !== 'all') isFiltered = true;
        if (currentVaultHistoryFilter.type && currentVaultHistoryFilter.type !== 'all') isFiltered = true;
        if (currentVaultHistoryFilter.tab && currentVaultHistoryFilter.tab !== 'all') isFiltered = true;
        if (currentVaultHistoryFilter.search && currentVaultHistoryFilter.search.trim()) isFiltered = true;
        if (currentVaultHistoryFilter.date_from || currentVaultHistoryFilter.date_to) isFiltered = true;
      }
      if (typeof currentVaultHistorySection !== 'undefined' && currentVaultHistorySection === 'hands') {
        if (typeof currentVaultHandsTab !== 'undefined' && currentVaultHandsTab && currentVaultHandsTab !== 'all') {
          isFiltered = true;
        }

      }

      if (isFiltered) {
        badge.classList.remove('hidden');
        badge.classList.add('inline-flex');
      } else {
        badge.classList.add('hidden');
        badge.classList.remove('inline-flex');
      }
    }
    window.updateVaultHistoryActiveFiltersBadge = updateVaultHistoryActiveFiltersBadge;

    function debounceVaultHistorySearch() {
      const sInp = document.getElementById('vh-filter-search');
      const clearBtn = document.getElementById('vh-search-clear-btn');
      if (clearBtn) {
        if (sInp && sInp.value.trim().length > 0) clearBtn.classList.remove('hidden');
        else clearBtn.classList.add('hidden');
      }

      clearTimeout(vaultHistorySearchTimeout);
      vaultHistorySearchTimeout = setTimeout(() => {
        fetchAndRenderVaultHistory();
      }, 250);
    }
    window.debounceVaultHistorySearch = debounceVaultHistorySearch;

    function copyVaultLedgerText(text, label, ev) {
      if (ev) {
        ev.stopPropagation();
        ev.preventDefault();
      }
      if (!text) return;
      const clean = String(text).trim();
      if (!clean) return;
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(clean).then(() => {
          if (typeof showToast === 'function') {
            const msg = (window.i18n ? window.i18n.t('dashboard.vh_copy_toast', 'Copied {label}: {value}') : 'Copied {label}: {value}')
              .replace('{label}', label)
              .replace('{value}', clean);
            showToast(msg, 'success');
          }

        }
).catch(() => {
          if (typeof showToast === 'function') {
            showToast(_t('vault.toast_label_clean', `${label}: ${clean}`, { label: label, clean: clean }), 'info');
          }

        }
);
      } else {
        if (typeof showToast === 'function') {
          showToast(_t('vault.toast_label_clean', `${label}: ${clean}`, { label: label, clean: clean }), 'info');
        }

      }
    }
    window.copyVaultLedgerText = copyVaultLedgerText;

