    function handleUserCapitalBtnClick(e) {
      if (e) e.preventDefault();
      const container = document.getElementById('user-capital-injection-fields');
      const btn = document.getElementById('toggle-user-capital-btn');
      if (!container || !btn) return;

      const isUnlocked = !container.classList.contains('hidden');

      if (isUnlocked) {
        // When unlocked, single click immediately cancels and locks back
        setCapitalInjectionLockedState(true);
        return;
      }

      // When locked, support double-click / double-tap detection within 400ms:
      const now = Date.now();
      if (now - _lastCapitalBtnTap < 500) {
        _lastCapitalBtnTap = 0;
        setCapitalInjectionLockedState(false);
        return;
      }
      _lastCapitalBtnTap = now;

      // Single click while locked: strictly NEVER open fields!
      // Trigger pulse animation and warning toast
      btn.classList.add('animate-pulse', 'ring-2', 'ring-amber-400');
      setTimeout(() => {
        btn.classList.remove('animate-pulse', 'ring-2', 'ring-amber-400');
      }, 600);

      const _t = (k, d) => (typeof window.__t === 'function' ? window.__t(k, d) : (d !== undefined ? d : k));
      if (typeof showToast === 'function') {
        showToast(_t('users.modals_forms_double_click_hint', 'Capital injection is locked to protect cash vault. Double-click to unlock.'), 'info');
      }
    }

    function handleUserCapitalBtnDblClick(e) {
      if (e) e.preventDefault();
      const container = document.getElementById('user-capital-injection-fields');
      if (!container) return;
      const isUnlocked = !container.classList.contains('hidden');
      if (!isUnlocked) {
        setCapitalInjectionLockedState(false);
      }
    }

    function toggleUserCapitalInjection(e) {
      if (e && e.type === 'dblclick') {
        handleUserCapitalBtnDblClick(e);
      } else {
        handleUserCapitalBtnClick(e);
      }
    }

