    function populatePaySplitUsers() {
      const mainSel = document.getElementById('pay-cycle-payer-user');
      const partnerSel = document.getElementById('pay-split-partner-user');
      if (!mainSel || !partnerSel) return;

      const users = getUsers().filter(u => !u.deletedAt);
      const selectedMain = mainSel.value;

      partnerSel.innerHTML = users
        .filter(u => String(u.__backendId) !== selectedMain)
        .map(u => `<option value="${u.__backendId}">👤 ${escapeHtml(u.username)} (${(u.role === 'custom_services' || u.department === 'custom_services') ? 'Services' : 'Crypto'})</option>`)
        .join('');
    }

    function recalcBillSplit() {
      const totalAmt = document.getElementById('pay-cycle-amount')?.value || '0';
      const pctVal = parseInt(document.getElementById('pay-split-percent')?.value || '50', 10);
      const partnerPct = Math.max(1, Math.min(99, isNaN(pctVal) ? 50 : pctVal));
      const mainPct = 100 - partnerPct;

      if (!isNumeric(totalAmt) || exactCompare(totalAmt, '0') <= 0) return;

      const partnerAmt = exactMultiply(totalAmt, (partnerPct / 100).toString());
      const mainAmt = exactSubtract(totalAmt, partnerAmt);
      const sym = config.currency_symbol || 'DZD';

      const s1 = document.getElementById('pay-split-main-summary');
      const s2 = document.getElementById('pay-split-partner-summary');
      if (s1) s1.textContent = `Primary: ${mainPct}% (${formatNumber(mainAmt, 2)} ${sym})`;
      if (s2) s2.textContent = `Partner: ${partnerPct}% (${formatNumber(partnerAmt, 2)} ${sym})`;
    }

