    let currentBillPayMode = 'single';
    let billPayerRows = [];

    function setBillPayMode(mode) {
      currentBillPayMode = mode;
      const singleBtn = document.getElementById('pay-mode-single-btn');
      const splitBtn = document.getElementById('pay-mode-split-btn');
      const singleSec = document.getElementById('pay-single-payer-section');
      const splitSec = document.getElementById('pay-multi-split-section');

      if (mode === 'single') {
        singleBtn?.classList.add('bg-white', 'dark:bg-slate-900', 'text-slate-900', 'dark:text-white', 'shadow-2xs');
        singleBtn?.classList.remove('text-slate-500');
        splitBtn?.classList.remove('bg-white', 'dark:bg-slate-900', 'text-slate-900', 'dark:text-white', 'shadow-2xs');
        splitBtn?.classList.add('text-slate-500');
        singleSec?.classList.remove('hidden');
        splitSec?.classList.add('hidden');
      } else {
        splitBtn?.classList.add('bg-white', 'dark:bg-slate-900', 'text-slate-900', 'dark:text-white', 'shadow-2xs');
        splitBtn?.classList.remove('text-slate-500');
        singleBtn?.classList.remove('bg-white', 'dark:bg-slate-900', 'text-slate-900', 'dark:text-white', 'shadow-2xs');
        singleBtn?.classList.add('text-slate-500');
        singleSec?.classList.add('hidden');
        splitSec?.classList.remove('hidden');

        if (billPayerRows.length === 0) {
          initDefaultBillPayerRows();
        }

      }
      checkPayCycleHandoffWarning();
    }

    function initDefaultBillPayerRows() {
      const activeUsers = (typeof getUsers === 'function' ? getUsers() : usersCache).filter(u => !u.deletedAt && !u.deleted_at);
      const myId = (typeof currentUser !== 'undefined' && currentUser)
        ? parseInt(currentUser.__backendId || currentUser.id || currentUser.user_id, 10)
        : (activeUsers[0] ? parseInt(activeUsers[0].__backendId || activeUsers[0].id, 10) : 1);

      const totalDue = document.getElementById('pay-cycle-amount')?.value || '0';
      const precision = (config && config.display_decimals !== undefined && config.display_decimals !== null) ? config.display_decimals : 2;
      const initialAmt = (isNumeric(totalDue) && exactCompare(totalDue, '0') > 0) ? truncateDecimals(totalDue, precision) : '';

      billPayerRows = [
        { id: 1, user_id: myId, amount: initialAmt, percent: '100', paid_from: 'vault' }
      ];

      renderBillPayerRows();
      recalculateMultiPayerAllocations();
      checkPayCycleHandoffWarning();
    }
    window.initDefaultBillPayerRows = initDefaultBillPayerRows;

    function addBillPayerRow() {
      const activeUsers = (typeof getUsers === 'function' ? getUsers() : usersCache).filter(u => !u.deletedAt && !u.deleted_at);
      
      // Find the first active user not yet in billPayerRows
      const unselectedUser = activeUsers.find(u => {
        const uId = String(u.__backendId || u.id);
        return !billPayerRows.some(r => String(r.user_id) === uId);
      });

      if (!unselectedUser) {
        showToast(_t('bills.modals_forms_all_active_staff_members_have_already', 'All active staff members have already been added as payers.'), 'default');
        return;
      }

      const nextId = billPayerRows.length > 0 ? Math.max(...billPayerRows.map(r => r.id)) + 1 : 1;
      const uId = unselectedUser.__backendId || unselectedUser.id;

      billPayerRows.push({
        id: nextId,
        user_id: uId,
        amount: '',
        percent: '0',
        paid_from: 'vault'
      });

      renderBillPayerRows();
      recalculateMultiPayerAllocations();
      checkPayCycleHandoffWarning();
    }
    window.addBillPayerRow = addBillPayerRow;

    function removeBillPayerRow(rowId) {
      billPayerRows = billPayerRows.filter(r => r.id !== rowId);
      renderBillPayerRows();
      recalculateMultiPayerAllocations();
      checkPayCycleHandoffWarning();
    }
    window.removeBillPayerRow = removeBillPayerRow;

    function renderBillPayerRows() {
      const container = document.getElementById('pay-split-rows-container');
      if (!container) return;

      if (!billPayerRows || billPayerRows.length === 0) {
        container.innerHTML = `
          <div class="py-6 text-center text-slate-400 dark:text-slate-500 bg-slate-50 dark:bg-slate-800/40 rounded-2xl border border-dashed border-slate-200 dark:border-slate-700/80 p-4">
            <p class="text-xs font-bold">No payers currently allocated.</p>
            <p class="text-[11px] mt-0.5">Click <button type="button" onclick="addBillPayerRow()" class="text-indigo-600 dark:text-indigo-400 font-black hover:underline cursor-pointer">+ Add Payer</button> to assign a staff member.</p>
          </div>
        `;
        return;
      }

      const activeUsers = (typeof getUsers === 'function' ? getUsers() : usersCache).filter(u => !u.deletedAt && !u.deleted_at);
      const myId = (typeof currentUser !== 'undefined' && currentUser)
        ? String(currentUser.__backendId || currentUser.id || currentUser.user_id)
        : null;

      container.innerHTML = billPayerRows.map((row) => {
        const userOptions = activeUsers.map(u => {
          const uId = String(u.__backendId || u.id);
          const isSelectedInThisRow = String(row.user_id) === uId;
          const isSelectedInOtherRow = billPayerRows.some(r => r.id !== row.id && String(r.user_id) === uId);
          const isYou = (myId && uId === myId);
          const uRole = (u.role === 'custom_services' || u.department === 'custom_services') ? getSafeLocalizedName('services_safe', 'short') : getSafeLocalizedName('crypto_safe', 'short');
          
          let label = `👤 ${escapeHtml(u.username)} (${uRole})`;
          if (isYou) label += ' (You)';
          if (isSelectedInOtherRow) label += ' (Already added)';

          return `<option value="${uId}" ${isSelectedInThisRow ? 'selected' : ''} ${isSelectedInOtherRow ? 'disabled class="text-slate-400 dark:text-slate-600"' : ''}>${label}</option>`;
        }
).join('');

        return `
          <div class="p-3 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/80 dark:border-slate-700/80 flex flex-col sm:flex-row sm:items-center gap-2.5">
            <!-- User Selector -->
            <div class="flex-1 min-w-[130px]">
              <select onchange="updateBillPayerRow(${row.id}, 'user_id', this.value)"
                class="w-full px-3 py-2 bg-white dark:bg-slate-900 text-slate-900 dark:text-slate-100 rounded-xl text-xs font-bold border border-slate-200 dark:border-slate-700 outline-none">
                ${userOptions}
              </select>
            </div>

            <!-- Dual Split Inputs: Percentage (%) and Amount (DZD) Side-by-Side -->
            <div class="flex items-center gap-2">
              <!-- Percentage (%) Input -->
              <div class="w-20 relative">
                <input type="number" step="any" min="0" max="100" placeholder="0" value="${row.percent !== undefined && row.percent !== null ? row.percent : ''}"
                  id="payer-row-percent-${row.id}"
                  oninput="handleBillPayerPercentInput(${row.id}, this.value)"
                  class="w-full pl-2 pr-5 py-2 bg-white dark:bg-slate-900 text-slate-900 dark:text-slate-100 rounded-xl text-xs font-black font-mono border border-slate-200 dark:border-slate-700 outline-none focus:ring-2 focus:ring-emerald-500">
                <span class="absolute right-1.5 top-2 text-[10px] text-slate-400 font-sans font-bold">%</span>
              </div>

              <!-- Amount (DZD) Input -->
              <div class="w-28 relative">
                <input type="number" step="any" min="0" placeholder="0.00" value="${row.amount !== undefined && row.amount !== null ? row.amount : ''}"
                  id="payer-row-amount-${row.id}"
                  oninput="handleBillPayerAmountInput(${row.id}, this.value)"
                  class="w-full pl-2.5 pr-7 py-2 bg-white dark:bg-slate-900 text-slate-900 dark:text-slate-100 rounded-xl text-xs font-black font-mono border border-slate-200 dark:border-slate-700 outline-none focus:ring-2 focus:ring-emerald-500">
                <span class="absolute right-2 top-2 text-[10px] text-slate-400 font-sans font-bold">DZD</span>
              </div>
            </div>

            <!-- Payment Source -->
            <div class="w-32">
              <select onchange="updateBillPayerRow(${row.id}, 'paid_from', this.value)"
                class="w-full px-2.5 py-2 bg-white dark:bg-slate-900 text-slate-900 dark:text-slate-100 rounded-xl text-[11px] font-bold border border-slate-200 dark:border-slate-700 outline-none">
                <option value="vault" ${row.paid_from === 'vault' ? 'selected' : ''}>🏛️ User's Safe</option>
                <option value="hand" ${row.paid_from === 'hand' ? 'selected' : ''}>💵 Out of Hand</option>
              </select>
            </div>

            <!-- Delete Row Action -->
            <button type="button" onclick="removeBillPayerRow(${row.id})"
              class="w-8 h-8 rounded-xl bg-rose-50 hover:bg-rose-100 dark:bg-rose-950/60 text-rose-600 dark:text-rose-400 flex items-center justify-center transition-colors cursor-pointer shrink-0" title="Remove Payer">
              <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg>
            </button>
          </div>
        `;
      }).join('');
    }
    window.renderBillPayerRows = renderBillPayerRows;

    function handleBillPayerPercentInput(rowId, val) {
      const row = billPayerRows.find(r => r.id === rowId);
      if (!row) return;

      let pctVal = val;
      if (isNumeric(pctVal) && parseFloat(pctVal) > 100) {
        pctVal = '100';
        const pctEl = document.getElementById(`payer-row-percent-${rowId}`);
        if (pctEl) pctEl.value = '100';
        showToast(_t('bills.modals_forms_percentage_cannot_exceed_100', 'Percentage cannot exceed 100%'), 'default');
      }

      row.percent = pctVal;

      const totalDue = document.getElementById('pay-cycle-amount')?.value || '0';
      if (pctVal !== '' && isNumeric(pctVal) && isNumeric(totalDue) && exactCompare(totalDue, '0') > 0) {
        const precision = (config && config.display_decimals !== undefined && config.display_decimals !== null) ? config.display_decimals : 2;
        const ratio = exactDivide(pctVal, '100', precision + 6);
        let calculatedAmount = truncateDecimals(exactMultiply(totalDue, ratio), precision);
        if (exactCompare(calculatedAmount, totalDue) > 0) calculatedAmount = totalDue;
        row.amount = calculatedAmount;
        const amtEl = document.getElementById(`payer-row-amount-${rowId}`);
        if (amtEl) amtEl.value = calculatedAmount;
      } else if (pctVal === '' || exactCompare(pctVal, '0') === 0) {
        row.amount = '0';
        const amtEl = document.getElementById(`payer-row-amount-${rowId}`);
        if (amtEl) amtEl.value = '0';
      }
      recalculateMultiPayerAllocations();
    }
    window.handleBillPayerPercentInput = handleBillPayerPercentInput;

    function handleBillPayerAmountInput(rowId, val) {
      const row = billPayerRows.find(r => r.id === rowId);
      if (!row) return;

      const totalDue = document.getElementById('pay-cycle-amount')?.value || '0';
      let amtVal = val;

      if (isNumeric(amtVal) && isNumeric(totalDue) && exactCompare(totalDue, '0') > 0 && exactCompare(amtVal, totalDue) > 0) {
        amtVal = totalDue;
        const amtEl = document.getElementById(`payer-row-amount-${rowId}`);
        if (amtEl) amtEl.value = totalDue;
        showToast(_t('vault.toast_payer_amount_cannot_exceed_total_cy', `Payer amount cannot exceed total cycle amount (${formatPrice(totalDue)} DZD)`, { total: formatPrice(totalDue) }), 'default');
      }

      row.amount = amtVal;

      if (amtVal !== '' && isNumeric(amtVal) && isNumeric(totalDue) && exactCompare(totalDue, '0') > 0) {
        const ratio = exactDivide(amtVal, totalDue, 6);
        const calculatedPct = truncateDecimals(exactMultiply(ratio, '100'), 2);
        row.percent = calculatedPct;
        const pctEl = document.getElementById(`payer-row-percent-${rowId}`);
        if (pctEl) pctEl.value = calculatedPct;
      } else if (amtVal === '' || exactCompare(amtVal, '0') === 0) {
        row.percent = '0';
        const pctEl = document.getElementById(`payer-row-percent-${rowId}`);
        if (pctEl) pctEl.value = '0';
      }
      recalculateMultiPayerAllocations();
    }
    window.handleBillPayerAmountInput = handleBillPayerAmountInput;

    function handlePayCycleAmountChange() {
      const totalDue = document.getElementById('pay-cycle-amount')?.value || '0';
      if (typeof currentBillPayMode !== 'undefined' && currentBillPayMode === 'split' && isNumeric(totalDue) && exactCompare(totalDue, '0') > 0) {
        const precision = (config && config.display_decimals !== undefined && config.display_decimals !== null) ? config.display_decimals : 2;
        billPayerRows.forEach(r => {
          if (r.percent !== undefined && r.percent !== null && r.percent !== '' && isNumeric(r.percent)) {
            const ratio = exactDivide(String(r.percent), '100', precision + 6);
            let calculatedAmt = truncateDecimals(exactMultiply(totalDue, ratio), precision);
            if (exactCompare(calculatedAmt, totalDue) > 0) calculatedAmt = totalDue;
            r.amount = calculatedAmt;
            const amtEl = document.getElementById(`payer-row-amount-${r.id}`);
            if (amtEl) amtEl.value = r.amount;
          }

        }
);
      }
      recalculateMultiPayerAllocations();
      if (typeof handlePayCycleSourceChange === 'function') handlePayCycleSourceChange();
    }
    window.handlePayCycleAmountChange = handlePayCycleAmountChange;

    function updateBillPayerRow(rowId, field, val) {
      const row = billPayerRows.find(r => r.id === rowId);
      if (!row) return;
      row[field] = val;
      if (field === 'user_id') {
        renderBillPayerRows();
      }
      recalculateMultiPayerAllocations();
      checkPayCycleHandoffWarning();
    }
    window.updateBillPayerRow = updateBillPayerRow;

    function splitBillEvenlyAcrossPayers() {
      const totalDue = document.getElementById('pay-cycle-amount')?.value || '0';
      if (!isNumeric(totalDue) || exactCompare(totalDue, '0') <= 0 || billPayerRows.length === 0) return;

      const n = billPayerRows.length;
      const precision = (config && config.display_decimals !== undefined && config.display_decimals !== null) ? config.display_decimals : 2;
      const shareAmt = truncateDecimals(exactDivide(totalDue, String(n), precision + 4), precision);
      const sharePct = truncateDecimals(exactDivide('100', String(n), 4), 2);
      let cumulativeAmt = '0';
      let cumulativePct = '0';

      billPayerRows.forEach((r, i) => {
        if (i === n - 1) {
          r.amount = exactSubtract(totalDue, cumulativeAmt);
          r.percent = exactSubtract('100', cumulativePct);
        }
 else {
          r.amount = shareAmt;
          r.percent = sharePct;
          cumulativeAmt = exactAdd(cumulativeAmt, shareAmt);
          cumulativePct = exactAdd(cumulativePct, sharePct);
        }

        const amtEl = document.getElementById(`payer-row-amount-${r.id}`);
        if (amtEl) amtEl.value = r.amount;
        const pctEl = document.getElementById(`payer-row-percent-${r.id}`);
        if (pctEl) pctEl.value = r.percent;
      });

      renderBillPayerRows();
      recalculateMultiPayerAllocations();
    }
    window.splitBillEvenlyAcrossPayers = splitBillEvenlyAcrossPayers;

    function recalculateMultiPayerAllocations() {
      const totalDue = document.getElementById('pay-cycle-amount')?.value || '0';
      const allocatedEl = document.getElementById('pay-split-total-allocated');
      const remainingEl = document.getElementById('pay-split-remaining-val');
      const submitBtn = document.getElementById('confirm-pay-cycle-btn');
      const sym = (typeof config !== 'undefined' && config.currency_symbol) ? config.currency_symbol : 'DZD';

      let totalAlloc = '0';
      billPayerRows.forEach(r => {
        if (r.amount && isNumeric(r.amount) && exactCompare(r.amount, '0') > 0) {
          totalAlloc = exactAdd(totalAlloc, r.amount);
        }

      });

      const remaining = exactSubtract(totalDue, totalAlloc);

      if (allocatedEl) allocatedEl.textContent = formatNumber(totalAlloc, 2) + ' ' + sym;
      if (remainingEl) {
        if (exactCompare(remaining, '0') === 0) {
          remainingEl.className = 'font-black text-emerald-500';
          remainingEl.textContent = '0.00 ' + sym + ' (100% Balanced)';
          if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.classList.remove('opacity-50', 'cursor-not-allowed');
          }

        }
 else if (exactCompare(remaining, '0') < 0) {
          remainingEl.className = 'font-black text-rose-500 animate-pulse';
          remainingEl.textContent = '⚠️ Over-allocated by ' + formatNumber(exactSubtract('0', remaining), 2) + ' ' + sym;
          if (submitBtn) {
            submitBtn.disabled = true;
            submitBtn.classList.add('opacity-50', 'cursor-not-allowed');
          }

        }
 else {
          remainingEl.className = 'font-black text-amber-500';
          remainingEl.textContent = formatNumber(remaining, 2) + ' ' + sym;
          if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.classList.remove('opacity-50', 'cursor-not-allowed');
          }

        }

      }
    }
    window.recalculateMultiPayerAllocations = recalculateMultiPayerAllocations;

    function checkPayCycleHandoffWarning() {
      const warnBox = document.getElementById('pay-cycle-handoff-warning');
      if (!warnBox) return;

      const activeUsers = (typeof getUsers === 'function' ? getUsers() : usersCache).filter(u => !u.deletedAt && !u.deleted_at);

      if (typeof currentBillPayMode !== 'undefined' && currentBillPayMode === 'single') {
        const source = document.getElementById('pay-cycle-source')?.value || 'vault';
        if (source === 'hand') {
          const payerId = document.getElementById('pay-cycle-payer-user')?.value;
          const user = activeUsers.find(u => String(u.__backendId || u.id) === String(payerId));
          const userName = user ? user.username : 'Selected Staff Member';
          warnBox.innerHTML = `
            <div class="flex items-start gap-2.5">
              <span class="text-base shrink-0 leading-none">⚠️</span>
              <div>
                <p class="font-black text-amber-600 dark:text-amber-400">Paying Active Bill Out of Hand / Handoff (${escapeHtml(userName)})?</p>
                <p class="text-[11px] text-amber-600/90 dark:text-amber-400/90 mt-0.5">Are you sure? This payment is being settled out of pocket and will <strong>NOT</strong> be deducted from the physical cash safe drawer.</p>
              </div>
            </div>
          `;
          warnBox.classList.remove('hidden');
        }
 else {
          warnBox.classList.add('hidden');
          warnBox.innerHTML = '';
        }

      } else {
        // Multi-Split Mode
        const handPayers = (billPayerRows || []).filter(r => r.paid_from === 'hand');
        if (handPayers.length > 0) {
          const names = handPayers.map(r => {
            const u = activeUsers.find(user => String(user.__backendId || user.id) === String(r.user_id));
            return u ? u.username : `User #${r.user_id}`;
          }
);
          const namesList = names.map(n => `<strong>${escapeHtml(n)}</strong>`).join(', ');
          const isPlural = handPayers.length > 1;

          warnBox.innerHTML = `
            <div class="flex items-start gap-2.5">
              <span class="text-base shrink-0 leading-none">⚠️</span>
              <div>
                <p class="font-black text-amber-600 dark:text-amber-400">${isPlural ? 'Multiple Users' : 'User'} Paying by Handoff / Out of Pocket</p>
                <p class="text-[11px] text-amber-600/90 dark:text-amber-400/90 mt-0.5">The following ${isPlural ? 'staff members are' : 'staff member is'} paying this active bill by handoff: ${namesList}. Are you sure? Their split shares will <strong>NOT</strong> be deducted from their physical cash safe drawers.</p>
              </div>
            </div>
          `;
          warnBox.classList.remove('hidden');
        }
 else {
          warnBox.classList.add('hidden');
          warnBox.innerHTML = '';
        }

      }
    }
    window.checkPayCycleHandoffWarning = checkPayCycleHandoffWarning;

    // ══════════════════════════════════════════════════════════════
    // CUSTOM SERVICES & WORKSHOP ENGINE (Apple Bento Architecture)
    // ══════════════════════════════════════════════════════════════
    let customServicesCache = [];
    let customServicesKpis = {};
    let currentServicesViewMode = 'kanban';

    async function loadCustomServicesData() {
      try {
        const res = await apiRequest('/api/custom-services');
        if (!res) return;

        customServicesCache = res.services || [];
        customServicesKpis = res.kpis || {};

        // Update KPIs
        const kpiAct = document.getElementById('srv-kpi-active');
        const kpiProg = document.getElementById('srv-kpi-in-progress');
        const kpiRdy = document.getElementById('srv-kpi-ready');
        const kpiPrf = document.getElementById('srv-kpi-profit');
        const sym = config.currency_symbol || 'DZD';

        if (kpiAct) kpiAct.textContent = customServicesKpis.active_jobs || 0;
        if (kpiProg) kpiProg.textContent = customServicesKpis.in_progress || 0;
        if (kpiRdy) kpiRdy.textContent = customServicesKpis.ready_pickup || 0;
        if (kpiPrf) kpiPrf.textContent = formatNumber(customServicesKpis.services_profit || '0', 2) + ' ' + sym;

        populateCustomServicesTechFilter();
        renderCustomServicesViews();
      } catch (err) {
        console.error('Failed to load custom services:', err);
      }
    }

    function setServicesViewMode(mode) {
      currentServicesViewMode = mode;
      const kanbanBtn = document.getElementById('srv-view-kanban-btn');
      const tableBtn = document.getElementById('srv-view-table-btn');
      const kanbanView = document.getElementById('services-kanban-view');
      const tableView = document.getElementById('services-table-view');

      if (mode === 'kanban') {
        kanbanBtn?.classList.add('bg-white', 'dark:bg-slate-900', 'text-slate-900', 'dark:text-white', 'shadow-2xs');
        kanbanBtn?.classList.remove('text-slate-500');
        tableBtn?.classList.remove('bg-white', 'dark:bg-slate-900', 'text-slate-900', 'dark:text-white', 'shadow-2xs');
        tableBtn?.classList.add('text-slate-500');
        kanbanView?.classList.remove('hidden');
        tableView?.classList.add('hidden');
      } else {
        tableBtn?.classList.add('bg-white', 'dark:bg-slate-900', 'text-slate-900', 'dark:text-white', 'shadow-2xs');
        tableBtn?.classList.remove('text-slate-500');
        kanbanBtn?.classList.remove('bg-white', 'dark:bg-slate-900', 'text-slate-900', 'dark:text-white', 'shadow-2xs');
        kanbanBtn?.classList.add('text-slate-500');
        kanbanView?.classList.add('hidden');
        tableView?.classList.remove('hidden');
      }
    }

    function populateCustomServicesTechFilter() {
      const techSel = document.getElementById('srv-tech-filter');
      const intakeTechSel = document.getElementById('srv-intake-tech');
      const activeUsers = (typeof getUsers === 'function' ? getUsers() : usersCache).filter(u => !u.deletedAt && !u.deleted_at);

      if (techSel) {
        const curVal = techSel.value;
        const visibleTechs = activeUsers.filter(u => {
          const isSelf = (currentUser && (String(u.__backendId || u.id) === String(currentUser.__backendId || currentUser.id) || u.username === currentUser.username));
          if (!isSelf && isUserFilterHidden(u, 'orders')) return false;
          return true;
        }
);
        techSel.innerHTML = '<option value="all">👤 All Technicians</option>' + visibleTechs.map(u => {
          const uId = u.__backendId || u.id;
          return `<option value="${uId}">👤 ${escapeHtml(u.username)}</option>`;
        }
).join('');
        if (curVal && curVal !== 'all' && visibleTechs.some(u => String(u.__backendId || u.id) === String(curVal))) {
          techSel.value = curVal;
        }
 else {
          techSel.value = 'all';
        }

      }

      if (intakeTechSel) {
        intakeTechSel.innerHTML = activeUsers.map(u => {
          const uId = u.__backendId || u.id;
          const isTech = (u.role === 'custom_services' || u.department === 'custom_services');
          const safeShort = isTech ? getSafeLocalizedName('services_safe', 'short') : getSafeLocalizedName('crypto_safe', 'short');
          return `<option value="${uId}" ${isTech ? 'selected' : ''}>👤 ${escapeHtml(u.username)} (${safeShort})</option>`;
        }
).join('');
      }
    }

    function filterCustomServicesView() {
      renderCustomServicesViews();
    }

    function renderCustomServicesViews() {
      const q = document.getElementById('srv-search-input')?.value.toLowerCase().trim() || '';
      const techFilter = document.getElementById('srv-tech-filter')?.value || 'all';
      const stageFilter = document.getElementById('srv-stage-filter')?.value || 'all';
      const sym = config.currency_symbol || 'DZD';

      const filtered = customServicesCache.filter(s => {
        if (techFilter !== 'all' && String(s.owner_user_id) !== String(techFilter)) return false;
        if (stageFilter === 'active' && !['received', 'pending', 'diagnosing', 'in_progress', 'waiting_parts'].includes(s.status)) return false;
        if (stageFilter === 'ready' && s.status !== 'ready') return false;
        if (stageFilter === 'delivered' && !['delivered', 'completed'].includes(s.status)) return false;

        if (q) {
          const matchUid = (s.uid || '').toLowerCase().includes(q);
          const matchName = (s.service_name || '').toLowerCase().includes(q);
          const matchCust = (s.customer_name || s.customer_note || '').toLowerCase().includes(q);
          if (!matchUid && !matchName && !matchCust) return false;
        }

        return true;
      });

      // 1. Render Kanban Columns
      const cols = {
        received: document.getElementById('kanban-col-received'),
        in_progress: document.getElementById('kanban-col-in-progress'),
        ready: document.getElementById('kanban-col-ready'),
        delivered: document.getElementById('kanban-col-delivered')
      };

      const counts = { received: 0, in_progress: 0, ready: 0, delivered: 0 };
      Object.values(cols).forEach(col => { if (col) col.innerHTML = ''; });

      filtered.forEach(s => {
        let colKey = 'received';
        if (['in_progress', 'diagnosing', 'waiting_parts'].includes(s.status)) colKey = 'in_progress';
        else if (s.status === 'ready') colKey = 'ready';
        else if (['delivered', 'completed'].includes(s.status)) colKey = 'delivered';

        counts[colKey]++;

        if (cols[colKey]) {
          const cardHtml = `
            <div class="p-4 rounded-2xl bg-white dark:bg-slate-900 border border-slate-200/90 dark:border-slate-800 shadow-2xs space-y-3 hover:border-blue-500/50 transition-all">
              <div class="flex items-center justify-between">
                <span class="text-xs font-black font-mono text-blue-600 dark:text-blue-400">${escapeHtml(s.uid || 'SRV-' + s.id)}</span>
                <span class="text-[10px] text-slate-400 font-medium">${s.date ? parseMySQLDate(s.date).toLocaleDateString() : ''}</span>
              </div>

              <div>
                <h4 class="font-extrabold text-sm text-slate-900 dark:text-white line-clamp-2">${escapeHtml(s.service_name || 'Service Job')}</h4>
                <p class="text-[11px] text-slate-500 dark:text-slate-400 mt-0.5">${escapeHtml(s.customer_name || s.customer_note || 'Walk-in Client')}</p>
              </div>

              <div class="p-2.5 rounded-xl bg-slate-50 dark:bg-slate-800/60 text-xs font-mono flex justify-between items-center">
                <span class="text-[10px] text-slate-400 uppercase">Price:</span>
                <span class="font-black text-slate-900 dark:text-white">${formatNumber(s.total || '0', 2)} ${sym}</span>
              </div>

              <div class="flex items-center justify-between pt-2 border-t border-slate-100 dark:border-slate-800">
                <span class="text-[10px] font-bold text-slate-600 dark:text-slate-300">👤 ${escapeHtml(s.technician_name || 'Tech')}</span>
                <div class="flex items-center gap-1.5">
                  ${colKey === 'received' ? `
                    <button type="button" onclick="advanceServiceStage(${s.id}, 'in_progress')"
                      class="px-2.5 py-1 bg-cyan-600 hover:bg-cyan-500 text-white font-bold text-[10px] rounded-lg shadow-xs transition-all">
                      Start Repair →
                    </button>
                  ` : ''}
                  ${colKey === 'in_progress' ? `
                    <button type="button" onclick="advanceServiceStage(${s.id}, 'ready')"
                      class="px-2.5 py-1 bg-emerald-600 hover:bg-emerald-500 text-white font-bold text-[10px] rounded-lg shadow-xs transition-all">
                      Mark Ready →
                    </button>
                  ` : ''}
                  ${colKey === 'ready' ? `
                    <button type="button" onclick="advanceServiceStage(${s.id}, 'delivered')"
                      class="px-2.5 py-1 bg-blue-600 hover:bg-blue-500 text-white font-bold text-[10px] rounded-lg shadow-xs transition-all">
                      Deliver &amp; Settle 💰
                    </button>
                  ` : ''}
                  ${colKey === 'delivered' ? `
                    <span class="text-[10px] font-black text-emerald-500">🟢 Settled</span>
                  ` : ''}
                </div>
              </div>
            </div>
          `;
          cols[colKey].insertAdjacentHTML('beforeend', cardHtml);
        }

      });

      // Update kanban counters
      document.getElementById('kanban-count-received').textContent = counts.received;
      document.getElementById('kanban-count-in-progress').textContent = counts.in_progress;
      document.getElementById('kanban-count-ready').textContent = counts.ready;
      document.getElementById('kanban-count-delivered').textContent = counts.delivered;

      // 2. Render Table View
      const tbody = document.getElementById('services-table-tbody');
      if (tbody) {
        if (filtered.length === 0) {
          tbody.innerHTML = '<tr><td colspan="9" class="p-8 text-center text-slate-400 font-medium">No service jobs match your filter criteria</td></tr>';
          return;
        }

        tbody.innerHTML = filtered.map(s => `
          <tr class="hover:bg-slate-50/80 dark:hover:bg-slate-800/50 transition-colors">
            <td class="p-4 font-mono font-bold text-sm text-blue-600 dark:text-blue-400">${escapeHtml(s.uid || 'SRV-' + s.id)}<br><span class="text-[10px] font-normal text-slate-400">${s.date ? parseMySQLDate(s.date).toLocaleDateString() : ''}</span></td>
            <td class="p-4 font-bold text-slate-900 dark:text-white">${escapeHtml(s.service_name || '')}</td>
            <td class="p-4 text-slate-600 dark:text-slate-300 font-medium">${escapeHtml(s.customer_name || s.customer_note || 'Walk-in')}</td>
            <td class="p-4 font-bold text-indigo-500">👤 ${escapeHtml(s.technician_name || 'Tech')}</td>
            <td class="p-4 font-mono text-slate-500">${formatNumber(s.manual_cost || s.products_cost || '0', 2)} ${sym}</td>
            <td class="p-4 font-mono font-black text-slate-900 dark:text-white">${formatNumber(s.total || '0', 2)} ${sym}</td>
            <td class="p-4 font-mono font-black text-emerald-500">+${formatNumber(s.profit || '0', 2)} ${sym}</td>
            <td class="p-4"><span class="px-2.5 py-1 rounded-full text-[10px] font-black bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 uppercase">${escapeHtml(s.status)}</span></td>
            <td class="p-4 text-right">
              ${s.status !== 'delivered' && s.status !== 'completed' ? `
                <button type="button" onclick="advanceServiceStage(${s.id}, '${s.status === 'received' ? 'in_progress' : (s.status === 'in_progress' ? 'ready' : 'delivered')}')"
                  class="px-2.5 py-1 bg-violet-600 hover:bg-violet-500 text-white font-bold text-xs rounded-xl shadow-xs transition-all cursor-pointer">
                  Advance →
                </button>
              ` : '<span class="text-xs text-slate-400">Closed</span>'}
            </td>
          </tr>
        `).join('');
      }
    }

    function openNewServiceJobModal() {
      document.getElementById('new-service-job-form')?.reset();
      populateCustomServicesTechFilter();
      updateServiceJobProfitPreview();
      document.getElementById('new-service-job-modal')?.classList.remove('hidden');
    }

    function closeNewServiceJobModal() {
      document.getElementById('new-service-job-modal')?.classList.add('hidden');
    }

    function updateServiceJobProfitPreview() {
      const price = document.getElementById('srv-intake-price')?.value || '0';
      const cost = document.getElementById('srv-intake-cost')?.value || '0';
      const previewEl = document.getElementById('srv-intake-profit-preview');
      const sym = config.currency_symbol || 'DZD';

      if (previewEl) {
        const profit = exactSubtract(price, cost);
        previewEl.textContent = formatNumber(profit, 2) + ' ' + sym;
      }
    }

    async function saveNewServiceJob(e) {
      e.preventDefault();
      const name = document.getElementById('srv-intake-name').value.trim();
      const techId = document.getElementById('srv-intake-tech').value;
      const custName = document.getElementById('srv-intake-customer').value.trim();
      const desc = document.getElementById('srv-intake-desc').value.trim();
      const price = document.getElementById('srv-intake-price').value.trim();
      const deposit = document.getElementById('srv-intake-deposit').value.trim() || '0';
      const cost = document.getElementById('srv-intake-cost').value.trim() || '0';

      if (!name) {
        showToast(_t('vault.toast_please_enter_a_service_name', 'Please enter a service name'), 'default');
        return;
      }

      try {
        const res = await apiRequest('/api/custom-services', {
          method: 'POST',
          body: JSON.stringify({
            service_name: name,
            owner_user_id: techId,
            customer_note: custName,
            service_description: desc,
            total: price,
            deposit_paid: deposit,
            manual_cost: cost,
            status: 'received'
          }
)
        }
);

        showToast(_t('vault.toast_service_job_created_and_booked_succ', 'Service job created and booked successfully!'), 'default');
        closeNewServiceJobModal();
        await loadCustomServicesData();
        await updateDashboardVault();
      } catch (err) {
        showToast(err.message || _t('vault.toast_failed_to_create_service_job', 'Failed to create service job'), 'default');
      }
    }

    async function advanceServiceStage(orderId, nextStage) {
      try {
        await apiRequest(`/api/custom-services/${orderId}/stage`, {
          method: 'PUT',
          body: JSON.stringify({ stage: nextStage })
        }
);

        showToast(_t('vault.toast_job_advanced_to_stage_nextstage', `Job advanced to stage: ${nextStage}`, { stage: nextStage }), 'default');
        await loadCustomServicesData();
        await updateDashboardVault();
      } catch (err) {
        showToast(err.message || _t('vault.toast_failed_to_update_job_stage', 'Failed to update job stage'), 'default');
      }
    }

    let currentVaultLens = 'total';
    function switchVaultLens(lens) {
      currentVaultLens = lens;
      const totalBtn = document.getElementById('vault-lens-total');
      const mineBtn = document.getElementById('vault-lens-mine');
      if (lens === 'mine') {
        totalBtn.className = 'px-3 py-1.5 text-[11px] font-bold rounded-xl bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-400 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition-all';
        mineBtn.className = 'px-3 py-1.5 text-[11px] font-black rounded-xl bg-indigo-600 dark:bg-indigo-500 text-white transition-all shadow-md';
      } else {
        totalBtn.className = 'px-3 py-1.5 text-[11px] font-black rounded-xl bg-slate-900 dark:bg-white text-white dark:text-slate-900 transition-all';
        mineBtn.className = 'px-3 py-1.5 text-[11px] font-bold rounded-xl bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-400 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition-all';
      }
      updateDashboardVault(); 
    }
    window.switchVaultLens = switchVaultLens;

    async function updateDashboardEquityStrip() {
      try {
        const res = await apiRequest('/api/partner-settlements/summary');
        if (!res) return;

        const recEl = document.getElementById('dash-equity-receivable');
        if (recEl) recEl.textContent = formatPrice(res.total_receivable || '0');

        const payEl = document.getElementById('dash-equity-payable');
        if (payEl) payEl.textContent = formatPrice(res.total_payable || '0');

      } catch (err) {
        // Equity strip is optional — silently fail
      }
    }
