    /**
     * Parse lightweight Markdown subset into sanitized HTML for LICENSE.md
     */
    function parseSizarMarkdownToHtml(md) {
      if (!md) return '';
      const lines = md.replace(/\r\n/g, '\n').replace(/\r/g, '\n').split('\n');
      let html = '';
      let inList = false;
      let listType = null;
      let inBlockquote = false;
      let blockquoteBuffer = [];

      function flushBlockquote() {
        if (inBlockquote) {
          const innerHtml = blockquoteBuffer.map(l => parseInlineMarkdown(l)).join('<br>');
          html += `<blockquote>${innerHtml}</blockquote>\n`;
          blockquoteBuffer = [];
          inBlockquote = false;
        }

      }

      function flushList() {
        if (inList) {
          html += `</${listType}>\n`;
          inList = false;
          listType = null;
        }

      }

      function parseInlineMarkdown(text) {
        if (!text) return '';
        let s = text
          .replace(/&/g, '&amp;')
          .replace(/</g, '&lt;')
          .replace(/>/g, '&gt;');

        s = s.replace(/`([^`]+)`/g, '<code>$1</code>');
        s = s.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
        s = s.replace(/\*([^*]+)\*/g, '<em>$1</em>');
        return s;
      }

      for (let i = 0; i < lines.length; i++) {
        const line = lines[i];
        const trimmed = line.trim();

        if (trimmed.startsWith('>')) {
          flushList();
          inBlockquote = true;
          blockquoteBuffer.push(trimmed.replace(/^>\s*/, ''));
          continue;
        }
 else if (inBlockquote) {
          flushBlockquote();
        }


        if (!trimmed) {
          flushList();
          flushBlockquote();
          continue;
        }


        if (/^(\-{3,}|\*{3,}|_{3,})$/.test(trimmed)) {
          flushList();
          flushBlockquote();
          html += '<hr>\n';
          continue;
        }


        const h3Match = trimmed.match(/^###\s+(.+)$/);
        if (h3Match) {
          flushList();
          flushBlockquote();
          html += `<h3>${parseInlineMarkdown(h3Match[1])}</h3>\n`;
          continue;
        }

        const h2Match = trimmed.match(/^##\s+(.+)$/);
        if (h2Match) {
          flushList();
          flushBlockquote();
          html += `<h2>${parseInlineMarkdown(h2Match[1])}</h2>\n`;
          continue;
        }

        const h1Match = trimmed.match(/^#\s+(.+)$/);
        if (h1Match) {
          flushList();
          flushBlockquote();
          html += `<h1>${parseInlineMarkdown(h1Match[1])}</h1>\n`;
          continue;
        }


        const ulMatch = trimmed.match(/^[\*\-]\s+(.+)$/);
        if (ulMatch) {
          flushBlockquote();
          if (!inList || listType !== 'ul') {
            flushList();
            inList = true;
            listType = 'ul';
            html += '<ul>\n';
          }

          html += `  <li>${parseInlineMarkdown(ulMatch[1])}</li>\n`;
          continue;
        }


        const olMatch = trimmed.match(/^\d+\.\s+(.+)$/);
        if (olMatch) {
          flushBlockquote();
          if (!inList || listType !== 'ol') {
            flushList();
            inList = true;
            listType = 'ol';
            html += '<ol>\n';
          }

          html += `  <li>${parseInlineMarkdown(olMatch[1])}</li>\n`;
          continue;
        }


        flushList();
        flushBlockquote();
        html += `<p class="my-1.5 leading-relaxed">${parseInlineMarkdown(trimmed)}</p>\n`;
      }

      flushList();
      flushBlockquote();
      return html;
    }

